INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(81706, 'ث', '<span class=\"hlight\">ث .</span> (ع حرف ) حرف چهارم است از حروف هجای عرب و حرف پنجم از هجای فارسی و صوت آن سین است آنگاه که زبان در میان دندانها درآرند. یا اصوت ثتای یونانی میان حرف ت و ج و نام آن ثاء است و چهاردهمین از حروف جُمَّل و آنرا به پانصد دارند و در حساب ترتیبی نماینده ٔ عدد پنج است و هم از حروف روادف و از حروف مصمته است و در کتب لغت رمز است از حدیث و در علم هیئت (بدون نقطه ) رمز است از تثلیث . و این حرف در زبانهای اوستائی و پارسی باستان بوده است .<br />ابدالها:<br />در فارسی :<br />> گاه به «هَ» تبدیل شود، مانند:<br />سپیژه = سپهر.<br />پرثوه = پهله (پهلوی، با تبدیل و قلب ).<br />مثره = مهر.<br />> و گاه به «س » بدل گردد، مانند:<br />پوثره = پسر (پوهر پهلوی ).<br />> ثاء لغات عربی در فارسی گاه بدل به «تاء» شود، چون :<br />ثرید = ترید.<br /> <font color=\"Red\">و در زبان عربی :</font><br />> گاه بدل «تا» آید:<br />شبث = شبت .<br />حثیره = حتیره .<br />بقث = بقت .<br />> و گاه بدل «ض » آید:<br />تحاث = تحاض .<br />اثر = اضر.<br />> و گاه بدل «غ » آید:<br />ضیثم = ضیغم .<br />> و گاه بدل «ف » آید:<br />ثوم = فوم .<br />ثنأدار = قنأدار.<br />> و گاه بدل «ق » آید:<br />مِثِم و مِثِمَّه = مقم و مقمه .<br />> و گاه بدل «م » آید:<br />ثعو = معو.<br />> و گاه بدل «ن » آید:<br />ثتن اللحم = نتن اللحم .<br />و این حرف در فارسی دری نباشد لکن در کلمات کیومرث و طهمورث و ارثنک و ثغ، آمده است .<br /></font></div>'),
(81707, 'ثا', '<span class=\"hlight\">ثا.</span> (پسوند) این صورت در بعض اسماء امکنه چون مزید مؤخری آمده است و ظاهراً در یکی از زبانهای مجاور ایران معنی ناحیت یا زمین یا قریه یا شهر میداده است . مانند اکشوثا، باحسیثا، باعیناثا، باقسیاثا، براثا، تلقیاثا، توماثا، جبثا، جثا، جواثا، جوثا، حندوثا، خناثا، دبثا، دببثا، شلاثا، طیثثا، قبراثا، قسیاثا، کراثا، کفرتوثا، کفرلاثا، کفرلهثا، مصراثا، معراثا، هلثا، یکشوثا.<br /></font></div>'),
(81708, 'ثاء', '<span class=\"hlight\">ثاء.</span> (ع اِ) نام حرف «ث ». <BR><font color=\"Blue\">◄</font> کثیر از هر چیزی . <BR><font color=\"Blue\">◄</font> آنکه زندگانی کند از هر چیز. و تصغیر آن ثُییَّه است .<br /></font></div>'),
(81709, 'ثااجیس', '<span class=\"hlight\">ثااجیس .</span> <font color=\"DarkGreen\"><b>[ اِ ]</font></b> (اِخ ) رجوع به ثأجیس شود.<br /></font></div>'),
(81710, 'ثااطاطس', '<span class=\"hlight\">ثااطاطس .</span> <font color=\"DarkGreen\"><b>[ اِ طِ ]</font></b> (اِخ ) نام کتابی از افلاطون . (ابن الندیم ). رجوع به ثأططس شود.<br /></font></div>'),
(81711, 'ثاب', '<span class=\"hlight\">ثاب .</span> (اِخ ) محلی است در شعر اغلب .<br /></font></div>'),
(81712, 'ثابة', '<span class=\"hlight\">ثابة.</span> <font color=\"DarkGreen\"><b>[ ثاب ْ ب َ ]</font></b> (ع ص، اِ) زن جوان .<br /></font></div>'),
(81713, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن ودیعةبن خدام . یکی از بنی امیةبن زیدبن مالک . ابن حجر از ابن سعد روایت کند که پدر ثابت ازمنافقین بود و او غیر ثابت بن یزید معروف بابن ودیعةاست، زیرا نسب آنها مختلف است چه ودیعه نام پدر صاحب ترجمه است در مورد ثابت بن یزید نام مادر او است .<br /></font></div>'),
(81714, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b>(اِخ ) ابن محمد القمی، کمال الدین . از جمله ٔ ملازمان قدیم سلطان مسعود چون عزالملک ابن مجدالدین الیزدجردی در سن هفتاد سالگی منصب وزارت قبول نمود و او بسوء خلق و کثرت طمع و هرزه گوئی و عیب جوئی موصوف بود کمال الدین ثابت قمی که بر درگاه سلطان مسعود اعتبار و اختیار تمام داشت کمر عداوت عزالملک بر میان بسته خواست که او را از پای درآورد و دست جورش را از سر اهالی مملکت کوتاه گرداند. بنابر آن بسلطان سنجر عرضه داشت کرد که پیوسته تعیین وزراء مفوض به رأی عالم آرای نواب درگاه عالم بود حالااتابکان وزیرنشانی می کنند و درین باب از بندگان آن آستان اقبال آشیان استجازه نمی نمایند و مضمون این عریضه بسمع اتابک اقسنقر رسیده کمال الدین ثابت را در قلعه ٔ همدان بقتل رسانید .<br /></font></div>'),
(81715, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن نعیم . او در حمص مردم را بضد مروان بن محمدخلیفه ٔ اموی برانگیخت .<br /></font></div>'),
(81716, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن نعمان مکنی به ابوحبة البدری . صحابی است .<br /></font></div>'),
(81717, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن النعمان بن زیدبن عامربن سوادبن ظفرالأنصاری الظفری . ابن حجر گوید بقول ابوموسی این همان ثابت است که پیش از این ترجمه اش گذشت لکن ابوعمر میان آن دو فرق گذاشته است .<br /></font></div>'),
(81718, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن النعمان الحارث بن عبد رزاح بن ظفر الأنصاری الظفری . او صحابی است .مؤلف کتاب الاصابة گوید ثابت درک غزوه ٔ احد و مشاهد دیگر کرده است و در جنگ جسر ابی عبید بشهادت رسید.<br /></font></div>'),
(81719, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن نزیر قرطبی مالکی . او راست کتاب الجهاد. وی بسال <span class=\"hlight\" dir=\"rtl\">٣١٨</span> هَ . ق . درگذشت .<br /></font></div>'),
(81720, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن موسی مکنی به ابویزید. محدث است و از شریک روایت کند.<br /></font></div>'),
(81721, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ب ِ ]</font></b> (اِخ ) ابن موسی مکنی به ابویزید. تابعی است .<br /></font></div>'),
(81722, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ]</font></b> (اِخ ) ابن مخلدبن زیدبن مخلدبن حارثةبن عمرو الانصاری الخطمی . ابن حجر گوید ابن شاهین او را از صحابه شمرده است و وفات او را روز جنگ «الحرة» گفته است .<br /></font></div>'),
(81723, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن محمد کنانی، ابواسماعیل . تابعی است .<br /></font></div>'),
(81724, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن وقش بن زغبةبن زعور ابن عبدالأشهل الانصاری الأشهلی . صحابی انصاری است و در جنگ احد شهادت یافت .<br /></font></div>'),
(81725, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن محمد جرجانی مکنی به ابوالفتوح اندلسی متوفی در <span class=\"hlight\" dir=\"rtl\">٤٣١</span> هَ . ق . او راست شرح جمل زجاجی . یاقوت گوید: حمیدی درکتاب الاندلسیین نام او برده و گفته است که وی باندلس آمد و در اقطار و ثغور آن بسیاحت پرداخت و نزد ملوک اندلس رفت . او در عربیت امام و بعلم عرب آگاه بود.ابن بشکوال گوید او در محرم سال <span class=\"hlight\" dir=\"rtl\">٤٣١</span> هَ . ق . به امربادیس بن حبوس امیر صنهاجة بتهمت قیام بر ضد او با پسرعمش بیدربن حباسة بقتل رسید. تولد وی در سال <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> بود و در ادب مقامی بلند و بعلم منطق نیز نظر داشت و به بغداد رفت و در آنجا به تعلیم و تدریس پرداخت . کتاب شرح الجمل زجاج را در اندلس املاء کرد و در بغداد از ابن جنی و علی بن عیسی الربعی و عبدالسلام بن الحسین البصری روایت کرد و از علم ادب بسیار روایت داشت .<br /></font></div>'),
(81726, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن محمدبن عبدالملک ملقب به شمس الدین . رجوع به شمس الدین بن ثابت محمدبن عبدالملک شود.<br /></font></div>'),
(81727, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن محمد ارُزی ّ یا رزی ّ مکنی به ابوروح . محدث است .<br /></font></div>'),
(81728, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ )ابن قیس النخعی . از اکابر کوفه در خلافت عثمان و حکومت سعدبن العاص در کوفه .<br /></font></div>'),
(81729, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن قیس بن شماس الانصاری . صحابی است و درک غزوه ٔ بنی قریظه و المریسیع کرده است . و یکی از فصحاء و شعراء عرب است و در زمان خلافت ابوبکر در محاربه ٔ یمامه شهید شد .<br /></font></div>'),
(81730, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن قیس . ابوالغصن . تابعی است .<br /></font></div>'),
(81731, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b>(اِخ ) ابن قمع. او یکی از مترجمین و نقله ٔ کتب از زبانهای دیگر بعربی است .<br /></font></div>'),
(81732, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b>(اِخ ) ابن قَعطل ملقب به جواس . شاعری است از عرب .<br /></font></div>'),
(81733, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ب ِ ]</font></b> (اِخ ) ابن قرةالحرّانی . مکنی به ابی الحسن . یکی از مردم حران . او در ایام معتضدباﷲ عباسی ببغداد رفت و بمطالعه ٔ علوم حساب و هندسه و هیئت و نجوم و منطق مشغول گشت . ولادت او در <span class=\"hlight\" dir=\"rtl\">٢٢١</span> هَ . ق . به حرّان و وفات وی بسال <span class=\"hlight\" dir=\"rtl\">٢٨٨</span> بود. ثابت از مترجمین کتب علمی یونان بزبان عربی است . ابن الندیم گوید: ثابت قرة مروان بن ثابت بن کرایابن ابراهیم کسرایابن مارینوس بن سلامویوس . مولد او بسال و وفات او بسال <span class=\"hlight\" dir=\"rtl\">٢٨٨</span> بسن هفتاد و هفت سالگی بود و او در اول به حرّان شغل صیرفی می ورزید و گفته اند او نزد محمدبن موسی تعلیم یافت و از کتب اوست : کتاب حساب الاهلة. کتاب فی سنةالشمس . کتاب فی استخراج المسائل الهندسیة. کتاب فی الاعداد. کتاب الشکل القطاع . کتاب فی الحجة المنسوبة اًلی سقراط. کتاب اًبطال الحرکة فی فلک البروج .کتاب فی الحصی المتولد فی المثانة. کتاب وجعالمفاصل و النقرس . کتاب رسالة فی السبب الذی من أجله جعلت میاه البحار مالحة. کتاب فی البیاض الذی یظهر فی البدن . کتاب رسالة اًلی دانق . کتاب جوامعه لکتاب جالینوس فی الادویة المفردة. کتاب فی الجدری و الحصبته - انتهی . و نیز او راست : اصلاح اُکر ثاوذوسیوس و ترجمه ٔ اقلیدس و ترجمه ٔ کتاب اصول الهندسه ٔ منالاوس و کتاب تفسیر عربی کلام ارسطا طالیس در هاله و قوس قزح تألیف اثافرودیطوس و نقل کتاب جغرافیای بطلمیوس و ترجمه ٔ تفسیر ببس رومی از کتاب بطلمیوس و اصلاح نقل قدیم مجسطی و اصلاح نقل اسحاق بن حنین از مجسطی و اصلاح نقل قدیم بهتر است . بیهقی در تتمه ٔ صوان الحکمه (متن، ص <span class=\"hlight\" dir=\"rtl\">٦</span>) گوید: ثابت در اجزاء علوم حکمت کامل و متبحر بود و گویند مذهب صابئه داشت و جد محمدبن جابربن سنان صاحب رصد مشهور است و خلیفه المعتضد باﷲ در اعزاز و اکرام او مبالغتی بسیار مینمود.<br />شهرزوری در نزهةالارواح آورده است : او جد محمدبن جابربن سنان صاحب رصد معروف است و در زمان معتضد عباسی مقرب درگاه خلافت بود و در علت تقرب او بخلیفه ٔ عباسی آرند که موفق وقتی پسر خود معتضد را در خانه ٔ اسماعیل بن بلبل حبس کرد و اسماعیل به ثابت امرداد تا نزد او رود و او را به اخبار فلاسفه و قصص و روایات جمیله و مطالب علمیه سرگرم دارد ثابت همه روزه بدیدن معتضد میشد و او را از اخبار و سیر گذشتگان و مسائل فلسفی و حکایات ادبی مستفیض میکرد وقتی که معتضد بخلافت رسید حقوق زمان نکبت را منظور داشته و مال فراوان بوی عطا کرد و او را اجازه ٔ جلوس میداد. و گویند روزی خلیفه در بوستانی مشغول تماشا بود و دست بر روی دست ثابت داشت ناگاه دست بکشید بدانسان که ثابت را وحشت آمد و علت آن پرسید خلیفه گفت من بخطا دست بالای دست تو نهاده بودم و «العلم یعلو و لا یعلی علیه ».<br />و از مصنفات ثابت است کتاب ذخیره در طب که کمتر کتابی بخوبی آن تألیف شده است . ثابت چون بطریقه ٔ صابئین بود ریاست این فرقه در بغداد به او مفوض شده بود ابن ابی اصیبعة در عیون الانباء آورده است : ثابت از صابیان مقیم حران و صیرفی بود و چون محمدبن موسی از روم بازگشت و فصاحت ثابت را بدید او را بخود نزدیک گردانید، و گویند که اونزد محمدبن موسی تعلیم یافته بود و محمد او را بخدمت معتضد برده در جمع منجمان درآورد و این اصل و آغاز رونق کار و ریاست صابیان در بغداد نزد خلفا بود. در زمان ثابت بن قره در صناعت طب و جمیع اجزاء فلسفه کس مانند او نبود. او تصانیف نیکوی مشهور دارد. و جماعتی کثیر از اهل و اعقاب او در مهارت در علوم به او نزدیک و شبیه شدند ترجمه های ثابت نیکو و خوش عبارت است او بزبان سریانی و دیگرالسنه معرفت بسیار داشت ... تولد ثابت در حران روز پنجشنبه <span class=\"hlight\" dir=\"rtl\">٢١</span> صفر بسال <span class=\"hlight\" dir=\"rtl\">٢١١</span> هَ . ق . و وفات او در <span class=\"hlight\" dir=\"rtl\">٢٨٨</span> و عمرش <span class=\"hlight\" dir=\"rtl\">٧٧</span> سال بود. ثابت بن سنان بن ثابت بن قره گفته است که میان ابواحمد یحیی بن علی بن یحیی بن المنجم الندیم و جد من ابوالحسن ثابت بن قره دوستی محکم بود و چون جدّ من در سال <span class=\"hlight\" dir=\"rtl\">٢٨٨</span> وفات یافت ابواحمد در رثاء او این ابیات بگفت :<br />الا کل شی ٔ ما خلااﷲ مائت <br />و من یغترب یرجی و من مات فائت <br />أری من مضی عنا وخیم عندنا<br />کسفرثووا أرضا فسار و بائت <br />نعینا العلوم الفلسفیات کلها<br />خبا نورها اًذ قیل قد مات ثابت <br />و أصبح أهلوها حیاری لفقده <br />و زال به رکن من العلم ثابت <br />و کانوا اذا ضلوا هداهم لنهجها<br />خبیر بفصل الحکم للحق ناکت <br />و لما أتاه الموت لم یغن طبه <br />و لا ناطق مما حواه و صامت <br />و لا أمتعته بالغنی بغتةالردی <br />ألا رب رزق قابل و هو فائت <br />فلو أنه یسطاع للموت مدفع<br />لدافعه عنه حماة مصالت <br />ثقاة من الاخوان یصفون ودّه <br />و لیس لما یقضی به اﷲ لافت <br />أباحسن لا تبعدن وکلنا<br />لهلکک مفجوع له الحزن کابت <br />أآمل أن تجلی عن الحق شبهة<br />و شخصک مقبور و صوتک خافت <br />و قد کان یسرو حسن تبیینک العمی <br />و کل قول حین تنطق ساکت <br />کأنک مسؤولا من البحر غارف <br />و مستبدئاً نطقامن الصخر ناحت <br />فلم یتفقدنی من العلم واحد<br />هراق اناء العلم بعدک کابت <br />و کم من محب قد اُفدت و انه <br />لغیرک ممن رام شاؤک هافت <br />عجبت لارض غیبتک و لم یکن <br />لیثبت فیها مثلک الدهر ثابت <br />تهذبت حتی لم یکن لک مبغض <br />ولا لک لما اغتالک الموت شامت <br />و برزت حتی لم یکن لک دافع<br />عن الفضل الاکاذب القول باهت <br />مضی علم العلم الذی کان مقنعا<br />فلم یبق الامخطی ٔ متهافت .<br />کتب ذیل او راست : کتاب فی سبب کون الجبال مسائله الطبیة. کتاب فی النبض . کتاب فی وجع المفاصل و النقرس، جوامع کتاب باریمینیاس . جوامع کتاب انالوطیقا الاولی . اختصارالمنطق . نوادر محفوظة من طوبیقا. کتاب فی السبب الذی من أجله جعلت میاه البحر مالحة. اختصار کتاب ما بعدالطبیعة.مسائله المشوقة الی العلوم . کتاب فی اغالیط السوفسطائیین . کتاب فی مراتب العلوم . کتاب فی الردعلی من قال ان النفس مزاج . جوامع کتاب الادویة المفردة لجالینوس . جوامع کتاب المرةالسوداء لجالینوس . جوامع کتاب سوءالمزاج المختلف لجالینوس . جوامع کتاب الأمراض الحادة لجالینوس . جوامع کتاب الکثرة لجالینوس . جوامع کتاب تشریح الرحم لجالینوس . جوامع کتاب جالینوس فی المولودین لسبعة أشهر. جوامع ماقاله جالینوس فی کتابه فی تشریف صناعة الطب . کتاب اصناف الأمراض . کتاب تسهیل المجسطی . کتاب المدخل الی المجسطی . کتاب کبیر فی تسهیل المجسطی لم یتم و هو أجود کتبه فی ذلک . کتاب فی الوقفات التی فی السکون الذی بین حرکتی الشریان المتضادتین مقالتان . (این کتاب را بسریانی تصنیف کرده چه در آن اشاره برد بر کندی است و یکی از شاگردان او بنام عیسی بن اسیدالنصرانی آنرا به عربی درآورد و ثابت ترجمه ٔ عربی را اصلاح کرد و جمعی گویند که ناقل این کتاب حبیش بن الحسن الاعسم است ولی این خطاست ...) جوامع کتاب الفصد لجالینوس . جوامع تفسیر جالینوس لکتاب ابقراط فی الأهویة و المیاه و البلدان .کتاب فی وجع المفاصل و النقرس، مقالة. کتاب فی العمل بالکرة. کتاب فی الحصی المتولد فی الکلی و المثانة. کتاب فی البیاض الذی یظهر فی البدن . کتاب فی مُسألة الطبیب للمریض . کتاب فی سوءالمزاج المختلف . کتاب فی تدبیر الأمراض الحادة. رسالة فی الجدری ّ و الحصبة. اختصار کتاب النبض الصغیر لجالینوس . کتاب فی قطع الاسطوانة. کتاب فی الموسیقی، رسالة الی علی بن یحیی المنجم فیما امر باثباته من ابواب علم الموسیقی . رسالة الی بعض اخوانه فی جواب ما سأله عنه من امورالموسیقی . کتاب فی أعمال و مسائل اذا وقع خط مستقیم علی خطین . مقالة أخری له فی ذلک . کتاب فی المثلث القائم الزوایا. کتاب فی الاعداد المتحابة. کتاب فی الشکل القطاع . کتاب فی حرکة الفلک . کناشة المعروف بالذخیرة (که بنام پسر خود سنان بن ثابت کرده است ). جوابه لرسالة احمدبن الطیب الیه .کتاب فی التصرف فی أشکال القیاس . کتاب فی ترکیب الافلاک و خلقتها و عددها و عدد حرکات الجهات لها و الکواکب فیها و مبلغ سیرها و الجهات التی تتحرک الیها. کتاب فی جوامع المسکونة. کتاب الفرسطیون <font color=\"DarkGreen\"><b>[ فرسطون ؟ ]</font></b> .رسالة فی مذهب الصابئین و دیاناتهم . کتاب فی قسمةالارض . کتاب فی الهیئة. کتاب فی الاخلاق . کتاب فی مقدمات اقلیدس . کتاب فی اشکال اقلیدس . کتاب فی اشکال المجسطی . کتاب فی استخراج المسائل الهندسیة. کتاب رؤیةالاهلة بالجنوب . کتاب رؤیةالأهلة من الجداول . رسالة فی سنة الشمس . رسالة فی الحجة المنسوبة الی سقراط. کتاب فی ابطاء الحرکة فی فلک البروج و سرعتها و توسطها بحسب الموضع الذی یکون فیه من الفلک الخارج المرکز. جواب ماسئل عنه عن البقراطیین و کم مبلغ عددهم . مقالةفی عمل شکل مجسم ذی اربع عشرة قاعدة تحبط به کرة معلومة. مقالة فی الصفرةالعارضة للبدن و عدد اصنافها واسبابها و علاجها. مقالة فی وجع المفاصل . مقالة فی صفة کون الجنین . کتاب فی علم ما فی التقویم بالممتحن . کتاب فی الاطلال (شاید اظلال ) کتاب فی وصف القرص . کتاب فی تدبیر الصحة. کتاب فی محنة حساب النجوم . کتاب تفسیر الاربعة. رسالة فی اختیار وقت لسقوط النطفة. جوامع کتاب النبض الکبیر لجالینوس . کتاب الخاصة فی تشریف صناعة الطب و ترتیب اهلها و تعزیز المنقوصین منهم بالنفوس (؟) و الاخباران صناعة الطب أجل ّ الصناعات کتب به الی الوزیر أبی القاسم عبیداﷲ سلیمان . رسالة فی کیف ینبغی أن یسلک الی نیل المطلوب من المعالی الهندسیة. ذکر آثار ظهرت فی الجو و احوال کانت فی الهواء مما رصد بنوموسی و ابوالحسن ثابت بن قرة. اختصار کتاب جالینوس فی قوی الاغذیة ثلاث مقالات . مسائل عیسی بن أسید لثابت بن قرة و أجوبتها لثابت . کتاب البصر و البصیرة فی علم العین و عللها و مداواتها. المدخل الی کتاب اقلیدس و هو فی غایة الجودة. کتاب المدخل الی المنطق . اختصار کتاب حیلةالبرء لجالینوس . شرح السماع الطبیعی (و این کتاب ناتمام ماند). کتاب فی المربع و قطره . کتاب فیما یظهر فی القمر من آثارالکسوف و علاماته . کتاب فی علّة کسوف الشمس و القمر (عمده ٔ آن نوشته شد و ناتمام ماند). کتاب الی ابنه سنان فی الحث علی تعلم الطب و الحکمة. جوابان عن کتابی محمدبن موسی بن شاکر الیه فی أمرالزمان . کتاب فی مساحة الاشکال المسطحة و سائرالبُسُط و الأشکال . کتاب فی أن ّ سبیل الاثقال التی تعلّق علی عمود واحد منفصلة هی سبیلها اذا جُعلت ثقلا واحدا مبثوثا فی جمیع العمود علی تساو. کتاب فی طبائعالکواکب و تأثیراتها. مختصر فی الأصول من علم الاخلاق . کتاب فی آلات الساعات التی تسمّی رخامات . کتاب فی ایضاح الوجه الذی ذکر بطلمیوس أن به استخرج من تقدّمه مسیرات القمر الدوریة و هی المستویة. کتاب فی صفة استواءالوزن و اختلافه و شرایط ذلک . جوامع کتاب نیقوماخس فی الارثماطیقی مقالتان . أشکال له فی الحیل . جوامع المقالة الاولی من الاربع لبطلمیوس . جوابه عن مسائل سأله عنها ابوسهل النوبختی . کتاب فی تطعالمخروط المکافی . کتاب فی مساحةالأجسام المکافیة. کتاب فی مراتب قراءةالعلوم . اختصار کتاب أیام البحران لجالینوس ثلاث مقالات . اختصار کتاب الأسطقسات لجالینوس . کتاب فی أشکال الخطوط التی یمرعلیها ظل المقیاس . مقالة فی الهندسة ألفها لاسمعیل بن بلبل . جوامع کتاب جالینوس فی الادویةالمنقیة. جوامع کتاب الأعضاء الاَّلمة لجالینوس . کتاب فی العروض . کتاب فیما أغفله ثاون فی حساب کسوف الشمس و القمر. مقالة فی حساب خسوف الشمس و القمر. کتاب فی الانواء. ماوجد من کتابه فی النفس .مقالة فی النظر فی امر النفس . کتاب فی الطریق الی اکتساب الفضیلة. کتاب فی النسبة المؤلفة. رسالة فی العدد الوفق . رسالة فی تولد الناربین حجرین . کتاب فی العمل بالممتحن و ترجمته ما استدرکه علی حبش فی الممتحن . کتاب فی مساحة قطع الخطوط. کتاب فی آلة الزمر. کتب عدّة له فی الارصاد عربی و سریانی . کتاب فی تشریح بعض الطیور و أظنه مالک الحزین . کتاب فی أجناس ما تقسم به الأدویة صنف بالسریانی . کتاب فی اجناس ما تقسم الیه الادویة بالسریانی . کتاب فی أجناس ما توزن به الادویة بالسریانی . کتاب فی هجاءالسریانی و اعرابه . مقالة فی تصحیح مسائل الجبر بالبراهین الهندسیة. اصلاحه للمقالة الأولی من کتاب ابلونیوس فی قطع النسب المحدودة (این کتاب دو مقاله است و ثابت مقاله ٔ اولی آنرا اصلاح کرده و بر آن شرح و ایضاح و تفسیر نوشته است و مقاله ٔ ثانیه بی اصلاح مانده و از آن رو نا مفهوم است ). مختصر فی علم النجوم . مختصر فی علم الهندسیة.جوابات عن مسائل سأله عنها المعتضد. کلام فی السیاسة. جواب له عن سبب الخلاف بین زیج بطلمیوس و بین الممتحن . جوابات له عن عدة مسائل سأل عنها سندبن علی . رسالة فی حل رموز کتاب السیاسة لأفلاطن . اختصار القاطیغوریاس . و آنچه از ثابت در مذهب وی بدست است کتب ذیل است : رسالة فی الرسوم و الفروض و السنن . رسالة فی تکفین الموتی و دفنهم . رسالة فی اعتقاد الصابئین . رسالةفی الطهارة و النجاسة. رسالة فی السبب الذی لاجله الغز الناس فی کلامهم . رسالة فیما یصلح من الحیوان للضحایا و مالا یصلح . رسالة فی اوقات العبادات . رسالة فی ترتیب القراءة فی الصلاة و صلوات الابتهال الی اﷲ عزّ و جّل - انتهی . و نیز ابن ابی اصیبعه گوید ؛ ثابت بن قرة کتاب اقلیدس را که حجاج بن مطر برای مأمون نقل کرده بود اصلاح کرده است و همان مؤلف گوید ؛ ابومعشر در کتاب المذاکرات لشاذان گفته است، مترجمان حاذق در اسلام چهارتن اند؛ حنین بن اسحاق و یعقوب بن اسحاق الکندی و ثابت بن قرةالحرانی و عمربن الفرخان الطبری . قفطی در تاریخ الحکماء گوید : ... بخط ابی علی المحسن بن ابراهیم بن هلال الصابی اوراقی دیدم شامل ذکر نسب ابی الحسن ثابت بن قرةبن مروان و مصنفات او بوجه استیفاء و استقصاء و آن این است زیرا در این باب حجت است . و فهرست کتب ثابت را چنانکه سابقاً گفتیم آورده و درآخر آن فهرست گوید: ثابت عده ای مختصرات در نجوم و هندسه دارد که من آنها را بخط او دیدم و ظن من آنست که آنها را برای بنومحمدبن موسی بن شاکر کرده است . و اما آنچه از زبانی بزبان دیگر نقل کرده بسیار است و در دست مردم کناشی نیکو به عربی منسوب بثابت هست که معروف به ذخیره است و رساله ٔ عربی منسوب به او در شرح مذهب صابئین و من از ابوالحسن ثابت بن سنان بن ثابت بن قره از این رساله و کناش پرسیدم گفت آنها از ثابت نیست و من آنها را در کتب و دساتیر او ندیده ام . و نیز قفطی گوید نزد من کتابی سریانی از ثابت بود که به عربی نقل نشده و آن کتاب موسیقی اوست مشتمل بر پانصدورقه بتقریب و او را در موسیقی کتب و رسائل بسیار است همچنین در مسائل هندسی . و ابوالحسن بن سنان از یکی از اجداد خود حکایت کند که ثابت روزی نزد خلیفه میشد و آواز شیونی بشنید پرسید قصابی که در این دکان بود بمرد گفتند آری بسکته درگذشت گفت او نمرده است مرانزد وی برید او را بخانه ٔ قصاب بردنددستور داد تا زنان مزوّره ای کردند و بخدمتکار گفت با عصا بکعب قصاب زن و دوائی بساخت و بدهان وی ریخت پس از لحظه ای او چشم گشود ثابت مزوّره را به او خورانید و ساعتی نزد او نشست . عامه فریاد برداشتند که طبیب مرده را زنده کرده است و خلیفه او را بطلبید و گفت این مسیحیت چیست که از تو می شنوم گفت من همه روزه از دکان این قصاب می گذشتم و می دیدم که جگر را شکافته بر آن نمک می پاشد و می خورد و می دانستم که مبتلا بسکته خواهد شد و مراقب او بودم و برای سکته دوائی مرکب کردم و هر روز آن را با خود میداشتم چون امروز گذشتم و شیون شنیدم دانستم که سکته کرده است پیش او رفتم نبض وی ساقط بود بکعب او زدم تا نبض او بحرکت آمد و دوا به او خورانیدم و مزوّره ای باو دادم شب گرده ای نان با درّاج میخورد و فردا از خانه بیرون میرود - انتهی . همان مؤلف گوید : ابوالحسن حسین بن اسحاق بن ابراهیم بن یزیدالکاتب رای ثابت را در وجود سکون بین دو حرکت متساوی رد کرده است . حکیم ناصر در رساله ٔ جواب نود و یک فقره اسئله آورده است : ثابت بن قرة الحرانی که مر کتب فلسفی را ترجمه او کرده است از زبان و خط یونانی بزبان و خط تازی بر افلاک و کواکب که احیا و نطقااند برهان کرده است و گفته است اگر مردم را حیات و سخن بدانست کی جسد او شریفتر جسد است و اندر شریفتر جسدی کان جسد مردم است شریفتر نفس فرود آمده است و آن نفس زنده و سخنگوی است، و این مقدمه ٔ صادقه است، آنگاه گفته است و افلاک و انجم را اجسادایشان بغایت شرف و لطافت است، و بنهایت پاکیزگی است، و این مقدمه دیگر است صادقه، نتیجه از این دو مقدمه اینکه مر این افلاک و انجم را نفس ناطقه است و ایشان زندگان و سخنگویانند و این برهانی است که این فیلسوف کرده است برآنک فرشتگان افلاک و کواکب اند و زنده وسخن گویند و فلاسفه هرگز مر این را نستایند اما دیو را مقرند... و نیز حکیم ناصرگوید :<br />ازحق ّ تو به نگفته برهانی <br />بر باطل خویش ثابت قره .<br />و در جای دیگر گوید:<br />پیش داعی من امروز چو افسانه ست <br />حکمت ثابت بن قرّه ٔ حرّانی .<br />صاحب روضات الجنات گوید: ... از جمله ٔ مقالات او علی الظاهر مسئله ای بر بیان معنی ایام العالم و طریق عود آن است و اینکه آیا این امر ممکن است یانه و از غرایب آنچه حرّانی (بنقل امام راضی از او در کتاب السرالمکتوم ) ذکر کرده است این است که یکی ازحکماء سخن از سرمه ای (کحل ) کند که چشم را چنان قوت بخشد که هرچه هر جا باشد تواند دید چنانکه گویی در پیش اوست یکی از اهل بابل آن سرمه را بچشم کرد سپس حکایت کرد که همه ٔ ثوابت و سیارات را در موضعشان می بیند و دید چشمش در اجسام متکاثف نفوذ میکند و هرچه ماوراء آنهاست تشخیص میدهد من و قسطابن لوقا او را امتحان کردیم و داخل خانه ای شدیم چیزی نوشتیم و او آنرا میخواند و اول و آخر هر سطر را میگفت مثل اینکه نزد ما بود ما کاغذ میگرفتیم و روی آن می نوشتیم و میان ما دیوار ضخیم بود او نیز کاغذ میگرفت و هر چه ما می نوشتیم می نوشت مثل اینکه به آنچه ما می نویسیم نظر میکند...<br />او را پسری بود موسوم به ابراهیم که در فضل بمقام پدر رسید و در طب از حذاق طبیبان و مقدمان عصر خویش بود - انتهی .<br />کتب ذیل نیز از ثابت است : کتاب در قطوع استوانه و بسط آن . کتاب در تلاقی دو خط مستقیم در صورتیکه بر سطحی اخراج شوند و زاویه ٔ آن دو کمتر از قائمه باشد. کتاب در آلات تقدیر ازمنه (شاید مراد کتاب فی آلات الساعات التی تسمی رخامات است ؟ ) اصلاح کتاب الکرة و الأسطوانة تألیف ارشمیدس و مترجم اصلی پاره ای مطالب کتاب را نفهمیده و حذف کرده بوده است . نقل کتاب المأخوذات فی الاصول الهندسة لارشمیدس اختراع شکلی در مقاله ٔ اولی اصول هندسی اقلیدس . اصلاح ترجمه ٔ کتاب القسمة اقلیدس . نقل کتاب مایعتقده رایألجالینوس . ترجمه ٔ کتاب اصول الهندسه ٔ منالاؤس . ترجمه ٔ کتاب تفسیر کلام ارسطاطالیس در هاله و قوس قزح تألیف اثافرودیطوس . ترجمه ٔ سه مقاله ٔ آخر کتاب المخروطات ابلینوس حکیم ریاضی و کتاب المفروضات (<span class=\"hlight\" dir=\"rtl\">٣٦</span> شکل ). شرح غریب بر کنزالاسرار هرمس الهرامسه . دکتر لکلرک در تاریخ طب عرب گوید که ثابت بن قره و قسطابن لوقا ذوق عرب را در ترویج علوم ریاضی و نجومی با ترجمه ٔ مؤلفات مهمترین علماء یونان تأیید کرده اند... ثابت به ترجمه و تألیف کتب و هم بعمل طبابت پرداخت وی به زبان یونانی و سریانی و عربی بخوبی آشنا بود و اگر به قول مؤلف نسخه ٔ خطی پاریس اعتماد کنیم فارسی نیز میدانسته است . ترجمه های اواغلب مربوط به علوم ریاضی و نجوم بود و کمتر به طب .ثابت به ترجمه اکتفا نکرد بلکه در علومی که ترجمه کرد به تألیف نیز پرداخت بعلاوه عمل و نظر را در نجوم و طب توأم ساخت از حیث طبابت در درجه ٔ دوم است ولی از نظر آنکه به نشر آن علم همت گماشته اعتبار و شأنی دارد. او بر کتب ابقراط شروحی می نوشت و کتاب میاه و اهویه و امکنه ٔ او را مختصر کرد و هم بسیاری از کتب جالینوس را مختصر ساخت . آراء فلسفی او موجب اخراج او از فرقه ٔ صابیان شد. وقتی مؤلفات او را ببینیم و تألیفات کندی را نیز در مد نظر آریم سرعت نشر علم یونان در میان عرب بسی شگفت بنظر خواهد آمد. در کتابخانه ٔ ملی پاریس بشماره ٔ <span class=\"hlight\" dir=\"rtl\">١٠٣٨</span> (کتب قدیم ) نسخه ٔ خطی است که مؤلف آن ثابت را مترجم کتابی فارسی در بیطاری شناخته است . سدیو گوید«این ریاضیدان ماهر ظاهراً اول کس است که فن جبر رادر هندسه بکار برده است » . چندین کتاب ثابت به ما رسیده و بعض آنها به لاتینی ترجمه شده است . آنچه بر قدر ثابت می افزاید این است که او علاقه ٔ به علم را در خاندان خود داخل کرد و آن عنایت و دلبستگی چندین نسل در آن خاندان باقی ماند...<br />خلاصه ثابت یکی از بزرگان علماء قرن نهم است در طراز حنین بن اسحاق و قسطا بن لوقا و کندی .هر چند که او در معرفت طب بمقام حنین نمیرسد ولی درعلوم ریاضی بر او راجح است و از این حیث به کندی به قسطابن لوقا نزدیکتر است . هیچکس به اندازه ٔ او به تحقیق علوم ریاضی و نجوم در نزد عرب نپرداخت - انتهی .(نقل به اختصار). مآخذ که از دائرة المعارف اسلام و جز آن اقتباس شده : کتاب الفهرست ابن الندیم . تاریخ الحکماء ابن القفطی . وفیات الاعیان ابن خلکان . عیون الانباءابن ابی اصیبعة. تتمه ٔ صوان الحکمه ٔ بیهقی . درةالاخبار ترجمه ٔ تتمه ٔ صوان الحکمه . نزهةالارواح شهرزوری . کنزالحکمة ترجمه ٔ نزهةالارواح . طبقات الأمم صاعد اندلسی .نامه ٔ دانشوران . مطرح الانظار فی تراجم اطباء الاعصار و فلاسفة الامصار تألیف فیلسوف الدوله . مرآت الجنان یافعی . شذرات الذهب ابن العماد. تاریخ ادبیات عرب بروکلمان و ذیل آن مذهب صابئه و صابئان تألیف کولسن مقاله ٔ وپکه در روزنامه ٔ آسیایی پاریس سال <span class=\"hlight\" dir=\"rtl\">١٨٥٢</span> م . تاریخ اطباء لکلرک . مقاله ٔ دائرة المعارف اسلام بقلم روسکا . مقدمه ای بر تاریخ علوم تألیف سارتون . تحقیقات و تتبعات یونانی و عربی تألیف اسکوی . علم عرب تألیف میلی . تاریخ ادبیات عرب نیکلسن . کتاب الملل و النحل شهرستانی . تاریخ ریاضیین و منجمین عرب تألیف سوتر . تاریخ نظریه ٔ اعداد تألیف دیکسن . مبادی علم استاتیک تألیف دوهم . سیستم جهان تألیف دوهم .<br /></font></div>'),
(81734, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) اسلم تیانی قرشی . تابعی است .<br /></font></div>'),
(81735, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) محمدافضل (میر...). از شعرای هندوستان مولد او شهر دهلی و اجداد او از مردم بدخشان بوده اند و در سال <span class=\"hlight\" dir=\"rtl\">١١٥١</span> هَ . ق . وفات کرده است . دیوان او شامل پنج هزار بیت است .<br /></font></div>'),
(81736, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) اللغوی . رجوع به ثابت بن ابی ثابت عبدالعزیز اللغوی شود.<br /></font></div>'),
(81737, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) قمی . شاعری است ایرانی . (قاموس الاعلام ).<br /></font></div>'),
(81738, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ )قطنة ابوالعلأبن کعب عَتکی است . لاّنه اصیب عینه یوم سمرقند فکان یخشوها بِقُطنة و الاسماء المعارف الی ألقابها. و یکون الالقاب معارف . و یتعرّف بها الاسماء.کماقیل : قیس قفَّة. و زَید بطّة. و سعید کُرنز.<br /></font></div>'),
(81739, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) علاءالدین . از مشاهیر شعرای عثمانی مولد او شهر بوسنه . وی به اسلامبول شد و بکسب معلومات وقت پرداخت و در سال <span class=\"hlight\" dir=\"rtl\">١١٢</span> هَ . ق . وفات کرد و بیشتر در اشعار خویش امثال بکار میبرد و نیز پاره ای از شعرهای خود او مثل شده است .<br /></font></div>'),
(81740, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) الضریر. از مشایخ شیعه و راوی فقه از ائمه است .<br /></font></div>'),
(81741, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) سرقسطی . او راست : کتاب الدلائل .<br /></font></div>'),
(81742, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) الخیار. از قدماء مشایخ است و با جنید و رویم صحبت داشته وطریقت از ایشان گرفته و پیوسته حکایت ایشان گفتی .<br /></font></div>'),
(81743, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِ خ ) بنانی منسوب به قبیله ٔ بنانه . او در بنانه محله ای ببصره سکنی داشت .<br /></font></div>'),
(81744, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن فقیر. از شرفاء و امراء مدینه که به جمامره معروفند .<br /></font></div>'),
(81745, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابوحمزه ٔثمالی . تابعی است . و رجوع به ابوحمزه ٔ ثمالی شود.<br /></font></div>'),
(81746, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن یزید الأودی مکنی به ابوالسری . تابعی است .<br /></font></div>'),
(81747, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن یزید الانصاری . صحابی است . ابن حجر گوید که این ثابت بن یزید همان ابن ودیعة است .<br /></font></div>'),
(81748, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن یزید الأحول مکنی به ابوزید. تابعی است .<br /></font></div>'),
(81749, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن یحیی بن یسارالرازی مکنی به ابی عباد. هندوشاه بن سنجر در تجارب السلف آرد که ابوعباد کاتبی جلد بود و حساب بغایت نیکو می دانست الا آنکه سریعالحرکات و ابله وتندخوی بود وقتی که پیش مأمون آمدی مأمون گفتی :<br />و کأنّه من دیر هزقل مفلت <br />حرب یجرّ سلاسل الاقیاد.<br />مأمون را گفتند که دعبل تو را هجو گفته است مأمون گفت آن کس که ابوعبادرا با وجود جنون و حدّت و احمقی هجو گوید اگر مرا با وجود حلم و سکون و شهرت من بمحبت عفو هجو گوید عجب نباشد. و ابوعباد چنان تیز و سریعالغضب بود که اگر از یکی از خدمتکاران برنجیدی دوات بر او زدی و دشنامهای فاحش دادی . گویند غالبی شاعر قصیده ای پیش ابوعباد برد بر این سیاقت :<br />لما أنخنا بالوزیر رکابنا<br />متعرّضین لبرّه أغنانا<br />ثبتت رحی ملک الامام بثابت <br />و أفاض فینا لعدل و الاحسانا<br />یقری الوفود طلاقة و سماحة<br />والناکثین مهنداً و سنانا<br />من لم یزل للناس غیثاً ممرعا<br />متخرقاً فی جوده معوانا.<br />غالبی چون به این لفظ رسید که فی جوده سخن بر او ببست و معوانا را فراموش کرد و فی جوده را مکرر می کرد.ابوعباد ملول شد و سوداش غالب گشت و گفت ای شیخ بگوقرنانا یا صفعانا و ما را خلاص ده و همه ٔ اهل مجلس بخندیدند و ابوعباد نیز بخندید و غالبی را معوانا یادآمد و بعطائی نیکو از ابوعباد فایز شد. گویند ابوعباد روزی پیش مأمون نشسته بود و چیزی می نوشت قدری موی در شق قلم آمد ابوعباد با دندان از قلم جدا کرد و بنوشتن مشغول شد هم بقیتی مانده بود و کتابت نمیتوانست کرد بانگشت موی از سر قلم بیرون کشید رقعه بانگشت او آلوده شد و از موی هنوز در شق قلم چیزی مانده بود قلم را بشکست . آنگاه روی بقلم کرد و گفت لعنت بر تو باد و بر آن کس که ترا آورده و بر آن کس که ترا تراشیده و بر آن کس که ملک اویی . مأمون بخندید و باز بیت دعبل برخواند:<br />و کأنه من دیر هرقل مفلت <br />حرب یجرّ سلاسل الأقیاد .<br />در جامعالتواریخ مسطور است که در بعض تواریخ آمده است که احمدبن یوسف و ابوعباد ثابت بن یحیی الرازی و ابوعبداﷲ محمد در سلک وزرای مأمون انتظام داشتند .<br /></font></div>'),
(81750, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن یحیی الرازی مکنی به ابی عباد. رجوع به ابی عباد شود.<br /></font></div>'),
(81751, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> ابن هزال بن عمروبن قربوس الأنصاری . ابن حجر گوید صحابی است و درک غزوه ٔ بدر کرده و در جنگ یمامه بشهادت رسیده است .<br /></font></div>'),
(81752, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن هرمز الحداد الکوفی مکنی به ابوالمقدام . تابعی و محدث است و سفیان و اعمش از او روایت کنند.<br /></font></div>'),
(81753, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) الناقل . یکی از مترجمین و نقله ٔ علوم بعربی . او در نقل متوسط و مقل ّ است . از ترجمه های او ترجمه ٔ کتاب الکیموسین تصنیف جالینوس است .<br /></font></div>'),
(81754, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن دینار. ابوصفیة. تابعی است .<br /></font></div>'),
(81755, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن الدحداح . صحابی است و او را ثابت بن الدحداحة نیز گفته اند. مکنی به ابی الدحداح و ابی الدحداحة. ابن حجر در اصابه از طبرانی روایت کند که پیغمبر (صلعم ) درجنازه ٔ او حاضر بود و از واقدی نقل می کند که ثابت بن الدحداحة روز جنگ احد گفت ای مسلمانان اگر محمد کشته شده است خداوند حی لایموت است پس برای دین خود بجنگید و خود با کسانی که با او بودند بر کفار حمله کردخالد با نیزه به او ضربتی زد و او بشهادت رسید واقدی گوید: که بعضی گویند که ثابت مجروح شد و بهبود یافت و مرگش پس از آن بود .<br /></font></div>'),
(81756, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن خالدبن النعمان یا ثابت بن خالدبن عمروبن النعمان بن خنسأبن <font color=\"DarkGreen\"><b>[ کذا ]</font></b> عسیرةبن عبدبن عوف بن غنم بن مالک بن النجار الانصاری . در کتاب الاصابة آمده است که ابن اسحاق و موسی بن عقبة و ابن الکلبی اورا از جمله ٔ شهدای بدر و قداح از شهدای بئر معونة دانسته اند و ابن لهیعة از ابوالاسود و او از عروة روایت کرده است که ثابت از شهدای یمامة است . واقدی نیز روایت اخیر را نقل کرده ولی جد او را بجای نعمان، عمرو گفته است و او را دو دختر بود بنام دنیة و رقیة.<br /></font></div>'),
(81757, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن الحسین بن شراعة التمیمی مکنی به ابی طالب . یاقوت در معجم الادباء از شیرویه روایت کند که او از ابن سلمة و ابن عیسی و ابوالفضل محمدبن عبداﷲ الرشیدی و منصور بن رامش و ریحانی و جز آنان روایت کرده است و من از او روایت شنیدم و او مردی راستگو بود و در عشر آخر صفر سال <span class=\"hlight\" dir=\"rtl\">٤٦٩</span> هَ . ق . وفات کرد.<br /></font></div>'),
(81758, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن الحارث الانصاری . صاحب الاصابة گوید او را ابن حارثه نیز نامند و درست نیست .<br /></font></div>'),
(81759, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن الجذع . ابن حجر در کتاب الاصابة گوید: اسم او ثعلبةبن زیدبن الحارث بن حرام بن غنم بن کعب بن سلمة الانصاری السلمی است موسی بن عقبة و ابن اسحاق او را از شهداء طائف گفته اند و ابن اسحاق و موسی بن عقبه وی را از اهل عقبة ذکر کرده اند و در روایت طبرانی که نقل از موسی بن عقبه است نام او ثابت بن اجدع آمده و این تصحیف است - انتهی . در امتاع الاسماع الجذع، و در کتاب الاصابة الجدع دیده میشود و نیز در امتاع الاسماع ثعلبة نام پدر ثابت آمده است نه نام خود او.<br /></font></div>'),
(81760, 'ثابت', '<span class=\"hlight\">ثابت .</span><font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن جابر. رجوع به تأبّط شراً شود.<br /></font></div>'),
(81761, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن ثاوان نجم الدین ابوالبقاء التفلیسی الصوفی . صاحب فوات الوفیات قطعه ٔذیل را ازو آورده است :<br />اغتنم یومک هذا<br /> <font color=\"Red\">انما یومک ضیف </font><br />وانتهب فرصة عمر<br /> <font color=\"Red\">حاضر فالوقت سیف </font><br />لا تضیع هذه الانَ<br /> <font color=\"Red\">فاس فالتضییع حیف </font><br />عد عن سوف أو السا<br /><font color=\"Red\">عة أو أین و کیف .</font><br /></font></div>'),
(81762, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن دینار. رجوع به ابی حمزه ٔ ثمالی شود.<br /></font></div>'),
(81763, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن اقرم بن ثعلبةبن عدی بن العجلان البلوی حلیف الانصار. ابن حجر در کتاب الاصابة گوید: موسی بن عقبة او را صحابی بدری شمرده است . ارباب مغازی متفق اند که ثابت بن اقرم در عهد ابوبکر بدست طلیحةبن خویلد الاسدی کشته شد و پس از آنکه طلیحه اسلام آورد عمر به او گفت من چگونه ترا دوست گیرم و حال آنکه تو عکاشةبن محصن و ثابت بن اقرم را که از صلحاء بودند کشته ای طلیحه گفت خداوند آنان را بدست من خلعت شهادت پوشانید و هنوز مرگ من بدست آنان مقدر نبود.<br /></font></div>'),
(81764, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن اسلم بن عبدالوهاب الحلبی النحوی مکنی به ابی الحسین خازن . صاحب طبقات از ذهبی آورده است که ثابت یکی از کبار نحویین و شیعی و متولی خزانه ٔ سیف الدوله بحلب بود و او راست کتابی در تعلیل قرائت عاصم . و اسماعیلیه او را به تهمت تصنیف کتابی در تفضیح اسماعیلیه و ابتداء دعوت آنان دستگیر کرده بمصر بردند و او را بدانجا در حدود <span class=\"hlight\" dir=\"rtl\">٤٢٠</span> هَ . ق . بیاویختند. رجوع به روضات ص <span class=\"hlight\" dir=\"rtl\">١٤٢</span> شود.<br /></font></div>'),
(81765, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن اسلم البنانی مکنی به ابومحمد. تابعی و صاحب حسن بصری و انس بن مالک است . صاحب صفةالصفوة از بکربن عبداﷲ روایت کند که ثابت البنانی پارساترین مردم زمان خود بود و نیز از سهل بن اسلم آورده است که اسلم هر شب سیصد رکعت نماز میکرد همان مؤلف از جعفربن سلیمان آورده است که ثابت از ضعف چشم نزد طبیب شکایت کرد طبیب به او گفت اگر خصلتی را رعایت کنی چشمت را بهبود باشد گفت آن خصلت کدام است طبیب گفت آنکه گریه نکنی ثابت گفت فایده ٔ چشمی که نگرید چیست . همان مؤلف از مبارک بن فضاله آورده است که ثابت شب زنده دار بود و روزها را روزه میگرفت و میگفت چیزی در قلب خود لذت بخش تر از شب زنده داری نیافتم . ثابت بسال <span class=\"hlight\" dir=\"rtl\">١٢٣</span> هَ . ق . در ولایت خالدبن عبداﷲ بر عراق وفات کرد .<br /></font></div>'),
(81766, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن اثلة الانصاری الاوسی . صحابی است . او در غزوه ٔ خیبر درجه ٔ شهادت یافت .<br /></font></div>'),
(81767, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن ابی صفیة، ابوحمزه . صحابی است .<br /></font></div>'),
(81768, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن ابی ثابت علی بن عبداﷲ ابومحمد کوفی . زبیدی گوید: وی بزرگترین اصحاب ابی عبیدالقاسم بن سلام بوده است بعضی نام ابی ثابت را سعید گفته اند. ابن الندیم گوید به نقل از سکری که نام ابی ثابت محمد است و لغوی است و درک صحبت فصحای اعراب کرده و از آنان لغت فراگرفته است و خود ازکبار مذهب کوفیین است و باز محمدبن اسحاق گوید او راست : کتاب خلق الانسان . کتاب الفرق . کتاب الزجر و الدعا.کتاب خلق الفرس . کتاب الوحوش . کتاب مختصرالعربیة. کتاب العروض . و رجوع به ثابت بن عبدالعزیز لغوی ... شود.<br /></font></div>'),
(81769, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ )ابن ابراهیم بن زهرون . طبیب حرانی مکنی به ابی الحسن .مؤلف مطرح الأنظار گوید کنیت او ابوالحسن و از اطبای مشهور مائه ٔ چهارم هجری، و بوفور علم و حدس صائب معروف بود. عبیداﷲبن جبرئیل گوید در ایامی که عضدالدوله ٔ دیلمی وارد بغداد شد ابوالحسن ثابت بن ابراهیم در بغداد مقیم و سرآمد اطبای آن دیار بود. روز ورود عضدالدوله از اطبای بغداد اول کس که نزد او رفت ثابت بن ابراهیم طبیب مزبور و سنان طبیب بودند عضدالدوله از معرف حال آن دو نفر پرسش فرمود، معرف عرض کرد که دو طبیب معتبر شهر بغداد می باشند عضدالدوله گفت بحمداﷲ ما در کمال صحت و عافیتیم و محتاج آنها نیستیم و التفاتی بآن دو طبیب نکرد وهر دو با کمال خجلت به دهلیزخانه مراجعت کردند. سنان طبیب که اصغر سناً از ثابت بن ابراهیم بود بثابت گفت که بما بسی گران است که با این کثرت علم و وفور دانش از نزد این مرد با این خفت بیرون آییم اگر اجازت دهی بمجلس برگشته و جوابی که سزاوار است بر وی عرضه دارم ثابت قبول کرد و هر دو پیش عضدالدوله معاودت کردند. سنان عرض کرد أطال اﷲ بقاءالملک همانا که موضوع علم ما حفظ صحت است و ملک حاجتمندترین تمام مردم است بدان موضوع . عضدالدوله را این تقریر خوش آمد و فرمود صدقت یا حکیم، سپس آن دو طبیب را در جرگه ٔ اطبای حضور خویش منسلک فرمود. گویند یک سال پیش از آنکه عضدالدوله مبتلا بمرض اختلال دماغ شود ثابت بن ابراهیم خبر داده بود. در باب حدس صائب و تقدمةالمعرفه ٔ آن حکیم در کتب تواریخ حکایات غریبه ذکر کرده اند چون اغلب آنها خالی از اغراق نبود لذا بذکر آنها نپرداخت . وفات ثابت بن ابراهیم بنا بنوشته ٔ مورخ خزرجی در یازدهم ذی القعده ٔ سنه ٔ خمس و ستین و ثلثمائة (<span class=\"hlight\" dir=\"rtl\">٣٦٥</span> هَ . ق .) در شهر بغداد اتفاق افتاد و تولد او بنا بنوشته ٔ مورخ مزبور در شهر ذی القعدة ثلاث و ثمانین و مأتین (<span class=\"hlight\" dir=\"rtl\">٢٨٣</span> هَ . ق .) در شهر رقه بوده، ولی صاحب کتاب مختصرالدول وفات ثابت را در سال <span class=\"hlight\" dir=\"rtl\">٣٦٩</span> ضبط کرده . از تألیفات حکیم مزبور دو کتاب مابین اطبا معروف است یکی کتاب اصلاح مقالات یوحنابن سرابیون و دیگری اجوبه ٔ مسائلی است که بعضی از اطبای عصر از وی سؤال کرده اند - انتهی . قفطی در تاریخ الحکما گوید که ابوالحسن ثابت بن ابراهیم روز جمعه یازده شب مانده از شوال سال <span class=\"hlight\" dir=\"rtl\">٣٦٩</span> در بغداد وفات کرد و مولدش در رقة شب پنجشنبه دو شب مانده از ذی القعده ٔ سال دویست و هشتاد و سه بود. دکتر لکلرک در تاریخ طب عرب آورده است : پدرش ابراهیم نیز طبیب بود و در حرّان میزیست . ابوالحسن ثابت پزشکی مجرب و حاذق بود ابن بطلان درکتاب خود بدانجا که از معالجه ٔ جدید بعض امراض مانند فالج که قبلاً بوسیله ٔ ادویه ٔ محرکه مداوا میشد بحث کرده ذکر او آورده است . ابوالفرج بن العبری از حدس وحذاقت ثابت اموری حکایت کرده که بیشتر معرف بی باکی اوست تا غریزه ٔ طبی وی و او برادری داشت بنام هلال بن ابراهیم که در بغداد طبابت میکرد و شهرتی داشت و در خدمت امیرامراء توزون میزیست . رجوع به ابی الحسن الحرانی و تاریخ الحکماء قفطی ص <span class=\"hlight\" dir=\"rtl\">١٠١</span>، <span class=\"hlight\" dir=\"rtl\">١١١</span>، <span class=\"hlight\" dir=\"rtl\">١١٢</span>، <span class=\"hlight\" dir=\"rtl\">١١٥</span> شود.<br /></font></div>'),
(81770, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) نعت فاعلی از ثبات و ثبوت . پابرجا. برقرار. مُزلَئم . سجّین . محکم . استوار. (دهار). پایدار. پاینده .مقرر. ایستاده . ایستنده . برقرار. بارد <span class=\"hlight\">:</span> <br />فتح است کز او ملک بود ثابت و دین راست .<br />زین بیش چه خواهید که باشد هنر فتح .<br /> <font color=\"Red\">مسعود سعد (دیوان ص <span class=\"hlight\" dir=\"rtl\">٧٩</span>)</font><br />بقدمی راسخ و عزمی ثابت بر جای ایستاده . (ترجمه ٔ تاریخ یمینی ).<br />مشکل تر آنکه گر بمثل دور روزگار<br />روزی دو مهلتی دهدت گوئی آن بقاست <br />ملک خداست ثابت و باقی و بعد از آن <br />آثار خیر و نام نکو و دگر هباست .<br /> <font color=\"Red\">(از تاریخ گزیده ).</font><br /> <BR><font color=\"Blue\">◄</font> برجای مانده . راسب . <BR><font color=\"Blue\">◄</font> محقق . مُدّلل <span class=\"hlight\">:</span> <br />و ثابت ساز نزدعام و خاص که امیرالمؤمنین فروگذاشتی نمیکند مصلحت خلافت را. (تاریخ بیهقی ).<br />گرچه دراز است مر این را زمان <br />ثابت کرده ست خرد منتهاش .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> مداوم . مواظب . <BR><font color=\"Blue\">◄</font> قائم و برجای .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مردی ثابت </span> ؛ مردی قائم و برجای .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ودیعه ٔ ثابت </span> ؛ اصطلاح بانکی است .<br /> <BR><font color=\"Blue\">◄</font> مثبت، مقابل منفی . <BR><font color=\"Blue\">◄</font> که نشود. که نرود: رنگی ثابت ؛ رنگی که با شستن و تافتن آفتاب متغیر و محو نگردد. <BR><font color=\"Blue\">◄</font> صاحب کشاف اصطلاحات الفنون گوید «هو الموجود الذّی لایزال بتشکیک المشکک و عند اهل الرمل یجی ٔ فی لفظ الشکل و جمعه الثوابت و هی أی الثوابت تطلق علی ماسوی السیّارات من الکواکب و تسمّی بالبیابانیات أیضاً علی ما فی شرح التذکرة و یجی ٔ فی لفظ الکواکب ». مقابل سیّار. کوکب بیابانی یا یبانی . ج، ثوابت .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثابت ارکان </span> ؛ که پایه های محکم دارد <span class=\"hlight\">:</span> <br />عدلش از عزم و حزم برجایست (؟)<br />ملکش از چرخ ثابت ارکان باد.<br /> <font color=\"Red\">؟</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثابت الأصل </span> ؛ نباتاتی که چند سال دوام کنند یا آنکه چند بار در دوره ٔ حیات خود بار دهند .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثابت شدن </span> ؛ مبرهن و مدلل شدن . درست شدن . ثبوت . تمّهد. اَرز. أرَوز. اقرار. استقرار. بَرد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثابت قدم </span> ؛ که از جای نجنبد با فشار یا زوری یا مانند آن . پادار. پای برجا. متین . استوار <span class=\"hlight\">:</span> واقسام سعادات بدان نزدیکتر که در کارها ثابت قدم باشد. (کلیله و دمنه ).<br />طریقت شناسان ثابت قدم <br />بخلوت نشستند چندی بهم .<br /> <font color=\"Red\">(بوستان ).</font><br />دلا در عاشقی ثابت قدم باش <br />که در این ره نباشد کار بی اجر.<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثابت کردن </span> ؛ اثبات . درست کردن . محق کردن . تصدیق کردن . مدلل کردن . محقق شمردن در دعوی <span class=\"hlight\">:</span> <br />قاضی که به رشوت بخورد پنج خیار<br />ثابت کند از بهر تو صد خربزه زار.<br /> <font color=\"Red\">سعدی .</font><br />زَمَعان ؛ ثابت بودن . زاهل ؛ ثابت دل . ثبت ؛ ثابت زبان . (منتهی الارب ). ثباتة؛ ثابت رأی شدن . اِزماع ؛ ثابت عزم بودن .<br /></font></div>'),
(81771, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن رفیع یا رویفع انصاری . صحابی انصاری است . وی ساکن بصره بود و سپس به مصر شد و حسن بصری از او روایت دارد.<br /></font></div>'),
(81772, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ]</font></b> (اِخ ) ابن العوام . صحابی و از شهدای یمامه است .<br /></font></div>'),
(81773, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن عمروبن حبیب مولی علی بن رابطه از شاگردان و روات ابوعبید قاسم بن سلام . او همه ٔ کتب ابوعبید را روایت کرده است .<br /></font></div>'),
(81774, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن علی کوفی . او راست : کتاب خلق الانسان وخلق الفرس . و رجوع به ثابت بن عبدالعزیزاللغوی شود.<br /></font></div>'),
(81775, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن عتیک بن النعمان الانصاری . صحابی است و در جنگ جسر ابوعبید در سال <span class=\"hlight\" dir=\"rtl\">١٥</span> هَ . ق . کشته شد .<br /></font></div>'),
(81776, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن عبیدالانصاری . صحابی است . او غزوه ٔ بدر را دریافت و در جنگ صفین بقتل رسید .<br /></font></div>'),
(81777, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن عبداﷲبن زبیر. جد عبداﷲبن مصعب است .<br /></font></div>'),
(81778, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن ظریف المرادی . صحابی است و شاهد فتح مصر بود. او ایام جاهلیت را نیز درک کرد و از ثقات تابعین است . (ابن حجر).<br /></font></div>'),
(81779, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن عبدالعزیزاللغوی .یاقوت گوید او صاحب کتاب خلق الانسان است و یکی از علمای لغت است و از ابی عبید قاسم بن سلام و ابی الحسن علی بن المغیرةبن الاثرم و اللحیانی و ابی نصر احمدبن حاتم و سلمةبن عاصم التمیمی و ابی عبداﷲ محمدبن زیاد و دیگران روایت کند و از او ابوالفوارس داودبن محمدبن صالح المروزی النحوی معروف به صاحب ابن سکیت و پسر وی عبدالعزیزبن ثابت روایت کنند و نام ابی ثابت پدر او عبدالعزیز است و او از اهل عراق مردی جلیل القدر وموثوق به و در لغت مقبول القول بود و به وراق ابی عبید شهرت داشت - انتهی . و صاحب روضات الجنات گوید: و ظاهر این است که این مرد بعینه همان ثابت بن ابی ثابت علی بن عبداﷲ الکوفی الصفدی است یعنی همان کس که باز یاقوت نقل کرده است و گوید که وی از کبار کوفیین است مثل اصحاب ابی عبیدالسلم نحوی لغوی . و فصحاء عرب را دیده است و کتبی چون مختصر فی العربیة و کتاب خلق الانسان و کتاب الفرق و کتاب خلق الفرس و کتاب الدعاء و کتاب الوحوش و کتاب العروض دارد چنانکه صاحب طبقات النحاة نیز همین معنی را تقویت کند و به قولی اسم پدر او سعید و بعضی محمد گفته اند و بنابراین او غیر از ابی الفتح ثابت بن محمدالجرجانی الاندلسی النحوی است که اونیز در عربیت امام و قیم بعلم منطق بود و جمل زجاجی را شرح کرده است و از ابن جنی و از ابن عیسی الربعی روایت دارد و بادیس عمید صنهاجه او را بتهمت قیام برامیر با پسر عم او در محرم سال <span class=\"hlight\" dir=\"rtl\">٤٣١</span> هَ . ق . بکشت .<br /></font></div>'),
(81780, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن ضحاک انصاری اشهلی . صحابی است و او در <span class=\"hlight\" dir=\"rtl\">٤٥</span> هَ . ق . درگذشت .<br /></font></div>'),
(81781, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن شرح الدوسی . مکنی به ابی سلمة، تابعی است .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(81782, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن سنان بن ثابت بن قره ٔ صابی حرانی مکنی به ابی الحسن، طبیب و مورخ و ادیب معروف . وفات او بیازده شب از ذی القعده ٔ سال <span class=\"hlight\" dir=\"rtl\">٣٦٥</span> هَ . ق . گذشته بوده است و او را تاریخی است از اول خلافت المقتدر تا سال <span class=\"hlight\" dir=\"rtl\">٣٦٠</span> و هلال ابن محسن را براین کتاب تتمه ای است . و نیز او را کتابی است در اخبار شام و مصر در یک مجلد. و او با علی بن الراهبة و بختیشوع در خدمت طبابت دربار المقتفی خلیفه بودند. صاحب کتاب مختصرالدول گوید ثابت در طب بارع و به اصول آن عالم و برگشودن مشکلات فن قادر بود و ریاست اداره ٔبیمارستان بغداد داشت . مؤلف عیون الانباء به نقل از کتاب تاریخ ثابت گوید که او و پدرش خدمت الراضی باﷲ کرده اند و ثابت خود طبیب المتقی بن المقتدر باﷲ و المستکفی باﷲ و المطیعﷲ بوده است و او خال هلال بن المحسن بن ابراهیم الصابی است و در <span class=\"hlight\" dir=\"rtl\">٣٦٣</span> هَ . ق . درگذشته است . قفطی گوید : ثابت بن سنان در ایام المطیعﷲ و در امارت ابوالحسن احمدبن بویه الاقطع میزیست، و پیش از آن مختص الراضی بود... ثابت صاحب کتاب تاریخ مشهوری است و کتابی در تاریخ مشروح تراز آن نوشته نشده است و آن حاوی وقایع سال دویست و نود و اند تا هنگام وفات اوست در شهور سال <span class=\"hlight\" dir=\"rtl\">٣٦٣</span>، و خواهرزاده ٔ او هلال بن المحسن بن ابراهیم بر آن ذیلی نوشته است و اگر آن دو کتاب نبود بسیاری از وقایع تاریخ این دو مدت مجهول میماند... هلال بن المحسن گوید ابوالحسن ثابت بن سنان در شب چهارشنبه یازده شب گذشته از ذی القعده ٔ سال <span class=\"hlight\" dir=\"rtl\">٣٦٥</span> وفات یافت - انتهی . دکتر لکلرک گوید : ثابت بن سنان در بیمارستان طب را بر اساس تعلیمات ابقراط و جالینوس تدریس میکرد و تألیفاتی در طب ندارد و آنچه او را مورد نظرقرار داده مأموریتی است که در معالجه ٔ ابن مقله وزیر و خوش نویس معروف به او داده شد و در تاریخ خود داستان تیره روزی آن مرد هنرمند را آورده است او برادری داشت بنام ابراهیم که به علم نجوم می پرداخت و فرزندی بنام اسحاق که طب آموخت - انتهی . (الفهرست ابن الندیم ) (عیون الانباء ابن ابی اصیبعة) (تاریخ الحکماء قفطی ) (معجم الادباء یاقوت حموی ) (تاریخ طب عرب لکلرک ).<br /></font></div>'),
(81783, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن سلیمان الحسنی . وزیر رسائل ابوخالد یزیدبن ولید خلیفه ٔ اموی است .<br /></font></div>'),
(81784, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ]</font></b> (اِخ ) ابن سلطان بن علی بن مزید در لشکر سیف الدوله صدقةبن منصور بود و هنگام مقابله ٔ صدقه با سپاه سلطان محمد از صدقة بگریخت و نزد سلطان محمد رفت و لشکریان صدقة دل شکسته شدند و محاربه ناکرده روی بفرار نهادند و صدقة بقتل رسید .<br /></font></div>'),
(81785, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن سفیان . صحابی است و او در جنگ احد بشهادت رسیده است .<br /></font></div>'),
(81786, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن زید. یکی از شش تن باشد که بعهد رسول صلوات اﷲ علیه قرآن را گرد کرده اند.صاحب کتاب الاصابة گوید: ثابت بن زیدالحارثی مکنی بابی زیر جامع قرآن است و محمدبن سعداز ابی زید نحوی روایت کند که او مدّعی بود که ثابت بن زید جد اوست و بعضی گویند اسم او قیس بوده است و این قول اکثریست و اوپسری داشته است نام او ثابت که تابعی است . و رجوع به ابوزید ثابت بن زید و به قیس در این لغت نامه شود.<br /></font></div>'),
(81787, 'ثابت', '<span class=\"hlight\">ثابت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن الزبیربن هشام بن عروة. مرزبانی در الموشح او را از جمله ٔ روات اخبار ابوالعتاهیه شاعر ذکر کرده است .<br /></font></div>'),
(81788, 'ثابت قیس', '<span class=\"hlight\">ثابت قیس .</span> <font color=\"DarkGreen\"><b>[ ب ِ ق َ ]</font></b> (اِخ ) النخعی . یکی از اشراف کوفه . او در خلافت عثمان با بزرگان و فصحای کوفه مجامعی بر مخالفت عثمان داشت ازینرو خلیفه او را از کوفه بسال <span class=\"hlight\" dir=\"rtl\">٣٣</span> هَ . ق . نفی کرد. و رجوع به ثابت بن قیس ... شود.<br /></font></div>'),
(81789, 'ثابتات', '<span class=\"hlight\">ثابتات .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص، اِ) ج ِ ثابته . کواکب ثابته . ثوابت .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چرخ ثابتات </span> . فلک ثوابت . فلک هشتم <span class=\"hlight\">:</span> <br />یا کسی دیگر مر او را برکشید<br />آنکه کرسی اوست چرخ ثابتات .<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(81790, 'ثابته', '<span class=\"hlight\">ثابته .</span> <font color=\"DarkGreen\"><b>[ ب ِ ت َ]</font></b> (ع ص، اِ) تأنیت ثابت . <BR><font color=\"Blue\">◄</font> یکی از ثوابت کواکب . خلاف سیّارة. هر یک از ستارگان که حرکت آنرادر نتوان یافت . ج، ثوابِت، ثابتات . نور در هر ثانیه سیصد هزار هزار گز طی مسافت کند و نور نزدیکترین ثوابت بکره ٔ زمین در مدت سه تا چهار سال بما رسد. <BR><font color=\"Blue\">◄</font> بروج ثابته ؛ ثور و اسد و دلو و عقرب است .<br /></font></div>'),
(81791, 'ثابتی', '<span class=\"hlight\">ثابتی .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابونصر عبداﷲبن احمدبن ثابت بخاری ثابتی . رجوع به عبداﷲبن احمد... شود.<br /></font></div>'),
(81792, 'ثابج', '<span class=\"hlight\">ثابج .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) نعت فاعلی از ثبج .<br /></font></div>'),
(81793, 'ثابر', '<span class=\"hlight\">ثابر.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) نعت فاعلی از ثبر.<br /></font></div>'),
(81794, 'ثابری', '<span class=\"hlight\">ثابری .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ص نسبی ) منسوب است به زمینی در شعر. (مراصد).<br /></font></div>'),
(81795, 'ثابن', '<span class=\"hlight\">ثابن .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) نعت فاعلی از ثبن .<br /></font></div>'),
(81796, 'ثابور', '<span class=\"hlight\">ثابور.</span> (اِخ ) (طور... جبل ...) نام کوه کوچکی بشام (فلسطین شمالی ) بالای ساحل راست اردن آنجا که آن نهر از دریاچه ٔ طبریه خارج میشود. ارتفاع آن از سطح دریا <span class=\"hlight\" dir=\"rtl\">٥٦١</span>گز است . و رجوع به تابور در قاموس کتاب مقدس شود.<br /></font></div>'),
(81797, 'ثات', '<span class=\"hlight\">ثات .</span> (اِخ ) ناحیه ای به یمن منسوب به ذوثات . (مراصد). و از آنجاست ذوثات حمیری یکی از مهتران یمن . رجوع به ذوثات شود.<br /></font></div>'),
(81798, 'ثات', '<span class=\"hlight\">ثات .</span> (اِخ ) ابن رعین . یکی از اجداد ابوخزیمه ابراهیم بن یزید ثاتی است .<br /></font></div>'),
(81799, 'ثاتی', '<span class=\"hlight\">ثاتی .</span> (ص نسبی ) منسوب به ثات بن زیدبن اعین از قبیله ٔ حمیر. (سمعانی ).<br /></font></div>'),
(81800, 'ثاثالس', '<span class=\"hlight\">ثاثالس .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) یکی از شاگردان بقراط. (الفهرست ) (عیون الانباء).<br /></font></div>'),
(81801, 'ثاج', '<span class=\"hlight\">ثاج .</span> <font color=\"DarkGreen\"><b>[ جِن ْ ]</font></b> (ع ص ) ثاجی . نعت فاعلی از ثجو. ج، ثاجون، ثاجین .<br /></font></div>'),
(81802, 'ثاج', '<span class=\"hlight\">ثاج .</span> (اِخ ) دهی است به بحرین . (مراصد الاطلاع ).<br /></font></div>'),
(81803, 'ثاج', '<span class=\"hlight\">ثاج .</span> <font color=\"DarkGreen\"><b>[ ثاج ج ]</font></b> (ع ص ) روان کننده . نعت فاعلی از ثج ّ.<br /></font></div>'),
(81804, 'ثاجر', '<span class=\"hlight\">ثاجر.</span> <font color=\"DarkGreen\"><b>[ ج ِ ]</font></b> (ع ص ) نعت فاعلی از ثجر.<br /></font></div>'),
(81805, 'ثاجن', '<span class=\"hlight\">ثاجن .</span> <font color=\"DarkGreen\"><b>[ ج ُ ]</font></b> (اِخ ) مصحف ثاخن . رجوع به ثاخن شود.<br /></font></div>'),
(81806, 'ثاجه', '<span class=\"hlight\">ثاجه .</span> <font color=\"DarkGreen\"><b>[ ج َ ]</font></b> (اِخ ) یکی از وادیهای قبلیة نواحی مکه . (مراصد).<br /></font></div>'),
(81807, 'ثاجی', '<span class=\"hlight\">ثاجی .</span> (ع ص ) نعت فاعلی از ثجو. ثاج . ج، ثاجون، ثاجین .<br /></font></div>'),
(81808, 'ثاخن', '<span class=\"hlight\">ثاخن .</span> <font color=\"DarkGreen\"><b>[ خ ُ ]</font></b> (اِخ ) محرف تاخن . نام یکی از غلامان ارسطو است . (ابن الندیم در وصیت نامه ٔ ارسطو).<br /></font></div>'),
(81809, 'ثادری الاسقف', '<span class=\"hlight\">ثادری الاسقف .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) اسقفی بکرخ بغداد. او بطلب کتب میل شدید داشت و بتقرب و تحبیب قلوب نقله ٔ علوم میکوشید و کتابهای بسیار جمع کرد و قومی از اطباء نصاری را بنام اوتصنیفاتی است . (عیون الانباء). و محتمل است که او همان کس باشد که انالوطیقای اول ارسطو را بعربی آورد وحنین آن نقل را اصلاح کرد. (لکلرک، تاریخ طب عرب ).<br /></font></div>'),
(81810, 'ثادغ', '<span class=\"hlight\">ثادغ .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (ع ص ) نعت فاعلی از ثَدْغ . شکننده .<br /></font></div>'),
(81811, 'ثادق', '<span class=\"hlight\">ثادق .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (ع ص ) سحاب ثادِق ؛ ابر ریزان . <BR><font color=\"Blue\">◄</font> وادی ثادِق ؛ وادی سائل . وادی سیلناک .<br /></font></div>'),
(81812, 'ثادق', '<span class=\"hlight\">ثادق .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِخ ) نام وادئی در دیار بنی عقیل و در آنجا آبهائی است . اصمعی گفته است که ثادق وادی بزرگ و پهناوری است که به رُمّه منتهی میشود. (مراصد). <BR><font color=\"Blue\">◄</font> نام اسب منقذبن ظریف .<br /></font></div>'),
(81813, 'ثاذون', '<span class=\"hlight\">ثاذون .</span> (اِخ ) الطبیب . او در صدر اسلام میزیست و طبیب حجاج بن یوسف ثقفی بود. کناش بزرگی بنام پسر خود تألیف کرده است . گویند روزی حجاج از او پرسید دواء گِل خوارگی چیست ؟ او گفت عزیمت مردی چون تو. و حجاج بترک آن عادت گفت و دیگر بار گل نخورد . ممکن است او همان ثیاذوق طبیب باشد. رجوع به ثیاذوق شود.<br /></font></div>'),
(81814, 'ثاذینس', '<span class=\"hlight\">ثاذینس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) او راست : کتاب الطوفانات وکتاب الکواکب المذنبه .<br /></font></div>'),
(81815, 'ثار', '<span class=\"hlight\">ثار.</span> (ع مص، اِ) کینه . <BR><font color=\"Blue\">◄</font> کینه کشیدن . <BR><font color=\"Blue\">◄</font> انتقام . خونخواهی . طلب کردن خون <span class=\"hlight\">:</span> جز انتصار و طلب ثار روی ندید و جز حرکةالمذبوح چاره ندانست . (ترجمه ٔ تاریخ یمینی <span class=\"hlight\" dir=\"rtl\">٢٦</span>). از دیار هندوستان هر کجا نافخ ناری و طالب ثاری و ساکن داری ... بود، رو بدو آورد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٥٠</span>). سیف الدوله بعقب ایشان میرفت و بحجت قاطع شمشیر ثار و انتصار از ایشان می ستد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١٢١</span>).<br />أسأت الی النوائب فاستثارت <br />فانت قتیل ثار النایبات .<br /> <font color=\"Red\">محمد انباری .</font><br /> <BR><font color=\"Blue\">◄</font> انتقام خون کردن . (از منتخب و غیره از غیاث ). <BR><font color=\"Blue\">◄</font> کشنده ٔ کسی را بکشتن . قاتل دوست یا خویشاوند را بقصاص کشتن . <BR><font color=\"Blue\">◄</font> لاثارت فلاناً یداه ؛ نفع نرساند او را دو دست وی . (زوزنی ) (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> کشنده و قاتل دوست یا خویشاوند. ج، اَثآر، آثار، ثُؤر. <BR><font color=\"Blue\">◄</font> یا ثارات ِ فلان ؛ ای کشندگان و قاتلان فلان . <BR><font color=\"Blue\">◄</font> یا لَلثارات ؛ بیائید برای کشتن کشندگان .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">أخذ ثار</span> ؛ کین کشی . خونخواهی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ادراک ثار</span> ؛ انتقام قتل .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثار منیم </span> ؛ انتقام خونی که چون گرفته شود منتقم راضی می شود و آرامش می یابد.<br /></font></div>'),
(81816, 'ثارب', '<span class=\"hlight\">ثارب .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ع ص ) نعت فاعلی از ثرب .<br /></font></div>'),
(81817, 'ثارد', '<span class=\"hlight\">ثارد.</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ع ص ) نعت فاعلی از ثَرد.<br /></font></div>'),
(81818, 'ثاسلس', '<span class=\"hlight\">ثاسلس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) یکی از شاگردان برمانیدس طبیب یونانی است .<br /></font></div>'),
(81819, 'ثاسلس', '<span class=\"hlight\">ثاسلس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) فرزند ابقراط طبیب یونانی .<br /></font></div>'),
(81820, 'ثاسلس', '<span class=\"hlight\">ثاسلس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) حیلی مغالط، موسوم به مارس و ملقب به ثاسلس یکی از اطباء یونانی و از اصحاب حیل . او عقیده داشت که طب نه بر تجربه است و نه بر قیاس بلکه بر حیله است . و افلاطون کتب وی و شاگردان او را بسوخت .<br /></font></div>'),
(81821, 'ثاسلوس', '<span class=\"hlight\">ثاسلوس .</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (اِخ ) نام پدر ابقراط چهارم و نام پسر ابقراط طبیب یونانی معروف که او نیز پزشک بوده است . و رجوع به ثاسلس شود.<br /></font></div>'),
(81822, 'ثاسیلیوس', '<span class=\"hlight\">ثاسیلیوس .</span> (اِخ ) یکی از حکماست . شهرزوری از آداب منسوب به او نقل کرده است .<br /></font></div>'),
(81823, 'ثاطی', '<span class=\"hlight\">ثاطی .</span> (ع ص ) نعت فاعلی از ثطا. پاسپرکننده . کوبنده .<br /></font></div>'),
(81824, 'ثاطیطس', '<span class=\"hlight\">ثاطیطس .</span> <font color=\"DarkGreen\"><b>[ طی طِ ]</font></b> (اِخ ) رجوع به ثأططس شود.<br /></font></div>'),
(81825, 'ثاع', '<span class=\"hlight\">ثاع .</span> <font color=\"DarkGreen\"><b>[ ثاع ع ]</font></b> (ع ص ) نعت فاعلی از ثاعة. قی و شکوفه کننده . هراشان .<br /></font></div>'),
(81826, 'ثاعب', '<span class=\"hlight\">ثاعب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) روان سازنده .<br /></font></div>'),
(81827, 'ثاعة', '<span class=\"hlight\">ثاعة.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) یک مرتبه انداختن قی . <BR><font color=\"Blue\">◄</font> روان شدن، چنانکه آب : ثاع الماء؛ روان شد آب . (منتهی الارب ).<br /></font></div>'),
(81828, 'ثاعم', '<span class=\"hlight\">ثاعم .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) کشنده . جارّ. جاذب . جالب . نازع .<br /></font></div>'),
(81829, 'ثاعی', '<span class=\"hlight\">ثاعی .</span> (ع ص ) دشنام دهنده . <BR><font color=\"Blue\">◄</font> نسبت کننده کسی را به بدی .<br /></font></div>'),
(81830, 'ثاغ', '<span class=\"hlight\">ثاغ .</span> (ع اِ) ما بالدار ثاغ ِ و لا راغ ؛ در خانه کسی نیست . در دار دیّاری نیست .<br /></font></div>'),
(81831, 'ثاغب', '<span class=\"hlight\">ثاغب .</span> <font color=\"DarkGreen\"><b>[ غ ِ ]</font></b> (ع ص ) نعت فاعلی از ثغب . نیزه زننده . <BR><font color=\"Blue\">◄</font> ذبح کننده .<br /></font></div>'),
(81832, 'ثاغم', '<span class=\"hlight\">ثاغم .</span> <font color=\"DarkGreen\"><b>[ غ ِ ]</font></b> (ع ص ) نعت فاعلی از ثغم : لون ثاغم ؛ رنگی مانند درمنه سپید. <BR><font color=\"Blue\">◄</font> رأس ثاغم ؛ سری تمام سپید چون درمنه .<br /></font></div>'),
(81833, 'ثاغمة', '<span class=\"hlight\">ثاغمة.</span> <font color=\"DarkGreen\"><b>[ غ ِ م َ ]</font></b> (ع ص ) تأنیث ثاغم .<br /></font></div>'),
(81834, 'ثاغیة', '<span class=\"hlight\">ثاغیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع اِ) گوسفند: ماله ثاغیة ولا راغیة؛ نیست او را گوسفند و نه شتر. <BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثاغیه و راغیه نداشتن </span> ؛ هیچ نداشتن .<br /></font></div>'),
(81835, 'ثافت', '<span class=\"hlight\">ثافت .</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (اِخ ) موضعی است در یمن و آنرا ثافث نیز گویند. (مراصد).<br /></font></div>'),
(81836, 'ثافرورس', '<span class=\"hlight\">ثافرورس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) یکی از شاگردان افلاطون طبیب یونانی و استاد وی او رابه علاج جراحات میداشت .<br /></font></div>'),
(81837, 'ثافسیا', '<span class=\"hlight\">ثافسیا.</span> (معرب، اِ) اذرباس . (بحر الجواهر). <BR><font color=\"Blue\">◄</font> ثافیسا. در منهاج ثافیستا نیز آمده است و آن صمغ سداب برّی است . (بحر الجواهر). <BR><font color=\"Blue\">◄</font> صمغ سداب کوهی . <BR><font color=\"Blue\">◄</font> یتبون . <BR><font color=\"Blue\">◄</font> و بزبان بربر آن را ادریاس نامند. بقول دیسقوریدس این نبات نامش از جزیره ٔ تافسیس مشتق است چه آنرا اول بار بدآنجا یافتند برگهایش مجموعاً شبیه نارثقس است بیخ شاخه های آن شبیه به رازیانه است گل آن زرد و تخم آن اندک مستطیل و شبیه نبات نارثقس است جز آنکه آن کوچکتر است ریشه ٔ آن در خارج سیاه و در داخل سپید است و پوست آن سطبر و گس است عصاره ٔ ریشه ٔ آن را هنگامی که باد میوزد نگیرند چون ترشح آن از غایت تندی زیان رساند به اعضای بدن و بثور و دمل آرد. ریشه ٔ آن چون بیش از یکسال ماند از آن پس نفع ندهد. ریشه ٔ آن را خرد کرده در مسکه پزند تا آن اندازه که خاصیت آن بمسکه منتقل شود سپس بیالایند و آن روغن را در مواقع حاجت بکار برند و آن برای تقویت عصب و درد مفاصل نافع باشد اگر ریشه ٔ ثافسیا را بسایند و با آردجو مخلوط کنند برای جراحات و درد سینه مفید است . جالینوس در کتاب میامر گوید که بدل آن ترتیزک در داءالثعلب . ثافسیا را بخطا با صمغ سداب بری یکی دانند. (مفردات ابن البیطار) . صمغ نباتی است سفیدرنگ شبیه به انزروت با طعم تند و تلخ و بسیار تندبو و نبات او شبیه به رازیانه و گلش سفید و تخمش مانند انجره و با اندک عرض و در اطراف شعبه های او مثل اکله ٔ شبت و بیخش غلیظ و بسیار تند و تلخ و منبت او کوههای سخت و درتنکابن و الموت «جرنذ» و به دیلمی «تُنبلی » گویند. و بیخ او را زخم کرده رطوبت او را بعد از انجماد میگیرند و بعضی مجموع آن نبات را فشرده عصاره میگیرند وآخرین متخلخل و سبز مایل به سیاهی می باشد در آخر سیم گرم و خشک و با رطوبت فضلیه و مقئی و مسهل بلغم غلیظ و جهت درد پهلو و بطلان اشتها و تحلیل ریاح و سدد و ضماد او جهت داءالثعلب و رویانیدن مو و درد زانو وامثال آن و با هم وزن او موم و کندر جهت اسقاط بواسیر و جهت قلع آثار سیاهی و بنفشی و کبودی جلد و با عسل جهت جرب متقرح و با گوگرد جهت انفجار ورم صلب نافعو زیادت از دو ساعت نباید گذاشت و قدر شربتش تا پنج قیراط و پوست بیخ او در افعال مثل صمغ او است و چون ریزه کرده در روغن زیتون بجوشانند جهت تقویت عصب و درد مفاصل و آشامیدن او جهت فالج بغایت مفید و قدر شربت از پوست بیخ او و جرم او تا نه قیراط و اکثار اومورث ورم حلق و معده و احتباس بول و عروض ضیق النفس و غشی و مصلحش شیر تازه و لعاب بزرقطونا و بدلش در داءالثعلب حرف بابلی و گویند بالخاصیه تخم سداب رفع مضرت او میکند و چون گیاه و ساق او را داخل اغذیه کنند بمرتبه ای احداث حرارت کند که در زمستان محتاج بپوشش نباشند و رنگ رخسار را سرخ کند و جهت اکثر امراض بارده ٔ رحم نافع و او غیر صمغ سداب برّی است چه سداب برّی را صفات غیر او است . (تحفه ٔ حکیم مؤمن ). <BR><font color=\"Blue\">◄</font> و آن را ثفسیا نیز گویند و یتبون هم خوانند و آن صمغ سداب کوهی است و گویند صمغ سداب برّی حرمل است، و سداب کوهی برگ آن به حرمل ماند لیکن درازتر وپهن تر بود و بوی عظیم منتن دارد و تخم آن به شکل تخم سداب بود و طبیعت آن بغایت گرم بود محرق و مسخن قوی و مجفف و در وی رطوبتی فصلی بود و گویند گرمی وی در سیم بود و مسهل و منضج و منقی بود و جذبی بغایت کند از عمق بدن و موی برویاند و پوست و بیخ وی نیز بر داءالثعلب مالند بغایت نافع بود و استرخا و نقرس سردرا سودمند بود و حقنه کردن جهت عرق النساء نافع بود و بر نفث دم و فضول طلی کردن و مقدار شربت از وی در استسقاء نیم درم بود با ماءالعسل و مسهل و مقیی ٔ بودو اگر زیاده از این بود بول و طبع ببندد و ورم زبان آورد و قراقر و سوزش حلق و معده و سرخی روی و باشد که غشی و ضیق النفس پیدا کند علاج وی بقی کنند بعد از آن شیر و مسکه و جوآب بدهند و غرغره ٔ شیر تازه و روغن گل و از ادویه تخم سداب بغایت نافع بود و این از خواص است و جالینوس گوید بدل وی در داءالثعلب حرف است و وی مضر بود بمثانه و آلات بول و مصلح وی حب الاَّس و بلوط بود. (اختیارات بدیعی ). و رجوع به ثفسیا شود.<br /></font></div>'),
(81838, 'ثافل', '<span class=\"hlight\">ثافل .</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (ع ص، اِ) نعت فاعلی از ثفل . <BR><font color=\"Blue\">◄</font> سرگین . <BR><font color=\"Blue\">◄</font> آنچه بتک نشیند از هرچیز.<br /></font></div>'),
(81839, 'ثافل اصغر', '<span class=\"hlight\">ثافل اصغر.</span> <font color=\"DarkGreen\"><b>[ ف ِ ل ِ اَ غ َ ]</font></b> (اِخ ) کوهی است براه مکه . <BR><font color=\"Blue\">◄</font> ثافل اصغر و ثافل اکبر نام دو کوه است از بنی ضمره که فاصله ٔ آنها تا رضوی دو شب است . (مراصد).<br /></font></div>'),
(81840, 'ثافل اکبر', '<span class=\"hlight\">ثافل اکبر.</span> <font color=\"DarkGreen\"><b>[ ف ِ ل ِ اَ ب َ ]</font></b> (اِخ ) رجوع به ثافل اصغر شود.<br /></font></div>'),
(81841, 'ثافن', '<span class=\"hlight\">ثافن .</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (ع ص ) اسم فاعل از ثفن .<br /></font></div>'),
(81842, 'ثافی', '<span class=\"hlight\">ثافی .</span> (ع ص ) نعت فاعلی از ثفاء.<br /></font></div>'),
(81843, 'ثافیسا', '<span class=\"hlight\">ثافیسا.</span> (معرب اِ) رجوع به ثافسیا و ثفسیا شود.<br /></font></div>'),
(81844, 'ثاقب', '<span class=\"hlight\">ثاقب .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (ع ص ) نعت فاعلی از ثقوب و ثقب . مضی ٔ. روشن . فروزان . <BR><font color=\"Blue\">◄</font> سوراخ کننده . <BR><font color=\"Blue\">◄</font> نافذ. <BR><font color=\"Blue\">◄</font> رخشان . تابان .تابنده . <BR><font color=\"Blue\">◄</font> افروخته . <BR><font color=\"Blue\">◄</font> روشن کننده . <BR><font color=\"Blue\">◄</font> باتلألؤ. درخشان . (غیاث، کشف و منتخب ). <BR><font color=\"Blue\">◄</font> نام دردی است که صاحبش چنان پندارد که کسی در اندام او سوراخها میکند. (لطائف و کنز). <BR><font color=\"Blue\">◄</font> نیازک . <BR><font color=\"Blue\">◄</font> ستاره ٔ روشن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">رأی ثاقب </span> ؛ رأی نافذ. رأی حاذق <span class=\"hlight\">:</span> ودر معرفت کارها و شناخت مناظم آن رأی ثاقب و فکرت صایب روزی کرد. (کلیله و دمنه ). چه به زمانی اندک بسیاری از ممالک عالم به رأی ثاقب و تدبیر صایب ... (رشیدی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">شهاب ثاقب </span> ؛ شعله ٔ افروخته . افروزه ٔ روشن <span class=\"hlight\">:</span> <br />زرقیب دیوسیرت بخدای خود پناهم <br />مگر آن شهاب ثاقب مددی کند سها را.<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عقل ثاقب </span> ؛ عقل نافذ.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">نجم ثاقب </span> ؛ ستاره ٔ بلند و روشن از ستارگان یا اسم زحل است که کیوان باشد <span class=\"hlight\">:</span> کان رأی الامام القادر بالله نجماً ثاقباً (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٠٠</span>).<br />نجم ثاقب گشته حارس دیو ران <br />که بهل دزدی ز احمد سِر ستان .<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> اشتر بسیارشیر. ج، ثواقب .<br /></font></div>'),
(81845, 'ثاقب', '<span class=\"hlight\">ثاقب .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (اِخ ) شاعری از مردم هندوستان . وفات او بشهر بنارس در <span class=\"hlight\" dir=\"rtl\">١٢٢٩</span> هَ . ق . و این دو بیت از اوست :<br />از پشت فلک بر شده در زیر زمین باش <br />با سیر و تماشای جهان خانه نشین باش <br />بر مائده ٔاهل دول دست مینداز<br />از مکسب خود قانع یک نان جوین باش .<br /><font color=\"Red\">(قاموس الاعلام ).</font><br /></font></div>'),
(81846, 'ثاقب', '<span class=\"hlight\">ثاقب .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (اِخ ) شاعری از مردم انقره . او در اندرون همایون تربیت شده است و در <span class=\"hlight\" dir=\"rtl\">١٢٥٨</span> هَ . ق . درگذشته است . وی را قولها و بعض اشعار است . (قاموس الاعلام ).<br /></font></div>'),
(81847, 'ثاقب', '<span class=\"hlight\">ثاقب .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (اِخ ) (شیخ مصطفی ) از مشایخ طریقه ٔ مولویه و یکی از شعراست . او در کوتاهیه میزیست و اصل وی از ازمیر است و از برآوردگان مصطفی پاشا کوپریلی زاده است سپس به أدرنه شد و به طریقه ٔ مولویه درآمد و بعد از آن به قونیه رفت و پس از دیری خدمت پیر بمشیخت خانقاه کوتاهیه منتصب گشت و در <span class=\"hlight\" dir=\"rtl\">١١٤٨</span> هَ . ق . وفات کرد. او را دیوانی مرتب است و نیز سفینه ای دارد در مناقب عرفای مولویة. (قاموس الاعلام ).<br /></font></div>'),
(81848, 'ثاقب', '<span class=\"hlight\">ثاقب .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (اِخ ) نام شاعری از مردم بخارا و بیت ذیل از اوست :<br />قدم ببحر خطرناک عشق ماندم و آخر<br />کمر ز موج و کلاه از سر حباب گرفتم .<br /><font color=\"Red\">(قاموس الاعلام ).</font><br /></font></div>'),
(81849, 'ثاقب افندی', '<span class=\"hlight\">ثاقب افندی .</span> <font color=\"DarkGreen\"><b>[ ق ِ اَ ف َ ]</font></b> (اِخ ) (حکیم ...) اصل او از اخسخه است و آنگاه که بدر سعادت درآمد در مدرسه ٔ قره مصطفی پاشا واقع در بازار ارغادبتحصیل علوم پرداخت و نیز طب آموخت و پس از اکمال تحصیل در مقابل جامع شریف سلیمانیه در مریضخانه ای بتعلیم فن طب مشغول گردید و بسال <span class=\"hlight\" dir=\"rtl\">١٢٦٩</span> هَ . ق . در <span class=\"hlight\" dir=\"rtl\">١٢٠</span> سالگی وفات کرد و او را اشعاری است . (قاموس الاعلام ).<br /></font></div>'),
(81850, 'ثاقب الثلج', '<span class=\"hlight\">ثاقب الثلج .</span> <font color=\"DarkGreen\"><b>[ ق ِ بُث ْ ث َ ]</font></b> (ع ص مرکب ) رجوع به برف سُنْب شود.<br /></font></div>'),
(81851, 'ثاقب الحجر', '<span class=\"hlight\">ثاقب الحجر.</span><font color=\"DarkGreen\"><b>[ ق ِ بُل ْ ح َ ج َ ]</font></b> (ع اِ مرکب ) بسپایه . کثیرالارجل . بسفایج . (مفردات ابن البیطار) (تذکره ٔ اولی الالباب ). اضراس الکلب . تشمیر. سقی رغلا. چشمک . مشوطالغراب . و نیز رجوع به کثیرالارجل شود.<br /></font></div>'),
(81852, 'ثاقبة', '<span class=\"hlight\">ثاقبة.</span> <font color=\"DarkGreen\"><b>[ ق ِ ب َ ]</font></b> (ع ص ) تأنیث ثاقب <span class=\"hlight\">:</span> رأی امیرالمؤمنین بفطرته الثاقبة و فکرته الصافیة صرف الخاطر عن الجزع . (تاریخ بیهقی <span class=\"hlight\" dir=\"rtl\">٣٠٠</span>).<br /></font></div>'),
(81853, 'ثاقراطس', '<span class=\"hlight\">ثاقراطس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) العین زربی . از اطباء زمان فترت بین ابقراط و جالینوس است .<br /></font></div>'),
(81854, 'ثاقف', '<span class=\"hlight\">ثاقف .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (ع ص ) نعت فاعلی از ثقف .<br /></font></div>'),
(81855, 'ثاقل', '<span class=\"hlight\">ثاقل .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (ع ص ) سخت بیمار. <BR><font color=\"Blue\">◄</font> بیماری که بیماریش سنگین شده : اصبح ثاقلاً؛ سخت بیمار گردید. بیماری وی سنگین شد. <BR><font color=\"Blue\">◄</font> دینار ثاقل ؛ دینار درست و کامل . ج، ثَواقل .<br /></font></div>'),
(81856, 'ثاقل', '<span class=\"hlight\">ثاقل .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (اِخ ) نام شهری است .<br /></font></div>'),
(81857, 'ثال', '<span class=\"hlight\">ثال .</span> <font color=\"DarkGreen\"><b>[ ثال ل ]</font></b> (ع ص ) نعت فاعلی از ثل ّ و ثلَل .<br /></font></div>'),
(81858, 'ثالب', '<span class=\"hlight\">ثالب .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص، اِ) نعت فاعلی از ثلب . <BR><font color=\"Blue\">◄</font> نام درختی .<br /></font></div>'),
(81859, 'ثالبة', '<span class=\"hlight\">ثالبة.</span> <font color=\"DarkGreen\"><b>[ل ِ ب َ ]</font></b> (ع ص ) امراءة ثالبةالشوی ؛ متشققةالقدمین .<br /></font></div>'),
(81860, 'ثالث', '<span class=\"hlight\">ثالث .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص، اِ) نعت فاعلی از ثلث . <BR><font color=\"Blue\">◄</font> سوم . <BR><font color=\"Blue\">◄</font> سه کننده . <BR><font color=\"Blue\">◄</font> شخص خارجی <span class=\"hlight\">:</span> و هر راز که ثالثی در آن محرم نشود هر آینه از اشاعت مصون ماند. (کلیله و دمنه ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">شخص ثالث </span> ؛ در مرافعات آنکه نه مدعی و نه مدعی علیه است و دعوی مابه الادّعا کند. (اصطلاح عدلیه ).<br /></font></div>'),
(81861, 'ثالث ثلاثه', '<span class=\"hlight\">ثالث ثلاثه .</span> <font color=\"DarkGreen\"><b>[ ل ِ ث َ ث َ ]</font></b> (ع اِ مرکب ) سوم از سه یعنی یکی از سه . (مجمل اللغة) <span class=\"hlight\">:</span> <br />فرستم نسخه ٔ ثالث ثلاثه <br />سوی بغداد در سوق الثلاثا.<br /> <font color=\"Red\">خاقانی </font><br /> <BR><font color=\"Blue\">◄</font> نام ستاره ای ؟<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">گویندگان ثالث ثلاثة</span> ؛ ترسایان <span class=\"hlight\">:</span> <br />ثالثاً تا از تو بیرون رفته ام <br />گوئیا ثالث ثلاثه گفته ام .<br /><font color=\"Red\">(مثنوی ).</font><br /></font></div>'),
(81862, 'ثالس', '<span class=\"hlight\">ثالس .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) ملطی . نخستین فیلسوف یونان که فحص علل اشیاء در طبیعت کرد و از انتساب آن بغیب چنانکه تا آن روز عادت رفته بود چشم پوشید. او موضوع علل طبیعی اشیاء را مطرح کرده و در جهان و اصل و حقیقت عالم به پژوهش پرداخته است . او زماناً اولین فیلسوف نحله ٔ ایونی می باشد. تا این زمان مردم عموماً پاسخ مسائل مربوطبجهان و طبیعت را در کتب و روایات و اساطیر دینی جستجو میکردند، ثالس و دیگر فلاسفه ٔ نحله ٔ ایونی اولین کسانی هستند که برای امور و حوادث طبیعی بعللی طبیعی متوسل شده اند. ثالس از مردم «ملطیه » شهری به ایونیا معاصر سولون و کرزوس و کوروش و بعضی گویند وی از مردم فینیقیه بود و بشهر ملطیه تبعید شده است لکن ظاهراً اجداد وی فینیقی بوده اند. گویند او سفری به مصرکرده از پیشوایان دینی آنجا دانش هندسه آموخته است و هم گویند که او کرتی به کلده رفته است ولی این روایت درخور اعتماد نیست . دیوجانس لائرتیوس گوید ثالس پیش از اشتغال به طبیعیات به امور ملکی اشتغال داشت و مردم را از مخالفت با کورش شاهنشاه ایران و اتحاد با کرزوس منع میکرد لیکن این گفته با دو فقره ٔ دیگر که هردوتوس آورده موافقت ندارد. هرودوتوس گوید که هنگام جنگ کوروش با کرزوس او در سپاه کوروش بود و برای عبور از رود هالیس گفت تا نهری از وی جدا کردند ورود قابل عبور شد و در جای دیگر گوید که ثالس بمردم ایونی پیش از آنکه تابع ایران شوند سفارش کرد که اتحادیه ای با حکومت مرکزی درتئوس برای مقاومت در برابر ایرانیان تشکیل دهند هر چند گفته ٔ هردوتوس در امرجدا کردن نهری از رود هالیس حقیقت ندارد ولی از آن روایت و روایت دوم، خبر مربوط به اقدام ثالس به نفع شاهنشاه ایران تضعیف میشود و تا حدی معلوم میگردد که قدما ثالیس را طرفدار ایرانیان نمیدانستند. دیوگنس روایت کرده است که ثالس گوشه نشین و متبتل بود ولی صحت این گفته مورد تردید است زیرا جنبه ٔ عملی کارهای او بکلی منافی با این احوال است آنچه قدما در شرح حال این حکیم گفته اند همه با یکدیگر متناقض است، در بعض آن ها ثالس مردی منغمر درعلم و مستغرق مطالعه و تحقیق است در بعض دیگر شخصی ماهر در عمل مینماید که از همه ٔ معاصرین خود پیش افتاده و آنان از آراء و راهنمائیهای او مستفید می شوند به هر حال مسلم است که قدما به اهمیت مقام علمی او چنانکه بایست پی نبرده اند ارسطو، ثالس را پس از متألهین اول فیلسوف نامیده است، ثالس نه اول کس است که به فلسفه پرداخته و نه مخترع فلسفه می باشد او اول کسی است از فلاسفه که ما می شناسیم و از احوالش مختصر اطلاعی داریم . ثالس مهندس و منجم و صاحب عقیده ٔ خاص در باب تکوین عالم و جویای علل امور آن در طبیعت بود ثالس و پیروان او از نحله ٔ ایونی بیش از هر چیز بعالم خارج توجه داشتند و بقول ارسطو «او چون مشاهده کرد که غذای تمام موجودات مرطوب است و حرارت هم از تری می زاید و رطوبت است که مایه ٔحیات جانداران می باشد و بذر نباتات و نطفه ٔ حیوانات تری دارد و آب مبداء طبیعی تمام اجسام مرطوب است » نتیجه گرفت که اشیاء متکثره همه شی ٔ و طبیعت و آن شی ٔ که ماده ٔ ابتدائی یا مادةالمواد یا وجود اصیل است آب است خاصه که از تمام چیزها آب است که بطور طبیعی به اشکال متنوع جامد و مایع و بخار درمی آید. ثئوفرسطس گوید که «ظواهر حسی او را بدین نتیجه رهبری میکرد زیرا هم آنچه گرم است برای حیات نیازمند رطوبت است و هم آنچه میمیرد خشک میشودو تمام بذور مرطوب است و هر غذائی رطوبت دارد» به هرحال این نظریه که ارتباطبا مقام دینی و مرجع فوق طبیعی ندارد و مأخذ آن عالم طبیعت است موجب شد که دیگر فلاسفه ٔ عنصر منتشرتر وسبک تر یعنی «هوا» یا قوی تر یعنی «آتش » را پیش کشیدند و آنها را مایه ٔ حقیقی موجودات و وجود اصیل دانستند و از منابعی که بدست داریم نمی توان دانست که چگونه اشیاء از آب پدید آمده اند. ثالس خاصیت جاذبه ٔ بعض اشیاء مانند کهربا و آهن ربا را بدید و دعوی کرد که اشیاء عموماً صاحب نفس می باشند . ارسطو گوید که او عقیده داشت که جهان پر از خدایان است . ظاهراً باید این عقیده را با قول درباره ٔنفس اشیاء نزدیک کرده گفت که او ماده ٔ ابتدائی را زنده می پنداشته است بطوری که ماده مانند خواء اساطیر قدیم اشیاء را بی مداخله ٔ خدا بوجود می آورده است .<br />درباره ٔ اطلاعات ثالس از هندسه، پروکلوس، شارح کتاب تاریخ ریاضیات تألیف اودموس آورده است : «ثالس آنگاه که بمصر رفت هندسه را باخود بیونان (هلاد) آورد. او خود چند کشف کرد و اعقاب خود را با تحقیقات خویش که گاه جنبه ٔ عمومی و گاه جنبه ٔ عملی داشت براه اکتشافات دیگر انداخت ». گویند ثالس اول کس است که گفت در هر مثلث متساوی الساقین دو زاویه ٔ مقابل بدو ضلع متساوی متساویند (بجای متساوی ثالس اصطلاح قدیم را استعمال کرده میگفت متشابه اند) «این قضیه که چون دو خط مستقیم یکدیگر را قطع کنند زوایای متقابله ٔ برأس متساوی اند چنانکه اودموس گوید اول بار بوسیله ٔ ثالس کشف شد. و اوقلیدس برهان علمی آن را آورده است ». «اودموس این قضیه را که هرگاه دو زاویه و ضلع بینهما از مثلثی مساوی باشد با دو زاویه وضلع بینهما از مثلث دیگر آن دو مثلث متساوی هستند از ثالس داند و گوید که ثالس ناچار آن را برای تعیین مسافت کشتی ها در دریا بکار می برده است ...» از این روایات ظاهر می شود که معلومات ثالس بکلی در اثر تحقیقات علمی نظری برای او حاصل نشده و آنچه قدما باو نسبت میدادند در مورد مسائل عملی بوده است خاصه که پروکلوس در مورد یکی از قضایا گفته است که ثالس آن قضیه را کشف و اوقلیدس آنرا اثبات کرد. دیوجانس لائرتیوس گوید که پامفیلا ثالس را اول کس میداند که مثلث قائم الزاویه را در دائره رسم کرده است و بنابراین ثالس میدانسته است که مجموع زوایای هر مثلث مساوی است با دو زاویه ٔ قائمه . ولی باید دانست که اولا اثبات قضیه ٔ اخیر را اودموس به فیثاغورسیان منسوب داشته است . ثانیاً برای اثبات قضیه رسم زاویه ٔ قائمه در نیم دایره دانستن مجموع زوایای یک مثلث را بطور نظری ضرورت ندارد . فلوطرخس گوید که ثالس ارتفاع اهرام را از سایه ٔ آنها با مقایسه ٔ سایه ٔ یک عصا اندازه گرفت این قول مبنی بر روایتی است که دیوجانس لائرتیوس بصورت ذیل نقل کرده است : هیرونیم از مردم رودس گوید که ثالس اهرام را با ملاحظه ٔ سایه ٔ شیئی وقتیکه آن سایه مساوی شی ٔ است اندازه گرفت . در این حال مسئله باین صورت در می آید که وقتی سایه ٔ یک چیز مساوی آن است در آن وقت این تساوی نسبت بتمام اشیاء صادق می آید و البته در ملاحظه ٔ این امر هیچ نوع تحقیقات نظری مهم ضرور نیست . درباره ٔ اطلاع او از علم نجوم و هیئت گفته اند که ثالس کسوف سال <span class=\"hlight\" dir=\"rtl\">٥٨٥</span> م . (<span class=\"hlight\" dir=\"rtl\">٢٨</span> مه ) را در آسیای صغیر از پیش خبر داد ولی بعض محققین در صحت این امر تردید کرده اند زیرا علت حقیقی کسوف تا مدتی پس از ثالس نیز معلوم نبود قدما مخصوصاً کلدانیان که از سالیان دراز متوالیاً کسوف و خسوف را ضبط میکردند شاید به اجمال میدانستند که تقریباً هر هجده سال کسوف و خسوف منظماً وقوع می یابد بدون اینکه علت حقیقی آنرا دریافته باشند اگر پیش گوئی ثالس صحت داشته باشد باید گفت که او معلومات تجربی و عملی را که خارج از زادبوم خود کسب کرده بود در ایونی نشر داده است .<br />گویندثالس قطر ظاهری خورشید را اندازه گرفت و خورشید را <span class=\"hlight\" dir=\"rtl\">٧٢٠</span> بار بزرگتر از ماه دانست و بتعیین فصول نجومی و اطلاع از انقلابات صیفی و شتوی توفیق یافت سال را به <span class=\"hlight\" dir=\"rtl\">٣٦٥</span> روز بخشید و صورت دب اصغر را او در اول تصویر کردو زمین را مرکز عالم گمان برد لیکن مانند قرصی مسطح که روی آبی شناور باشد .<br />درباره ٔ این معلومات به صعوبت میتوان تحقیقات و ملاحظات نظری او را از اشتغالات عملی تفکیک کرد ولی از مجموع نظریات و اکتشافاتی که به او نسبت داده اند می توان نتیجه گرفت که با ثالس علوم عقلیه آغاز شده است . ثالس و دیگر فلاسفه ٔ ایونی در حقیقت پیشوایان و بانیان تحقیقات طبیعی و علوم ریاضی در یونان شمرده میشوند و واسطه ٔ میان یونانیان و ملل متمدن قدیم مشرق می باشند .<br />نظریه ٔ او نسبت به بقای نفس و صحت انتساب حکم و امثالی که از او دانسته اند محل تردید می باشد تألیفاتی در علم نجوم و طبیعیات به او منسوب داشته اند ولی صحت نسبت آنها به او معلوم نیست بلکه محتمل است که او هیچ ننوشته باشد .<br /></font></div>'),
(81863, 'ثالسقیس', '<span class=\"hlight\">ثالسقیس .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (معرب، اِ) بیونانی تخمی است که بفارسی آنرا سپندان گویند چون دود کنند جمیع گزندگان بگریزند و بر گزندگی عقرب مالند نافع باشد. (برهان ). تخم سپندان . سفیداسفند. رشاد. حرف بابلی . (تحفه ٔ حکیم مؤمن ) (اختیارات بدیعی ). این نام در بعض نسخ ثالسفیس آمده است . (بحر الجواهر) . و در بعض نسخ ثالیفس و ثالیسقیس .<br /></font></div>'),
(81864, 'ثالع', '<span class=\"hlight\">ثالع.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص ) نعت فاعلی از ثلع.<br /></font></div>'),
(81865, 'ثالغ', '<span class=\"hlight\">ثالغ.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص ) ثالع.<br /></font></div>'),
(81866, 'ثالم', '<span class=\"hlight\">ثالم .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص ) نعت فاعلی از ثلم .<br /></font></div>'),
(81867, 'ثالوث', '<span class=\"hlight\">ثالوث .</span> (ع اِ) آنچه مرکب از سه شده باشد. <BR><font color=\"Blue\">◄</font> ثالوث اقدس ؛ أب و ابن و روح القدس در مذهب نصاری . أقانیم .<br /></font></div>'),
(81868, 'ثالیس', '<span class=\"hlight\">ثالیس .</span> (اِخ ) نام غلام ارسطو . و نیز رجوع به ثالس شود.<br /></font></div>'),
(81869, 'ثالیقطرون', '<span class=\"hlight\">ثالیقطرون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) کزبرةالحبشة است . دیسقوریدس گوید که آن نباتیست دارای برگهای شبیه به برگهای کزبرة جز آنکه روی آنها مرطوب و چسبناک است و ساقه ٔ آن کوچک باشد. این نبات اغلب در دشت ها رویدخاصیت آن خشک کردن و التیام زخمهاست و بهمین سبب آنرا در قروح مزمن معده بکار برند مؤلف گوید که جمعی بخطا تصور میکنند که این نبات همان رقعةالطالبیة است . (مفردات ابن البیطار) .<br /></font></div>'),
(81870, 'ثام', '<span class=\"hlight\">ثام .</span> <font color=\"DarkGreen\"><b>[ ثام م ]</font></b> (ع ص ) نعت فاعلی از ثَم ّ.<br /></font></div>'),
(81871, 'ثامانیان', '<span class=\"hlight\">ثامانیان .</span> (اِخ ) نام سرزمینی جزء ایالت چهاردهم شاهنشاهی ایران هخامنشی .<br /></font></div>'),
(81872, 'ثامج', '<span class=\"hlight\">ثامج .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) نعت فاعلی از ثمج . آمیزنده .<br /></font></div>'),
(81873, 'ثامد', '<span class=\"hlight\">ثامد.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص، اِ) نعت فاعلی ازثَمد. <BR><font color=\"Blue\">◄</font> ستور ریزه که علف خوردن گیرد.<br /></font></div>'),
(81874, 'ثامر', '<span class=\"hlight\">ثامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص، اِ) نعت فاعلی از ثَمر. <BR><font color=\"Blue\">◄</font> غله ای است که آنرا لوبیا خوانند. آبی که آنرا در آن پخته باشند حیض و بول را براند. (برهان ). لوبیا. دجر. <BR><font color=\"Blue\">◄</font> درختی که میوه ٔ او رسیده باشد. <BR><font color=\"Blue\">◄</font> درخت میوه ناک . <BR><font color=\"Blue\">◄</font> گل یا شکوفه ٔ حُماض که بفارسی ترشه است، و رنگ آن سرخ باشد.<br /></font></div>'),
(81875, 'ثامر', '<span class=\"hlight\">ثامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) نامی از نامهای مردان عرب از جمله پدر عبداﷲ رئیس ترسایان معاصر ذونواس صاحب الاخدود. (مجمل التواریخ و القصص ص <span class=\"hlight\" dir=\"rtl\">١٦٩</span>).<br /></font></div>'),
(81876, 'ثامسطیوس', '<span class=\"hlight\">ثامسطیوس .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) خطیب و حکیمی از مفسرین کتب ارسطاطالیس . او کاتب یولیانس مرتد بود. او راست : شرح قاطیغوریاس (مقولات ) ارسطو. تفسیر تمام انالوطیقای اولی در سه مقاله . تفسیر انالوطیقای ثانی . دو شرح بر کتاب الکون و الفساد ارسطو صغیر و کبیر. بعض مواضع طوبیقا. بحثی راجع به بوئطیقا. شرح تمام کتاب السماء و العالم و آنرا یحیی بن عدی نقل یا اصلاح کرده است . تفسیر مقاله ٔ لام کتاب الحروف (الهیات ) ارسطو. تفسیر چند مقاله ٔ کتاب اخلاق ارسطو. شرح تمام کتاب النفس ارسطو. کتاب اًلی یولیانوس فی التدبیر. کتاب النفس در دو مقاله . رسالة الی یولیانس الملک . و هم ثامسطیوس اصول و کلیات . (جوامع). مقاله ٔ اول کتاب راجع به طبیعیات اسکندر افرودیسی را تفسیر کرده است . دکتر لکلرک در تاریخ طب عرب گوید مترجمین کتب ثامسطیوس به عربی یا سریانی حنین بن اسحاق و اسحاق بن حنین و ابوبشر متی و یحیی بن عدی بوده اند. شروح قاطیغوریاس او را حنین بن اسحاق شرح کرده . تفسیر انالوطیقای ثانی او را نیز به عربی ترجمه کرده اند زیرا که ترجمه ٔ به لاطینی از آن در دست است که بی شک از عربی نقل شده است . و ابوالفرج (ابن العبری ) گوید ثامسطیوس در نامه ٔ خود به یولیانوس نوشت که تنوع ادیان درپیشگاه خدایان امری پسندیده است و با این گفته او را از قتل و آزار مسیحیان بازداشت ... و ظاهراً یحیی بن عدی شروح او را بر کتاب ما بعدالطبیعه ٔ ارسطو به عربی ترجمه کرده باشد چه ابن الندیم گوید آن را به خط یحیی بن عدی دیدم - انتهی . (نقل به اختصار). مؤلف نزهةالارواح آورده است که او در میان حکمای یونان روش معلم خود ارسطو را اختیار کرد و به سمت وزارت برقرار گردید و کتب استاد خود را به بهترین و نیکوترین وجهی ترجمه کرد و بطوریکه شیخ ابوعلی رحمةاﷲ تقریرات و شروح ثامسطیوس را بر سایر شروح ترجیح میدهد و معتبر میداند . از ثامسطیوس سی و پنج خطابه در دست است که بیست خطابه ٔ آن دارای فوائد تاریخی و اجتماعی است . مولد او میان سالهای <span class=\"hlight\" dir=\"rtl\">٣١٠</span> و <span class=\"hlight\" dir=\"rtl\">٣٢٠</span> م . و وفات وی در حدود <span class=\"hlight\" dir=\"rtl\">٣٩٥</span> در قسطنطنیه بوده است .<br />مآخذ: ابن الندیم کتاب الفهرست ص <span class=\"hlight\" dir=\"rtl\">٣٥٥</span> ابن ابی اصیبعة عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٩</span>، <span class=\"hlight\" dir=\"rtl\">٣٦</span>، <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٠١</span>، <span class=\"hlight\" dir=\"rtl\">٢٠٦</span> قفطی، تاریخ الحکماء ص <span class=\"hlight\" dir=\"rtl\">٣٥</span>، <span class=\"hlight\" dir=\"rtl\">٣٦</span>، <span class=\"hlight\" dir=\"rtl\">٣٧</span>، <span class=\"hlight\" dir=\"rtl\">٣٨</span>، <span class=\"hlight\" dir=\"rtl\">٣٩</span>، <span class=\"hlight\" dir=\"rtl\">٤٠</span>، <span class=\"hlight\" dir=\"rtl\">٤١</span>، <span class=\"hlight\" dir=\"rtl\">٤٢</span>، <span class=\"hlight\" dir=\"rtl\">١٠٧</span>، <span class=\"hlight\" dir=\"rtl\">١٧٢</span>، <span class=\"hlight\" dir=\"rtl\">١٧٤</span>، <span class=\"hlight\" dir=\"rtl\">٢٤٥</span>، <span class=\"hlight\" dir=\"rtl\">٣٠٠</span>، <span class=\"hlight\" dir=\"rtl\">٣٢٣</span>، <span class=\"hlight\" dir=\"rtl\">٣٥٦</span>. ترجمه ٔ شهرزوری ص <span class=\"hlight\" dir=\"rtl\">١٩١</span>. (کشف الظنون ).<br /></font></div>'),
(81877, 'ثامسطیوس', '<span class=\"hlight\">ثامسطیوس .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) طبیبی از یونان قدیم . یحیی نجومی زمان او را فترت بین افلاطون و اسقلبیوس ثانی گفته است .<br /></font></div>'),
(81878, 'ثامغ', '<span class=\"hlight\">ثامغ.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) نعت فاعلی از ثمغ.<br /></font></div>'),
(81879, 'ثامل', '<span class=\"hlight\">ثامل .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) شمشیری که از دیر صیقل نشده . <BR><font color=\"Blue\">◄</font> بلد ثامل ؛ ای یحمل المقام . (منتهی الارب ).<br /></font></div>'),
(81880, 'ثاملیه', '<span class=\"hlight\">ثاملیه .</span> <font color=\"DarkGreen\"><b>[ م ِ لی ی َ ]</font></b> (اِخ ) آبی است اشجع را. (منتهی الارب ). منسوب است به ماءالاشجع بین الصراد و رحرحان . (معجم البلدان ).<br /></font></div>'),
(81881, 'ثامن', '<span class=\"hlight\">ثامن .</span> <font color=\"DarkGreen\"><b>[م ِ ]</font></b> (ع ص ) نعت فاعلی از ثمن . <BR><font color=\"Blue\">◄</font> هشتم .<br /></font></div>'),
(81882, 'ثامنة', '<span class=\"hlight\">ثامنة.</span> <font color=\"DarkGreen\"><b>[ م ِ ن َ ]</font></b> (ع ص، اِ) تأنیث ثامن . <BR><font color=\"Blue\">◄</font> یک جزء از شصت جزء سابعه و ثامنه قسمت شده است به شصت تاسعة (فلک ). ج، ثوامن .<br /></font></div>'),
(81883, 'ثاموس', '<span class=\"hlight\">ثاموس .</span> (معرب، اِ) (کلمه ٔ یونانی ) مرزنجوش . رجوع به آذان الفار شود. (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(81884, 'ثامی', '<span class=\"hlight\">ثامی .</span> (ع ص ) نعت فاعلی از ثَماء.<br /></font></div>'),
(81885, 'ثامیطا', '<span class=\"hlight\">ثامیطا.</span> (اِخ ) قفطی در تاریخ الحکماء در شرح حال ارسطو گوید : «و جدّد بناء مدینة ثامیطا» و ظاهراً کلمه ٔ ثامیطا تحریف اسطاغیرا باشد چنانکه در عیون الانباء ابن ابی اصیبعة نیز بدان صورت ضبط شده است .<br /></font></div>'),
(81886, 'ثانسیا', '<span class=\"hlight\">ثانسیا.</span> (معرب، اِ) در نسخه ٔ چاپی تذکره ٔ ضریر انطاکی بجای ثافسیا آمده است و ظاهراً غلط کاتب است .<br /></font></div>'),
(81887, 'ثانط', '<span class=\"hlight\">ثانط.</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ع ص ) نعت فاعلی از ثَنط.<br /></font></div>'),
(81888, 'ثانوی', '<span class=\"hlight\">ثانوی .</span> <font color=\"DarkGreen\"><b>[ ن َ وی ی ]</font></b> (ع ص نسبی ) منسوب به ثانی . <BR><font color=\"Blue\">◄</font> دومی . دومین : عادت، طبیعت ثانوی است .<br /></font></div>'),
(81889, 'ثانویه', '<span class=\"hlight\">ثانویه .</span> <font color=\"DarkGreen\"><b>[ ن َ وی ی َ ]</font></b> (ع ص نسبی ) تأنیث ثانوی .<br /></font></div>'),
(81890, 'ثانی', '<span class=\"hlight\">ثانی .</span> (ع ص، اِ) نعت فاعلی از ثنی . <BR><font color=\"Blue\">◄</font> دوم . دوّم . دویم . <BR><font color=\"Blue\">◄</font> جفت . <BR><font color=\"Blue\">◄</font> دوتاکننده . <BR><font color=\"Blue\">◄</font> برگرداننده . <BR><font color=\"Blue\">◄</font> پیچیده . <BR><font color=\"Blue\">◄</font> اسم یکی از اقسام مروارید. <BR><font color=\"Blue\">◄</font> هذا ثانی اثنین ؛ أی هو احد اثنین . همچنین است ثالث ثلاثة تا عشرة.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">فجر ثانی </span> ؛ صبح دوم . و رجوع به فجر شود.<br /></font></div>'),
(81891, 'ثانی', '<span class=\"hlight\">ثانی .</span> (اِخ ) جان ممی . متوفی <span class=\"hlight\" dir=\"rtl\">٩٩٥</span> هَ . ق . او را دیوانی است بترکی .<br /></font></div>'),
(81892, 'ثانی', '<span class=\"hlight\">ثانی .</span> (اِخ ) تخلص شاه عباس ثانی صفوی در شعر و این رباعی ازوست :<br />از هجر توام بدیده خون میگردد<br />احوال دلم بی تو زبون میگردد<br />ای دوست اگر ترا ببیند ثانی <br />برگرد سرت ببین که چون میگردد.<br />و رجوع به عباس ... شود.<br /></font></div>'),
(81893, 'ثانی', '<span class=\"hlight\">ثانی .</span> (اِخ ) نام دو تن از شعرای عثمانی است :<br /><span class=\"hlight\" dir=\"rtl\">١</span> - در عصر سلطان بایزید ثانی و او در حسن و جمال بی نظیر بوده است واز این رو بدو یوسف ثانی می گفته اند و وی از این شهرت تخلص خود را گرفته است و او را در جوانی یکی از دوستداران او از راه حسد بکشته است و از شعر اوست :<br />دلربا لر دلا بتم نه مدر<br />نور دیده م سرور سینه مدر.<br /><span class=\"hlight\" dir=\"rtl\">٢</span> - از شعرای دوره ٔ سلطان مرادخان سوم و از طایفه ٔ قول اوغلی اسلامبول می باشد و او تتبع اشعار شعراء ایران میکرد بالخاصه بدیوان امیرعلی شیر نوائی توجه داشت و او را دیوانی است و از جمله ٔ اشعار اوست :<br />کوکل مرآتنی صوفی مجلا ایتسک اولمزمی <br />جمال یاری بویوزدن تماشا ایتسک اولمزمی .<br /></font></div>'),
(81894, 'ثانی اثنین', '<span class=\"hlight\">ثانی اثنین .</span> <font color=\"DarkGreen\"><b>[ اِ ن َ ]</font></b> (ع اِ مرکب ) دوم دو. <BR><font color=\"Blue\">◄</font> یکی از دو. <BR><font color=\"Blue\">◄</font> دومی . <BR><font color=\"Blue\">◄</font> مجازاً، همتا. تالی تلو. نسخه ٔ ثانی . عدیل . قرین . نائب مناب . قائم مقام . دیگرم . لنگه . دگر. دیگر. <BR><font color=\"Blue\">◄</font> کنایه از مثل و مانند ونظیر. چرا که عدد دوم از مجموع دو عدد و بالضروره در ذات و اکثر صفات مثل عدد اول خواهد بود. (غیاث ).<br /></font></div>'),
(81895, 'ثانی خان', '<span class=\"hlight\">ثانی خان .</span> (اِخ ) یکی از شعرای فارسی گوی هندو و از امراء دوره ٔ همایون و اکبر شاه هندی است و این بیت او راست :<br />ای رسم تو آزار من و قاعده بیداد<br />بیداد از این رسم و از این قاعده فریاد.<br /></font></div>'),
(81896, 'ثانی سماوی', '<span class=\"hlight\">ثانی سماوی .</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِ مرکب ) اسم یکی از اقسام مروارید است .<br /></font></div>'),
(81897, 'ثانیة', '<span class=\"hlight\">ثانیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص، اِ) تأنیث ثانی . <BR><font color=\"Blue\">◄</font> شصت یک از دقیقه و او قسمت میشود به شصت ثالثه (فلک ). <BR><font color=\"Blue\">◄</font> از درجه ٔ دوم . از درجه ٔ ثانیه (اصطلاح طب ). رجوع به درجه شود. ج، ثوانی . <BR><font color=\"Blue\">◄</font> شاة ثانیة؛ گوسفند که گردن کج کند بی علتی .<br /></font></div>'),
(81898, 'ثانیه شمار', '<span class=\"hlight\">ثانیه شمار.</span> <font color=\"DarkGreen\"><b>[ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ش ُ ]</font></b> (نف مرکب، اِ مرکب ) عقربک خرد که ثانیه های دقیقه را در دستگاه ساعت معلوم کند.<br /></font></div>'),
(81899, 'ثاهت', '<span class=\"hlight\">ثاهت .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) حلقوم . <BR><font color=\"Blue\">◄</font> آنچه جنبان باشد از حلقوم . مَلاذة. <BR><font color=\"Blue\">◄</font> بن دندان . <BR><font color=\"Blue\">◄</font> غلاف دل .<br /></font></div>'),
(81900, 'ثاوی', '<span class=\"hlight\">ثاوی .</span> (ع ص ) نعت از ثواء. <BR><font color=\"Blue\">◄</font> فرودآینده . <BR><font color=\"Blue\">◄</font> اقامت دراز کننده . <BR><font color=\"Blue\">◄</font> مقیم <span class=\"hlight\">:</span> بیابانی است خالی از هر ثاوی و انیس و ویرانه ای است تهی از هر ساکن و جلیس . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٥٣</span>).<br /></font></div>'),
(81901, 'ثاویة', '<span class=\"hlight\">ثاویة.</span> <font color=\"DarkGreen\"><b>[ وی ی َ ]</font></b>(ع ص نسبی ) منسوب به ثاء حرف چهارم از حروف هجاء.<br /></font></div>'),
(81902, 'ثاکل', '<span class=\"hlight\">ثاکل .</span> <font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (ع ص، اِ) نعت مذکر و مؤنث از ثکل . <BR><font color=\"Blue\">◄</font> فرزندمرده . <BR><font color=\"Blue\">◄</font> زن یا مرد فرزند یا دوست گم کرده .<br /></font></div>'),
(81903, 'ثاکلة', '<span class=\"hlight\">ثاکلة.</span> <font color=\"DarkGreen\"><b>[ ک ِ ل َ ]</font></b> (ع ص، اِ) زن بچه مرده . ثکلی . ثکول . <BR><font color=\"Blue\">◄</font> هاویه . ج، ثواکل .<br /></font></div>'),
(81904, 'ثای گرچیش', '<span class=\"hlight\">ثای گرچیش .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (اِ) به فارسی هخامنشی نام یکی از سه ماه بهار. (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٩٩</span>).<br /></font></div>'),
(81905, 'ثایب', '<span class=\"hlight\">ثایب .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص، اِ) باد تند که پیش از باران وزد. <BR><font color=\"Blue\">◄</font> باد سخت .<br /></font></div>'),
(81906, 'ثایة', '<span class=\"hlight\">ثایة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع اِ) شوغای گوسفند. آغل گوسپندان و شتران در صحرا یا نزدیک خانه . <BR><font color=\"Blue\">◄</font> سنگ توده ای است پست بقدر مرد نشسته که در صحرا سازند برای نشان . <BR><font color=\"Blue\">◄</font> ثاوة.<br /></font></div>'),
(81907, 'ثایر', '<span class=\"hlight\">ثایر.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) کینه کشنده .<br /></font></div>'),
(81908, 'ثب', '<span class=\"hlight\">ثب .</span> <font color=\"DarkGreen\"><b>[ ث َب ب ]</font></b> (ع مص ) نشستن با تمکین و وقار. <BR><font color=\"Blue\">◄</font> ثَب ّ امر؛ راست و تمام گردیدن کار.<br /></font></div>'),
(81909, 'ثبات', '<span class=\"hlight\">ثبات .</span> <font color=\"DarkGreen\"><b>[ ث َب ْ با ]</font></b> (ع ص، اِ) آنکه در دوائر و ادارات دولتی و شرکتها و تجارتخانه ها نامه های رسیده را در دفاتر مخصوص ثبت کنند.<br /></font></div>'),
(81910, 'ثبات', '<span class=\"hlight\">ثبات .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع اِ) بند برقع. <BR><font color=\"Blue\">◄</font> تسمه و مانند آن که بدان پالان را بندند. دوالی که پالان بدان استوار کنند.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(81911, 'ثبات', '<span class=\"hlight\">ثبات .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) میرمحمد عظیم . یکی از شعراء هندوستان پسر میرمحمد افضل متخلص به ثبات مولد او بسال <span class=\"hlight\" dir=\"rtl\">١١٢٢</span> هَ . ق . در اﷲآباد و وفات وی بسال <span class=\"hlight\" dir=\"rtl\">١١٦١</span> هَ . ق . بوده است و از اشعار اوست :<br />بخت بد گر برد از کوی توام سوی بهشت <br />پرسم از حور که آن سایه ٔ دیوار کجاست .<br /></font></div>'),
(81912, 'ثبات', '<span class=\"hlight\">ثبات .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) ج ِ ثُبة.<br /></font></div>'),
(81913, 'ثبات', '<span class=\"hlight\">ثبات .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b>(ع مص، اِمص ) قرار. استقرار. برجای بودن . بر جای ماندن . قرار گرفتن . ثبوت . توطد. پایداری . استواری . استوار شدن . قیام . (از منتخب از غیاث ). بقا. دوام . پابرجائی . پافشاری . ایستادن . (زوزنی ). سکون <span class=\"hlight\">:</span> <br />همی تاخت تا پیش آب فرات <br />ندید اندر آن پادشاهی ثبات .<br /> <font color=\"Red\">فردوسی .</font><br />اگر خوارزمشاه آن ثبات نکردی ... خللی افتادی بزرگ . (تاریخ بیهقی ).<br />گه وقار و گه جود دست و طبع تراست <br />ثبات تند جبال و مضاء تیز ریاح .<br /> <font color=\"Red\">مسعود.</font><br />ای پادشاه مشرق و مغرب ثبات تو<br />بر تخت پادشاهی سالی هزار باد.<br /> <font color=\"Red\">مسعود.</font><br />آنم به ثبات و وفا که دیدی <br />در چهره و قامت اگر جز آنم .<br /> <font color=\"Red\">مسعود.</font><br />باز در عواقب کارهای عالم تفکری کردم تا روشن گشت که نعمتهای این جهانی چون روشنائی برق است بی دوام و ثبات . (کلیله و دمنه ). و ثبات بر عهد ومیثاقی که با سلطان داشت در سابق الایام فرا می نمود. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>). <BR><font color=\"Blue\">◄</font> صاحب کشاف اصطلاحات الفنون گوید: هو عدم احتمال الزوال بتشکیک المشکک . و قیل هوالجزم المطابق الذی لیس بثبات و هو تقلید المصیب . کذا فی شرح العقاید و حواشیه فی بیان خبرالرسول .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثبات حزم </span> ؛ استواری و هوشیاری در کار <span class=\"hlight\">:</span> ارکان و حدود آن را به ثبات حزم و نفاذ عزم چنان مستحکم و استوار گردانید که چهارصد سال بگذشت . (کلیله و دمنه ص <span class=\"hlight\" dir=\"rtl\">٢٣</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثبات خواهش </span> ؛ پایداری اراده و عزم <span class=\"hlight\">:</span> بیعت کردم بسید خود... از روی اعتقاد و از ته دل براستی نیت و اخلاص درونی و موافقت اعتقاد و ثبات خواهش . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣١٥</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثبات رأی </span> ؛ استواری در رأی . ثبات عزم <span class=\"hlight\">:</span> با آنچه ملک عادل انوشیروان کسری بن قباد را سعادت ذات ... و ثبات رأی حاصل است می بینم که کارهای زمانه میل به ادبار دارد. (کلیله و دمنه ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثبات عزم </span> ؛ استواری در رأی و اراده . ثبات رأی . زماع <span class=\"hlight\">:</span> ثبات عزم صاحب شرع بدان پیوست .(کلیله و دمنه ). و آن را ثبات عزم و حسن عهد نام نکند. (کلیله و دمنه ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثبات قدم </span> ؛ استقامت و پایداری <span class=\"hlight\">:</span> <br />سفله طبعست جهان بر کرمش تکیه مکن <br />ای جهاندیده ثبات قدم از سفله مجوی .<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثبات کردن </span> ؛ پایداری کردن <span class=\"hlight\">:</span> خوارزمشاه میمنه ٔ خود را سوی میسره ٔ ایشان فرستاد نیک ثبات کردند دشمن سخت چیره شد. (تاریخ بیهقی ). احمدثباتی کرد و بزدند او را و بهزیمت رفت . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٤١</span>). اگر سلطان به فراوه رود همانا ایشان ثبات نخواهند کرد. (تاریخ بیهقی <span class=\"hlight\" dir=\"rtl\">٦١٩</span>). و عبداﷲ بیرون آمد لشکر خویش را بیافت پراکنده ... مگر قومی که از اهل و خویش او بودند که با وی ثبات خواستند کرد. (تاریخ بیهقی <span class=\"hlight\" dir=\"rtl\">١٨٧</span>).<BR>۩ ثابت شدن و پایدار ماندن . مداومت کردن . مواظبت کردن <span class=\"hlight\">:</span> با خود گفتم اگر بردین اسلاف بی ایقان و تیقن ثبات کنم همچون آن جادو باشم که بر آن نابکاری مواظبت می نماید. (کلیله و دمنه ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثبات ورزیدن </span> ؛ پای داشتن و مقاومت کردن .<br /></font></div>'),
(81914, 'ثبات', '<span class=\"hlight\">ثبات .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) دردی که آدمی را از حرکت باز دارد: داءُ ثبات ؛ دردی عاجزگرداننده ٔ از حرکت .<br /></font></div>'),
(81915, 'ثباتت', '<span class=\"hlight\">ثباتت .</span> <font color=\"DarkGreen\"><b>[ ث َ ت َ ]</font></b> (ع مص ) ثبوتت . <BR><font color=\"Blue\">◄</font> شجاع و دلاور گردیدن . <BR><font color=\"Blue\">◄</font> ثابت عقل شدن . ثابت رای شدن . <BR><font color=\"Blue\">◄</font> (اِ) بیماریی که زمن کند و از حرکت بازدارد.<br /></font></div>'),
(81916, 'ثباج', '<span class=\"hlight\">ثباج .</span> <font color=\"DarkGreen\"><b>[ ث َب ْ با ]</font></b> (اِخ ) موضعی است در شعر. (مراصد الاطلاع ).<br /></font></div>'),
(81917, 'ثباج', '<span class=\"hlight\">ثباج .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (اِخ ) کوهی است به یمن .<br /></font></div>'),
(81918, 'ثبار', '<span class=\"hlight\">ثبار.</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع اِ) بر ثبار امر بودن ؛ به برآمدن کار نزدیک بودن .<br /></font></div>'),
(81919, 'ثبار', '<span class=\"hlight\">ثبار.</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (اِخ ) موضعی است بر شش میلی خیبر.<br /></font></div>'),
(81920, 'ثبازریطوس', '<span class=\"hlight\">ثبازریطوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) معجونی است که در دردهای هائجه سود دارد.<br /></font></div>'),
(81921, 'ثباش', '<span class=\"hlight\">ثباش .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (اِخ ) از اعلام است .<br /></font></div>'),
(81922, 'ثباط', '<span class=\"hlight\">ثباط.</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع اِ) ج ِ ثَبط.<br /></font></div>'),
(81923, 'ثبان', '<span class=\"hlight\">ثبان .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع مص ) ثبن . ثبین . <BR><font color=\"Blue\">◄</font> درنوشتن عطف جامه و دوختن آن . <BR><font color=\"Blue\">◄</font> در دامن چیزی کرده در برگرفتن . <BR><font color=\"Blue\">◄</font> فراهم آوردن نیفه ٔ ازار رااز پیش . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دامن بر دوختن .(تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> به هر دو دست گرفتن دامن را. <BR><font color=\"Blue\">◄</font> (اِ) آوند. <BR><font color=\"Blue\">◄</font> انبان . <BR><font color=\"Blue\">◄</font> زنبیل . <BR><font color=\"Blue\">◄</font> هر وعائی که در آن چیزی کنند و بجائی برند. رجوع به ثبة شود.<br /></font></div>'),
(81924, 'ثبان', '<span class=\"hlight\">ثبان .</span> <font color=\"DarkGreen\"><b>[ ث ُب ْ با ]</font></b> (اِخ ) از اعلام مردان عرب از جمله پدر سعیدبن ثبان و او محدث است .<br /></font></div>'),
(81925, 'ثبة', '<span class=\"hlight\">ثبة.</span> <font color=\"DarkGreen\"><b>[ ث ُ ب َ ]</font></b> (ع اِ) جماعت . گروه .گروه مردم . <BR><font color=\"Blue\">◄</font> گروه دلاوران . <BR><font color=\"Blue\">◄</font> میانه ٔ حوض که در آن آب گرد آید. ج، ثُبات، ثبون .<br /></font></div>'),
(81926, 'ثبة', '<span class=\"hlight\">ثبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ب َ ]</font></b> (ع اِ) میانه ٔ حوض که آب در آن گرد آید. <BR><font color=\"Blue\">◄</font> جماعت و گروه دلاوران . ج، ثبات و ثبون .<br /></font></div>'),
(81927, 'ثبت', '<span class=\"hlight\">ثبت .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص، ص، اِ) قرار دادن . برجای بودن . ثبوت . استواری . پایداری . <BR><font color=\"Blue\">◄</font> حجت . دلیل . برهان . بینة. سلطان . <BR><font color=\"Blue\">◄</font> نوشتن . <BR><font color=\"Blue\">◄</font> مهر توقیع. <BR><font color=\"Blue\">◄</font> مرد معتمد. <BR><font color=\"Blue\">◄</font> مرد دلاور و قائم بر جای و ثابت رای . <BR><font color=\"Blue\">◄</font> مرد ثابت دل . <BR><font color=\"Blue\">◄</font> مرد ثابت زبان وقت خصومت و جز آن . <BR><font color=\"Blue\">◄</font> و ثبت اگرچه مصدر است گاهی بمعنی مفعول هم میباشد، چنانکه ثبت بمعنی قرار داده شده و نوشته شده و مرقوم می آید. (غیاث ). <BR><font color=\"Blue\">◄</font> نوشته <span class=\"hlight\">:</span> و آن شعرها که خواندند همه در دواوین ثبت است . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٧٦</span>). <BR><font color=\"Blue\">◄</font> استوار. ایستاده برجای مانده .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثبت آمدن </span> ؛ نوشته شدن <span class=\"hlight\">:</span> <br />ظلم کم کن برتن خود تا که ثبت از دست دین <br />آید اندر نامه ٔ عمرت و هم لایظلمون .<br /> <font color=\"Red\">سنائی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثبت برداشتن </span> ؛ صورت برداشتن، سیاهه برداشتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثبت کردن </span> ؛ اثبات . نوشتن <span class=\"hlight\">:</span> نامها اینجا ثبت کنم تا بر آن واقف شده آید. (تاریخ بیهقی ). عتبی میگوید و آن رساله را به اشارت سلطان در ضمن شرح حال امیر نصر ثبت کردم . (ترجمه ٔ تاریخ یمینی <span class=\"hlight\" dir=\"rtl\">٤٤٢</span>). رجوع به تقیید کردن و تعداد کردن شود.<br /></font></div>'),
(81928, 'ثبت', '<span class=\"hlight\">ثبت .</span> <font color=\"DarkGreen\"><b>[ ث َ ب َ ]</font></b> (ع اِ) ثبات و قیام . له ثَبَت ٌ عندالحملة. <BR><font color=\"Blue\">◄</font> دلیل . حجت : لا اَحکم ُ بهذا الاّ به ثَبَت . <BR><font color=\"Blue\">◄</font> مرد ثقه : فلان ثبت من الأثبات و آن مجاز است چنانکه گویند: فلان حجة آنگاه که او در روایت ثقه باشد. (اقرب الموارد). و در اصطلاح درایة، یقال : و أعلی مراتب التعدیل ثقة. و قد یؤکد بالتکریر و اضافة ثبت و ورع و شبههما ممّا یدل ّ علی علوّ شأنه . ثم ّ عدل، ضابط، او ثبت او حافظاو متقن او حجة. (درایة تألیف حسین بن عبدالصمد الحارثی الهمدانی ص <span class=\"hlight\" dir=\"rtl\">١٨٨</span>). ج، اثبات . رجوع به متقن شود.<br /></font></div>'),
(81929, 'ثبت', '<span class=\"hlight\">ثبت .</span> <font color=\"DarkGreen\"><b>[ ث َب ْ ب ِ ]</font></b> (ع ص ) در اصطلاح درایه رجوع به متقن شود.<br /></font></div>'),
(81930, 'ثبت اسناد', '<span class=\"hlight\">ثبت اسناد.</span> <font color=\"DarkGreen\"><b>[ ث َ ت ِ اَ ]</font></b> (ترکیب اضافی، اِ مرکب ) اداره ٔ ثبت اسناد؛ اداره ای که بدانجا اسناد عقود و ایقاعات را در دفاتر رسمی دولتی نویسند تاحجت باشد. <BR><font color=\"Blue\">◄</font> مباشر ثبت . آن کس که شغل ثبت اسناد یا املاک ورزد. ثبات . شروطی . چک نویس . صکاک .<br /></font></div>'),
(81931, 'ثبثب', '<span class=\"hlight\">ثبثب .</span> <font color=\"DarkGreen\"><b>[ ث َث َ ]</font></b> (ع مص ) ثب ّ در همه ٔ معانی آن . (منتهی الارب ).<br /></font></div>'),
(81932, 'ثبج', '<span class=\"hlight\">ثبج .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) تعمیه کردن در بیان چیزی .<br /></font></div>'),
(81933, 'ثبج', '<span class=\"hlight\">ثبج .</span> <font color=\"DarkGreen\"><b>[ ث َب َ ]</font></b> (ع اِ) میان کتف و پشت . <BR><font color=\"Blue\">◄</font> میانه ٔ هر چیز: ثبج بحر؛ میانه ٔ دریا و معظم بحر. <BR><font color=\"Blue\">◄</font> سینه ٔ سنگخوار یعنی سینه ٔ اسفرود. <BR><font color=\"Blue\">◄</font> مرغ حق . شب آهنگ . <BR><font color=\"Blue\">◄</font> مرغی است . ج، اَثباج .<br /></font></div>'),
(81934, 'ثبج', '<span class=\"hlight\">ثبج .</span> <font color=\"DarkGreen\"><b>[ ث َ ب َ ]</font></b> (اِخ ) نام یکی از پادشاهان یمن . گویند او از قوم خود دفاع نکرد تا مغلوب شدند.<br /></font></div>'),
(81935, 'ثبجاره', '<span class=\"hlight\">ثبجاره .</span> <font color=\"DarkGreen\"><b>[ ث ِ رَ ]</font></b> (ع اِ) مغاکچه ای که آنرا آب ناودان کنده باشد.<br /></font></div>'),
(81936, 'ثبر', '<span class=\"hlight\">ثبر.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) منع. بازداشتن از حاجت . (منتهی الارب ). تثبیر. <BR><font color=\"Blue\">◄</font> بدرنگ و بطوء داشتن . <BR><font color=\"Blue\">◄</font> حبس . <BR><font color=\"Blue\">◄</font> لعن . <BR><font color=\"Blue\">◄</font> طرد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثبرقرحه </span> ؛ گشاده شدن ریش و آماس کردن آن . (از منتهی الارب ).<br /></font></div>'),
(81937, 'ثبر', '<span class=\"hlight\">ثبر.</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع مص ) راندن . <BR><font color=\"Blue\">◄</font> ناامید کردن . <BR><font color=\"Blue\">◄</font> بازگشتن آب دریا. جزر، مقابل مدّ.<br /></font></div>'),
(81938, 'ثبر', '<span class=\"hlight\">ثبر.</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (اِخ ) ریگزارهائی است در بلاد بنی نمیر. (مراصد الاطلاع ).<br /></font></div>'),
(81939, 'ثبرات', '<span class=\"hlight\">ثبرات .</span> <font color=\"DarkGreen\"><b>[ ث َ ب َ ]</font></b> (ع اِ) ج ِ ثبرة.<br /></font></div>'),
(81940, 'ثبط', '<span class=\"hlight\">ثبط.</span> <font color=\"DarkGreen\"><b>[ ث َ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ب َ ]</font></b> (ع مص ) ثبط از امر؛ بازداشتن از کار و بر تأخیر و درنگ داشتن کسی را. <BR><font color=\"Blue\">◄</font> آماسیدن، چنانکه لب . <BR><font color=\"Blue\">◄</font> سست و گران بار شدن . <BR><font color=\"Blue\">◄</font> ثبط بر امری ؛ واقف کردن بر کاری .<br /></font></div>'),
(81941, 'ثبط', '<span class=\"hlight\">ثبط.</span> <font color=\"DarkGreen\"><b>[ ث َ ب ِ ]</font></b> (ع ص، اِ) احمق در کار خود. <BR><font color=\"Blue\">◄</font> مرد ضعیف . <BR><font color=\"Blue\">◄</font> مرد گرانبار. <BR><font color=\"Blue\">◄</font> اسب گران و سست . ج، اثباط، ثِباط.<br /></font></div>'),
(81942, 'ثبق', '<span class=\"hlight\">ثبق .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) بسیارآب شدن و تیزرو گردیدن جوی . <BR><font color=\"Blue\">◄</font> ثبق عین ؛ زوداشک شدن چشم .<br /></font></div>'),
(81943, 'ثبل', '<span class=\"hlight\">ثبل .</span> <font color=\"DarkGreen\"><b>[ ث ُ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ب َ ]</font></b> (ع اِ) بقیه ٔ چیزی در ته آوند و غیر آن .<br /></font></div>'),
(81944, 'ثبن', '<span class=\"hlight\">ثبن .</span> <font color=\"DarkGreen\"><b>[ ث ُ ب َ ]</font></b> (ع اِ) ج ِ ثُبنة.<br /></font></div>'),
(81945, 'ثبن', '<span class=\"hlight\">ثبن .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) ثِبان . <BR><font color=\"Blue\">◄</font> درنوشتن عطف جامه و دوختن آن . <BR><font color=\"Blue\">◄</font> دامن بردوختن . <BR><font color=\"Blue\">◄</font> فراهم آوردن نیفه ٔ ازار را از پیش . خبن . <BR><font color=\"Blue\">◄</font> در دامن چیزی کرده در بر گرفتن .<br /></font></div>'),
(81946, 'ثبنة', '<span class=\"hlight\">ثبنة.</span> <font color=\"DarkGreen\"><b>[ ث َ ب ِ ن َ ]</font></b> (اِخ ) موضعی است .<br /></font></div>'),
(81947, 'ثبنة', '<span class=\"hlight\">ثبنة.</span> <font color=\"DarkGreen\"><b>[ ث ُ ن َ ]</font></b> (ع اِ) ثبن . ثبین . ثبان . دامن جامه و مانند آن که در آن خرما و جز آن کرده در بر گیرند. <BR><font color=\"Blue\">◄</font> آنچه در کش گرفته شود. ج، ثُبَن .<br /></font></div>'),
(81948, 'ثبوت', '<span class=\"hlight\">ثبوت .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع مص ) ایستادن . برجای ماندن . بُروک . تبراک . قرار گرفتن . <BR><font color=\"Blue\">◄</font> استوار شدن . پایداری . استقرار. <BR><font color=\"Blue\">◄</font> مداومت . <BR><font color=\"Blue\">◄</font> مواظبت . <BR><font color=\"Blue\">◄</font> ثابت شدن . تحقق . <BR><font color=\"Blue\">◄</font> حکم بوجود نسبت . <BR><font color=\"Blue\">◄</font> ثَبت . صاحب کشاف اصطلاحات الفنون گوید: نزد اشاعره با لفظ کون و وجود مرادف باشد و نزد معتزله اعم از کون است و شرح آن در ذکرلفظ کون بیاید هم چنین در ذکر لفظ معلوم در این باب بیاناتی ایراد شود. و نیز اطلاق بر وقوع و ایقاع نسبت شود. و شرح آن نیز در لفظ نسبت گفته آید - انتهی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">به ثبوت رسانیدن </span> ؛ درست کردن .<br /></font></div>'),
(81949, 'ثبوتت', '<span class=\"hlight\">ثبوتت .</span> <font color=\"DarkGreen\"><b>[ ث ُ ت َ ]</font></b> (ع مص ) ثباتت . <BR><font color=\"Blue\">◄</font> شجاع و دلاور گردیدن . <BR><font color=\"Blue\">◄</font> ثابت رأی شدن .<br /></font></div>'),
(81950, 'ثبوتی', '<span class=\"hlight\">ثبوتی .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b>(اِخ ) شاعری است و او را دیوانی است بترکی وی اشربه و معاجین در بازار قرامان قسطنطنیه میفروخته است .<br /></font></div>'),
(81951, 'ثبوتی', '<span class=\"hlight\">ثبوتی .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ص نسبی ) مقابل سلبی . یطلق علی ما لایکون السلب جزءً من مفهومه و علی ما من شأنه الوجود الخارجی و علی الموجود الخارجی . و یرادف الثبوتی الوجودی . و یجی ٔ فی محله . رجوع به اثباتی شود.<br /></font></div>'),
(81952, 'ثبوتیه', '<span class=\"hlight\">ثبوتیه .</span> <font color=\"DarkGreen\"><b>[ ث ُ تی ی َ ]</font></b> (ع ص نسبی ) تأنیث ثبوتی . مقابل سلبیه : صفات ثبوتیه . رجوع به اثباتی شود.<br /></font></div>'),
(81953, 'ثبور', '<span class=\"hlight\">ثبور.</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِمص ) هلاکی . عذاب . <BR><font color=\"Blue\">◄</font> زیان . خسران . <BR><font color=\"Blue\">◄</font> بازداشتن . <BR><font color=\"Blue\">◄</font> زیان کشیدن . <BR><font color=\"Blue\">◄</font> هلاک گردیدن . <BR><font color=\"Blue\">◄</font> هلاک گردانیدن . هلاک کردن کسی را. <BR><font color=\"Blue\">◄</font> رسیدن سختی و بدی . <BR><font color=\"Blue\">◄</font> واهلاکا گفتن . (غیاث ). ویل ! وای ! <span class=\"hlight\">:</span> <br />بانگ میزد واثبورا واثبور<br />همچو جان کافران در قعر گور.<br /> <font color=\"Red\">مولوی .</font><br />آن چنان کاندر زمستان مردعور<br />او همی لرزید و میگفت ای ثبور.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> مولوی در شعر ذیل ترکیب نان ثبور را بمعنی حق ناشناس آورده است <span class=\"hlight\">:</span> <br />از برای آب جو خصمش شدند<br />آب کور و نان ثبور ایشان بدند.<br /><BR><font color=\"Blue\">◄</font> زفیر. زفره .<br /></font></div>'),
(81954, 'ثبون', '<span class=\"hlight\">ثبون .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) ج ِ ثُبة. جماعات متفرقه .<br /></font></div>'),
(81955, 'ثبیة', '<span class=\"hlight\">ثبیة.</span> <font color=\"DarkGreen\"><b>[ ث ُ ب َی ْ ی َ ]</font></b> (ع اِ مصغر) تصغیر ثُبة و یا آن ثویبة است .<br /></font></div>'),
(81956, 'ثبیت', '<span class=\"hlight\">ثبیت .</span> <font color=\"DarkGreen\"><b>[ ث ُ ب َ ]</font></b> (اِخ ) ابن کثیر. محدث است .<br /></font></div>'),
(81957, 'ثبیت', '<span class=\"hlight\">ثبیت .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص، اِ) نعت از ثبات و ثبوت . <BR><font color=\"Blue\">◄</font> مرد دلاور. <BR><font color=\"Blue\">◄</font> مرد ثابت عقل . <BR><font color=\"Blue\">◄</font> اسب سبک و تیز رو. <BR><font color=\"Blue\">◄</font> ایستاده . برجای مانده . قرارگیرنده .<br /></font></div>'),
(81958, 'ثبیت', '<span class=\"hlight\">ثبیت .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) از اعلام است .<br /></font></div>'),
(81959, 'ثبیتة', '<span class=\"hlight\">ثبیتة.</span> <font color=\"DarkGreen\"><b>[ث ُ ب َ ت َ ]</font></b> (اِخ ) بنت حنظله ٔ اسلمیة. تابعیه است .<br /></font></div>'),
(81960, 'ثبیتة', '<span class=\"hlight\">ثبیتة.</span> <font color=\"DarkGreen\"><b>[ ث ُ ب َ ت َ ]</font></b> (اِخ ) بنت یعار. صحابیه است .<br /></font></div>'),
(81961, 'ثبیتة', '<span class=\"hlight\">ثبیتة.</span> <font color=\"DarkGreen\"><b>[ ث ُ ب َ ت َ ]</font></b> (اِخ ) بنت ضحاک . صحابیه است یا آن نبیتة به نون است . (منتهی الارب ).<br /></font></div>'),
(81962, 'ثبیتی', '<span class=\"hlight\">ثبیتی .</span><font color=\"DarkGreen\"><b>[ ث ُ ب َ ]</font></b> (ص نسبی ) منسوب است به ثبیت که جد ابوالحسن احمدبن محمدبن ثبیت قاضی شیراز باشد. (سمعانی ).<br /></font></div>'),
(81963, 'ثبیر', '<span class=\"hlight\">ثبیر.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) کوهی است بظاهر مکه و از قلل این کوه است : ثبیرالأثبرة. ثبیرالأحدَب . ثبیرالأعرج . ثبیرالخضراء. ثبیرالزنج . ثبیر غینی . ثبیرالنّضع <span class=\"hlight\">:</span> <br />نجنبد ز جا ای پسر چون درخت <br />بباد سحرگاه کوه ثبیر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />یکی سفینه ز علمش هزار بحر محیط<br />یکی دقیقه ز حلمش هزار کوه ثبیر.<br /> <font color=\"Red\">رضی نیشابوری .</font><br />و لقد کان علیه عمره <br />عدل رضوی و ثبیر وحضن .<br /> <font color=\"Red\">قثم بن عباس (از عیون الانباء).</font><br />اصمعی گفته است :ثبیر اعرج مشرف بمکه است به برّ سوی حق الطارقتین و ثبیر غینی در حرا است . (مراصد الاطلاع ). <BR><font color=\"Blue\">◄</font> آبی است بدیار مُزینة و رسول (ص ) آن را بقطیعه شریس بن ضمره داد و نام او را به شریح بگردانید.<br /></font></div>'),
(81964, 'ثبیر غینی', '<span class=\"hlight\">ثبیر غینی .</span> <font color=\"DarkGreen\"><b>[ ث َ رُ غ َ نا ]</font></b> (اِخ ) رجوع به ثبیر شود.<br /></font></div>'),
(81965, 'ثبیرالاحدب', '<span class=\"hlight\">ثبیرالاحدب .</span> <font color=\"DarkGreen\"><b>[ ث َ رُل ْ اَ دَ ]</font></b> (اِخ ) رجوع به ثبیر شود.<br /></font></div>'),
(81966, 'ثبیرالاعرج', '<span class=\"hlight\">ثبیرالاعرج .</span> <font color=\"DarkGreen\"><b>[ ث َ رُل ْ اَ رَ ]</font></b> (اِخ ) رجوع به ثبیر شود.<br /></font></div>'),
(81967, 'ثبیرالزنج', '<span class=\"hlight\">ثبیرالزنج .</span> <font color=\"DarkGreen\"><b>[ ث َ رُزْ زَ ]</font></b> (اِخ ) رجوع به ثبیر شود.<br /></font></div>'),
(81968, 'ثبیرالنضع', '<span class=\"hlight\">ثبیرالنضع.</span> <font color=\"DarkGreen\"><b>[ ث َ رُن ْ ن َ ]</font></b> (اِخ ) رجوع به ثبیر شود.<br /></font></div>'),
(81969, 'ثبیری', '<span class=\"hlight\">ثبیری .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ص نسبی ) منسوب است به ثبیر. (سمعانی ).<br /></font></div>'),
(81970, 'ثبین', '<span class=\"hlight\">ثبین .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) رجوع به ثبنه و ثبان شود.<br /></font></div>'),
(81971, 'ثت', '<span class=\"hlight\">ثت .</span> <font color=\"DarkGreen\"><b>[ ث َت ت ]</font></b> (ع اِ) شکاف در زمین و سنگ . <BR><font color=\"Blue\">◄</font> (مص ) شکافتن زمین . <BR><font color=\"Blue\">◄</font> عیبی در آرامش با زنان . ج، ثتوت .<br /></font></div>'),
(81972, 'ثت گوش', '<span class=\"hlight\">ثت گوش .</span> <font color=\"DarkGreen\"><b>[ ث َ ت َ ش َ ]</font></b> (اِخ ) (ساتاگید) ناحیه ای است از شاهنشاهی ایران در جنوب باختریش (باختر) و آن افغانستان مرکزی است که تقریباً از هرات تا حوالی سند باشد. (ایران باستان ص <span class=\"hlight\" dir=\"rtl\">١٤٥٢</span>).<br /></font></div>'),
(81973, 'ثتا', '<span class=\"hlight\">ثتا.</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (یونانی، اِ) در یونانی نام حرف «ث » باشد و صورت آن این است :<br /><font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٠</span> )</font><br /></font></div>'),
(81974, 'ثتانة', '<span class=\"hlight\">ثتانة.</span> <font color=\"DarkGreen\"><b>[ث ُ ن َ ]</font></b> (اِخ ) موضعی است در شعر. و ثبانة هم روایت شده است و آن در شعر زیدالخیل است . (مراصد الاطلاع ).<br /></font></div>'),
(81975, 'ثتم', '<span class=\"hlight\">ثتم .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) انداختن زن بچه ٔ شکم خود را. <BR><font color=\"Blue\">◄</font> تباه کردن . <BR><font color=\"Blue\">◄</font> ثتم زن خرز خویش را؛ تباه کردن او مهره های خود را: ثتمت المراةُ خرزها؛ یعنی فاسد کرد زن مهره های خود را.<br /></font></div>'),
(81976, 'ثتن', '<span class=\"hlight\">ثتن .</span> <font color=\"DarkGreen\"><b>[ ث َ ت َ ]</font></b> (ع مص ) گنده شدن و بوی گرفتن (گوشت ). <BR><font color=\"Blue\">◄</font> گنده شدن بن دندان و بدبو و فروهشته گردیدن آن .<br /></font></div>'),
(81977, 'ثتن', '<span class=\"hlight\">ثتن .</span> <font color=\"DarkGreen\"><b>[ ث َ ت ِ ]</font></b> (ع ص ) گنده .<br /></font></div>'),
(81978, 'ثتنة', '<span class=\"hlight\">ثتنة.</span> <font color=\"DarkGreen\"><b>[ ث َ ت ِ ن َ ]</font></b> (ع ص ) تأنیث ثَتن . لثه ٔ ثتنه ؛ لثه ٔ بوی گرفته و گنده شده و فروهشته گشته .<br /></font></div>'),
(81979, 'ثتی', '<span class=\"hlight\">ثتی .</span> <font color=\"DarkGreen\"><b>[ ث َ تی <span class=\"hlight\" dir=\"rtl\">/</span> ث َ تا ]</font></b> (ع اِ) پوستهای خرما یا خرمائی که تباه شده از درخت فروریزد و خرمای ردی . <BR><font color=\"Blue\">◄</font> ریزه ٔ کاه و هر چیز ریزه که بدان غراره ها پر کنند.<br /></font></div>'),
(81980, 'ثج', '<span class=\"hlight\">ثج .</span> <font color=\"DarkGreen\"><b>[ ث َج ج ]</font></b> (ع مص ) روان شدن آب . <BR><font color=\"Blue\">◄</font> روان کردن آب و خون قربانی و جز آن . آب ریختن . شریدن آب .<br /></font></div>'),
(81981, 'ثجات', '<span class=\"hlight\">ثجات .</span> <font color=\"DarkGreen\"><b>[ ث َج ْ جا ]</font></b> (ع اِ) ج ِ ثجّة.<br /></font></div>'),
(81982, 'ثجاج', '<span class=\"hlight\">ثجاج .</span> <font color=\"DarkGreen\"><b>[ ث َج ْ جا ]</font></b> (ع ص ) فروریزنده . ریزان . روان شونده . سیّال <span class=\"hlight\">:</span> چون بحر مواج و سیل ثجاج به بلخ آمد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٦٤</span>). بر دفع و انتقام چون برق وهّاج و سیل ثجاج اندرونی از انتقام مشحون با لشکری از قطار باران افزون . (جهانگشای جوینی ).<br /></font></div>'),
(81983, 'ثجر', '<span class=\"hlight\">ثجر.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) آمیختن ثفل خرما با چیز دیگر. <BR><font color=\"Blue\">◄</font> خرما را به کنجاره ٔ غوره ٔ خرما آمیختن . و آن در حدیث است . <BR><font color=\"Blue\">◄</font> روان کردن (آب و جز آن ).<br /></font></div>'),
(81984, 'ثجر', '<span class=\"hlight\">ثجر.</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) ج ِ ثجرة.<br /></font></div>'),
(81985, 'ثجر', '<span class=\"hlight\">ثجر.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) آبی است نزدیک نجران یا مابین وادی القری و شام . <BR><font color=\"Blue\">◄</font> آبی است از بنی القین بن جسر در جوش . (معجم البلدان ).<br /></font></div>'),
(81986, 'ثجر', '<span class=\"hlight\">ثجر.</span> <font color=\"DarkGreen\"><b>[ ث َ ج ِ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ج َ ]</font></b> (ع ص ) سطبر. پهناور.<br /></font></div>'),
(81987, 'ثجر', '<span class=\"hlight\">ثجر.</span> <font color=\"DarkGreen\"><b>[ ث ُ ج َ ]</font></b> (ع اِ) جماعتهای متفرقه . <BR><font color=\"Blue\">◄</font> تیرهای پهناور سطبربیخ .<br /></font></div>'),
(81988, 'ثجل', '<span class=\"hlight\">ثجل .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع ص، اِ) ج ِ ثَجلاء و اَثجل .<br /></font></div>'),
(81989, 'ثجل', '<span class=\"hlight\">ثجل .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (اِخ ) موضعی است به شق ّ عالیه . (مراصد الاطلاع ).<br /></font></div>'),
(81990, 'ثجل', '<span class=\"hlight\">ثجل .</span> <font color=\"DarkGreen\"><b>[ ث َ ج َ ]</font></b> (ع مص ) اَثْجَل گردیدن .<br /></font></div>'),
(81991, 'ثجلة', '<span class=\"hlight\">ثجلة.</span> <font color=\"DarkGreen\"><b>[ ث َ <span class=\"hlight\" dir=\"rtl\">/</span> ث ُ ل َ ]</font></b> (ع مص ) کلانی و فراخی شکم . <BR><font color=\"Blue\">◄</font> بزرگ شکم شدن . فراخ شکم شدن .<br /></font></div>'),
(81992, 'ثجم', '<span class=\"hlight\">ثجم .</span> <font color=\"DarkGreen\"><b>[ ث َ ج َ ]</font></b> (ع مص ) زود برگردیدن .<br /></font></div>'),
(81993, 'ثجم', '<span class=\"hlight\">ثجم .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) زود باریدن و دوام گرفتن باران . <BR><font color=\"Blue\">◄</font> زود بازداشتن از چیزی .<br /></font></div>'),
(81994, 'ثجن', '<span class=\"hlight\">ثجن .</span> <font color=\"DarkGreen\"><b>[ ث َ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ج َ ]</font></b> (ع اِ) راه در زمین سخت و سنگستان .<br /></font></div>'),
(81995, 'ثجو', '<span class=\"hlight\">ثجو.</span> <font color=\"DarkGreen\"><b>[ ث َج ْوْ ]</font></b> (ع مص ) خاموش گردیدن .<br /></font></div>'),
(81996, 'ثجوج', '<span class=\"hlight\">ثجوج .</span> <font color=\"DarkGreen\"><b>[ ث ُ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ]</font></b> (ع مص ) ثج ّ. ثجیج .روان شدن آب و خون به نیرو. (تاج المصادر بیهقی ).<br /></font></div>'),
(81997, 'ثجیج', '<span class=\"hlight\">ثجیج .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) ثج ّ. ثجوج . ریخته شدن آب و خون به نیرو. (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> روان شدن آب و خون و جز آن . <BR><font color=\"Blue\">◄</font> (اِ) سیلاب که توجبه باشد. <BR><font color=\"Blue\">◄</font> (ص ) فروریزنده . <BR><font color=\"Blue\">◄</font> روان شونده .<br /></font></div>'),
(81998, 'ثجیر', '<span class=\"hlight\">ثجیر.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) کنجاره . ثفل . <BR><font color=\"Blue\">◄</font> تکس خرما و انگور. هسته و استخوان انگور. (دهار). دانه ٔ انگور. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> در تحفه ٔ حکیم مؤمن آمده است : لای چیزهای افشرده است و قوتش متوسط است ما بین عصاره و جرم آن چیز و از مطلق ثجیر مراد لای آب انگور است و آن قابض و ضمادش با نمک جهت ورم حار و ورم صلب و ورم پستان و حقنه ٔ او جهت قرحه ٔ امعاء و اسهال مزمن و سیلان رطوبات رحم و آشامیدن برشته کرده ٔ او با دانه های انگور که در او یافت شود جهت قرحه ٔ امعاء و تقویت معده و اسهال بغایت نافع است .<br /></font></div>'),
(81999, 'ثحثاح', '<span class=\"hlight\">ثحثاح .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص ) سریع و شتاب . (منتهی الارب ).<br /></font></div>'),
(82000, 'ثحثحة', '<span class=\"hlight\">ثحثحة.</span> <font color=\"DarkGreen\"><b>[ ث َ ث َ ح َ ]</font></b> (ع اِ) آوازی که در اوگرفتگی باشد نزدیک کام . <BR><font color=\"Blue\">◄</font> آواز گرفته .<br /></font></div>'),
(82001, 'ثحج', '<span class=\"hlight\">ثحج .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) سخت کشیدن چیزی را.<br /></font></div>'),
(82002, 'ثحف', '<span class=\"hlight\">ثحف .</span> <font color=\"DarkGreen\"><b>[ ث ِ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ح ِ ]</font></b> (ع ص ) دارای راهها (در شکنبه ) که گوئی طبقات سرگین است . ج، اثحاف .<br /></font></div>'),
(82003, 'ثخ', '<span class=\"hlight\">ثخ .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) خمیر ترش . خمیرمایه . مایه .<br /></font></div>'),
(82004, 'ثخانت', '<span class=\"hlight\">ثخانت .</span> <font color=\"DarkGreen\"><b>[ ث ِ ن َ ]</font></b> (ع مص ) ثخونت . ثَخن . سطبر و سخت گردیدن . <BR><font color=\"Blue\">◄</font> استوار شدن .<br /></font></div>'),
(82005, 'ثخب', '<span class=\"hlight\">ثخب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) کوهی است به نجد بنی کلاب را و نزدیک آن کوه کان زر و کان مهره ٔ سپید است .<br /></font></div>'),
(82006, 'ثخذ', '<span class=\"hlight\">ثخذ.</span> <font color=\"DarkGreen\"><b>[ ث َ خ ِ ]</font></b> (اِ) صورت و جمله ٔ هفتم از صور و جمل هفت گانه ٔ حروف جُمَّل .<br /></font></div>'),
(82007, 'ثخرط', '<span class=\"hlight\">ثخرط.</span> <font color=\"DarkGreen\"><b>[ ث ِ رِ ]</font></b> (ع اِ) گیاهی است .<br /></font></div>'),
(82008, 'ثخطع', '<span class=\"hlight\">ثخطع.</span> <font color=\"DarkGreen\"><b>[ ث َ طَ ]</font></b> (اِخ ) نامی از نامهای مردان عرب .<br /></font></div>'),
(82009, 'ثخن', '<span class=\"hlight\">ثخن .</span> <font color=\"DarkGreen\"><b>[ ث ُ خ ُ ]</font></b> (ع ص، اِ) ج ِ ثخین . (منتهی الارب ).<br /></font></div>'),
(82010, 'ثخن', '<span class=\"hlight\">ثخن .</span> <font color=\"DarkGreen\"><b>[ ث ِ خ َ ]</font></b> (ع مص، اِمص ) ستبرنا. ستبرا. سطبرا. سطبری . قطر. ضخامت . حجم . دبز. کلفتی . هنگفتی . لُکی . گندگی . غلّت . <BR><font color=\"Blue\">◄</font> غلظت . <BR><font color=\"Blue\">◄</font> سختی . <BR><font color=\"Blue\">◄</font> ثخانت . ثخونت . سطبر و سخت گردیدن . <BR><font color=\"Blue\">◄</font> صاحب کشاف اصطلاحات الفنون گوید: ثخن، بالخاء المعجمه سطبر شدن . کما فی بحر الجواهر و فی کنز اللغات . ثخن سطبری و ثخین سطبر و عندالحکماء هوالجسم التعلیمی و هو حشو یحصره سطح اوسطوح . ای حشو یحیط به سطح واحد کمافی الکرة.اوسطوح ای اکثر من سطح واحد سواء کان سطحان کما فی المخروط المستدیر او سطوح کما فی المکعب . و بالجملة ففی السطح اوالسطوح شیئان . أحدهما الجسم الطبعی المنتهی الی السطوح، و ثانیهما البُعد النافذ فی اقطاره الثلاثة الساری فیها الواقع حشوها و هوالجسم التعلیمی و الثخن . فان کان الثخن نازلاً أی آخذاً من فوق الی اسفل یسمّی عمقا کما فی الماء. و ان کان صاعداً ای آخذاً من الاسفل الی فوق یسمی سمکا کما فی النّبت . و قد یطلق علی الثخن مطلقا سواء کان نازلاً او صاعداً و البعض عرف الثخن بانّه حشوما بین السطوح و فیه انّه منقوض بالکرة اذ لیس له سطوح الا ان یقال ببطلان الجمعیة بدخول لام التعریف . و فی الطّوالع، المقدار ان انقسم فی الجهات الثلث فهوالجسم التعلیمی . و الثخین و الثخن اسم لحشو ما بین السطوح . فان اعتبر نزولاً فعمق، و ان اعتبر صعوداً فسمک . - انتهی . قال السید السند فی حاشیته : اعلم ان الجسم التعلیمی اُتم ّ المقادیر ویسمی ثخناً. لانه حشو مابین السطوح و عمقا اذا اعتبرالنزول لانه ثخن نازل و سمکا اذا اعتبر الصعود فانه ثخن صاعد. هکذا فی شرح الملخص . فعلم ان الجسم التعلیمی لایسمی بالثخین . اذ معناه ذوالثخن . و عرفه بحشو ما بین السطوح و هو نفس الجسم التعلیمی . فلو اطلق علیه الثخین لکان الجسم التعلیمی ذا جسم تعلیمی . و توجیه ما قال ان یحمل الحشو علی المعنی المصدری اعنی التوسط فیکون الجسم التعلیمی ذا توسط - انتهی . و فی شرح الاشارات و حاشیة المحاکمات فی بیان ان ّ للجسم ثخنا متصلاً، ما حاصله ان ّ الثخن مقول بالاشتراک علی حشو ما بین السطوح و علی الامرالذی یقابله رقةالقوام و هو غلظالقوام و هو ایضا حشو ما بین السطوح لکنه صعب الانفصال و کذا الثخین مقول بالاشتراک علی ما هو ذوحشو بین السطوح و هو فصل الجسم التعلیمی یفصله عن الخط و السطح و علی ما یقابل الرّقیق من الاجسام و هو الغلیظ. فان قلت الجسم التعلیمی حشو مابین السطوح و ذوالحشو انما هو الجسم الطبیعی . قلت المراد من الحشو المصدر ای التخلخل و التوسط فالمتخلخل و المتوسط هو الجسم الطبعی و لذا حمل ایضاً علی غلظ القوام، لا علی الغلیظ.<br /></font></div>'),
(82011, 'ثخونت', '<span class=\"hlight\">ثخونت .</span><font color=\"DarkGreen\"><b>[ ث ُ ن َ ]</font></b> (ع مص ) سطبر و سخت گردیدن . ثخانت . ثخن .<br /></font></div>'),
(82012, 'ثخین', '<span class=\"hlight\">ثخین .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص ) سطبر و سخت . <BR><font color=\"Blue\">◄</font> محکم . <BR><font color=\"Blue\">◄</font> غلیظ. <BR><font color=\"Blue\">◄</font> حلیم . بارزانت . رزین . <BR><font color=\"Blue\">◄</font> مردی ثخین السلاح ؛ مردی باسلاح و بعضی گفته اند یقال للاعزل الذی لاسلاح معه، اعزل ثخین، مرد بی سلاح . <BR><font color=\"Blue\">◄</font> ثوب ثخین النسج ؛ جامه ٔ سطبرباف . ج، ثخن .<br /></font></div>'),
(82013, 'ثداء', '<span class=\"hlight\">ثداء.</span> <font color=\"DarkGreen\"><b>[ث ُدْ دا ]</font></b> (ع اِ) گیاهی است و در بیخ آن طرثوث می روید. (منتهی الارب ). ثُداة یکی ثُداء. (منتهی الارب ).<br /></font></div>'),
(82014, 'ثدام', '<span class=\"hlight\">ثدام .</span> <font color=\"DarkGreen\"><b>[ ث َ <span class=\"hlight\" dir=\"rtl\">/</span> ث ِ ]</font></b> (ع اِ) پالونه . (منتهی الارب ). پالاون . ترشی پالا. آبکش . صافی .<br /></font></div>'),
(82015, 'ثدغ', '<span class=\"hlight\">ثدغ .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) ثدغ رأس ؛ شکستن سر را.<br /></font></div>'),
(82016, 'ثدق', '<span class=\"hlight\">ثدق .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) نیک باریدن : ثدق مطر؛ نیک باریدن باران . <BR><font color=\"Blue\">◄</font> ثدق وادی ؛ روان شدن آب . <BR><font color=\"Blue\">◄</font> ثدق خیل ؛ فروگذاشتن خیل را برفتار. <BR><font color=\"Blue\">◄</font> ثدق بطن شاة؛ شکافتن شکم گوسفند.<br /></font></div>'),
(82017, 'ثدقم', '<span class=\"hlight\">ثدقم .</span> <font color=\"DarkGreen\"><b>[ ث ِ ق ِ ]</font></b> (ع ص ) گنگلاج . گنگ و لال .<br /></font></div>'),
(82018, 'ثدقم', '<span class=\"hlight\">ثدقم .</span> <font color=\"DarkGreen\"><b>[ ث ِ ق ِ ]</font></b> (اِخ ) از اعلام مردان است .<br /></font></div>'),
(82019, 'ثدم', '<span class=\"hlight\">ثدم .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص ) گنگلاج . <BR><font color=\"Blue\">◄</font> فربه گول .<br /></font></div>'),
(82020, 'ثدمة', '<span class=\"hlight\">ثدمة.</span> <font color=\"DarkGreen\"><b>[ ث َ م َ ]</font></b> (ع ص ) تأنیث ثدم .<br /></font></div>'),
(82021, 'ثدن', '<span class=\"hlight\">ثدن .</span><font color=\"DarkGreen\"><b>[ ث َ دَ ]</font></b> (ع مص ) بسیارگوشت و گران گردیدن کسی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ثدن لحم ؛ بوی گرفتن گوشت .<br /></font></div>'),
(82022, 'ثدن', '<span class=\"hlight\">ثدن .</span> <font color=\"DarkGreen\"><b>[ ث َ دِ ]</font></b> (ع ص ) فربه . گوشت گن . مرد بسیارگوشت . <BR><font color=\"Blue\">◄</font> متعفن و گندیده .<br /></font></div>'),
(82023, 'ثدنة', '<span class=\"hlight\">ثدنة.</span> <font color=\"DarkGreen\"><b>[ ث َ دِ ن َ ]</font></b> (ع ص ) تأنیت ثدن .<br /></font></div>'),
(82024, 'ثدی', '<span class=\"hlight\">ثدی .</span> <font color=\"DarkGreen\"><b>[ ث َ دا ]</font></b> (ع مص ) بزرگ پستان شدن . <BR><font color=\"Blue\">◄</font> تر کردن . <BR><font color=\"Blue\">◄</font> تر گردیدن .<br /></font></div>'),
(82025, 'ثدی', '<span class=\"hlight\">ثدی .</span> <font color=\"DarkGreen\"><b>[ ث ُ دَی ْ ی َ ]</font></b>(اِخ ) بلفظ تصغیر. محلی است در نجد. و جمیل آن را در شعر خود آورده است و منزل او در شام بود و یاقوت گوید گمان میکنم ثدی هم در شام است . (مراصد الاطلاع ).<br /></font></div>'),
(82026, 'ثدی', '<span class=\"hlight\">ثدی .</span> <font color=\"DarkGreen\"><b>[ ث ِ دی ی ]</font></b> (ع اِ) ج ِ ثَدی .<br /></font></div>'),
(82027, 'ثدی', '<span class=\"hlight\">ثدی .</span> <font color=\"DarkGreen\"><b>[ ث َدْی ْ <span class=\"hlight\" dir=\"rtl\">/</span> ث ِدْی ْ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ دا ]</font></b> (ع اِ) پستان مرد و زن . <BR><font color=\"Blue\">◄</font> پستان زنان یا عام است حیوانات را. ضرع و ابن حاج گوید که پستان مردم را ثدوة گویند و پستان بهائم را ضرع . (غیاث اللغة). ج، اَثد، ثُدی ّ، ثِدی ّ.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">تجوع الحُرّة ولاتأکل ثدییها</span> . ای لاتأکل اجرة الرضاع . و عرب مزد دایگانی را عار میشمردند و مثل در نظائر مورد بکار است .<br /></font></div>'),
(82028, 'ثدیه', '<span class=\"hlight\">ثدیه .</span> <font color=\"DarkGreen\"><b>[ ث ُ دَی ْ ی َ ]</font></b> (ع اِ) چیزی که درآن سواران و تیراندازان پی و پر و مانند آن نهند.<br /></font></div>'),
(82029, 'ثر', '<span class=\"hlight\">ثر.</span> <font color=\"DarkGreen\"><b>[ ث َرر ]</font></b> (ع ص، اِ) مرد بسیارگوی . پرسخن . پرگوی . پرحرف . پرروده . روده دراز. پرچانه . <BR><font color=\"Blue\">◄</font> فراخ . <BR><font color=\"Blue\">◄</font> فرس ثرّ؛ اسب تیزرو. مُنَثَّر. <BR><font color=\"Blue\">◄</font> آب بسیار. <BR><font color=\"Blue\">◄</font> ابر سیاه . <BR><font color=\"Blue\">◄</font> ابر بسیارباران . <BR><font color=\"Blue\">◄</font> ثرورة. ثَرارَت . ثرور. <BR><font color=\"Blue\">◄</font> (مص ) بسیارآب شدن چشمه . <BR><font color=\"Blue\">◄</font> تر کردن زمین . <BR><font color=\"Blue\">◄</font> بسیار خون روان شدن از ریش و خستگی . <BR><font color=\"Blue\">◄</font> بسیارشیر شدن شتر ماده و گوسپند. <BR><font color=\"Blue\">◄</font> پراکندن . پریشان کردن . و رجوع به ثرور شود.<br /></font></div>'),
(82030, 'ثرا', '<span class=\"hlight\">ثرا.</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (اِخ )جائی است بین رویثة و صفراء در پائین وادی حی . یوم ذی ثرا؛ نام یکی از جنگهای عرب است . (مراصد الاطلاع ).<br /></font></div>'),
(82031, 'ثراب', '<span class=\"hlight\">ثراب .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع اِ) ج ِ ثَربة.<br /></font></div>'),
(82032, 'ثرات', '<span class=\"hlight\">ثرات .</span> <font color=\"DarkGreen\"><b>[ ث َرْ را ]</font></b> (ع ص، اِ) ج ِ ثرّة. زنان پرگوی .<br /></font></div>'),
(82033, 'ثراتم', '<span class=\"hlight\">ثراتم .</span> <font color=\"DarkGreen\"><b>[ ث َ ت ِ ]</font></b> (ع اِ) ج ِ ثُرتُم .<br /></font></div>'),
(82034, 'ثراثر', '<span class=\"hlight\">ثراثر.</span> <font color=\"DarkGreen\"><b>[ ث َث ِ ]</font></b> (اِخ ) محلی است در شعر شماخ . (مراصد الاطلاع ).<br /></font></div>'),
(82035, 'ثرار', '<span class=\"hlight\">ثرار.</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع اِ) ج ِ ثَرة و ثرة.<br /></font></div>'),
(82036, 'ثرارت', '<span class=\"hlight\">ثرارت .</span> <font color=\"DarkGreen\"><b>[ ث َ رَ ]</font></b> (ع مص ) ثَرّ. ثُرورَت . ثُرور. رجوع به ثرّ و ثرور شود. <BR><font color=\"Blue\">◄</font> (اِ) چشمه ٔ بسیارآب .<br /></font></div>'),
(82037, 'ثراسابولوس', '<span class=\"hlight\">ثراسابولوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) جالینوس راکتابی است بنام کتاب اًلی ثراسابولوس . (ابن الندیم و قفطی ). این نام بصورت تراسبولوس نیز دیده میشود. واصل آن تراسوبولس است .<br /></font></div>'),
(82038, 'ثراقیه', '<span class=\"hlight\">ثراقیه .</span> <font color=\"DarkGreen\"><b>[ ث َ ی َ ]</font></b> (اِخ ) تراکیه . تراس . ناحیه ای واقع در شمال یونان قدیم که امروز در قسمت جنوبی بلغارستان واقع است و قسمت یونانی نشین ثراقیه که بلغارستان را از دریای گنگبار اِژه جدا میکند و دارای <span class=\"hlight\" dir=\"rtl\">٦٦٩٠٠٠</span> سکنه است .<br /></font></div>'),
(82039, 'ثرام', '<span class=\"hlight\">ثرام .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) پشته ای است به یمن در دیار اوس . (مراصد الاطلاع ).<br /></font></div>'),
(82040, 'ثرایتااونا', '<span class=\"hlight\">ثرایتااونا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ثاثری تئون . صورت نام فریدون پادشاه پیشدادی در اوستا .<br /></font></div>'),
(82041, 'ثرب', '<span class=\"hlight\">ثرب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) (معرب چربی و چربو) چادرپیه و آن آستر و بطانه ٔ صفاق و ابره و ظهاره ٔ معده باشد. و آن پیه رقیقی است که معده و امعاء را فرا گرفته است و از فم معده تا معی قولون بکشد. و صاحب غیاث اللغات گوید: در حدودالامراض بفتحتین است . <BR><font color=\"Blue\">◄</font> خاقانی آنرا بمعنی غش مشک آورده است یعنی ناک <span class=\"hlight\">:</span> <br />خوش نفسی نیست بی گرانی کامروز<br />نافه ٔ بی ثرب در تتار نیابی .<br />ج، ثروب، أثرب . جج، أثارب .<br /></font></div>'),
(82042, 'ثرب', '<span class=\"hlight\">ثرب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) سرزنش کردن . نکوهیدن بر گناه . <BR><font color=\"Blue\">◄</font> ثرب مریض ؛ برکندن جامه ٔ بیمار.<br /></font></div>'),
(82043, 'ثرب', '<span class=\"hlight\">ثرب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) ج ِ ثربَة.<br /></font></div>'),
(82044, 'ثرب', '<span class=\"hlight\">ثرب .</span> <font color=\"DarkGreen\"><b>[ ث َ رِ ]</font></b> (اِخ ) چاهی است محارب را و گاه حاجیان وارد آن شوند برای آب برداشتن و آب آن بسیار بد است . (مراصد الاطلاع ).<br /></font></div>'),
(82045, 'ثربات', '<span class=\"hlight\">ثربات .</span><font color=\"DarkGreen\"><b>[ ث َ رَ ]</font></b> (ع اِ) انگشتان . <BR><font color=\"Blue\">◄</font> ج ِ ثَرب .<br /></font></div>'),
(82046, 'ثرباط', '<span class=\"hlight\">ثرباط.</span> <font color=\"DarkGreen\"><b>[ث ِ ]</font></b> (اِخ ) یا ثُربُط. پدر قبیله ای است از قضاعه .<br /></font></div>'),
(82047, 'ثربان', '<span class=\"hlight\">ثربان .</span> <font color=\"DarkGreen\"><b>[ ث َ رَ ]</font></b> (اِخ ) قلعه ای است از توابع صنعاء یمن . (مراصد الاطلاع ).<br /></font></div>'),
(82048, 'ثربان', '<span class=\"hlight\">ثربان .</span> <font color=\"DarkGreen\"><b>[ ث َ رِ ]</font></b> (اِخ ) دو کوه است در دیار بنی سلیم . (مراصد الاطلاع ).<br /></font></div>'),
(82049, 'ثربة', '<span class=\"hlight\">ثربة.</span><font color=\"DarkGreen\"><b>[ ث َ ب َ ]</font></b> (ع اِ) دنب یا پیه آن . ج، ثَرب، ثِراب .<br /></font></div>'),
(82050, 'ثربط', '<span class=\"hlight\">ثربط.</span> <font color=\"DarkGreen\"><b>[ ث ُب ُ ]</font></b> (اِخ ) یا ثِرباط. پدر قبیله ای است از قضاعة.<br /></font></div>'),
(82051, 'ثربی', '<span class=\"hlight\">ثربی .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ص نسبی ) منسوب به ثرب که چادرپیه باشد. <BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">فتق ثربی </span> . رجوع به فتق شود.<br /></font></div>'),
(82052, 'ثربیه', '<span class=\"hlight\">ثربیه .</span> <font color=\"DarkGreen\"><b>[ ث َ بی ی َ ]</font></b> (ع اِ) (ازکلمه ٔ چربی و چربو) پیه وا، پیه با. (مهذب الاسماء).<br /></font></div>'),
(82053, 'ثرتم', '<span class=\"hlight\">ثرتم .</span> <font color=\"DarkGreen\"><b>[ ث ُ ت ُ ]</font></b>(ع اِ) باقی طعام یا نان خورش در خنور یا در بن کاسه . <BR><font color=\"Blue\">◄</font> آنچه فزون آید از طعام . ج، ثراتِم .<br /></font></div>'),
(82054, 'ثرثار', '<span class=\"hlight\">ثرثار.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) نهر یا وادی بزرگی است که موقع فراوانی باران طولش بسیار بود ولی به تابستان در آن جز برکه های کوچک و چشمه های شور و جزئی آب چیزی نیست و آن در صحرا از نزدیک سنجار سرازیر شده تا به پائین تکریت رسیده از حضر میگذرد و در اطراف آن دیهای بسیار و آبادانی بوده که اکنون خراب است . (مراصد الاطلاع ).<br /></font></div>'),
(82055, 'ثرثار', '<span class=\"hlight\">ثرثار.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص ) بسیارگوی . <BR><font color=\"Blue\">◄</font> بیهوده گوی بسیارفریاد. ج، ثَرثارون، ثرثارین .<br /></font></div>'),
(82056, 'ثرثارون', '<span class=\"hlight\">ثرثارون .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص، اِ) ج ِ ثرثار.<br /></font></div>'),
(82057, 'ثرثارین', '<span class=\"hlight\">ثرثارین .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص، اِ) ج ِ ثرثار.<br /></font></div>'),
(82058, 'ثرثال', '<span class=\"hlight\">ثرثال .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) جد والد احمدبن عبدالعزیزبن احمد محدث بغدادی . او راست جزئی در حدیث .<br /></font></div>'),
(82059, 'ثرثره', '<span class=\"hlight\">ثرثره .</span> <font color=\"DarkGreen\"><b>[ ث َ ث َ رَ ]</font></b> (ع مص ) بسیار گفتن . بیهوده بتکرار حرف زدن . <BR><font color=\"Blue\">◄</font> پراکندن . پریشان کردن . <BR><font color=\"Blue\">◄</font> بسیار خوردن . <BR><font color=\"Blue\">◄</font> آمیختن طعام .<br /></font></div>'),
(82060, 'ثرثور', '<span class=\"hlight\">ثرثور.</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (اِخ ) نام دو نهر است به ارمنستان یکی را ثرثور کبیر و دیگری را ثرثور صغیر گویند بین یکی از آنها و بردعه کمتر از یک فرسخ است . (مراصد الاطلاع ). صاحب قاموس الاعلام گوید: در نزدیک اران و بردعه دو نهر به این نام هست یکی را ثرثور صغیر گویند و این قول یاقوت است در معجم البلدان و در نقشه های امروزی در ارمنستان رودی بنام تَرتَر دیده میشود و ظاهراً این ترتر همان ثرثورجغرافی نویسان عرب است و گویا ثرثور کبیر همین است وشاید ثرثور صغیر شعبه ای از همین ثرثور کبیر باشد.<br /></font></div>'),
(82061, 'ثرد', '<span class=\"hlight\">ثرد.</span> <font color=\"DarkGreen\"><b>[ ث َ رَ ]</font></b> (ع اِمص ) ترکیدگی و کفتگی لب . شکافتگی لب . شکافته شدن لب .<br /></font></div>'),
(82062, 'ثرد', '<span class=\"hlight\">ثرد.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) نان در کاسه شکستن . (تاج المصادر بیهقی ). اشکنه کردن . ترید کردن نان را. <BR><font color=\"Blue\">◄</font> غوطه دادن جامه را در رنگ . <BR><font color=\"Blue\">◄</font> شکستن گردن مذبوح پیش از آنکه سرد شود و این در شرع ممنوع است . <BR><font color=\"Blue\">◄</font> ذبح کردن ذبیحه را با چیزی کند و اوداج آن پاک بریده نشدن . <BR><font color=\"Blue\">◄</font> مجروحی را از معرکه برداشتن که هنوز رمقی در او باقی باشد. <BR><font color=\"Blue\">◄</font> ثرد خصیه ؛ مالیدن آن برای خصی کردن .<br /></font></div>'),
(82063, 'ثرد', '<span class=\"hlight\">ثرد.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) باران نرم ضعیف . <BR><font color=\"Blue\">◄</font> گیاهی است .<br /></font></div>'),
(82064, 'ثردق', '<span class=\"hlight\">ثردق .</span> <font color=\"DarkGreen\"><b>[ ث َ دَ ]</font></b> (اِخ ) دهی است بزرگ قبیله ٔ دَوس را. (منتهی الارب ).<br /></font></div>'),
(82065, 'ثرده', '<span class=\"hlight\">ثرده .</span> <font color=\"DarkGreen\"><b>[ ث ُ دَ ]</font></b>(ع اِ) نان شکسته در کاسه . نان ترید کرده . ثریدة.<br /></font></div>'),
(82066, 'ثرط', '<span class=\"hlight\">ثرط.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) گولی . گول شدن . <BR><font color=\"Blue\">◄</font> عیب کردن . <BR><font color=\"Blue\">◄</font> ثَلط. سرگین انداختن . ریغ زدن . ریخ زدن . <BR><font color=\"Blue\">◄</font> سریش کردن .<br /></font></div>'),
(82067, 'ثرط', '<span class=\"hlight\">ثرط.</span> <font color=\"DarkGreen\"><b>[ ث َ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ رَ ]</font></b> (ع اِ) (ظَ . معرب سریش ) سریش . (از منتخب و صراح ) (غیاث اللغة). سریش کفشگران . <BR><font color=\"Blue\">◄</font> سرگین . ج، ثروط.<br /></font></div>'),
(82068, 'ثرطلة', '<span class=\"hlight\">ثرطلة.</span> <font color=\"DarkGreen\"><b>[ ث َ طَ ل َ ]</font></b> (ع مص ) فروهشتگی و سستی .<br /></font></div>'),
(82069, 'ثرطمه', '<span class=\"hlight\">ثرطمه .</span> <font color=\"DarkGreen\"><b>[ ث َ طَ م َ ]</font></b> (ع مص ) سرنگون کردن نه از غضب و تکبر. <BR><font color=\"Blue\">◄</font> بسیار فربه شدن چنانکه ستور.<br /></font></div>'),
(82070, 'ثرع', '<span class=\"hlight\">ثرع .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) طفیلی شدن قوم را.<br /></font></div>'),
(82071, 'ثرعط', '<span class=\"hlight\">ثرعط.</span> <font color=\"DarkGreen\"><b>[ث ُ ع ُ ]</font></b> (ع ص ) طین ثرعط؛ گل تُنک و رقیق . ثرعُطط.<br /></font></div>'),
(82072, 'ثرعطط', '<span class=\"hlight\">ثرعطط.</span> <font color=\"DarkGreen\"><b>[ ث ُ رُ طُ ]</font></b> (ع ص ) طین ثرعطط؛ گل تُنک . <BR><font color=\"Blue\">◄</font> آشامیدنی رقیق . ثرعطه . ثرعطیطة.<br /></font></div>'),
(82073, 'ثرعطه', '<span class=\"hlight\">ثرعطه .</span> <font color=\"DarkGreen\"><b>[ ث ُ ع ُ طَ ]</font></b> (ع اِ) آشامیدنی رقیق .<br /></font></div>'),
(82074, 'ثرعلة', '<span class=\"hlight\">ثرعلة.</span> <font color=\"DarkGreen\"><b>[ ث ُ ع ُ ل َ ]</font></b> (ع اِ) پرهای گردن خروس .<br /></font></div>'),
(82075, 'ثرغ', '<span class=\"hlight\">ثرغ .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) فراخ شدن مخرج آب از دلو و جز آن . ج، ثُرُوغ .<br /></font></div>'),
(82076, 'ثرغامه', '<span class=\"hlight\">ثرغامه .</span> <font color=\"DarkGreen\"><b>[ ث ِ م َ ]</font></b> (ع اِ) زوجه . زن . (منتهی الارب ).<br /></font></div>'),
(82077, 'ثرغل', '<span class=\"hlight\">ثرغل .</span> <font color=\"DarkGreen\"><b>[ ث ُ غ ُ ]</font></b> (ع اِ) روباه ماده .<br /></font></div>'),
(82078, 'ثرغول', '<span class=\"hlight\">ثرغول .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) گیاهی است .<br /></font></div>'),
(82079, 'ثرقبی', '<span class=\"hlight\">ثرقبی .</span> <font color=\"DarkGreen\"><b>[ ث ُ ق ُ ]</font></b> (ع ص نسبی، اِ) قُرقُبی . قُرقوبی . نوعی جامه ٔ سپید مصری است که از کتان بافند.<br /></font></div>'),
(82080, 'ثرقبیه', '<span class=\"hlight\">ثرقبیه .</span> <font color=\"DarkGreen\"><b>[ ث ُ ق ُ بی ی َ]</font></b> (ع ص نسبی، اِ) نوعی از جامه های سپید مصری است که از کتان بافند. ثوب ثرقبی و قُرقبی . پارچه ٔ مصری .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(82081, 'ثرم', '<span class=\"hlight\">ثرم .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص )شکستن دندان کسی را به زدن . <BR><font color=\"Blue\">◄</font> افتادن دندان . <BR><font color=\"Blue\">◄</font> (اصطلاح عروض ) اجتماع قبض و ثلم است در فعولن عول ُ بماند فعل بسکون عین و ضم ّ لام بجای آن بنهند و ثرم در اشعار عجم نیاید. (المعجم ). و صاحب کشاف اصطلاحات الفنون گوید: نزد عروضیان اجتماع خرم و قبض باشد. چنانکه در عنوان الشرف مذکور است و در پاره ای از رسائل عروض اهل عرب آمده که خرم بعد از قبض اگر در فعولن واقع شود آنرا شتر خوانند - انتهی . وعبارة عنوان الشرف را باید حمل بر تعریف دومین کرد.بدلیل اینکه صاحب عنوان الشرف شتر را تعریف کرده بعین تعریفی که در ثرم کرده . و اگر چنین حمل نکنیم لازم می آید که ثرم و شتر در تعریف و سایر خصوصیات یکسان باشند. و سید جرجانی در تعریفات گفته که ثرم عبارت است از حذف فاء و نون از فعولن تا فقط عول باقی ماند که بتوان آنرا به فعل نقل کرد که این عمل ثرم است .<br /></font></div>'),
(82082, 'ثرم', '<span class=\"hlight\">ثرم .</span> <font color=\"DarkGreen\"><b>[ث َ رَ ]</font></b> (اِخ ) کوهی است به یمامة. (مراصد الاطلاع ).<br /></font></div>'),
(82083, 'ثرم', '<span class=\"hlight\">ثرم .</span> <font color=\"DarkGreen\"><b>[ ث َ رَ ]</font></b> (ع مص ) اثرم گردیدن . افتادن دندان از ثنایا و رباعیات . دندان پیشین کسی شکستن . بردهن زدن چنانکه دندان بیفتد.<br /></font></div>'),
(82084, 'ثرمان', '<span class=\"hlight\">ثرمان .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِ) درختی است که به اشنان ماند و آن ترش است و شتران و گوسفندان خورند.<br /></font></div>'),
(82085, 'ثرمة', '<span class=\"hlight\">ثرمة.</span> <font color=\"DarkGreen\"><b>[ ث َ <span class=\"hlight\" dir=\"rtl\">/</span> ث ِ م َ ]</font></b> (اِخ ) شهر کوچکی است در ساحل شمالی جزیره ٔ صقلیه نزدیک شفلوی . (رحله ٔ ابن جبیر). کیکش بسیار و گرمایش شدید است . (مراصد الاطلاع ). این نام از یونانی ترمس بمعنی آب گرم معدنی و حمّه .<br /></font></div>'),
(82086, 'ثرمد', '<span class=\"hlight\">ثرمد.</span> <font color=\"DarkGreen\"><b>[ ث َ م َ ]</font></b> (اِخ ) شعبی است در کوه اجاء از بنی ثعلبه گویند آبی است . (مراصد الاطلاع ).<br /></font></div>'),
(82087, 'ثرمط', '<span class=\"hlight\">ثرمط.</span> <font color=\"DarkGreen\"><b>[ ث ِ م ِ ]</font></b> (ع ص ) نعجةثرمط؛ میش ماده ٔ بزرگ که از خائیدنش آوازی برآید.<br /></font></div>'),
(82088, 'ثرمط', '<span class=\"hlight\">ثرمط.</span> <font color=\"DarkGreen\"><b>[ ث ُ رَ م ِ ]</font></b> (ع اِ) گِل تر یا رقیق آبناک . ثرمطة.<br /></font></div>'),
(82089, 'ثرمل', '<span class=\"hlight\">ثرمل .</span> <font color=\"DarkGreen\"><b>[ ث ُ م ُ ]</font></b> (ع اِ) جانوری است .<br /></font></div>'),
(82090, 'ثرملة', '<span class=\"hlight\">ثرملة.</span> <font color=\"DarkGreen\"><b>[ ث َ م َ ل َ ]</font></b> (ع مص ) ریخ زدن . <BR><font color=\"Blue\">◄</font> خوردن گوشت که هنوز پخته نباشد. <BR><font color=\"Blue\">◄</font> خام داشتن طعام . <BR><font color=\"Blue\">◄</font> آوردن نان آلوده بخاکستر از عجلت مهمانی . <BR><font color=\"Blue\">◄</font> تباه خوردن طعام چنانکه لحیه و پیرامون دهان بیالاید. دژ آلود خوردن یعنی بی ادب و پریشان خوردن . <BR><font color=\"Blue\">◄</font> ثَرمَل َالقوم من الطعام ؛ ای أکلوا ما شاؤوا. <BR><font color=\"Blue\">◄</font> ریزه کاری ناکردن در کار. سنبل کردن . (در تداول عوام ).<br /></font></div>'),
(82091, 'ثرملة', '<span class=\"hlight\">ثرملة.</span> <font color=\"DarkGreen\"><b>[ ث ُ م ُ ل َ ]</font></b> (اِخ ) نام شاعری از ظبی . (منتهی الارب ).<br /></font></div>'),
(82092, 'ثرملة', '<span class=\"hlight\">ثرملة.</span> <font color=\"DarkGreen\"><b>[ ث ُ م ُ ل َ ]</font></b> (ع اِ) چاهک لب . <BR><font color=\"Blue\">◄</font> چیزی باقی مانده در خنور. <BR><font color=\"Blue\">◄</font> روباه ماده .<br /></font></div>'),
(82093, 'ثرملیة', '<span class=\"hlight\">ثرملیة.</span> <font color=\"DarkGreen\"><b>[ ث ُ م ُ لی ی َ ]</font></b> (اِخ ) آبی است از بنی عطارد در یمامه . (معجم البلدان ).<br /></font></div>'),
(82094, 'ثرن', '<span class=\"hlight\">ثرن .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) رنجانیدن دوست و همسایه ٔ خود را.<br /></font></div>'),
(82095, 'ثرنطی', '<span class=\"hlight\">ثرنطی .</span> <font color=\"DarkGreen\"><b>[ ث َ رَ طا ]</font></b> (ع ص، اِ) مرد احمق گران .<br /></font></div>'),
(82096, 'ثرو', '<span class=\"hlight\">ثرو.</span> <font color=\"DarkGreen\"><b>[ ث َرْوْ ]</font></b> (ع مص ) بسیار شدن . <BR><font color=\"Blue\">◄</font> بسیار گردانیدن . بسیار عدد گردانیدن چیزی را. <BR><font color=\"Blue\">◄</font> زیاده کردن مال و غیر آن . <BR><font color=\"Blue\">◄</font> به بسیاری غلبه کردن . (تاج المصادر بیهقی ).<br /></font></div>'),
(82097, 'ثروان', '<span class=\"hlight\">ثروان .</span> <font color=\"DarkGreen\"><b>[ ث َرْ ]</font></b> (ع ص، اِ) مرد بسیارمال .<br /></font></div>'),
(82098, 'ثروان', '<span class=\"hlight\">ثروان .</span> <font color=\"DarkGreen\"><b>[ ث َرْ ]</font></b> (اِخ ) نامی از نامهای مردان عرب .<br /></font></div>'),
(82099, 'ثروان', '<span class=\"hlight\">ثروان .</span> <font color=\"DarkGreen\"><b>[ ث َرْ ]</font></b> (اِخ ) ابن فزارةبن عبد یغوث . صحابی است . و بیت ذیل را گاه درک صحبت رسول صلوات اﷲ علیه سروده است :<br />الیک رسول اﷲ خبت مطیتی <br />مسافة ارباع تروح و تغتدی .<br /></font></div>'),
(82100, 'ثروان', '<span class=\"hlight\">ثروان .</span> <font color=\"DarkGreen\"><b>[ ث َرْ ]</font></b> (اِخ ) کوهی است از بنی سلیم . (مراصد الاطلاع ).<br /></font></div>'),
(82101, 'ثروان', '<span class=\"hlight\">ثروان .</span> <font color=\"DarkGreen\"><b>[ ث َ رَ ]</font></b> (ع اِ) رجوع به ثَریان شود.<br /></font></div>'),
(82102, 'ثروب', '<span class=\"hlight\">ثروب .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) ج ِ ثَرب .<br /></font></div>'),
(82103, 'ثروت', '<span class=\"hlight\">ثروت .</span> <font color=\"DarkGreen\"><b>[ ث َرْ وَ ]</font></b> (ع اِ) ثراء. دارائی . توانگری . کثرت مال . مال . مکنت . نعمت . دولت . هستی . ذروت <span class=\"hlight\">:</span> <br />با کرم او الف که هیچ ندارد<br />در سرش اکنون هوای ثروت شین است .<br /> <font color=\"Red\">انوری .</font><br />اسلاف او در ایام آل سامان به ثروت تمام و حرمت موفور مشهور بودند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٣٥</span>).<br />این دعا می کرد دایم کای خدا<br />ثروتی بی رنج روزی کن مرا.<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> بسیاری مردم . بسیار عدد از مردم : انه لذو ثروة من مال و رجال . <BR><font color=\"Blue\">◄</font> شبی که ماه و پروین با هم جمع شوند. <BR><font color=\"Blue\">◄</font> مهتری . (غیاث اللغة). <BR><font color=\"Blue\">◄</font> ثروت یا علم ثروت، علم اقتصاد، علم تولید و تقسیم و مصرف ثروت، و در این مورد ثروت عبارت است از انواع دارائی آدمی از کالا و خواربار و ابزار و ماشین آلات و راه آهن و غیره .<br /></font></div>'),
(82104, 'ثروت افندی', '<span class=\"hlight\">ثروت افندی .</span> <font color=\"DarkGreen\"><b>[ ث َرْ وَ اَ ف َ ]</font></b> (اِخ ) یکی از شعرای متأخر عثمانی است و مولد او استانبول است . او در اندرون همایون تربیت شده و در <span class=\"hlight\" dir=\"rtl\">١٢٨٠</span> به مرعش وفات کرده است و دیوان کوچکی دارد. (قاموس الاعلام ).<br /></font></div>'),
(82105, 'ثروت مند', '<span class=\"hlight\">ثروت مند.</span> <font color=\"DarkGreen\"><b>[ ث َرْ وَ م َ ]</font></b> (ص مرکب ) دارا. توانگر. مالدار.<br /></font></div>'),
(82106, 'ثرور', '<span class=\"hlight\">ثرور.</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (اِخ ) یکی از نواحی طائف است . (مراصد الاطلاع ).<br /></font></div>'),
(82107, 'ثرور', '<span class=\"hlight\">ثرور.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) ثرّ. ثرارت . ثرورت . ثرور ناقه ؛ بسیارشیر شدن و فراخ سوراخ پستان شدن اشتر ماده و همچنین است ثرور عین، و ثرور طَعنه . <BR><font color=\"Blue\">◄</font> (ص، اِ) ناقه یا گوسفند بسیار شیر و فراخ سوراخ پستان .<br /></font></div>'),
(82108, 'ثرور', '<span class=\"hlight\">ثرور.</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع ص، اِ) ج ِ ثَرّة.<br /></font></div>'),
(82109, 'ثرورت', '<span class=\"hlight\">ثرورت .</span> <font color=\"DarkGreen\"><b>[ ث ُ رَ ]</font></b> (ع مص ) ثرارت . ثرّ. ثرور. رجوع به ثر و ثُرور شود.<br /></font></div>'),
(82110, 'ثروغ', '<span class=\"hlight\">ثروغ .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) ج ِ ثَرغ .<br /></font></div>'),
(82111, 'ثروق', '<span class=\"hlight\">ثروق .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (اِخ ) نام دهی است از بنی دوس . معجم البلدان . (مراصد الاطلاع ). و رجوع به ثردق شود.<br /></font></div>'),
(82112, 'ثروی', '<span class=\"hlight\">ثروی .</span> <font color=\"DarkGreen\"><b>[ ث َرْ وا ]</font></b> (ع ص، اِ) زن بسیارمال . مقابل اثری، مرد بسیارمال .<br /></font></div>'),
(82113, 'ثری', '<span class=\"hlight\">ثری .</span> <font color=\"DarkGreen\"><b>[ ث َری ی ]</font></b> (ع ص، اِ) توانگری . <BR><font color=\"Blue\">◄</font> مال بسیار. <BR><font color=\"Blue\">◄</font> غنی . توانگر: رجل ثری ؛ مرد بسیارمال .<br /></font></div>'),
(82114, 'ثری', '<span class=\"hlight\">ثری .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) مماله ثری بمعنی خاک و زمین <span class=\"hlight\">:</span> <br />هر که او را بتو مانند کند هیچکس است <br />باز نشناسد گوینده بهی از بتری <br />تا مجره ز بلندی نکند قصد نشیب <br />تا ثریا بزیارت نشود سوی ثری .<br /> <font color=\"Red\">فرخی .</font><br />وحشی مکر برجهد بکمر<br />دمنه ٔ حیله در خزد بثری .<br /> <font color=\"Red\">ابوالفرج .</font><br />چارکس یابی که مهجومنند<br />گر بجوئی از ثریا تا ثری .<br /> <font color=\"Red\">انوری .</font><br />کوه برفی میزند بر دیگری <br />میرساند برف سردی ثری .<br /> <font color=\"Red\">مولوی .</font><br />هر یک آهنگش ز کرسی تا ثریست <br />وز ثری تا عرش درکروفریست .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(82115, 'ثری', '<span class=\"hlight\">ثری .</span> <font color=\"DarkGreen\"><b>[ ث َ را ]</font></b> (ع اِ) (این ماده مثل این مینماید که از تر مقابل خشک فارسی مأخوذ است ). تری زمین . رطوبت . <BR><font color=\"Blue\">◄</font> خاک نمناک یا خاکی که اگرتر گردانند چفسنده نگردد. خاک نم دار. خاک نمگن . <BR><font color=\"Blue\">◄</font> زیر زمین . (غیاث ). زمین . خاک <span class=\"hlight\">:</span> <br />همت تیز و بلند تو بدانجای رسید<br />که ثری گشت مراو را فلک فیرونا.<br /> <font color=\"Red\">خسروانی .</font><br />چو خورشید از پرده بالا گرفت <br />جهان از ثری تا ثریا گرفت .<br /> <font color=\"Red\">فردوسی .</font><br />آن کن که خرد کند اشارت <br />تا برشوی از ثری به کیوان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />برآمدش ز کمال تو بر ثریا سر<br />چو کوه خاراش اندر ثری فروشد لاد.<br /> <font color=\"Red\">مسعود.</font><br />ز جرم جرم نماند اثر برحمت تو<br />اگر بود ز ثری جرم تا اثیر مرا.<br /> <font color=\"Red\">سوزنی .</font><br />چندان بریخت خنجرشان خون دشمنان <br />کاجزاء خاک تا به ثری جمله در نم است .<br /> <font color=\"Red\">(ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١٦١</span>).</font><br />نور حسی میکشد سوی ثری <br />نور حقش می برد سوی علا.<br /> <font color=\"Red\">مولوی .</font><br />بر همان بو میخوری این خشک را<br />بعد از آن کامیخت معنی باثری .<br /> <font color=\"Red\">مولوی .</font><br />آدم خاکی برو تو برسما<br />ای بلیس آتشی رو تا ثری .<br /> <font color=\"Red\">مولوی .</font><br />میکند توحید تو بهر ثنا<br />هر چه هست است از ثریا تا ثری .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">از ثری تا بثریا</span> ؛ از زیر زمین تا بالای آسمان . <BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاب ثراه </span> ؛ پاک باد خاک او.<br /><BR><font color=\"Blue\">◄</font> شهر ثری ؛ ماهی که باران آیدو نبات بدمد. اصمعی گوید عرب گویند: شهر ثری و شهر تری و شهر ثری و شهر قرعی ؛ أی تمطر اولاً ثم یطلع النبات فترویه ثم یطول فترعاه . الغنم . <BR><font color=\"Blue\">◄</font> خیر. نیکوئی . احسان . <BR><font color=\"Blue\">◄</font> خوی . عرق . ج، اثراء.<br /></font></div>'),
(82116, 'ثری', '<span class=\"hlight\">ثری .</span> <font color=\"DarkGreen\"><b>[ ث ِ را ]</font></b> (اِخ ) موضعی است میان روَیثه و صُفرا. (منتهی الارب ).<br /></font></div>'),
(82117, 'ثری', '<span class=\"hlight\">ثری .</span> <font color=\"DarkGreen\"><b>[ ث َرْی ْ ]</font></b>(ع مص ) ثری أرض ؛ ترونم دار شدن زمین بعد خشکی آن .<br /></font></div>'),
(82118, 'ثریا', '<span class=\"hlight\">ثریا.</span> <font color=\"DarkGreen\"><b>[ ث ُ رَی ْ یا ]</font></b> (اِخ ) نام چاهی است در مکه از بنی تمیم بن مره . <BR><font color=\"Blue\">◄</font> آبهائی است از بنی محارب در شعبی . <BR><font color=\"Blue\">◄</font> آبی است از بنی ضباب در حمی ضریة. <BR><font color=\"Blue\">◄</font> قصری است که معتضد نزدیک تاج بنا کرد بدومیلی آنجا. (مراصد الاطلاع ).<br /></font></div>'),
(82119, 'ثریا', '<span class=\"hlight\">ثریا.</span> <font color=\"DarkGreen\"><b>[ ث ُ رَی ْ یا ]</font></b> (اِخ ) نام کتابی است که مؤلف آن شناخته نشد. ابوریحان بیرونی فقره ای از آن نقل کرده است . (کتاب الجماهر ص <span class=\"hlight\" dir=\"rtl\">١٩١</span>).<br /></font></div>'),
(82120, 'ثریا', '<span class=\"hlight\">ثریا.</span> <font color=\"DarkGreen\"><b>[ ث ُ رَی ْ یا ]</font></b> (اِخ ) الهانی بن احمد. محدث است .<br /></font></div>'),
(82121, 'ثریا', '<span class=\"hlight\">ثریا.</span> <font color=\"DarkGreen\"><b>[ ث ُ رَی ْ یا ]</font></b> (ع ص، اِ) مصغر ثروی . <BR><font color=\"Blue\">◄</font> (اِخ ) پروین پرن . پرند. پرو. پروه . رَفه . رَمه . نرگسه . نرگسه ٔ چرخ . نرگسه ٔ سقف لاجورد. و آن منزل سوم است از منازل قمر پس از بطین و پیش از دبران و آن شش ستاره است برکوهان ثور. عرب جای آنرا بر دنبه ٔ حمل (ألیةالحمل ) تو هم کند و ثریا را نجم نیز نامند. مؤلف غیاث اللغة گوید: پروین . و آن شش ستاره است متصل همدیگر و آن منزل سوم است ازمنازل قمر در اصل لغت تصغیر ثروی که صیغه ٔ مؤنث افعل التفضیل است مشتق از ثرا که بمعنی کثرت است چون در ستارگان مذکور قدری کثرتست لهذا بدین اسم مسمی گشت . از صراح . و در بیرجندی شرح بیست باب آمده است که تصغیر در ثریا بلحاظ خردی کواکب اوست یا این تصغیر بجهت تعظیم باشد. و ثریا رقیب اکلیل است و گویند رقیب عیوق است . و منزل سیم است از منازل قمر و آن از آخر بطین است تا هشت درجه و سی و چهار دقیقه و هفده ثانیه از ثور. و این منزلی است میانه ٔ سعد و نحس نزد احکامیان . مؤلف یواقیت العلوم گوید <span class=\"hlight\">:</span> ثریا و آن در یازدهم تشرین الاخر فروشود - انتهی <span class=\"hlight\">:</span> <br />همه روی صحرا چو دریا کنیم <br />ز خورشید تابان ثریا کنیم .<br /> <font color=\"Red\">فردوسی .</font><br />جهان را شب از روز پیدا نبود<br />تو گفتی سپهر و ثریا نبود.<br /> <font color=\"Red\">فردوسی .</font><br />همه رودها همچو دریا شده <br />بپالیز گل چون ثریا شده .<br /> <font color=\"Red\">فردوسی .</font><br />ز کین روی ایران چو دریا کنیم <br />نشست ترا بر ثریا کنیم .<br /> <font color=\"Red\">فردوسی .</font><br />سراندر ثریا یکی کوه دید<br />تو گفتی ستاره بخواهد کشید.<br /> <font color=\"Red\">فردوسی .</font><br />که گفتی که هامون چو دریا کند<br />سر خویش را بر ثریا کند.<br /> <font color=\"Red\">فردوسی .</font><br />بکردار ماهی بدریا شود<br />سر بدکنش بر ثریا شود.<br /> <font color=\"Red\">فردوسی .</font><br />تو گفتی ز خون دشت دریا شده ست <br />ز خنجر هوا چون ثریا شده ست .<br /> <font color=\"Red\">فردوسی .</font><br />من این دشت جهرم چو دریا کنم <br />ز خورشید تابان ثریا کنم .<br /> <font color=\"Red\">فردوسی .</font><br />ثریا چون منیژه بر سر چاه <br />دو چشم من بر او چون چشم بیژن .<br /> <font color=\"Red\">منوچهری .</font><br />وان ثریا چون ز دست جبرئیل <br />مانده نوری بر قفای اهرمن .<br /> <font color=\"Red\">ناصرخسرو.</font><br />چو بر روی فرعون بر دست موسی <br />بروی فلک بر ثریا منور.<br /> <font color=\"Red\">ناصرخسرو.</font><br />بستان ز نوشکوفه چو گردون شد<br />تا نسترن بسان ثریا شد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />بر آمدش زکمال تو بر ثریا سر<br />چو کوه خاراش اندر ثری فرو شدلاد.<br /> <font color=\"Red\">مسعود.</font><br />کی پشه تواند که ثریا بیند<br />یا مورچه ای گلشن خضرا بیند.<br /> <font color=\"Red\">عطار.</font><br />ازثریا گر بپرد تا ثری <br />نرم گردد چون ببیند او مرا.<br /> <font color=\"Red\">مولوی .</font><br />عقد ثریا از تاکش آویخته .<br /> <font color=\"Red\">سعدی (گلستان ).</font><br />از بام خانه تا بثریا از آن تو.<br /> <font color=\"Red\">وحشی .</font><br />کین تو برآمد بثریا و بعیوق <br />لرزان شد و پیچان شد عیوق و ثریا<br />از برای سم ّ یکرانش به هر سی روز چرخ <br />از مه نو نعل و مسمار از ثریا ساخته .<br /> <font color=\"Red\">مبارک شاه غزنوی .</font><br />ثنا میکنم ایزد پاک را<br />ثریاده طارم تاک را.<br /> <font color=\"Red\">ظهوری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">برج ثریا</span> ؛ دهان شاهدان و خوبان و نیز برج ثور <span class=\"hlight\">:</span> <br />آخر تو آسمان شکنی یا کمرشکن <br />از درج درّ و برج ثریا چه خواستی .<br /> <font color=\"Red\">خاقانی .</font><br />و رجوع به پروین شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کاری به ثریا رسیدن </span> ؛ یعنی به اوج خود رسیدن و بالا گرفتن <span class=\"hlight\">:</span> در مدتی نزدیک کار او به ثریا رسید. (ترجمه ٔ تاریخ یمینی <span class=\"hlight\" dir=\"rtl\">٤٣٨</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل ثریا</span> ؛ مجموع . گرد. فراهم . مجتمع.<br /><BR><font color=\"Blue\">◄</font> (اِ) صاحب تحفه یعنی حکیم مؤمن گوید ثریا، به لغت اندلس ایرفارون است . در فهرست مخزن الادویه آمده است که : ثریابلغت اندلس ایفارون است و چنانکه ظاهر است ثریا و مرادف آن ایفارون یا ایری فارون نام گیاهی یا داروئی است . لکن معنی هردو بر نگارنده مجهول است . <BR><font color=\"Blue\">◄</font> نامی از نامهای زنان . <BR><font color=\"Blue\">◄</font> به استعاره . دندان معشوق و گوهر آبدار: و کنا باجتماع کالثریا فصیّرنا الزمان بنات نعش .<br /></font></div>'),
(82122, 'ثریا جاه', '<span class=\"hlight\">ثریا جاه .</span> <font color=\"DarkGreen\"><b>[ ث ُ رَی ْیا ]</font></b> (اِخ ) تخلص امجدعلی شاه یکی از حکمرانان اوده ٔ هندوستان . رجوع به امجدعلی شاه شود. (قاموس الاعلام ).<br /></font></div>'),
(82123, 'ثریا پاشا', '<span class=\"hlight\">ثریا پاشا.</span> <font color=\"DarkGreen\"><b>[ ث ُ رَی ْ یا ]</font></b> (اِخ ) یکی از وزرای دولت عثمانی پسر عثمان پاشای گمرک چی . مولد او بسال <span class=\"hlight\" dir=\"rtl\">١٢٤١</span> هَ . ق . در اسلامبول . او پس از اکمال تحصیلات در باب عالی عضو مضبطه ٔ همایونی شد و بواسطه ٔ حسن کفایت و استعداد ذاتی مأموریتهای گوناگون یافت از جمله ریاست کمیسیون روسیه که برای ماده ٔ «کولیروز» بروسیه رفته بودند سپس بسمت منشی اول سفارت عثمانی بپاریس رفت و در <span class=\"hlight\" dir=\"rtl\">١٢٧٥</span> هَ . ق . برتبه ٔ بیگلربیگی روملی مأمور قدس شریف شد و در جلوس سلطان عبدالعزیزخان در <span class=\"hlight\" dir=\"rtl\">١٢٨٠</span> هَ . ق . ولایت حلب به او مفوض گشت و سپس رتبه ٔ وزارت یافت وناحیه ٔ زور را پس از طغیان و انقلابی که در آنجا پیدا شده بود مسخر و هم اعاده ٔ امنیت کرد. در <span class=\"hlight\" dir=\"rtl\">١٢٨٣</span> به ولایت آیدین منصوب گشت . یکسال بعد به اسلامبول آمد و در<span class=\"hlight\" dir=\"rtl\">١٢٨٥</span> ولایت خداوندگار بدو دادند و کارهائی از این قبیل داشت تا در <span class=\"hlight\" dir=\"rtl\">١٢٩٦</span> هَ . ق . به ماه شعبان بسیواس درگذشت . او مردی عالم و ادیب و محب علماء بود و در زبان ترکی عثمانی منشی و کاتبی زبردست بشمار می آمد و در زبان فرانسه نیز مهارتی بسزا داشت . (قاموس الاعلام ).<br /></font></div>'),
(82124, 'ثریان', '<span class=\"hlight\">ثریان .</span> <font color=\"DarkGreen\"><b>[ ث َ رَ ]</font></b> (ع اِ) التقاء ثَریان و ثَروَان ؛ نم به نم رسیدن، یعنی بحدی باران آمدن که بزمین فرو شود تا با نم و تری زیر زمین تلاقی کند و نیز التقاء ثَرَیان و التقاء ثروان . فزودن شرف أب بر شرف ام ّ.<br /></font></div>'),
(82125, 'ثریان', '<span class=\"hlight\">ثریان .</span> <font color=\"DarkGreen\"><b>[ ث َرْ ]</font></b> (ع ص ) تَر.<br /></font></div>'),
(82126, 'ثریة', '<span class=\"hlight\">ثریة.</span> <font color=\"DarkGreen\"><b>[ ث َ ری ی َ ]</font></b> (ع ص ) أرض ثریه ؛ زمینی تر شده و نم دار بعد از آنکه خشک و یابس بود.<br /></font></div>'),
(82127, 'ثرید', '<span class=\"hlight\">ثرید.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (معرب، اِ)معرب ترید. (بحر الجواهر). تریت . تلیت . (عامیانه ). ابورزین . اشکنه . نان شکسته در کاسه . یخنی . اُثردان . مثرود. ثریده . ثُردَه . و آن غالباً از گوشت باشد. <BR><font color=\"Blue\">◄</font> نوعی از طعام که پاره های نان را در شوربای گوشت تر کنند. (از بحر الجواهر و لطائف ) (غیاث اللغة) <span class=\"hlight\">:</span> رسول گفت چون بمدینه آمدم عمر را دیدم که در مسجد نشسته بود و طعام همی داد و عمر هر روزشتری بکشتی بآب و نمک بپختی و درویشان و غریبان را بدادی و کاسه های ثرید بر خوان نهادی و آن طعام بدادی پس بخانه شدی و طعام خوردی . (ترجمه ٔ طبری بلعمی ).<br />چو بنهاد آن تل سوسن به پیش من چنان بودم <br />که پیش گرسنه بنهی ثرید چرب بهنانه .<br /> <font color=\"Red\">حکاک .</font><br />نه قدید و نه ثرید و نه عدس <br />آنچه خوردی آن بگو تنها و بس .<br /> <font color=\"Red\">مولوی .</font><br />او پس از تو زاد و از تو بگذرید<br />تو چنان خشکی ز سودای ثرید.<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> کفی که بالای خمر پدید آید. ج، ثرائد.<br /></font></div>'),
(82128, 'ثرید', '<span class=\"hlight\">ثرید.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ )قلعه ای است در یمن از بنی حاتم بن سعد. گویند به میان آن چشمه ای است که بشدت فوران کند. (مراصد الاطلاع ).<br /></font></div>'),
(82129, 'ثریر', '<span class=\"hlight\">ثریر.</span> <font color=\"DarkGreen\"><b>[ ث ُ رَ ]</font></b> (اِخ ) بصیغه ٔ تصغیر، جائی است نزدیک انصاب الحرم که متصل به مستوفر است و گویند ناحیه ای است از نواحی حجاز که آنجا مال و ثروتی از ابن زبیر بوده است . (مراصد الاطلاع ).<br /></font></div>'),
(82130, 'ثش', '<span class=\"hlight\">ثش .</span> <font color=\"DarkGreen\"><b>[ ث َش ش ]</font></b> (ع مص ) بیرون کردن باد از مشک : ثش ّ سقاه .<br /></font></div>'),
(82131, 'ثط', '<span class=\"hlight\">ثط.</span> <font color=\"DarkGreen\"><b>[ ث َطط ]</font></b> (ع ص، اِ) مرد کوسه یا کسی که مو در ریش و ابروی او کم باشد: رجل ثطّ الحاجبین . <BR><font color=\"Blue\">◄</font> مرد گران شکم که راه رفتن نتواند. ج، اثطاط، ثُطّ، ثطان، ثطاط، ثططة.<br /></font></div>'),
(82132, 'ثط', '<span class=\"hlight\">ثط.</span> <font color=\"DarkGreen\"><b>[ ث ُطط ]</font></b> (ع ص، اِ) ج ِ ثطّ و اَثط.<br /></font></div>'),
(82133, 'ثط', '<span class=\"hlight\">ثط.</span> <font color=\"DarkGreen\"><b>[ ث َطط ]</font></b> (ع مص ) ثطط. ثطاطت . ثطوطت . کوسه شدن . <BR><font color=\"Blue\">◄</font> گران شکم شدن . <BR><font color=\"Blue\">◄</font> ریخ زدن .<br /></font></div>'),
(82134, 'ثطاء', '<span class=\"hlight\">ثطاء.</span> <font color=\"DarkGreen\"><b>[ ث َطْ طا]</font></b> (ع اِ) زن پَست سرین . <BR><font color=\"Blue\">◄</font> عنکبوت . تننده .کارتنک . <BR><font color=\"Blue\">◄</font> جانوری است کوچک سخت گزنده .<br /></font></div>'),
(82135, 'ثطاط', '<span class=\"hlight\">ثطاط.</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع ص، اِ) جمع ثَطّ.<br /></font></div>'),
(82136, 'ثطاطت', '<span class=\"hlight\">ثطاطت .</span><font color=\"DarkGreen\"><b>[ ث َ طَ ]</font></b> (ع مص ) ثَطط. کوسه گردیدن . <BR><font color=\"Blue\">◄</font> گران شکم شدن . <BR><font color=\"Blue\">◄</font> ریخ زدن . (منتهی الارب ).<br /></font></div>'),
(82137, 'ثطاع', '<span class=\"hlight\">ثطاع .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) زکام . سرماخوردگی . چاییدگی . چایمان .<br /></font></div>'),
(82138, 'ثطاعی', '<span class=\"hlight\">ثطاعی .</span> <font color=\"DarkGreen\"><b>[ ث ُ عی ی ]</font></b> (ع ص ) مزکوم . زکام زده . سرماخورده . چایمان کرده . چاییده .<br /></font></div>'),
(82139, 'ثطان', '<span class=\"hlight\">ثطان .</span> <font color=\"DarkGreen\"><b>[ ث َطْ طا ]</font></b> (ع ص، اِ) ج ِ ثطّ، و اَثط.<br /></font></div>'),
(82140, 'ثطط', '<span class=\"hlight\">ثطط.</span> <font color=\"DarkGreen\"><b>[ ث َ طَ ]</font></b> (ع اِ) ریش تنک . ریش سبک .<br /></font></div>'),
(82141, 'ثطط', '<span class=\"hlight\">ثطط.</span> <font color=\"DarkGreen\"><b>[ ث َ طَ ]</font></b> (ع مص ) ثَطّ. ثَطاطَت ثطوطت . کوسه شدن . <BR><font color=\"Blue\">◄</font> گران شکم گردیدن .<br /></font></div>'),
(82142, 'ثطع', '<span class=\"hlight\">ثطع.</span> <font color=\"DarkGreen\"><b>[ ث َ<span class=\"hlight\" dir=\"rtl\">/</span> ث َ طَ ]</font></b> (ع مص ) آشکار کردن . <BR><font color=\"Blue\">◄</font> ظاهر شدن . <BR><font color=\"Blue\">◄</font> زکام گرفتن کسی را. مزکوم گردیدن . ثُطِعَ (مجهولاً)؛ مزکوم شد. <BR><font color=\"Blue\">◄</font> حدث کردن .<br /></font></div>'),
(82143, 'ثطعمة', '<span class=\"hlight\">ثطعمة.</span> <font color=\"DarkGreen\"><b>[ ث َ ع َ م َ ]</font></b> (ع اِمص ) چرب زبانی و تفوق در سخن .<br /></font></div>'),
(82144, 'ثطف', '<span class=\"hlight\">ثطف .</span> <font color=\"DarkGreen\"><b>[ث َ طَ ]</font></b> (ع اِمص ) آسایش در طعام و شراب و خواب . <BR><font color=\"Blue\">◄</font> ارزانی . گشایش . فراخی خِصب . سِعة. رخاء.<br /></font></div>'),
(82145, 'ثطوطت', '<span class=\"hlight\">ثطوطت .</span> <font color=\"DarkGreen\"><b>[ ث ُ طَ ]</font></b> (ع مص ) ثطط. کوسه گردیدن . <BR><font color=\"Blue\">◄</font> گران شکم شدن .<br /></font></div>'),
(82146, 'ثع', '<span class=\"hlight\">ثع.</span> <font color=\"DarkGreen\"><b>[ ث َع ع ]</font></b> (ع مص ) قی کردن .<br /></font></div>'),
(82147, 'ثعابیب', '<span class=\"hlight\">ثعابیب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) گویند، فوه یجری ثعابیب ؛ یعنی از دهن او لعاب صافی مانند رشته های دراز بر می آید.<br /></font></div>'),
(82148, 'ثعابین', '<span class=\"hlight\">ثعابین .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b>(ع اِ) ج ِ ثعبان بمعنی اژدرها. <BR><font color=\"Blue\">◄</font> رئیس الثعابین . ماری خرافی که از تخم خروس زاید و مار پرزهرو نیز مرغی موهوم که دم وی مانند مار بود و نوعی حیوان نیش غولی چون غولی که نظر و نفس وی کشنده است .<br /></font></div>'),
(82149, 'ثعاریر', '<span class=\"hlight\">ثعاریر.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) ج ِ ثُعرور.نباتی است مانند هلیون . <BR><font color=\"Blue\">◄</font> کفتگی بینی .<br /></font></div>'),
(82150, 'ثعال', '<span class=\"hlight\">ثعال .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) روباه ماده .<br /></font></div>'),
(82151, 'ثعال', '<span class=\"hlight\">ثعال .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (اِخ )شعبه ای است بین روحاء و رویثة. <BR><font color=\"Blue\">◄</font> چراگاه و منزلگاهی است میان عرج و روحاء. (مراصد الاطلاع ).<br /></font></div>'),
(82152, 'ثعالب', '<span class=\"hlight\">ثعالب .</span> <font color=\"DarkGreen\"><b>[ ث َ ل ِ ]</font></b> (ع اِ) ج ِ ثَعلب . روباهان .<br /></font></div>'),
(82153, 'ثعالبات', '<span class=\"hlight\">ثعالبات .</span> <font color=\"DarkGreen\"><b>[ ث ُ ل ِ ]</font></b> (اِخ ) ث-ُعیلبات . از کوههای بلاد بنوجعفربن کلاب است و آن چندین ناحیه و قطعه است . و نیز رجوع به ثعیلبات شود.<br /></font></div>'),
(82154, 'ثعالبة', '<span class=\"hlight\">ثعالبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل ِ ب َ ]</font></b> (اِخ ) فرقه ای از پانزده فرقه ٔ خوارج . (مفاتیح العلوم ) (بیان الادیان ). از اصحاب ثعلب بن عامر. این فرقه ولایت را درباره ٔ کودکان شرط دانند. خواه کوچک باشند یا بزرگ تا زمانی که انکار وحدانیت الهی بعد از رسیدن به حد بلوغ از آنها سرنزده باشد و از این گروه نقل است که گفته اند بر اطفال حکمی در دوستی و دشمنی نیست تا زمانی که به حد بلوغ رسند. و از غلام زرخرید در صورتی که به حد بی نیازی و مالداری برسند زکوة بستانند. و چون نیازمند گردند بدیشان زکوة دهند. و این گروه بر چهار تیره باشند. اخنسیه . معبدیه . شیبانیه . و مکرمیه . (کشاف اصطلاحات الفنون ).<br /></font></div>'),
(82155, 'ثعالبه', '<span class=\"hlight\">ثعالبه .</span> <font color=\"DarkGreen\"><b>[ ث َ ل ِ ب َ ]</font></b> (اِخ ) مؤلف قاموس الاعلام گوید ثعالبه قبیله ای از عرب باشند که در مغرب الجزائر ساکن بودند از اولاد ثعلب بن بکربن صفیره . مسکن این قبیله کوههای وانشریش بود و رئیس قبیله بنی توجین محمدبن عبدالقوی با آنان جنگی درپیوسته و ایشان را مغلوب و از موطنشان اخراج کرد و ثعالبه به مغرب اقصی شدند و مدت زمانی در تحت اداره ٔ رئیس خود در زیر حمایت امراء بنی عمرین بزیستند سپس در قرن هشتم هجری ابوحمویغمراسون با این طایفه جنگهای بسیار کرد و تمام این قبیله را محو و نابود ساخت .<br /></font></div>'),
(82156, 'ثعالبی', '<span class=\"hlight\">ثعالبی .</span> <font color=\"DarkGreen\"><b>[ ث َ ل ِ ]</font></b> (ع ص نسبی، اِ) منسوب به ثعلب . آن که اشتغال به عمل پوست روباه دارد. (سمعانی ).<br /></font></div>'),
(82157, 'ثعالبی', '<span class=\"hlight\">ثعالبی .</span> <font color=\"DarkGreen\"><b>[ ث َ ل ِ ]</font></b> (اِخ ) رجوع به احمدبن محمدبن ابراهیم ثعلبی یا ثعالبی شود.<br /></font></div>'),
(82158, 'ثعالبی', '<span class=\"hlight\">ثعالبی .</span> <font color=\"DarkGreen\"><b>[ ث َ ل ِ ]</font></b> (اِخ ) علامه ابومنصور عبدالملک بن محمدبن اسماعیل نیشابوری (<span class=\"hlight\" dir=\"rtl\">٣٥٠</span> - <span class=\"hlight\" dir=\"rtl\">٤٢٩</span> هَ . ق .). از آنرو وی را ثعالبی گویندکه از پوستهای روباه پوستین کردی . ابن خلکان گوید: قال ابن بسام صاحب ذخیره ٔ فی حقه کان فی وقته راعی تلعات العلم و جامع اشتات النثر و النظم، رأس المؤلفین فی زمانه و امام المصنفین بحکم قرانه، سار ذکره سیر المثل و ضربت الیه آباط الابل و طلعت دواوینه فی المشارق و المغارب طلوع الشمس فی الغیاهب و توالیفه اشهر مواضع و ابهر مطالع و اکثر راولها و جامع من ان یستوفیها حدّ اوصف او یوفیها حقوقها نظم او نثر و ذکر له طرفاً من النثر و او رد شیئاً من نظمه فمن ذلک ماکتبه الی الامیر ابی الفضل عبیداﷲبن احمد المیکالی :<br />لک فی المفاخر معجزات جمة<br />ابداً لغیرک فی الوری لم تجمع<br />بحران بحر فی البلاغة شابه <br />شعر الولید و حسن لفظ الاصمعی <br />و ترسل الصابی یزین علوّه <br />خط ابن مقلة ذوالمحل الأرفع<br />کالنور او کالسحرا و کالبدر او<br />کالوشی فی برد علیه موشع<br />شکراً فکم لک من ضیع کالغنی <br />وافی الکریم بعید فقر مدفع<br />و اذا تفتق نور شعرک ناظراً<br />فالحسن بین مرصع و مصرّع <br />ارجلت فرسان الکلام و رضت افَ<br />راس البدیع وانت امجد مبدع <br />و نقشت فی قص الزمان بدایعا<br />تزری بآثار الربیع الممرع .<br />و نیز اوراست :<br />لما بعثت فلم توجب مطالعتی <br />و امعنت نار شوقی فی تلهبها<br />و لم اجد حیلة تبقی علی رمقی <br />قبلت عینی رسولی اذرآک بها.<br />و در وصف اسبی که ممدوح وی او را هدیه داده بود:<br />یا واهب الطرف الجواد کأنما<br />قد انعلوه بالریاح الا ربع<br />لاشی ٔ اسرع منه الا خاطری <br />فی وصف نائلک اللطیف الموقع<br />ولو اننی انصفت فی اکرامه <br />لجلال مهدیه الکریم الالمعی <br />اقصمته حب الفؤاد لحبه <br />و جعلت مربطه سواد المدمع<br />و خلعت ثم قطعت غیر مضیع<br />برد الشباب لجله و البرقع.<br />و به ابی نضربن سهل بن المرزبان نوشته است :<br />حاجیت شمس العلم فی ذا العصر<br />ندیم مولینا الامیر نصر<br />ما حاجة الاهل کل مصر<br />فی کل ما دار و کل قطر <br />لیست تری الا بعید العصر.<br />و ابونصر در پاسخ او گوید:<br />یا بحر آداب بغیر جزر<br />و حظه بالعلم غیر نزر<br />حررت ما قلت و کان حزری <br />ان ّ الذی عنیت دهن البزر<br />یعصره ذوقوة و ازر.<br />و یکی از مؤلفات او یتیمةالدهر فی محاسن اهل العصر است که بزرگترین کتب او است و جامعترین و نیکوترین است و ابوالفتوح نصراﷲبن قلاقس شاعر اسکندری مشهور در وصف کتاب یتیمه گوید:<br />ابیات اشعار الیتیمة<br />ابکار افکار القدیمة<br />ماتوا و عاشت بعدهم <br />فلذاک سمیت الیتیمة.<br />دیگر ازکتب او فقه اللغة و سحرالبلاغة و سرالبراعة، و من غاب عنه المطرب، و مونس الوحید (فی المحاضرات ) و کتب بسیار دیگر که در آنها اشعار و رسائل واخبار و احوال کسان را گرد کرده که همه دلیل کثرت اطلاع اوست و او را اشعار بسیار است ولادت وی در سال <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> و وفات او بسال <span class=\"hlight\" dir=\"rtl\">٤٢٩</span> هَ . ق . بود. - انتهی . (صص <span class=\"hlight\" dir=\"rtl\">٣١٥</span> - <span class=\"hlight\" dir=\"rtl\">٣١٦</span>). و در ترجمه ٔ یمینی آمده است : ثعالبی در جنگ ابوالحسن سیمجور با حسام الدوله ابوالعباس تاش در نیشابور و انهزام ابوالحسن گوید:<br />قل للذی انا فی هواه ُ خاشی <br />صاد الفؤادَبصدغه ِ الجماش <br />صدغ یُری عندالریاح ِ کاَنّه <br />قَلب ُ ابن ِ سیمجور احس ّ بتاش .<br />و همو گوید:<br />اِن ّ الشتاء مضی بقبح فاشی <br />و اتی الربیع لنا بحسن ریاش <br />و مضی ابن ُ سیمجور بقبح فعاله <br />و انتاش ابناءالکرام بتاش .<br />و در شرح وقایع و مصایب سال <span class=\"hlight\" dir=\"rtl\">٣٨٧</span> هَ . ق . گوید:<br />الم تر مذ عامان املاک عصرنا<br />یصیح بهم للموت و القتل صائح <br />فنوح بن منصور حوته یدالردی <br />علی حسرات ضمنتها الجوانح <br />و یابؤس منصور و فی یوم سرخس <br />تمزق عنه ملکه و هو طائح <br />و فرّق عنه الشمل بالسمل فاغتدی <br />اسیراً ضریراً تنتحیه الجوائح <br />و صاحب مصر قد مضی لسبیله <br />و والی الجبال قد علته الصّفائح <br />وصاحب جرجانیة فی ندامة<br />ترصده طرف من الحین طامح <br />تساقوا کؤوس الراح ثم تشاربوا<br />کؤوس المنایا و الدماء سوافح <br />و خوارزم شاه شاه وجه نعیمه <br />وَ عن له یوم من النحس کالح <br />و کان علی فی الارض یخبطها ابو <font color=\"DarkGreen\"><b>[کذا ]</font></b><br />علی ّ الی ان طوحته المطاوح <br />فعارضه ناب من الشرّ اعصل <br />و عن له طیر من الشوم بارح <br />و صاحب بست ذلک الضیغم الذی <br />براثنه للمشرقین مفاتح <br />أناخ به من صدمة الدّهر کلکل ُ<br />فلم یغن عنه و المقدر سانح <br />خیول کامثال السیول سوابح <br />فیول کامثال الجبال سوارح <br />جیوش اذا اربت علی عدد الحصی <br />تغص بها قیعانها و الصحاصح <br />و دارت علی صمصام دولة بویة<br />دوایر سوء نبلهن فوادح <br />و قد جاز والی الجوزجان قناطر<br />الحیوة فوافته المنایا الطوائح <br />و فایق المجبوب قدجب ّ عمره <br />فقاظ و لم یندبه فی الارض نائح <br />مضوا فی مدی عامین فاختطفتهم <br />عقاب اذا طارت تخرالجوارح <br />و کان بنو سامان اطواد عزة<br />فاضحت لصرف الدهر وهی اباطح <br />ا ما لک فیهم عبرة مستفادة<br />بلی ان ّ نهج الاعتبار لواضح <br />تسل عن الدنیا و لا تخطبنّها<br />ولا تخطبن قتالة من تناکح <br />فلیس یفی مرجوها بمخوفها<br />و مکروهها اما تدبرت راجح <br />لقد قال فیها الواصفون فاکثروا<br />و عندی لها وصف لعمرک صالح <br />سلاف قصارا، ذعاف و مرکب <br />شهی اذا استلذذته فهو جامح <br />و شخص جمیل یونق الناس حسنه <br />ولکن له اسرار سوء قبایح .<br />و در واقعه ٔ هزیمت ابوابراهیم اسماعیل بن نوح منتصر از امیر نصربن ناصرالدین این قصیده گفته است :<br />تبلجت الایام عن غرةالدهر<br />و حلت باهل البغی قاصمةالدهر<br />وولی بنوالادبار ادبارهم و قد<br />تحکم فیهم صاحب الدهر بالقهر<br />و قد جاء نصراﷲ و الفتح مقبلا<br />الی الملک المنصور سیدنا نصر<br />غیاث الوری شمس الزمان و بدره <br />و من هو بالعلیاء اولی اولی الامر<br />فیالک من فتح غدا زینةالعلی <br />و واسطةالدنیا و فائدةالعصر<br />أبی اﷲ الانصر نصر و رفعه <br />علی قمةالعیوق اوهامةالبدر<br />و ملکه صدرالسریر کانه <br />لنا فلک بالخیر اوضده یجری <br />و خوله دون الملوک محاسنا<br />تبر علی الشمس المنیرة و القطر<br />اذا ذکرت فاح الندی بذکرها<br />کما فاح اذ کی الندّ فی وهج الجمر<br />فتی السن کهل الحلم و الرای و الحجی <br />یعم بنی الامال بالنائل الغمر<br />له همة لما حسبت علوها<br />حسبت الثریا فی الثری ابداً تسری <br />غدا راعیاً للمسلمین و ناصراً<br />له اﷲ راع قد تکفل بالنصر<br />الا ایها الملک الذی ترک العدی <br />عبادید بین القتل و الکسر و الاسر<br />قدمت قدوم الغیث ایمن مقدم <br />فحلیت وجه الدهر بالحسن و البشری <br />الست تری کتب الربیع و رسله <br />یقولون هذاک الربیع علی الاثر<br />نسیم نسیب للحیوة بلطفه <br />یجر فویق الارض اردیةالعطر<br />و ترب بانفاس الربیع معنبر<br />فیالک من طیب و یالک من نشر<br />و غیم یحاکی راحتیک کانه <br />علی المسک و الکافور یهطل بالخمر<br />فروح بشرب الراح روحک انها<br />لفی تعب من وقعة البیض و السمر<br />و دم لأقتناء الملک فی اکمل المنی <br />و فی ارفع العلیا و فی اطول العمر.<br />و در حق سید ابوجعفر محمدبن موسی بن احمدبن القاسم بن حمزةبن موسی بن جعفر گوید:<br />اﷲ جارک یا من قد غدا جاری <br />من صرف دهر بما لا اشتهی جار<br />یابن النبوة و البیت العتیق معا<br />یا وارث المصطفی یا حجةالباری <br />یا من یظل لسان المجد ینشده <br />ﷲ من رایش غمر ومن بار<br />اُنت الذی اصبحت فینا مناقبه <br />مثل النجوم تضی ٔ اللیل للسّاری <br />انت الرفیع عماداً و الجواد ندی <br />انت الحیاء الغمر انت الضیغم الضاری <br />من اسرة ثبت التیجان هامتهم <br />اذا تکلف تاجاً راس جبار<br />ای الکتاب علیهم انزلت و لهم <br />تهدی محاسن الفاظ و اشعار<br />اذا اقمت بطوس زدتها شرفاً<br />تعض رفعته ابصار امصار<br />و ان طلعت بنیسابور کنت لها<br />زین المجالس و المیدان و الدار.<br /> <font color=\"Red\">(از ترجمه ٔ تاریخ یمینی ).</font><br />و نیز ثعالبی راست :<br />من ذا الذی لابذل الدهر صعبته <br />ولا تلین ید الایام صعدته <br />اَما تری خلفا شیخ الملوک غدا<br />مملوک من فتح العذراء بلدته <br />قدکان بالامس ملکا لا نظیرله <br />فالیوم فی الاسرلا ینتاش اسرته .<br />و رجوع بشرح یمینی مسمی بفتح الوهبی جزء اول صص <span class=\"hlight\" dir=\"rtl\">١٣٥</span> - <span class=\"hlight\" dir=\"rtl\">٢٦٥</span> -<span class=\"hlight\" dir=\"rtl\">٣٣٢</span> - <span class=\"hlight\" dir=\"rtl\">٣٧٤</span> شود.<br />مؤلف حبیب السیر گوید: از افاضل جهان ابومنصور ثعالبی معاصر قابوس (شمس المعالی ) بود و نام او ابومنصور عبدالملک بن محمدبن اسماعیل است و کتاب غرر سیر الملوک از جمله ٔتصنیفات اوست - انتهی . وهمو گوید: از ثعالبی مرویست که گفت اگر بگویم که سیدرضی اشعر قریش است دور از کار نیست - انتهی .<br />مؤلف روضات الجنات گوید: امام متبحر مشهور ابومنصور عبدالملک بن محمدبن اسماعیل ثعالبی فراء نیسابوری ادیب لغوی صاحب تصانیف فاخره سائره ٔ دائره است مانند کتاب یتیمةالدهر و کتاب فقه اللغة و کتاب سحرالبلاغة و کتاب سرالبلاغة (ظ. البراعة) فی طریق الکتابة الی الاشخاص المختلفة. و کتاب سرالادب فی دقایق اللغات العربیة و الالفاظ المترادفةو المعانی المتقاربة و امثال ذلک . دمیری ذکر او را در کتاب حیوةالحیوان آورده و گوید: امام علامة ابی منصور عبدالملک نیسابوری را رأس مؤلفین و امام مصنفین، و امام ادیب گویند صاحب تصانیف عالی و آداب رائق مانند ثمارالقلوب <font color=\"DarkGreen\"><b>[ فی المضاف و المنسوب ]</font></b> و فقه اللغةو یتیمةالدهر فی محاسن اهل العصر و تصانیف دیگر. ثعالبی منسوب بدوختن پوست روباه و عمل آنست زیرا او فراء بود و یتیمةالدهر بزرگترین کتب او و نیکوترین آنهاست ... و از اشعار ابی منصور ثعالبی است :<br />یا سیدا بالمکرمات ارتدی <br />وانتفل العیوق و الفرقدا<br />ما لک لاتجری علی مقتضی <br />مودة طال علیهاالمدی <br />ان غبت لم اطلب فهذا<br />سلیمان بن داود النبی الهدی <br />تفقد الطیر علی شغله <br />فقال مالی لااری الهدهدا.<br />و وی در سال <span class=\"hlight\" dir=\"rtl\">٤٢٩</span> هَ . ق . وفات کرد و گویند در سال <span class=\"hlight\" dir=\"rtl\">٤٣٠</span> - انتهی . صاحب قاموس الاعلام گوید: ابومنصور عبدالملک بن محمدبن اسماعیل نیسابوری یکی از مشاهیر علماء و ادباء مولد او بسال <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> هَ . ق . به نیشابور و وفات در <span class=\"hlight\" dir=\"rtl\">٤٢٩</span> هَ . ق . او در نظم و نثر فرید عصر خویش بود و تألیفات او در شرق و غرب شهرتی بسزا دارد و چون پوست روباه می فروخت او را لقب ثعالبی دادند بزرگترین آثار وی یتیمةالدهر فی محاسن اهل العصر است در چهار مجلد بزرگ و این کتاب تراجم احوال مشاهیر شعرای معاصر اوست و در دمشق شام طبع و نشر شده است و باخرزی بنام دمیةالقصر و عصرة اهل العصرذیلی بر آن کرده و عمادالدین اصفهانی را نیز ذیل دیگر بنام خریدةالقصر و جریدة اهل العصر بر آن کتاب است و نیز ابوالمعالی سعد وراق را ذیلی است بر آن بنام زینةالدهر و هم ثعالبی راست کتاب فقه اللغة و سحرالبلاغه و سرالبراعة و کتاب من غاب منه المطرب و کتاب مونس الوحید و یتیمةالیتیمة یا تتمة الیتیمة.<br />و کتب ذیل نیز در کشف الظنون بنام او آمده است : لطائف المعارف فیما للموسم العام من الوظائف . اوله : اما بعد حمداﷲ استفتاحاً به الخ، رتبه علی عشرة ابواب الاول فی ذکر الاوائل . الثانی فی القاب الشعراءالذین لقبوا من اشعارهم . الثالث فی سائرالالقاب الاسلامیة. الرابع فی الکتاب المتقدمین . الخامس فی الاعرقین من کل طبیعة. السادس فی الغایات من طبقات الناس . السابع فی ظرائف الاتفاقات . الثامن فی فنون شتی من المعارف . التاسع فی ملح النوادر. العاشر فی انموذج من خصائص البلدان . و مبهج که آنرا برای امیر شمس المعالی قابوس تألیف کرده . اوله : باسم اﷲ استفتاحاً و استبجاحاً الخ . ذکر فیه انه اهداه الی شمس المعالی حین وروده ثم زاد فیه و نقص و بدل فانشأه نشاءة اخری و رتبه علی سبعین بابا.<br />و در دائرة المعارف اسلام آمده است : ابومنصور عبدالملک بن محمدبن اسماعیل یکی از ادباء کثیرالتصنیف قرن پنجم هجری است . از زندگانی او جز اینکه در نیشابور بسال <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> هَ. ق . (<span class=\"hlight\" dir=\"rtl\">٩٦١</span> م .) تولد یافت و در <span class=\"hlight\" dir=\"rtl\">٤٢٩</span> هَ . ق . (<span class=\"hlight\" dir=\"rtl\">١٠٣٨</span> م .) وفات کرد چیزی نمیدانیم و در کتب ثعالبی غالباً اقوال دیگران نقل و جمع شده است و در این عمل چندان دربند رعایت امانت حفظ حق اسلاف خود نیست و گفته های خود را مکرر میکند و کتب او مخصوصاً مربوط بشعرای عصر او و نیز راجع به مسائل لغوی و خطابی است . معروفترین کتب او و مهمترین آنها یتیمةالدهر فی محاسن اهل العصر درباره ٔ ادباء عصر وی و عصر قبل از او است تراجم ادباء مذکور بر حسب ناحیت مرتب گشته است . کتاب یتیمة در واقع منتخبات نظم است که اغلب مختصر شرح حالی از صاحبان شعر به آنها افزوده شده و مانند کتب نظیر خود بصور مختلف انشاء و انشاد شده است (رجوع به ارشاد الادیب یاقوت ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٠</span>) ثعالبی خود ذیلی بر آن کتاب نوشته است بنام تتمةالیتیمة (یاقوت ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤١١</span>) و هم منتخبات دیگری بر حسب ماده گرد آورده بنام کتاب احسن ماسمعت که کتاب من غاب عنه المطرب ذیل آن بشمار میرود. کتاب خاص الخاص او که نام شعرا در آن ذکر نشده و کتاب المنتحل و کتاب طرائف الطرّف که منتخبات دیگری از شعراست و کتاب کنزالکتاب را از <span class=\"hlight\" dir=\"rtl\">٢٥٠٠</span> فقره مأخوذ از <span class=\"hlight\" dir=\"rtl\">٢٥٠</span> شاعر فراهم آورده و آنرا مخصوص دبیران کرده است . ثعالبی اشعاری را که در کتاب منتخبات موسوم به مونس الادباء که از مؤلفی مجهول یافته بود بفرمان خوارزمشاه ابوالعباس به نثر درآورد و بنام نثرالنظم و حل العقد من مختارالشعرالذی یشتمل علیه الکتاب المترجم بمونس الادباء موسوم ساخت . دسته ٔ دوم تألیفات او کتبی است که برای مطالعه و قرائت ترتیب کرده و در این نوع اطلاعات مفید مخصوصاً مجموعی از حکایات تاریخی موجود است از آن جمله است کتاب لطائف المعارف و کتاب الفرائد و القلائد یا کتاب العقد النفیس و نزهةالجلیس . کتاب المُبهج یا کتاب المُبهّج و دو کتاب در مدح و ذم اشیاء که در ادب عرب از قدیم بسیار زبانزد بوده بعنوان کتاب اللطائف و الظرائف . و کتاب یواقیت المواقیت . و کتاب غررالبلاغة و طرف البراعه یا غررالبلاغة للنظم و النثر. و کتب ذیل را نیز بغلط بدو نسبت کرده اند:کتاب الامثال و کتاب الفرائد و القلائد لاهوازی و کتاب محاسن المحاسن .<br />ثعالبی چندین مجموعه ٔ امثال و حکم ترتیب کرده است مانند کتاب التمثل و المحاضرة و کتاب احاسن کلم النبی والصحابة و التابعین و ملوک الجاهلیة و ملوک الاسلام والوزراء و الکتاب و البلغاء و الحکماء و العلماء که مؤلف سپس این کتاب را جزء کتاب دیگر بنام کتاب الاعجاز و الایجاز آورده است . کتاب حلیةالمحاضرة و عنوان المذاکرة و میدان المصارعة. کتاب لطائف الصحابة و التابعین . مجموعه ٔ کوچکی از حکم . (طبع شیخو در مجلةالمشرق ). و کتابی در ادب بنام مونس الوحید. و بقول حاج خلیفه ثعالبی کتابی بنام سیرة الملوک یا کتاب الملوکی داشته ولی هنوز معلوم نشده است که این همان کتاب سراج الملوک منسوب به او است یا کتابی دیگر. و کتاب الوزراء ذیلی است بر کتاب مذکور. و از کتب ادب که از نظر ادب در درجه ٔ دوم است : کتاب مرآت المروآت و اعمال الحسنات و کتاب بردالاکباد فی الاعداد رامی توان نام برد. دسته ٔ سوم مؤلفات او شامل کتب فقه اللغة بمعنی اخص است . معروفترین آنها کتاب مترادفات عرب است که ثعالبی آنرا در آخر عمر نوشت و در ابتداء آن را شمس الادب فی استعمال العرب نامید و آن کتاب دو جزء داشت مترادفات بمعنی اخص بعنوان اسراراللغة العربیة و خصائصها دیگر ملاحظات اسلوب کلام بعنوان مجاری کلام العرب برسومها و ما یتعلق ُ بالنحو و الاعراب منها و الاستشهاد بالقرآن علی اکثرها. جزء دوم را ثعالبی غالباً حرف بحرف از کتاب فقه اللغه ٔ احمدبن فارس اخذ کرده است ثعالبی بعد جزء اول را جداگانه بعنوان فقه اللغه منتشر ساخت جزء دوم اصلی بعنوان سرالادب فی مجاری علوم العرب که علیحده بچاپ رسیده است (با السامی فی الاسامی میدانی چ سنگی طهران ) و در نیشابور کتابی در فن بیان کرد که در آن بیشتر ببحث از کنایات پرداخته است . نام این کتاب که بخوارزمشاه مأمون بن مأمون اهداء شده گاه الکفایة فی الکنایة و گاه نهایة فی التعریض و الکنایةو گاه الکنایة و التعریض ثبت شده است و کتاب سحرالبلاغة و سرالبراعة مجموعه ای است از اصطلاحات ظریف عربی .کتاب ثمار القلوب (یا ثمرالقلوب ) فی المضاف و المنسوب را که بنام میرابوالفضل عبیداﷲ احمد المیکالی (متوفی بسال <span class=\"hlight\" dir=\"rtl\">٤٣٦</span> هَ . ق .) کرده است شامل شرح و بیان اصطلاحات مرکب متداول عربی است و کتاب التذییل المرغوب من ثمر القلوب جدولی از رجال معروف بدست میدهد و بمنزله ٔ ذیل آن کتاب شمرده میشود. (بروکلمان از دائرة المعارف اسلام نقل به اختصار). و نیز ثعالبی راست : کتاب الکشف و البیان و کتاب الغلمان و مرآةالمداواة. مرحوم مشیرالدوله در ایران باستان آورده است که : کتاب غرر اخبار ملوک الفرس و سیرهم کاملا در زمینه ٔ داستانهای ما نوشته شده و با جزئی اختلافاتی همان مضامین شاهنامه است بنابراین در عداد منابع نمیآید ولی برای تتبع در داستانها مفید است - انتهی . محققین در انتساب کتاب غرر اخبار ملوک الفرس به ابی منصور عبدالملک ثعالبی تردید کرده اند و اغلب آنرا از ابومنصور الحسین بن محمد المرغنی الثعالبی میدانند. رجوع به ثعالبی حسن بن محمد شود.<br />مأخذ:<br />شرح وهبی بر تاریخ عتبی، ترجمه ٔ تاریخ یمینی، جرفادقانی، وفیات الاعیان، ابن خلکان، کتاب الحیوان دمیری، کشف الظنون حاج خلیفه، حبیب السیر میرخوند، روضات الجنات خوانساری، ایران باستان، <span class=\"hlight\" dir=\"rtl\">٢٥٥٨</span> و <span class=\"hlight\" dir=\"rtl\">٢٥٥٩</span> و <span class=\"hlight\" dir=\"rtl\">٢٥٦٠</span> و <span class=\"hlight\" dir=\"rtl\">٢٥٦٥</span> و حدائق السحر.<br /></font></div>'),
(82159, 'ثعالبی', '<span class=\"hlight\">ثعالبی .</span> <font color=\"DarkGreen\"><b>[ ث َ ل ِ ]</font></b> (اِخ ) ابومنصور الحسین بن محمدالمرغنی (از مرغن غور افغانستان ) او مورخی اسلامی است که از شرح حال وی جز اینکه او تألیف خویش موسوم به غررالسیر را به امیر نصر (متوفی بسال <span class=\"hlight\" dir=\"rtl\">٤١٢</span> هَ . ق .)برادر محمود غزنوی اهداء کرده چیز دیگر نمیدانیم و این کتاب تاریخی از آدم ابوالبشر تا محمود سبکتکین است قسمت اول آن در نسخ موجود در استانبول (کتابخانه ٔابراهیم پاشا شماره ٔ <span class=\"hlight\" dir=\"rtl\">٩١٦</span>) و پاریس (کتابخانه ٔ ملی شماره ٔ <span class=\"hlight\" dir=\"rtl\">٥٠٥٣</span>) محفوظ است . زوتنبرگ بخش تاریخ فرس را از آن قسمت نشر داده است و در مقدمه بدون دلایل قاطع خواسته است که صحت انتساب آنرا به ابی منصور عبدالملک ثعالبی اثبات کند. این بخش از کتاب مذکور مخصوصاً مهم است زیرا در بسیاری از موارد منابعی را که فردوسی در شاهنامه از آنها استفاده کرده است صحیح تر از طبری نقل شده و مؤلف ظاهراًعین متن شاهنامه را که در حدود <span class=\"hlight\" dir=\"rtl\">٩٥٠</span> م . به امر سپهسالار طوس ابومنصور محمدبن عبدالرزاق بوسیله ٔ چهار تن از نویسندگان تدوین شده به عربی آورده و از متون طبری و جوالیقی و دیگر مورخین اسلامی نیز بدون انتقاد استفاده کرده است . از چهار مجلد کتاب (حاج خلیفه شماره ٔ <span class=\"hlight\" dir=\"rtl\">٨٥٩٢</span> چ فلوگل ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٩</span>) تنها یک مجلد در کتابخانه ٔ بادلیان اکسفرد باقیست . این مجلد از سال <span class=\"hlight\" dir=\"rtl\">٧٤</span>-<span class=\"hlight\" dir=\"rtl\">٧٥</span> آغاز و بسال <span class=\"hlight\" dir=\"rtl\">١٥٨</span> هَ . ق . پایان می پذیرد. (رجوع به دائرة المعارف اسلام شود.). مآخذ: نولدکه، داستانهای حماسی ملی ایران . کائتانی . غررالسیر. که نسخه ٔ عربی و مجهول المؤلف است متعلق به کتابخانه ٔبادلیان اکسفرد. گابریلی در، ر. ر. آ. ل . (سلسله ٔ پنجم ج <span class=\"hlight\" dir=\"rtl\">٢٥</span> ص <span class=\"hlight\" dir=\"rtl\">١١٣٨</span> و بعد).<br /></font></div>'),
(82160, 'ثعالة', '<span class=\"hlight\">ثعالة.</span> <font color=\"DarkGreen\"><b>[ ث ُ ل َ ]</font></b> (اِخ ) موضعی است در شعر امروءالقیس . (مراصد الاطلاع ).<br /></font></div>'),
(82161, 'ثعالة', '<span class=\"hlight\">ثعالة.</span> <font color=\"DarkGreen\"><b>[ ث ُ ل َ ]</font></b> (ع اِ) روباه ماده . <BR><font color=\"Blue\">◄</font> عنب الثعلب . تاجریزی . سکنگور. روباه تُربَک . <BR><font color=\"Blue\">◄</font> ثعالةالکلأ؛ گیاه خشک .<br /></font></div>'),
(82162, 'ثعالی', '<span class=\"hlight\">ثعالی .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) ج ِ ثعلب . ثعالب .<br /></font></div>'),
(82163, 'ثعامة', '<span class=\"hlight\">ثعامة.</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (ع ص، اِ) زن تباه کار. زانیة.<br /></font></div>'),
(82164, 'ثعب', '<span class=\"hlight\">ثعب .</span> <font color=\"DarkGreen\"><b>[ ث َ ع َ ]</font></b> (ع اِ) راه گذار آب . <BR><font color=\"Blue\">◄</font> آب راهه ٔ وادی . ممر آب در بیابان . <BR><font color=\"Blue\">◄</font> چشمه ای که در سایه ٔ کوه باشد. ج، ثعبان . ماء ثعب ؛ آب روان .<br /></font></div>'),
(82165, 'ثعب', '<span class=\"hlight\">ثعب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) روان ساختن آب یا خون و امثال آن . آب راندن . (تاج المصادر بیهقی ).<br /></font></div>'),
(82166, 'ثعب', '<span class=\"hlight\">ثعب .</span> <font color=\"DarkGreen\"><b>[ ث ُ ع َ ]</font></b> (ع اِ) ج ِ ثعبة، وزغها.<br /></font></div>'),
(82167, 'ثعبان', '<span class=\"hlight\">ثعبان .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) مار بزرگ . مار عظیم . اژدها.(غیاث اللغة) (نصاب الصبیان ) (السامی فی الاسامی ). اژدر. (بحر الجواهر). یا خاص است به مار نر. یا مطلق مار است . تنین . برغمان . برسان . ج، ثعابین <span class=\"hlight\">:</span> <br />میر موسی کف، شمشیر چو ثعبان دارد<br />دست فرعون و جنودش کند ازما کوتاه .<br /> <font color=\"Red\">منوچهری .</font><br />در کف او بزخم فرعونان <br />نیزه ٔ سرگرای ثعبان باد.<br />چو هنگام عزائم زی معزّم <br />بتک خیزند ثعبانان ریمن .<br /> <font color=\"Red\">منوچهری .</font><br />روز در چشم من چو اهرمنست <br />بند بر پای من چو ثعبانیست .<br /> <font color=\"Red\">مسعود سعد.</font><br />دست موسی گشت گوئی عارض رخشان او<br />زلف او ثعبان موسی چشم او چون سامری .<br /><font color=\"Red\">معزی .</font><br /></font></div>'),
(82168, 'ثعبان', '<span class=\"hlight\">ثعبان .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) ج ِ ثعب . آبراهه های وادی . ج، ثعابین .<br /></font></div>'),
(82169, 'ثعبة', '<span class=\"hlight\">ثعبة.</span> <font color=\"DarkGreen\"><b>[ ث ُ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ب َ ]</font></b> (ع اِ) نوعی از کربسه ٔ سبزسر خبیث، ج، ثعب . <BR><font color=\"Blue\">◄</font> موش . <BR><font color=\"Blue\">◄</font> درختی است .<br /></font></div>'),
(82170, 'ثعثع', '<span class=\"hlight\">ثعثع.</span> <font color=\"DarkGreen\"><b>[ث ُ ث ُ ]</font></b> (ع اِ صوت ) امر بانبساط بلاد فی طاعةاﷲ تعالی . امر بالانبساط فی البلاد فی طاعةاﷲ. (تاج العروس ).<br /></font></div>'),
(82171, 'ثعثع', '<span class=\"hlight\">ثعثع.</span> <font color=\"DarkGreen\"><b>[ ث َ ث َ ]</font></b> (ع اِ) مروارید. <BR><font color=\"Blue\">◄</font> صدف . <BR><font color=\"Blue\">◄</font> پشم سرخ .<br /></font></div>'),
(82172, 'ثعج', '<span class=\"hlight\">ثعج .</span> <font color=\"DarkGreen\"><b>[ ث َ ع َ ]</font></b> (ع اِ) گروه مسافران .<br /></font></div>'),
(82173, 'ثعد', '<span class=\"hlight\">ثعد.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص، اِ) رُطب یا غوره ٔ خرمای نرم شده و آب گرفته . <BR><font color=\"Blue\">◄</font> بَقل ثعد؛ تره ٔ تازه و تر. <BR><font color=\"Blue\">◄</font> ثری ثعد؛ خاک نرم . <BR><font color=\"Blue\">◄</font> ماله ثعد و لامعد؛ نیست او را اندک و بسیار.<br /></font></div>'),
(82174, 'ثعر', '<span class=\"hlight\">ثعر.</span> <font color=\"DarkGreen\"><b>[ ث َ <span class=\"hlight\" dir=\"rtl\">/</span> ث ُ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ع َ ]</font></b> (ع اِ) صمغمانندی که از بیخ درخت طلح برآید و آن زهر کشنده است .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(82175, 'ثعر', '<span class=\"hlight\">ثعر.</span> <font color=\"DarkGreen\"><b>[ ث َ ع َ ]</font></b> (ع اِ) کثرة ثآلیل . بسیاری ازخها. (تاج العروس ).<br /></font></div>'),
(82176, 'ثعران', '<span class=\"hlight\">ثعران .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) دو آزخ غلاف نره ٔ ستور. <BR><font color=\"Blue\">◄</font> دو آزخ پستان گوسپند.<br /></font></div>'),
(82177, 'ثعرور', '<span class=\"hlight\">ثعرور.</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) مرد کوتاه . <BR><font color=\"Blue\">◄</font> سرطرثوت و بر آن . <BR><font color=\"Blue\">◄</font> بر گیاه ذؤنون . <BR><font color=\"Blue\">◄</font> بیخ پیاز دشتی . <BR><font color=\"Blue\">◄</font> خیار کوچک . <BR><font color=\"Blue\">◄</font> دستنبویه . <BR><font color=\"Blue\">◄</font> ثؤلول . زگیل . <BR><font color=\"Blue\">◄</font> چیزی مانند سر پستان که بر غلاف ایر اسب می باشد. ج، ثعاریر.<br /></font></div>'),
(82178, 'ثعروران', '<span class=\"hlight\">ثعروران .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) دو آزخ غلاف نره ٔ ستور، مانند دو سر پستان . چیزی که بر دو طرف غلاف شرم اسب می باشد. <BR><font color=\"Blue\">◄</font> دو ازخ پستان گوسپند. تکمه های پستان گوسپند.<br /></font></div>'),
(82179, 'ثعط', '<span class=\"hlight\">ثعط.</span> <font color=\"DarkGreen\"><b>[ ث َ ع َ ]</font></b> (ع مص ) گندا شدن . گندیدن : ثعطِ لحم ؛ بوی گرفتن گوشت . ثعطِ ماء؛ گندیدن آب . <BR><font color=\"Blue\">◄</font> ثعط جلد؛ بوی گرفتن و پاره پاره شدن پوست . <BR><font color=\"Blue\">◄</font> ثعط شفه ؛ برآماسیدن لب و کفته گردیدن .<br /></font></div>'),
(82180, 'ثعط', '<span class=\"hlight\">ثعط.</span> <font color=\"DarkGreen\"><b>[ ث َ ع ِ]</font></b> (ع ص ) گندا. گنده . گندیده . بوی گرفته . (چون گوشت و آب و جلد). <BR><font color=\"Blue\">◄</font> برآماسیده و کفته (لب ).<br /></font></div>'),
(82181, 'ثعل', '<span class=\"hlight\">ثعل .</span> <font color=\"DarkGreen\"><b>[ ث ُ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ]</font></b> (ع ص، اِ) دندان افزونی پس دندانها یا کج و راست برآمدگی دندان . <BR><font color=\"Blue\">◄</font> دندان زائد و پستان افزونی از ستور. ج، ثعول .<br /></font></div>'),
(82182, 'ثعل', '<span class=\"hlight\">ثعل .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع ص، اِ) ج ِ اَثعل و ثَعلاء.<br /></font></div>'),
(82183, 'ثعل', '<span class=\"hlight\">ثعل .</span> <font color=\"DarkGreen\"><b>[ ث َ ع َ ]</font></b> (ع مص ) ثعل سن ؛ برآمدن دندان زائد. <BR><font color=\"Blue\">◄</font> کج و راست برآمدن دندان .<br /></font></div>'),
(82184, 'ثعل', '<span class=\"hlight\">ثعل .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b>(ع اِ) کرمکی است که در خیک پیدا گردد چون فاسد شودو بویناک گردد. <BR><font color=\"Blue\">◄</font> مرد لئیم . مرد ناکس .<br /></font></div>'),
(82185, 'ثعل', '<span class=\"hlight\">ثعل .</span> <font color=\"DarkGreen\"><b>[ ث ُ ع َ ]</font></b> (اِخ ) نام شخصی است . <BR><font color=\"Blue\">◄</font> پدر قبیله ای است ؛ بنوثعل .<br /></font></div>'),
(82186, 'ثعل', '<span class=\"hlight\">ثعل .</span> <font color=\"DarkGreen\"><b>[ ث ُ ع َ ]</font></b>(اِخ ) موضعی است به نجد. ابن درید گوید به این معنی با ضم ثاء و عین است اما با سکون عین آبی است از بنی قواله نزدیک سجابه ٔ نجد در دیار کلاب . و گویند وادیی است نزدیک مکه در دیار بنی سلیم . (مراصد الاطلاع ).<br /></font></div>'),
(82187, 'ثعلب', '<span class=\"hlight\">ثعلب .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ]</font></b> (ع اِ) روباه ماده یا عام است . روبه . گته سک . و در اختیارات بدیعی آمده است : بپارسی روباه گویند چون به آب بپزند و بر مفاصل طلا کنند بغایت نافع بود خاصه همچنان زنده بپزند وزمانی نیک در آن آب نشینند اما بعد از تنقیه این عمل کنند و پیه وی درد مفاصل را سودمند بود و درد گوش ببرد چون در گوش چکانند و اگر به آن ادمان نمایند کری زایل کند و درد گوش ببرد و شش وی خشک کرده و سحق نموده بیاشامند نافع بود جهت ربو و سرفه و پیه وی چون در دهان گیرند درد دندان زایل کند و درد چشم را نافع بود و شریف گوید پیه وی چون با پوست تخم مرغ سوخته بیامیزند و بر داءالثعلب نهند نافع بود و مجرب است و زهره ٔ وی با کرفس و اشق بگدازند مساوی و سعوط کننددر بینی کسی که ابتداء جذام بود در هر روز یکبار بغایت نافع بود و چون آدمی دندان وی در دست گیرد ایمن باشد از بانک کردن سگ و پیه وی با زیت انفاق کهن بگدازند و بر نقرس و مفاصل طلا کنند نافع بود پوست وی بغایت گرم بود از همه پوستها مسخن تر بود و مرطوب مزاج را شاید پوشیدن و محرورمزاج را نشاید. و کسی را که سرما بروی غالب باشد شاید و هرچند که موی بر وی زیاده بود سخونت وی بیشتر بود و آن لباس زنان بلغمی مزاج و پیران باشد و در خواص ابن زهر آمده است که پیه وی چون طلا کنند بر تازیانه که چوبی در اندرون او بود در هر خانه که بنهند مجموع کیکها بر آن جمع شوند و این مؤلف گوید اگر بادام تلخ بکوبند و بر گوشت افشانند چون روباه بخورد بیهوش شود . و در تحفه ٔ حکیم مؤمن آمده است : به فارسی روباه گویند و آن حیوان معروفی است پوست او در گرمی قریب به سمور جهت مبرودین و مرطوبین و نطول طبیخ زنده ٔ او و مذبوح او در درد مفاصل سودمند و طبیخ زنده قویترخصوصاً که در روغن زیتون جوشانیده باشند جهت تعقد وصلابت مفاصل نافع و باعث سرعت راه رفتن اطفال و رفع اعیاء و آشامیدن یک مثقال از شش او که خشک کرده باشند با آب عسل جهت ربو و سرفه و طلاء آن با پوست سوخته ٔتخم مرغ جهت داءالثعلب مجرّب و پیه او جهت درد گوش وبا روغن زیتون و امثال آن جهت نقرس و دردهای بارد وسعوط زهره ٔ او باهم وزن آن آب کرفس در هر ده روز یکبار جهت ابتداء جذام و زیاده نشدن آن بغایت مؤثر و گوشت او جهت مبرودین و تحریک باه و صاحبان استسقا مفید و خاکستر پوست او جهت سوختگی آتش و بواسیر و قروح حاره و تدهین دست و پا به پیه او مانع مضرت سرما و نگاه داشتن دندان او را جهة منع فریاد کردن سگ مجرب دانسته اند و مالیدن پیه او بر چوبی و نصب کردن آن درموضعی از خانه سبب اجتماع کیک بر آن چوب - انتهی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">هو أروغ من ثعلب </span> ؛ پویاتر از روباه .<br /> <BR><font color=\"Blue\">◄</font> موی روباه . ج، ثعالب و ثعالی . <BR><font color=\"Blue\">◄</font> جای بیرون آمدن آب از حوض . <BR><font color=\"Blue\">◄</font> جای بیرون آمدن آب باران از موضع خشک کردن خرما. <BR><font color=\"Blue\">◄</font> بیخ نهال خرما. <BR><font color=\"Blue\">◄</font> سر نیزه که در کعب سنان باشد. زبانه ٔ نیزه که در سنان باشد. <BR><font color=\"Blue\">◄</font> نباتی است طبی .و بهترین نوع آن در دشت ایجرود زنجان است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">داءالثعلب </span> ؛ بیماری است که تمامی یا بعض از پشم یا موی حیوان را بریزاند و چون این مرض بیشتر روباهان دارند بیماری آن نیز بنام بیماری ثعلب مشهوراست .<br /></font></div>'),
(82188, 'ثعلب', '<span class=\"hlight\">ثعلب .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ]</font></b> (اِخ ) احمدبن یحیی بن زیدبن سیارشیبانی بولاء. رجوع به احمدبن یحیی و فهرست ابن الندیم . (ص <span class=\"hlight\" dir=\"rtl\">١١٠</span>) و الموشح مرزبانی و ارشاد یاقوت (ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>-<span class=\"hlight\" dir=\"rtl\">١٥٤</span>) و وفیات الاعیان ابن خلکان و بغیةالوعاة سیوطی و روضات الجنات خونساری (ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٦</span>) و دائرة المعارف اسلام (ماده ٔ ثعلب ) شود.<br /></font></div>'),
(82189, 'ثعلب', '<span class=\"hlight\">ثعلب .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ]</font></b> (اِخ ) ابن عمرو. پدر خزاعة که بنی خزاعة جمله فرزندان اویند. (مجمل التواریخ و القصص ص <span class=\"hlight\" dir=\"rtl\">١٥١</span> و <span class=\"hlight\" dir=\"rtl\">١٧٣</span>).<br /></font></div>'),
(82190, 'ثعلب', '<span class=\"hlight\">ثعلب .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ]</font></b> (اِخ ) نام جمل پیغمبر. (امتاع الأسماع مقریزی ).<br /></font></div>'),
(82191, 'ثعلب مصری', '<span class=\"hlight\">ثعلب مصری .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ م ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) نام دوائی و در این تخفیف کرده اند زیرا این کلمه در اصل خصیةالثعلب باشد چه دوای مذکور بیخی است بشکل خایه ٔ روباه . چون در نواحی مصر پیدا میشود بمصر منسوب کنند ظاهراً فقط ثعلب مصری یا ثعلب گفتن درست نباشد مگر آنکه گوئیم چون لفظ خصیه مکروه است لهذا اگر فقط بلفظ ثعلب موسوم کنند جائز باشد. (غیاث اللغة).<br /></font></div>'),
(82192, 'ثعلبان', '<span class=\"hlight\">ثعلبان .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ]</font></b> (ع اِ) تثنیه ٔ ثعلب . دو روباه . <BR><font color=\"Blue\">◄</font> روباه . و درکنز ثعلبان بضم اول و سوم روباه نر. (غیاث اللغة).<br /></font></div>'),
(82193, 'ثعلبان', '<span class=\"hlight\">ثعلبان .</span> <font color=\"DarkGreen\"><b>[ ث ُ ل َ ]</font></b> (ع اِ) روباه نر. <BR><font color=\"Blue\">◄</font> ذوثعلبان ؛ بیماریی است .<br /></font></div>'),
(82194, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َل َ ب َ ]</font></b> (اِخ ) ابن زیدبن الحارث بن حرام بن غنم بن کعب بن سلمةبن سعدبن علی بن ساردةبن یزیدبن جشم بن خزرج الانصاری الخزرجی الملقب بالجدع . موسی بن عقبه گوید ثعلبه غزوه ٔ بدر را درک کرده و در طائف کشته شد. ابن ثعلب پدر ثابت صحابی و خود نیز از صحابه است . ابن منده او را ثعلبةبن الجدع آورده و لقب او را نام پدر وی قرار داده است و در جائی دیگر او را ثعلبةبن حارث نامیده و نام جد ثعلبة را بجای نام پدر وی گذاشته است . و ابوموسی و ابن فتحون وی را ثعلبه بن حرام گفته اند و از این جهة، در بادی نظرچنین می نماید که سه تن باشند ولی ظاهراً این سه نام از یک کس است . رجوع به کتاب الاصابه چ مصر سنه <span class=\"hlight\" dir=\"rtl\">١٣٢٣</span> ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٦</span> و <span class=\"hlight\" dir=\"rtl\">٢٠٧</span> و رجوع به امتاع الاسماع ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٩٠</span> شود.<br /></font></div>'),
(82195, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن سلام . صحابی و برادر عبداﷲ ابن سلام است . ابو عمر آرد که طبری بروایت مقطوع، از ابن جریح آورده است که این ثعلبه یکی از کسانی است که آیه ٔ «من اهل الکتاب امة قائمة» (قرآن <span class=\"hlight\" dir=\"rtl\">١١٣/٣</span>) در باب آنان نازل شده است . رجوع به کتاب الاصابه چ مصر سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٣٢٣</span> ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٧</span> شود.<br /></font></div>'),
(82196, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن سوید انصاری . برادر اویس بن سوید انصاری صحابی است و ابن فتحون ثعلبه را نیز در شمار صحابه آورده است . رجوع به کتاب الاصابه چ مصر سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٣٢٣</span> ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٧</span> شود.<br /></font></div>'),
(82197, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن سعیةالیهودی او در غزوه ٔ بنی قریظة اسلام آورد .<br /></font></div>'),
(82198, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن سعید. و ثعلبةبن سلام دو تن صحابی باشند و این دو پیش از اسلام دین جهودان داشتند و آیت «لیسوا سوآء من اهل الکتاب امةً قاَّئمة (قرآن <span class=\"hlight\" dir=\"rtl\">١١٣/٣</span>) الخ .» درباره ٔ آن دو و اسیدبن سعید و عبداﷲبن سلام نازل شده است و ثعلبةبن سعید در حیات رسول (ص ) درگذشت . (قاموس الاعلام ).<br /></font></div>'),
(82199, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن سلامان بن ثعل از قبیله ٔ طی . جدی است جاهلی و بنو ثعلبه که در مشرق مصر و بادیةالشام متفرق اند از نسل وی میباشند. رجوع به الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧١</span> شود.<br /></font></div>'),
(82200, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن سعدبن ذبیان بن بغیض، از تیره ٔ غطفان، جدی است جاهلی، و فرزندان او بطنی ازذبیان میباشند. رجوع به الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧١</span> شود.<br /></font></div>'),
(82201, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن سعدبن ضبه . جدی است جاهلی و منسوب بدو را ثعلبی گویند و فرزندان او بطنی از قبیله ٔ ضبه باشد. رجوع به الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٠</span> شود.<br /></font></div>'),
(82202, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن سعد یا ثعلبةبن ساعده . صحابی است . او درک غزای بدر کرد و در غزوه ٔ احد بشهادت رسید. (قاموس الاعلام ) و رجوع به کتاب الاصابه چ مصر سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٣٢٣</span> ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٧</span> شود .<br /></font></div>'),
(82203, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن ساعده . رجوع به ثعلبةبن سعد شود.<br /></font></div>'),
(82204, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن مسلم . محدث است .<br /></font></div>'),
(82205, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) التمیمی العنبری . جد هرماس بن حبیب عنبری است . رجوع به الاصابة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٩</span> شود.<br /></font></div>'),
(82206, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) انصاری . پدر عبداﷲ و گویند نام پدر وی سهیل است . رجوع به الاصابه ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٠</span> شود.<br /></font></div>'),
(82207, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) اصفهانی . ابوبحر. تابعی است .<br /></font></div>'),
(82208, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابومالک . تابعی است . او از لیث بن ابی سلیم و از او فریابی روایت کند.<br /></font></div>'),
(82209, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن یزید. محدث است .<br /></font></div>'),
(82210, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span><font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن ودیعة. صحابی انصاری است اودر وقعه ٔ تبوک یکی از مخالفین بود سپس انابت جست و توبه ٔ او پذیرفته گشت و آیت «و آخرون اعترفوا بذنوبهم خلطوا عَمَلاً صالحاً و آخر سیئاً» (قرآن <span class=\"hlight\" dir=\"rtl\">١٠٢/٩</span>) درباره ٔ او و یارانش ابولبابه و اوس بن خذام و کعب بن مالک و مرارة و هلال بن امیة نازل گشت . (قاموس الاعلام ).<br /></font></div>'),
(82211, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن میمون . ابواسحاق مولی بنی اسد ثم بنی سلامة. در نامه ٔ دانشوران آمده است : ابو اسحاق ثعلبةبن میمون از بزرگان محدثین و اجلای فقهای امامیه است و در عداد راویان امامین همامین ابوعبداﷲ جعفربن محمدالصادق و ابوالحسن موسی بن جعفر علیهما السلام شمرده شود. شیخ نجاشی درکتاب رجال در تمجید و توصیف وی این عبارات آورده گوید: کان وجها فی اصحابنا قاریاً فقیها نحویا لغویا راویة و کان حسن العمل کثیرالعبادة و الزهد روی عن ابی عبداﷲ و ابی الحسن علیهما السلام له کتاب . روی عنه عبداﷲبن المزخرف الحجال یعنی ابواسحاق از بزرگان اصحاب ما امامیه بود بفن قرائت و علم نحو و لغت و حدیث معرفتی کامل داشت و به نیکوئی کردار و کثرت زهد و عبادت موصوف بود از جناب ابوعبداﷲ صادق و ابوالحسن کاظم روایت مینمود او را کتابی است و عبداﷲ بن المزخرف آن کتاب را از ابواسحاق روایت کند. علامه در کتاب خلاصه بر کلام نجاشی این عبارات را مزید آورده گوید: و کان فاضلاً متقدماً معدوداً فی العلماء و الفقهاء الاجلةفی هذه العصابة سمعه هارون الرشید یدعو فی الوتر فاعجبه . یعنی ابو اسحاق فقیه از فضلای متقدمین طایفه ٔ امامیه و در عداد علما و فقهای امامیه معدود بود وقتی در نماز وتر بخواندن دعا مشغول بود هارون الرشید از نزد وی عبور نمود ایستاد دعایش را استماع نمود از حالت وی و از دعای وی اظهار شگفتی کرد. ابوعمرو کشی در کتاب رجال گوید. ذکر حمدویه عن محمدبن عیسی اِن ّ ثعلبةبن میمون مولی محمدبن قیس الانصاری و هو ثقة خیر فاضل مقدم معدود فی العلماء و الفقهاء الأجلة فی هذه العصابة و یقال له ابواسحاق الفقیه کما یأتی فی ترجمة جمیل . یعنی حمدویه از محمد بن عیسی روایت کرده است که ابواسحاق ثعلبة بن میمون از موالی محمدبن قیس انصاری شمرده شود و او دانشمندی بود موثق و نیکوکار و بر علمای زمان خود تقدم و برتری داشت و در سلک بزرگان از علما و فقهای امامیه منظوم بود و چنانکه در ترجمت احوال جمیل خواهد آمد ثعلبة بن میمون را ابواسحاق فقیه گویند. ابوعلی در کتاب منتهی المقال در ترجمت احوال ابواسحاق صاحب عنوان گوید هو من اعاظم الثقات والزهاد و العباد و الفقهاء و العلماء الامجاد. الخ . در رجال نجاشی مسطور است و رأیت بخط ابن نوح فیما کان وصّی به الی من کتبه حدثنا محمدبن احمدعن احمدبن محمدبن سعید قال قال حدثنا علی بن الحسن بن فضال عن علی بن اسباط قال لما ان حج هارون الرشید مرّ بالکوفة فصار الی الموضع الذی یعرف بمسجد سمال و کان ثعلبة ینزل فی غرفة علی الطریق فسمعه هارون و هو فی الوتر و هو یدعو و کان فصیحا حسن العبارة فوقف یسمع دعأه و وقف من قدامه و من خلفه و اقبل یستمع ثم قال للفضل بن الربیع یا فضل تسمع ما أسمع ثم قال ان خیارنا بالکوفة. یعنی بخط ابن نوح دیدم که در وصایای خود چنین نوشته بود حدیث کرد ما را محمدبن احمد از احمدبن محمدبن سعید گفت خبر داد ما را علی بن حسن بن فضال از علی بن اسباط گفت چون هارون الرشید بحج میرفت از کوفه عبور نمود بمکانی که بمسجد سمال معروف است رسید و ثعلبة بن میمون در آنجا در غرفه ای که مشرف بر جاده بود سکنی داشت و بنماز وتر ایستاده بدعا و مناجات اشتغال داشت و ثعلبة مردی فصیح و به نیکوئی کلام معروف بود هرون کلام ثعلبة را شنید و بایستاد و بدعای ثعلبة گوش فراداشت و از ملازمان هارون کسانی که پیشروی او بودند و آنانی که از قفای او می آمدند ایستادند هرون زمانی ایستاده دعای ثعلبة را استماع نمود آنگاه بجانب فضل بن ربیع متوجه شده او را گفت ای فضل میشنوی آنچه را که من میشنوم آنگاه گفت برگزیدگان و اخیار ما در شهر کوفه می باشند... و ابن ابی عمیر و محمدبن اسماعیل بن بزیع و علی بن حکم از او روایت کنند و او خود از زرارة و ابوبکر خضرمی و از جناب ابوعبداﷲ صادق علیه السلام واز جناب ابوالحسن موسی کاظم علیه السلام روایت کند.<br /></font></div>'),
(82212, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن زهدم التمیمی الحنظلی، صحابی است . و از بنی ثعلبةبن یربوع بن حنظله است و ابن ابی حاتم گوید که ثعلبه صحبت پیغمبر درک کرد و در کوفه میزیست و از وی بعض احادیث روایت شده است . (قاموس الاعلام . و کتاب الاصابه چ مصر سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٣٢٣</span> ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٧</span>).<br /></font></div>'),
(82213, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن المطهربن احمد الحنظلی . مکنی به ابوطاهر. از ابوعلی مصاحفی، و جز او، سماع دارد، و وفات او در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٣٩٨</span> هَ . ق . بوده است . رجوع به ذکر اخبار اصفهان ابی نعیم ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٠</span> شود.<br /></font></div>'),
(82214, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b>(اِخ ) ابن جذع . صحابی انصاری است . او درک غزوه ٔ بدرکرد و در وقعه ٔ طائف بشهادت رسید. (قاموس الاعلام ).<br /></font></div>'),
(82215, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن رُهم العدوانی از تیره ٔ عدنان، جدی است جاهلی . عبداﷲبن جبیر و خوات بن جبیر و حارث بن نعمان و صباح بن ثابت، که در زمره ٔ صحابه اند از نسل ابن ثعلبه میباشند رجوع به الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٠</span> شود.<br /></font></div>'),
(82216, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ث َ ل َ ب َ ]</font></b> (اِخ ) ابن رومان، قبیله ای است از عرب .<br /></font></div>'),
(82217, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن الربیع، و بقولی ثعلبةبن سهل، المعالج . او از شهر قم، و بروایتی از اصفهان، از ثقات محدثین است و از جعفربن مغیره و اعمش بن سلیم روایت کند. و جریر و ابومعاویه ضریر و یعقوب قمی و مهران رازی از وی روایت دارند. رجوع به کتاب ذکر اخبار اصفهان ابی نعیم چ لیدن . سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٩٣١</span> ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٩</span> و <span class=\"hlight\" dir=\"rtl\">٢٤٠</span> شود.<br /></font></div>'),
(82218, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن الخشام . دلیری است از عرب . (منتهی الارب ).<br /></font></div>'),
(82219, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن خدام انصاری او از شش یا هفت تن صحابه ای است که از غزوه ٔ تبوک تخلف کردند. رجوع به کتاب الاصابه چ مصر سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٣٢٣</span> هَ . ق . ج <span class=\"hlight\" dir=\"rtl\">٨٥١</span> و <span class=\"hlight\" dir=\"rtl\">٢٠٧</span> شود.<br /></font></div>'),
(82220, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن حکم . صحابی است و درک غزوه ٔ خیبر کرده است و سپس در بصره و بعد از آن در کوفه اقامت گزیده و از او بعض روایات منقول است . (قاموس الاعلام ).<br /></font></div>'),
(82221, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) تابعی است و از عائشه رضی اﷲ عنها روایت کند و کنیت او ابوالکنود است .<br /></font></div>'),
(82222, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن حاطب . (در کتاب الاصابه، ابن ابی حاطب ). صحابی انصاری است . وی درک غزوه ٔ بدر کرد و تا گاه خلافت عثمان بزیست . او از رسول صلوات اﷲ علیه درخواست تا دعا کند که خدای تعالی او را مال فراوان عطا فرماید و رسول (ص ) در حق وی دعا کرد و او صاحب اموال و گله های مواشی شد و آنگاه که عامل صدقات برای اخذ زکوة نزد وی شد او از دادن صدقه امتناع ورزید و چون این خبر برسول برداشتند فرمود یاویح صدقة!یاویح صدقة! و آیت، و منهم من عاهداﷲ لئن آتانا من فضله (قرآن <span class=\"hlight\" dir=\"rtl\">٧٥/٩</span>). الخ . در حق وی فرود آمد، و او چون این آیت بشنید نزد رسول شد و صدقات خویش، پیش کشید و آنحضرت صدقه ٔ وی قبول نفرمود و بزمان ابی بکر و عمرو عثمان نیز خلفا صدقه ٔ او نپذیرفتند. (قاموس الاعلام ). مقریزی او را از بنی امیةبن زید و منافق و از اصحاب مسجد ضرار شمرده است .<br /></font></div>'),
(82223, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن جفنة. عمربن عامربن حارث بن امروءالقیس . یکی از ملوک عرب بنی جفنه معروف بغسانیان . (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٩١</span>).<br /></font></div>'),
(82224, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن سهیل . گویند که ثعلبة نام ابوامامه حارثی صحابی است و بقولی مشهورتر نام ابوامامه ایاس بن ثعلبه است نه ثعلبه . رجوع به کتاب الاصابه چ مصر سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٣٢٣</span> ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٨</span> و ج <span class=\"hlight\" dir=\"rtl\">٨</span> ص <span class=\"hlight\" dir=\"rtl\">٩</span> شود.<br /></font></div>'),
(82225, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ث َ ل َ ب َ ]</font></b> (اِخ ) ابن جدعاء. قبیله ای است از عرب .<br /></font></div>'),
(82226, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن ثابت و بقولی ثعلبةبن اوس . صحابی انصاری است . رجوع به کتاب الاصابه چ مصر سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٣٢٣</span> ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٦</span> و ج <span class=\"hlight\" dir=\"rtl\">٨</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧١</span> شود.<br /></font></div>'),
(82227, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن بلال البصری الاعمی محدث است . صاحب لسان المیزان گوید «لا یعرف » و همو گوید که قواریری حدیثی منکر از او روایت کرده . و بخاری در باب وی گوید: «لایتابع» ولی ابن جهان او را در زمره ٔ ثقات آرد. رجوع به لسان المیزان، ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨٢</span> شود.<br /></font></div>'),
(82228, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن بکربن حبیب از تیره ٔ تغلب بن وائل، جدی است جاهلی که اعشی تغلب شاعر از نسل او میباشد. رجوع به الاعلام زرکلی، ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٠</span> شود.<br /></font></div>'),
(82229, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن اودبن اسد. از تیره ٔ خزیمه از قبیله عدنان جدی است جاهلی . و کمیت اسدی شاعر و ضراربن عمروصحابی از فرزندان او باشند. رجوع به الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٠</span> شود.<br /></font></div>'),
(82230, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن ابراهیم کوفی . محدث است . ابن ابی طی وی را در زمره ٔ رجال شیعه آرد و گوید او را تصنیفی است که در آن از جماعتی از اهل سنت روایت حدیث کند. رجوع به لسان المیزان ج <span class=\"hlight\" dir=\"rtl\">٨٢٢</span> شود.<br /></font></div>'),
(82231, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن ابی مالک القرضی مکنی به ابویحیی صحابی است و او پیشوای قبیله ٔ بنی قریظه بود و از او بعض احادیث منقول است . (قاموس الاعلام ). و رجوع به کتاب الاصابة چ مصر سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٣٢٣</span> هَ . ق . ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٩</span> شود.<br /></font></div>'),
(82232, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن ابی رقیةاللخمی . صحابی است و حاضر فتح مصر بوده است . (قاموس الاعلام ).<br /></font></div>'),
(82233, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن ابی بلتعه . صحابی است . و در صغر سن درک صحبت رسول کرده است واز اکثر صحابه ٔ کرام روایت دارد. (قاموس الاعلام ). و رجوع به ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٦</span> کتاب الاصابة چ مصر سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٣٢٣</span> شود.<br /></font></div>'),
(82234, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن عمرو. یکی ازملوک عرب بنی جفنه معروف به غسانیان است که در بادیةالشام حکومت میکردند. ثعلبه نخستین کس است از این سلسله که به «ملک » ملقب گردید. وی از موالیان قیاصره ٔروم بود و معاصرین او در مقابل هجوم ایرانیان از جهة حیره، از وی کمک میخواستند. مدت سلطنت او در حدودبیست سال بود. او در قرن دوم بعد از میلاد میزیست . صاحب مجمل التواریخ و القصص در باب وی آرد: او هفده سال پادشاهی راند و بناها کرد چون عقه و صرح الغدیر یعنی کوشک غدیر و آن بجانب بلقاست در اطراف حوران . (مجمل التواریخ و القصص ص <span class=\"hlight\" dir=\"rtl\">١٧٤</span>) (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧١</span>).<br /></font></div>'),
(82235, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (ع اِ) روباه ماده .ثعال . ثعالة. <BR><font color=\"Blue\">◄</font> استخوان دمغزه و سرین .<br /></font></div>'),
(82236, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن مالک . ابوجعفر. تابعی است .<br /></font></div>'),
(82237, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن مازن بن الازد. از اجداد عمرو (یا عمر) بن مزیقیاء جد انصار و سیّد جمله ٔ بنی کهلان از آل قحطان .<br /></font></div>'),
(82238, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن قیظی بن صخربن سلمه ٔ انصاری . صحابی است . مطین و طیرانی، و جز آنان، او را در زمره ٔ اصحاب بدر و صفین گفته اند. (کتاب الاصابه ج <span class=\"hlight\" dir=\"rtl\">٢٠٩١</span>).<br /></font></div>'),
(82239, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن الفرات بن عبدالرحمن بن قیس . جد او درک صحبت پیغمبر کرده است . وی از یعقوب بن عبیدة و محمدبن کعب القرطی روایت دارد و زیدبن الحباب از او روایت کند و ابو حاتم گوید او را نشناسم، و ابو زرعه با اینکه او را مدنی داند نیز گوید او را نشناسم . رجوع به لسان المیزان چ حیدرآباد ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨٢</span> شود.<br /></font></div>'),
(82240, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن غنمة . صحابی انصاری است . او غزوه ٔ بدر و عقبه را درک کرد و بتان بنی سلمه را با معیت معاذبن جبل و عبداﷲبن انیس بشکست و در غزوه ٔخندق و بروایت دیگر در غزوه ٔ خیبر به عز شهادت نایل آمد. قاموس الاعلام و امتاع الاسماع ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤١</span>. و نیز درکتاب اخیر ص <span class=\"hlight\" dir=\"rtl\">٤٤٨</span> وی یکی از بکائین محسوب شده است .<br /></font></div>'),
(82241, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن عمرو الجذامی . صحابی است . ابن اسحاق، در مغازی، او را در زمره ٔ کسانی که زیدبن حارثه از بنی جذام اسیر کرد، و پیغمبر (ص ) امر به آزادی ایشان فرمود آورده است . رجوع به الاصابه چ مصر سنة <span class=\"hlight\" dir=\"rtl\">١٣٢٣</span> ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٨</span> و <span class=\"hlight\" dir=\"rtl\">٢٠٩</span> شود.<br /></font></div>'),
(82242, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن عمروبن محصن بن عمرو عتیک بن عمروبن مبذول بن مالک بن النجار الانصاری . صحابی است . موسی بن عقبه او را در شمار بدریین آرد و گوید در جنگ جسر ابی عبید بشهادت نائل شد و واقدی گوید او در خلافت عثمان وفات یافت .رجوع به کتاب الاصابه چ مصر سنة <span class=\"hlight\" dir=\"rtl\">١٣٢٣</span> ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٩</span> شود.<br /></font></div>'),
(82243, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن عمرو. بغوی گوید که نام ابوعمرة انصاری است . (کتاب الاصابه ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٩</span>).<br /></font></div>'),
(82244, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن عکابةبن صعب از بنی بکربن وائل عدنان . جدی است جاهلی که شیبان و ذهل و تیم اﷲ و قیس از فرزندان اویند. (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">١٧١١</span>).<br /></font></div>'),
(82245, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن عُکابة. نام قبیله ای از عرب است . (امتاع الاسماع ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠</span>).<br /></font></div>'),
(82246, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن عبیدبن عدی . صحابی است . ذهبی در تجرید آرد، که ابن الجوزی در تلقیح، ذکر او آورده است . عسقلانی گوید: ترسم که در نام پدر وی تصحیفی باشد و این مرد ظاهراً همان ثعلبه بن عنمةبن عدی است . رجوع به کتاب الاصابه چ مصر سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٣٢٣</span> ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٨</span> شود.<br /></font></div>'),
(82247, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن عبدالرحمن . صحابی انصاری است . وی ملازمت خدمت رسول می کرد و وقتی او را رسول صلوات اﷲ علیه به خانه ٔ یکی از اصحاب فرستاد و او در حرم آن صحابی بنظر ریبة نگریست و رسول (ص ) این معنی بوحی بدانست و او بگریخت و مدت چهل روز در کوه ها متواری بود. (قاموس الاعلام و ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٨</span> کتاب الاصابة).<br /></font></div>'),
(82248, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن عباد. محدث است .<br /></font></div>'),
(82249, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن عامر. پیشوای ثعالبة، یکی از پانزده ٔ فرقه ٔ خوارج . (بیان الادیان ).<br /></font></div>'),
(82250, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن صُعیرالمازنی . از شعراء متقدم عرب است .<br /></font></div>'),
(82251, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) نام خلقی و قبایلی چند. <BR><font color=\"Blue\">◄</font> نام بیست و دو تن صحابی و چند محدث .<br /></font></div>'),
(82252, 'ثعلبة', '<span class=\"hlight\">ثعلبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) ابن صعیر یا ابن ابی صعیر. او و پسر او عبداﷲبن ثعلبة صحابی باشند و از ثعلبة بعض احادیث مروی است .<br /></font></div>'),
(82253, 'ثعلبتان', '<span class=\"hlight\">ثعلبتان .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ب َ ]</font></b> (اِخ ) دو قبیله از عرب یعنی ثعلبة بن جدعاء و ثعلبة بن رومان .<br /></font></div>'),
(82254, 'ثعلبی', '<span class=\"hlight\">ثعلبی .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ]</font></b> (اِخ ) ابوعمرو. تابعی است .<br /></font></div>'),
(82255, 'ثعلبی', '<span class=\"hlight\">ثعلبی .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ]</font></b> (اِخ ) او راست : طبقات الثعلبی الموسوی و آنرا پیش از طبقات اسنوی نوشته است . (قاموس الاعلام ).<br /></font></div>'),
(82256, 'ثعلبی', '<span class=\"hlight\">ثعلبی .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ]</font></b> (اِخ ) رجوع بعمربن بندار شود.<br /></font></div>'),
(82257, 'ثعلبی', '<span class=\"hlight\">ثعلبی .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ]</font></b> (اِخ ) ابواسحاق احمدبن محمد نیشابوری . یکی از مشاهیر فقها و مفسرین . مولد او به نیشابور و در <span class=\"hlight\" dir=\"rtl\">٤٢٧</span> هَ . ق . درگذشته است . او راست : کتاب تاریخ الانبیاء و کتاب تاج العرائس و الکشف و البیان فی تفسیر القرآن ونیز رجوع به ابی اسحاق ثعلبی و احمدبن ثعلبی شود.<br /></font></div>'),
(82258, 'ثعلبی', '<span class=\"hlight\">ثعلبی .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ بی ی ]</font></b> (ع ص نسبی ) روباه فروش . <BR><font color=\"Blue\">◄</font> روباه دوز. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> منسوب است بقبیله ٔ بنی ثعلبة و صنعت پوستین روباه . (سمعانی ).<br /></font></div>'),
(82259, 'ثعلبیة', '<span class=\"hlight\">ثعلبیة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ بی ی َ ]</font></b> (اِخ ) یکی از منازل راه مکه است که سابق قریه ای بود و اکنون خرابه است و مشهور. (مراصد الاطلاع ). این موضع به سه منزلی کوفه بین شقوق و خزیمیه است . (معجم البلدان ) <span class=\"hlight\">:</span> <br />گرمگاهی کافتاب استاده در قلب اسد<br />سنگ و ریک ثعلبیه بید و ریحان دیده اند.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(82260, 'ثعلبیة', '<span class=\"hlight\">ثعلبیة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ بی ی َ ]</font></b> (ع اِ) رفتار اسب که برفتار سگ ماند.<br /></font></div>'),
(82261, 'ثعله و افرا', '<span class=\"hlight\">ثعله و افرا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام کتابی است از سهل بن هارون فارسی رامنوی . (ابن الندیم ).<br /></font></div>'),
(82262, 'ثعلول', '<span class=\"hlight\">ثعلول .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع ص، اِ) خشمناک . <BR><font color=\"Blue\">◄</font> گوسفندی که شیر آن از سه چهار جای دوشیدن توانند بجهت زیادتی پستان . و صغانی گوید: دندان زائد پس دندانها یا کج و راست برآمدگی دندان .<br /></font></div>'),
(82263, 'ثعم', '<span class=\"hlight\">ثعم .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) نزع . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> کشیدن چیزی را.<br /></font></div>'),
(82264, 'ثعو', '<span class=\"hlight\">ثعو.</span> <font color=\"DarkGreen\"><b>[ ث َع ْوْ ]</font></b> (ع اِ) نوعی از خرما یا خرمای بزرگ یا غوره ٔ خرما که نرم شده باشد. <BR><font color=\"Blue\">◄</font> لغتی است در معو.<br /></font></div>'),
(82265, 'ثعوب', '<span class=\"hlight\">ثعوب .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b>(ع اِ) تلخه . (منتهی الارب ). مِرّة. (تاج العروس ).<br /></font></div>'),
(82266, 'ثعول', '<span class=\"hlight\">ثعول .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) ج ِ ثَعْل و ثُعل و ثَعَل .<br /></font></div>'),
(82267, 'ثعول', '<span class=\"hlight\">ثعول .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص، اِ) ناقه و جز آن که بالای پستانش پستان زائدکوچک باشد یا پستانش سر دیگر دارد و آن عیب است . <BR><font color=\"Blue\">◄</font> کتیبه ٔ ثعول ؛ لشکری پر از حشو و توابع.<br /></font></div>'),
(82268, 'ثعیة', '<span class=\"hlight\">ثعیة.</span> <font color=\"DarkGreen\"><b>[ ث َ ی َ ]</font></b> (ع مص ) خالی شدن سرای از قبیله . <BR><font color=\"Blue\">◄</font> گرسنگی . گرسنه گردیدن .<br /></font></div>'),
(82269, 'ثعیجر', '<span class=\"hlight\">ثعیجر.</span> <font color=\"DarkGreen\"><b>[ ث ُ ع َ ج ِ ]</font></b> (ع اِ مصغر) تصغیر مثعنجر. (دریا و جای ژرف آن ).<br /></font></div>'),
(82270, 'ثعیط', '<span class=\"hlight\">ثعیط.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) خاک خرد. <BR><font color=\"Blue\">◄</font> ریگ تنک که بادش از جائی به جائی برد.<br /></font></div>'),
(82271, 'ثعیلب', '<span class=\"hlight\">ثعیلب .</span> <font color=\"DarkGreen\"><b>[ ث ُ ع َ ل ِ ]</font></b> (اِخ ) لقب فخرالدین ابوشجاع محمدبن علی بغدادی است . او بیست سال بموصل بود و سپس بدمشق شد و صلاح الدین ایوبی و دیگر رؤساء به او اکرام کردند و صلاح الدین برای او ماهی سی دینار اجری فرمود او مردی متدین و صاحب نسک و ورع و کثیرالصیام بودو در جامع دمشق ماهها معتکف میشد و مقصوره ٔ کلاسه رابرای او ساختند و او را تصانیف بسیار است از آنجمله زیج مشهور اوست که نیکو و صحیح است دیگر المنبر فی الفرائض و کتاب فی غریب الحدیث، عشر مجلدات و کتاب فی الخلاف مجدول بر وضع تقویم الصحة. و وی دائم الاشتغال بود و صاحب اشعار بسیار است آنگاه که از زیارت خانه باز می گشت چون بحله رسید چوب محمل بر سر او فرود آمد و بمرد و جسد وی به بغداد برده بجنب خاک پدر و مادر وی بخاک سپردند و غیبت او از بغداد چهل سال کشیده بود . رجوع به ابن الدهان فخرالدین ابوشجاع ... شود .<br /></font></div>'),
(82272, 'ثعیلبات', '<span class=\"hlight\">ثعیلبات .</span> <font color=\"DarkGreen\"><b>[ ث ُ ع َ ل ِ ]</font></b> (اِخ ) بصیغه ٔ تصغیر و جمع. محلی در شعر. (مراصد الاطلاع ). آنرا ثعالبات نیز گویند.<br /></font></div>'),
(82273, 'ثغ', '<span class=\"hlight\">ثغ.</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (اِ) بمعنی بت . (از برهان ). و بعض محققان گفته اند که چون در فارسی ثاء مثلثه نباید این لفظ فُغ بفاست . (غیاث اللغة).<br /></font></div>'),
(82274, 'ثغاب', '<span class=\"hlight\">ثغاب .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع اِ) ج ِ ثغب . آبهای خوش که در کوهها در آب گیرها مانده باشد.<br /></font></div>'),
(82275, 'ثغاریر', '<span class=\"hlight\">ثغاریر.</span> (ع اِ) درداب . شمامه . دستنبویه . کچری . و بلغت اهل شام شمام خوانند و به فارسی دستنبو و به اصفهانی دستنبویه . (اختیارات بدیعی ). و آن نوعی از خربزه ٔکوچک است در نهایت خوش خط و خالی و خوش بوئی بوئیدن آن دماغ را گرم کند و سُده بگشاید. (برهان قاطع).<br /></font></div>'),
(82276, 'ثغام', '<span class=\"hlight\">ثغام .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) درمنه ٔ سپید. (منتهی الارب ). جاورد. سپید خار. (مهذب الاسماء). در ترجمه ٔ کتاب صیدنه ٔ ابوریحان بیرونی آمده است : گفته اند نبات ثغام آن نباتی است که عرب او را حلی گوید و به فارسی او را سفیدگیاه گویند باریکتر است و ضعیف تر و به او مشابهت دارد و لیث گوید ثغامه نباتی است باساق و سر او بسر شیخ مشابهت دارد و شکوفه و میوه ٔ او سفید بود و سفید شدن موی را از پیری به او تشبیه کنند و حسّان بن ثابت در این معنی گفته است <span class=\"hlight\">:</span> <br />اما تری رأسی تغیّر لونه <br />شمطاً فأصبح کالثغام الممحل .<br />و ثعلب از ابن الأعرابی روایت کند که ثَغام درختی است که نبات او سفید بودمانند برف و در این معنی شعری ایراد کرده <span class=\"hlight\">:</span><br />اذا رایت صلفافی الهامة<br />و حدباً بعد اعتدال القامة<br />و صار رأس الشیخ کالثغامة<br />فأیس من الصحة و السلامة.<br /></font></div>'),
(82277, 'ثغب', '<span class=\"hlight\">ثغب .</span> <font color=\"DarkGreen\"><b>[ ث َ غ َ ]</font></b> (ع مص ) گداختن یخ . <BR><font color=\"Blue\">◄</font> هلاک شدن و یا به این معنی تَغَب به تاء دو نقطه است .<br /></font></div>'),
(82278, 'ثغب', '<span class=\"hlight\">ثغب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) نیزه زدن . <BR><font color=\"Blue\">◄</font> ذبح کردن .<br /></font></div>'),
(82279, 'ثغب', '<span class=\"hlight\">ثغب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) آب خوش که در کوهها در آبگیرها مانده باشد. ج، ثِغاب، اثغاب، ثُغبان، ثِغبان .<br /></font></div>'),
(82280, 'ثغب', '<span class=\"hlight\">ثغب .</span> <font color=\"DarkGreen\"><b>[ ث َ غ َ ]</font></b> (ع اِ)آبگیر در سایه ٔ کوه که آب خنک و خوش دارد و آنرا سردابه گویند. بقیه ٔ آبی که در وادی بماند. ج، ثغاب .<br /></font></div>'),
(82281, 'ثغبان', '<span class=\"hlight\">ثغبان .</span> <font color=\"DarkGreen\"><b>[ ث ُ <span class=\"hlight\" dir=\"rtl\">/</span> ث ِ ]</font></b> (ع اِ) ج ِ ثَغب .<br /></font></div>'),
(82282, 'ثغثاغ', '<span class=\"hlight\">ثغثاغ .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b>(ع ص، اِ) ثغثغ. آن که سخن از میان دندانها گوید.<br /></font></div>'),
(82283, 'ثغثغ', '<span class=\"hlight\">ثغثغ.</span> <font color=\"DarkGreen\"><b>[ ث َ ث َ ]</font></b>(ع ص، اِ) آنکه سخن از میان دندانها گوید. ثغثاغ .<br /></font></div>'),
(82284, 'ثغر', '<span class=\"hlight\">ثغر.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b>(ع مص ) دندان نمودن وقت خندیدن . <BR><font color=\"Blue\">◄</font> دندان شیر کسی را شکستن . <BR><font color=\"Blue\">◄</font> افتادن دندانها. <BR><font color=\"Blue\">◄</font> رخنه کردن . <BR><font color=\"Blue\">◄</font> رخنه بستن . <BR><font color=\"Blue\">◄</font> ثغر ثلمة؛ بستن رخنه را. (از اضداد است ).<br /></font></div>'),
(82285, 'ثغر', '<span class=\"hlight\">ثغر.</span> <font color=\"DarkGreen\"><b>[ ث َ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ غ َ ]</font></b> (ع اِ) درختی است که شکوفه ٔ سپید دارد. <BR><font color=\"Blue\">◄</font> گو. <BR><font color=\"Blue\">◄</font> رخنه . <BR><font color=\"Blue\">◄</font> دره ٔ فراخ . <BR><font color=\"Blue\">◄</font> دهن . <BR><font color=\"Blue\">◄</font> دندانها یا دندانهای پیشین یا دندان که هنوز در لثه باشد. <BR><font color=\"Blue\">◄</font> رسته ٔ دندان . <BR><font color=\"Blue\">◄</font> سرحد ملک کفار. مرز. دربند. دربند میان کفر و اسلام . (منتهی الارب ) (مهذب الاسماء) (السامی فی الاسامی ). <BR><font color=\"Blue\">◄</font> جای ترس از رخنه های شهر. <BR><font color=\"Blue\">◄</font> متفرق و پریشان . <BR><font color=\"Blue\">◄</font> ترسیدن گاه . <BR><font color=\"Blue\">◄</font> فرج . <BR><font color=\"Blue\">◄</font> سرحد ملک کفار <span class=\"hlight\">:</span> ملطیه بشام مهمترین ثغریست که از این سوی کوه لکام است . (حدود العالم ). و دهستان <font color=\"DarkGreen\"><b>[ بدیلمان ]</font></b> ثغر است بر روی غور. (حدود العالم ). فراو، ثغر است بر روی غور. (حدود العالم ). ملاذگرد، ثغری است بر روی رومیان . (حدود العالم ). و ثغراست <font color=\"DarkGreen\"><b>[ تفلیس ]</font></b> بر روی کافران . (حدود العالم ). شلات، ثغریست <font color=\"DarkGreen\"><b>[ به ماوراءالنهر ]</font></b> بر روی ترک نهاده . (حدود العالم ). خوارزم ثغری بزرگ است . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٨٣</span>). دانست که در آن ثغر بزرگ خللی خواهد افتاد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٨٤</span>). او را <font color=\"DarkGreen\"><b>[ سارغ ]</font></b> گفت توبه نندنه بازرو که آن ثغر را نتوان گذاشت خالی . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٤٤</span>). که بدیشان خللها را دریابد و ثغور را استوار کند. (تاریخ بیهقی ). زودتر بباید شتافت که از این خداوند ما <font color=\"DarkGreen\"><b>[محمدبن عبداﷲبن طاهر ]</font></b> هیچ کاری نیاید جز لهو تا ثغر خراسان که بزرگتر ثغریست بباد نشود. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٤٨</span>). این چیز را عوض است هر چند بر دل خداوند رنجگونه ای باشد اما التونتاش و آن ثغر بزرگ را عوض نیست . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٢٩</span>). چون اندیشیدیم که خوارزم ثغری بزرگست ... و باشد که دیگران تأویلی دیگر گونه کنند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٧٢٣</span>). چون دانست که در آن ثغر <font color=\"DarkGreen\"><b>[ خوارزم ]</font></b> بزرگ خللی خواهد افتاد چنانکه معتمدان وی <font color=\"DarkGreen\"><b>[ التونتاش ]</font></b> نبشته بودند بشتافت . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٧٦٦</span>). ما بسیار نصیحت کردیم و گفتیم چاکری است <font color=\"DarkGreen\"><b>[ التونتاش ]</font></b>مطیع از وی خطا نرفته است ... و خوارزم ثغر ترکان است . (تاریخ بیهقی <span class=\"hlight\" dir=\"rtl\">٩٨٢</span>). جمهوری عام از لشکر غور به حراست آن ثغر موکل بودند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٩٤</span>).<br />غایب ار شد در کنار ثغرها<br />همچو حاضر او نگه دارد وفا.<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> مؤلف مراصد الاطلاع گوید: ثغر، هر موضعی را گویند که نزدیک بخاک دشمن باشد و این کلمه از ثغرة الحائط آمده است زیرا محتاج بمحافظ است که دشمن از آنجا نیاید و سرحدات بسیار است از جمله ثغور شام بین شام و روم که درآنجا جماعتی از مشایخ مسلمین بوده و آنجا را محافظت می کنند. مثل بلاد ساحل که مانع است کشتی های روم به بنادر برسد مشهورترین آنها عسقلان است و طرسوس و مصیصه از طرف حلب و عواصم - انتهی . صاحب قاموس الاعلام گوید: ثغر، حد و مرز. و در اصطلاح جغرافیون اسلام ثغر الشام جهت اثینة و ثغر الجزیره طرف مرعش و ملطیة. رجوع به ثغور الجزیره شود. و ثغر ماوراءالنهر جانب شمال شرقی ترکستان و ثغر الاندلس ضلع شمالی شبه جزیره اسپانیاست - انتهی .<br /></font></div>'),
(82286, 'ثغر', '<span class=\"hlight\">ثغر.</span> <font color=\"DarkGreen\"><b>[ ث ُ غ َ ]</font></b> (ع اِ) ج ِ ثُغرة.<br /></font></div>'),
(82287, 'ثغر', '<span class=\"hlight\">ثغر.</span> <font color=\"DarkGreen\"><b>[ ث َ]</font></b> (اِخ ) شهری است نزدیک کرمان بر ساحل دریای هند.<br /></font></div>'),
(82288, 'ثغر ادنی', '<span class=\"hlight\">ثغر ادنی .</span> <font color=\"DarkGreen\"><b>[ ث َ رِ اَ نا ]</font></b> (اِخ ) بزمان بنی امیه طلیطلة و جهات آنرا ثغر ادنی مینامیدند. (نفح الطیب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٧</span>).<br /></font></div>'),
(82289, 'ثغر اعلی', '<span class=\"hlight\">ثغر اعلی .</span> <font color=\"DarkGreen\"><b>[ ث َ رِ اَ لا ]</font></b> (اِخ ) مقابل ثغر ادنی . در زمان بنی امیه نامی بود که به سرقسطه و جهات آن میدادند. (نفح الطیب ). این شهر را عرب البیضاء نیز نام میداد. و در <span class=\"hlight\" dir=\"rtl\">٥١٢</span> هَ . ق . فرنگیان آن شهر را از مسلمانان بستدند.<br /></font></div>'),
(82290, 'ثغرب', '<span class=\"hlight\">ثغرب .</span> <font color=\"DarkGreen\"><b>[ ث ِ رِ ]</font></b> (ع اِ) دندانهای زرد.<br /></font></div>'),
(82291, 'ثغره', '<span class=\"hlight\">ثغره .</span> <font color=\"DarkGreen\"><b>[ ث ُ رَ ]</font></b> (اِخ ) ناحیه ای است از توابع مدینه . (مراصد الاطلاع ).<br /></font></div>'),
(82292, 'ثغرور', '<span class=\"hlight\">ثغرور.</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) جای ترس از رخنه های شهرها.<br /></font></div>'),
(82293, 'ثغری', '<span class=\"hlight\">ثغری .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص نسبی ) منسوب است به ثغر که مرز است یعنی آنجاها که نزدیک به کفّار می باشد. (سمعانی ).<br /></font></div>'),
(82294, 'ثغم', '<span class=\"hlight\">ثغم .</span> <font color=\"DarkGreen\"><b>[ ث َ غ ِ ]</font></b> (ع ص، اِ) سگ گزنده و شکاری . <BR><font color=\"Blue\">◄</font> سگ خوگر.<br /></font></div>'),
(82295, 'ثغور', '<span class=\"hlight\">ثغور.</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) ج ِ ثغر. پیشینیان (از دندان ). <BR><font color=\"Blue\">◄</font> سرحدها ودربندها میان کفر و اسلام <span class=\"hlight\">:</span> که بدیشان خللها را دریابد و ثغور را استوار کند. (تاریخ بیهقی ).<br />بوم چالندر است مرتع من <br />مار و رنگم در این نقاب و ثغور.<br /> <font color=\"Red\">مسعود سعد (دیوان ص <span class=\"hlight\" dir=\"rtl\">٢٦٨</span>).</font><br />و نان پاره ٔ او به دیگری از بندگان دولت دادن که به کفایت امور و سد ثغور و موافقت جمهور قیام نماید. (ترجمه ٔ تاریخ یمینی <span class=\"hlight\" dir=\"rtl\">٥٨</span>).<br /></font></div>'),
(82296, 'ثغور', '<span class=\"hlight\">ثغور.</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (اِخ ) نام آن قسمت از بلاد شام است که نزدیک بقلمرو روم بوده . (مفاتیح العلوم ). و آنرا ثغورالروم نیز گفته اند. (الجماهرص <span class=\"hlight\" dir=\"rtl\">٤٨</span>). <BR><font color=\"Blue\">◄</font> ثغورالجزیره . نام شهرهائی و شهرکهائی است ثغر بر روی رومیان و از شامند ولکن بجزیره باز خوانند و از آنهاست ؛ سمیساط. سنجه . منصور. قورس ؟ ملطیه . مرعش . جذب ؟ هارونی . بیاس . کبیس . کمرینا؟ مصیصه . عین زربه . اذنة. طرسوس . اولاس . (حدود العالم ).<br /></font></div>'),
(82297, 'ثغور', '<span class=\"hlight\">ثغور.</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (اِخ ) قلعه ای است به یمن حمیر را.<br /></font></div>'),
(82298, 'ثغید', '<span class=\"hlight\">ثغید.</span> <font color=\"DarkGreen\"><b>[ ث ُ غ َ ]</font></b> (اِخ ) بلفظ تصغیر. آبی است از بنی عقیل . (معجم البلدان ).<br /></font></div>'),
(82299, 'ثفا', '<span class=\"hlight\">ثفا.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) نوعی از گربه ٔ دشتی است .<br /></font></div>'),
(82300, 'ثفاء', '<span class=\"hlight\">ثفاء.</span> <font color=\"DarkGreen\"><b>[ ث ُف ْ فا ]</font></b> (ع اِ) به لغت عبرانی اسم خردل سفید و حرف بابلی است . رشاد. حب الرشاد. تخم سپندان . سپندان خرد. سپندان خوش . سپندان سپید. پاسپندان گنده . تخم تره تیزک است و استرخای جمیع اعضاء را نافع است . (برهان قاطع).<br /></font></div>'),
(82301, 'ثفار', '<span class=\"hlight\">ثفار.</span> <font color=\"DarkGreen\"><b>[ ث َف ْ فا ]</font></b> (ع ص، اِ) پاردم گر.<br /></font></div>'),
(82302, 'ثفاریق', '<span class=\"hlight\">ثفاریق .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) ج ِ ثُفروق .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(82303, 'ثفافید', '<span class=\"hlight\">ثفافید.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) ابرهای سفید تودرتو و بطانها.مثافید. <BR><font color=\"Blue\">◄</font> نوعی جامه . <BR><font color=\"Blue\">◄</font> چیزهای خفی که زیر چیزی گذارند یا لغتی است در فثافید.<br /></font></div>'),
(82304, 'ثفال', '<span class=\"hlight\">ثفال .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) سنگ زیرین آسیا. سنگ زیرین دستاس .<br /></font></div>'),
(82305, 'ثفال', '<span class=\"hlight\">ثفال .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) سنگ زیرین آسیا. <BR><font color=\"Blue\">◄</font> ابریق . <BR><font color=\"Blue\">◄</font> سفره ای که زیر دستاس باز افکنند. آسیاروب . ج، أثفلة.<br /></font></div>'),
(82306, 'ثفال', '<span class=\"hlight\">ثفال .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص، اِ) اشتر دیررو و کاهل . گران رو از شتران و جز آن . <BR><font color=\"Blue\">◄</font> ابریق . ج، ثُفل .<br /></font></div>'),
(82307, 'ثفج', '<span class=\"hlight\">ثفج .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) گول گردیدن .<br /></font></div>'),
(82308, 'ثفر', '<span class=\"hlight\">ثفر.</span> <font color=\"DarkGreen\"><b>[ ث َ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ف َ ]</font></b> (ع اِ) پاردم که بهندوستان دمچی گویند. (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> شرم دد و دام و مرغان شکاری یا راه نره از آنان . ج، أثفار.<br /></font></div>'),
(82309, 'ثفر', '<span class=\"hlight\">ثفر.</span> <font color=\"DarkGreen\"><b>[ ث َ <span class=\"hlight\" dir=\"rtl\">/</span> ث ُ ]</font></b> (ع اِ) شرم ددگان و مرغان شکاری یا راه نره ٔ آنان .<br /></font></div>'),
(82310, 'ثفروق', '<span class=\"hlight\">ثفروق .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) چوب خوشه ٔ خرما. <BR><font color=\"Blue\">◄</font> پشیزه ٔ سر خرما یا آنچه بدان قمع خرما ملصق باشد. چوب خوشه ٔ انگور و خرما که دنباله ٔ انگورو خرما بدان پیوسته است . <BR><font color=\"Blue\">◄</font> انگور که به چوب خوشه متصل باشد. <BR><font color=\"Blue\">◄</font> چوب خوشه ٔ بی انگور، ج، ثفاریق ؛ او را ثفروقی نیست، نیست او را چیزی .<br /></font></div>'),
(82311, 'ثفسیا', '<span class=\"hlight\">ثفسیا.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (معرب اِ) صمغ سداب است . و آنرا بصورت ثافیسا و ثافسیا نیز ضبط کرده اند. رجوع به ثافسیا شود.<br /></font></div>'),
(82312, 'ثفل', '<span class=\"hlight\">ثفل .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) (شاید معرب از تفاله ٔ فارسی ) تفاله . کنجاره . <BR><font color=\"Blue\">◄</font> لفاظة. <BR><font color=\"Blue\">◄</font> دردی . ته نشین آب و دواء و جز آن . ثافل . تیرگی شیر و روغن . درشت پس افتاده ٔ از چیزی فشرده . ثجیر. جرم <span class=\"hlight\">:</span> <br />گر هوا و نار را سفلی کند<br />تیرگی و دردی و ثفلی کند.<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> دانه . <BR><font color=\"Blue\">◄</font> سفره ٔ زیر دستاس . <BR><font color=\"Blue\">◄</font> ثفل روغن . کداده . تِلزَه . <BR><font color=\"Blue\">◄</font> سرگین . ثفل غذاء. آنچه دفع شود از معده <span class=\"hlight\">:</span> هرچند طعام خوشتر ثفل وی گنداتر.(کیمیای سعادت ).<br /></font></div>'),
(82313, 'ثفل', '<span class=\"hlight\">ثفل .</span> <font color=\"DarkGreen\"><b>[ ث َ ف ِ ]</font></b> (ع ص، اِ) کسی که دُرد خورد. ثفل خوار.<br /></font></div>'),
(82314, 'ثفل', '<span class=\"hlight\">ثفل .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) ثفل رَحی ؛ سفره گستردن زیر دست آس . <BR><font color=\"Blue\">◄</font> ثفل شی ٔ، پراکنده کردن آن به یک بار (از منتهی الارب ).<br /></font></div>'),
(82315, 'ثفل', '<span class=\"hlight\">ثفل .</span> <font color=\"DarkGreen\"><b>[ ث َ ف َ ]</font></b> (ع ص ) گران رو، از شتر و جز آن .<br /></font></div>'),
(82316, 'ثفن', '<span class=\"hlight\">ثفن .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) دفع کردن و راندن . <BR><font color=\"Blue\">◄</font> زدن کسی را با دست . <BR><font color=\"Blue\">◄</font> پس روی کسی کردن . آمدن کسی را از پس . <BR><font color=\"Blue\">◄</font> زدن ناقه کسی را به ثفنات .<br /></font></div>'),
(82317, 'ثفن', '<span class=\"hlight\">ثفن .</span> <font color=\"DarkGreen\"><b>[ ث ُ ف ُ ]</font></b> (ع اِ) ج ِ ثَفَنة، بمعنی کناره ٔ سفره و توشه دان .<br /></font></div>'),
(82318, 'ثفن', '<span class=\"hlight\">ثفن .</span><font color=\"DarkGreen\"><b>[ ث َ ف َ ]</font></b> (ع مص ) درشت شدن دست و جز آن . (زوزنی ) (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> پینه بستن دست از کار یا سودگی . <BR><font color=\"Blue\">◄</font> بیماریی ای است در ثفنه .<br /></font></div>'),
(82319, 'ثفنات', '<span class=\"hlight\">ثفنات .</span> <font color=\"DarkGreen\"><b>[ث َ ف ِ ]</font></b> (ع اِ) ج ِ ثفنة. <BR><font color=\"Blue\">◄</font> ذوالثفنات . لقب علی بن الحسین زین العابدین علیهماالسلام زیرا مساجدآن حضرت از طول سجده پینه بسته شده بود. و نیز لقب علی بن عبداﷲبن عباس و لقب عبداﷲبن وهب رئیس خوارج .<br /></font></div>'),
(82320, 'ثفنة', '<span class=\"hlight\">ثفنة.</span> <font color=\"DarkGreen\"><b>[ ث َ ف ِ ن َ ]</font></b> (ع اِ) پینه ٔ زانو. <BR><font color=\"Blue\">◄</font> آنچه بر زمین رسد از تن شتر وقت نشستن، چون زانو و سینه و دست . <BR><font color=\"Blue\">◄</font> زانو و مجتمع ران و ساق از مردم . <BR><font color=\"Blue\">◄</font> باطن زانوی اسب یعنی چفته ٔ آن . <BR><font color=\"Blue\">◄</font> عدد و جماعت از مردم . <BR><font color=\"Blue\">◄</font> ناقه که به ثفنه کسی را زند. ج، ثَفنات . <BR><font color=\"Blue\">◄</font> نعت است از ثفن : ناقة ثفنه . <BR><font color=\"Blue\">◄</font> کناره ٔ سفره و توشه دان، ج، ثُفُن .<br /></font></div>'),
(82321, 'ثفوات', '<span class=\"hlight\">ثفوات .</span> <font color=\"DarkGreen\"><b>[ ث ُ ف ُ ]</font></b> (ع اِ) ج ِ ثُفوَة.<br /></font></div>'),
(82322, 'ثفی', '<span class=\"hlight\">ثفی .</span> <font color=\"DarkGreen\"><b>[ ث َف ْی ْ ]</font></b> (ع مص ) پیروی کردن کسی را. <BR><font color=\"Blue\">◄</font> ثفی قدر؛ بر دیگ پایه نهادن دیگ را. <BR><font color=\"Blue\">◄</font> سه زن کردن مرد. <BR><font color=\"Blue\">◄</font> ثفی قوم ؛ دفع کردن و راندن آنان را. (ذیل اقرب الموارد).<br /></font></div>'),
(82323, 'ثقاب', '<span class=\"hlight\">ثقاب .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع اِ) آتش افروزینه . ج، ثقب .<br /></font></div>'),
(82324, 'ثقاب', '<span class=\"hlight\">ثقاب .</span> <font color=\"DarkGreen\"><b>[ ث َق ْ قا ]</font></b> (ع ص ) سنبا. سنبنده . <BR><font color=\"Blue\">◄</font> سقاب الأکتاف، هویه . سنبا. لقب شاپور ذوالأکتاف .<br /></font></div>'),
(82325, 'ثقابت', '<span class=\"hlight\">ثقابت .</span> <font color=\"DarkGreen\"><b>[ ث َ ب َ ]</font></b> (ع مص ) ثقوب . <BR><font color=\"Blue\">◄</font> افروخته شدن آتش . (تاج المصادر بیهقی ). و بسیار سرخ گردیدن . <BR><font color=\"Blue\">◄</font> روشن شدن ستاره . <BR><font color=\"Blue\">◄</font> دمیدن بوی . <BR><font color=\"Blue\">◄</font> ثقبت الناقه ؛ بسیارشیر گردید اشتر ماده . <BR><font color=\"Blue\">◄</font> ثقب رأیه ؛ رای او نافذ گردید.<br /></font></div>'),
(82326, 'ثقات', '<span class=\"hlight\">ثقات .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع ص، اِ) ج ِ ثقة. بمعنی معتمد و شخص طرف اطمینان <span class=\"hlight\">:</span> و دارا را خود ثقات وی کشتند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٩٠</span>). ثقاة امیر رضی اﷲ عنه گفتند روی ندارد فرستادن . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٠٤</span>). و پوشیده مثال داد تا حاجب نوبتی برنشست و بخانه ٔبوسهل رفت با مشرفان و ثقات خواجه . (تاریخ بیهقی ). یحیی نسختی فرستاد با رسولی از ثقاة خویش . (تاریخ بیهقی <span class=\"hlight\" dir=\"rtl\">٤٢٣</span>). از ثقات وی شنیدم چون ابراهیم قاینی . (تاریخ بیهقی <span class=\"hlight\" dir=\"rtl\">٦٠٤</span>). شاه ملک چون عدت و آلت بر آنجمله دید بترسید و ثقاة خویش را گفت ... (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٦٩٨</span>).<br />از مرگ تو بشعر خبر چون کنم که نیست <br />دشمن ترین خلق جهان جز ثقات تو.<br /> <font color=\"Red\">مسعود.</font><br />از این اندیشه مستشعر شد و بی آرام گشت و قرب هفتصد سوار از خواص و ثقات خویش بگزید و از میان غز بیرون آمد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١٨٧</span>). از ثقات حضرت او باز می گفتند که بیست هزار دینار بر مراعات مؤلفان و مصنفان آن کتاب انفاق افتاده بود. (ترجمه ٔ تاریخ یمینی ). سلطان جمعی ثقاث از معتمدان حضرت بحفظ آن قلعه بازداشت . (ترجمه ٔتاریخ یمینی ). از ثقات حضرت سلطان جمعی از جهت نقل آن در یتیمه برفتند. (ترجمه ٔ تاریخ یمینی ). <BR><font color=\"Blue\">◄</font> استواریها. رجوع به ثقه شود. علم الثقات و الضعفاء من رواة الحدیث . و هو من أجل نوع و افخمه من انواع علم الاسماء و الرجال فانه المرقات الی معرفة صحةالحدیث و سقمه و الی الاحتیاط فی امورالدین و تمییز مواقع الغلط و الخطاء فی بدء الأصل الاعظم الذی علیه مبنی الأسلام و اساس الشریعة و للحفاظ فیه تصانیف کثیرةمنها ما افرد فی الثقات ککتاب الثقات للأمام الحافظ ابی حاتم محمدبن حبان البستی المتوفی سنة <span class=\"hlight\" dir=\"rtl\">٣٥٤</span> هَ . ق .اربع و خمسین و ثلثمائه و کتاب الثقات ممن لم یقع فی الکتب الستة للشیخ زین الدین قاسم بن قطلوبغا الحنفی المتوفی سنة <span class=\"hlight\" dir=\"rtl\">٨٧٩</span> هَ . ق . تسع و سبعین و ثمانمائه و هو کبیر فی اربع مجلدات و کتاب الثقات الخلیل بن شاهین و کتاب الثقات للعجلی و منهاما افرد فی الضعفاء ککتاب الضعفاء للبخاری و کتاب الضعفاء للنسائی و الضعفاء لمحمدبن عمرو العقیلی المتوفی سنة <span class=\"hlight\" dir=\"rtl\">٣٢٢</span> هَ . ق . اثنین و عشرین و ثلثمائة و منها ما جمع بینهما کتاریخ البخاری و تاریخ ابن ابی خیثمه . قال ابن الصلاح و ما اغزر فوائده و کتاب الجرح و التعدیل لأبن ابی حاتم . (کشاف اصطلاحات الفنون ).<br /></font></div>'),
(82327, 'ثقاف', '<span class=\"hlight\">ثقاف .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع اِ) آنچه نیزه و تیر را بدان راست کنند. <BR><font color=\"Blue\">◄</font> قالب نیزه . ج، ثُقُف . <BR><font color=\"Blue\">◄</font> شکلی است از اشکال رمل . <BR><font color=\"Blue\">◄</font> ثفف ؛ یعنی مخاصمت و جدال . و فی الحدیث اذا ملک اثنا عشر من بنی عمروبن کعب کان الثقف و الثقاف الی ان تقوم الساعة؛ یعنی الخصام و الجدال .<br /></font></div>'),
(82328, 'ثقاف', '<span class=\"hlight\">ثقاف .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (اِخ ) ابن عمروبن شمیط اسدی . صحابی است و یا آن ثقف بالفتح است .<br /></font></div>'),
(82329, 'ثقاف', '<span class=\"hlight\">ثقاف .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص ) زنی ثقاف ؛ زنی دانا و استادکار.<br /></font></div>'),
(82330, 'ثقافت', '<span class=\"hlight\">ثقافت .</span> <font color=\"DarkGreen\"><b>[ ث َ ف َ ]</font></b> (ع مص ) ثقف . ثَقَف . زیرکی . زیرک و سبک روح و چست و چالاک گردیدن . زیرک و استاد شدن . <BR><font color=\"Blue\">◄</font> سخت استوار شدن .<br /></font></div>'),
(82331, 'ثقال', '<span class=\"hlight\">ثقال .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص ) زنی ثقال ؛ زنی گران سرین و فربه . <BR><font color=\"Blue\">◄</font> بعیری ثقال ؛ شتری آهسته رو.<br /></font></div>'),
(82332, 'ثقال', '<span class=\"hlight\">ثقال .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع ص ) ج ِ ثقیل . و ثقال و یقال : هو من ثقال الناس و من ثقلائهم .<br /></font></div>'),
(82333, 'ثقالت', '<span class=\"hlight\">ثقالت .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ]</font></b> (ع مص ) ثقل .گران شدن . سنگین گشتن . گرانی . سنگینی . مقابل خفت .<br /></font></div>'),
(82334, 'ثقب', '<span class=\"hlight\">ثقب .</span> <font color=\"DarkGreen\"><b>[ ث ُ ق َ <span class=\"hlight\" dir=\"rtl\">/</span> ث ُ ]</font></b> (ع اِ) ج ِ ثُقبة. <BR><font color=\"Blue\">◄</font> روزن خانه . سوراخ . ج، ثقوب و اَثقب <span class=\"hlight\">:</span> <br />چرخ چون گوز شکسته است از آن روز که ماه <br />چهره چون چهره ٔ بادام جبین پر ثقب است .<br /><font color=\"Red\">انوری .</font><br /></font></div>'),
(82335, 'ثقب', '<span class=\"hlight\">ثقب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) سوراخ کردن . <BR><font color=\"Blue\">◄</font> بلند پریدن . <BR><font color=\"Blue\">◄</font> ثقب کوکب ؛ روشن شدن ستاره . <BR><font color=\"Blue\">◄</font> ثقب رائحه ؛ دمیدن بوی . <BR><font color=\"Blue\">◄</font> ثقب ناقه ؛ بسیار شیر شدن ناقة. <BR><font color=\"Blue\">◄</font> ثقب رأی ؛ نافذ گردیدن رأی .<br /></font></div>'),
(82336, 'ثقب', '<span class=\"hlight\">ثقب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) ابن فروه ٔ ساعدی . صحابی انصاری است . بعضی نام او را ثقیب گفته اند بر وزن زُبیر. وی در غزوه ٔ احد شهادت یافت واو واقف به انساب انصار بود. رجوع به ثقف ... شود.<br /></font></div>'),
(82337, 'ثقب', '<span class=\"hlight\">ثقب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) دهی است به یمامه .<br /></font></div>'),
(82338, 'ثقب', '<span class=\"hlight\">ثقب .</span> <font color=\"DarkGreen\"><b>[ ث ُ ق ُ ]</font></b> (ع اِ) ج ِ ثُقبة و ثقوب و ثقاب .<br /></font></div>'),
(82339, 'ثقبان', '<span class=\"hlight\">ثقبان .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (اِخ ) دهی است از توابع یمن به جند. (مراصد الاطلاع ).<br /></font></div>'),
(82340, 'ثقبة', '<span class=\"hlight\">ثقبة.</span> <font color=\"DarkGreen\"><b>[ ث ُ ب َ ]</font></b> (ع اِ) سوراخ کوچک . سولاخ . (زمخشری ) <span class=\"hlight\">:</span> <br />دو دیده همچون ثقبه گشاده ام شب و روز<br />ولیک بی خبر از آفتاب و از مهتاب .<br /> <font color=\"Red\">مسعود.</font><br />ج، ثُقَب . و ثُقب . <BR><font color=\"Blue\">◄</font> ثقبه ٔ اعور . (طب ). <BR><font color=\"Blue\">◄</font> ثقبه ٔ اعور زبان . (طب ). <BR><font color=\"Blue\">◄</font> ثقبه ٔ بیضی . (طب ). <BR><font color=\"Blue\">◄</font> ثقبه ٔ جنینیه دهلیز قلب . (طب )، ثُقبه ای که کشف آن به بتال منسوب است و دو دهلیز قلب جنین را بیکدیگر مربوط میکند و هنگام تولد مسدود میشود. <BR><font color=\"Blue\">◄</font> ثقبه ٔ منخرقه (طب ). <BR><font color=\"Blue\">◄</font> ثقبه ٔ سهمی و حُلمه . <BR><font color=\"Blue\">◄</font> ثقبه ٔ عصب باصره . <BR><font color=\"Blue\">◄</font> ثقبه ٔ عنبیه ؛ سوراخی در وسط طبقه ٔ عنبیه بسیاهی چشم، مانند سوراخی که در عنب یعنی انگوراست گاه جدا کردن آن از چوب خوشه، و آن سوراخ را که ثقبه ٔ عنبیّه عبارت از آن است به فارسی مردمک و به هندی تل گویند بکسر تای فوقانی و آن منفذ نور بصر است . (غیاث اللغة). <BR><font color=\"Blue\">◄</font> ثقبه ٔ عظم قمحدوه (طب ). <BR><font color=\"Blue\">◄</font> ثقبه ٔ مدوره (طب ). <BR><font color=\"Blue\">◄</font> ثقبه ٔ مسدوده یا ثقبه ٔ تحت زهار (طب )، ثقبه ٔ واقع در قسمت زیرین عظم خاصره که زهار آن را در قسمت قدامی محدود میکند. <BR><font color=\"Blue\">◄</font> ثقبه ٔ مقدم زائده ٔ خارجی قمحدوه (طب ). <BR><font color=\"Blue\">◄</font> ثقبه ٔ مؤخر زایده ٔ خارجی قمحدوه (طب ).<br /></font></div>'),
(82341, 'ثقبة', '<span class=\"hlight\">ثقبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ق َ ب َ ]</font></b> (اِخ ) کوهی است بین حراء و مکه و در زیر آن مزارع است . (مراصد الاطلاع ).<br /></font></div>'),
(82342, 'ثقبی', '<span class=\"hlight\">ثقبی .</span> <font color=\"DarkGreen\"><b>[ ث َق ْ ق ِ ]</font></b> (ع ص نسبی ) منسوب است به ثقّب سنبنده ٔ دانه ٔ لؤلؤ. (سمعانی ). کسپرج سُنبا.<br /></font></div>'),
(82343, 'ثقت', '<span class=\"hlight\">ثقت .</span> <font color=\"DarkGreen\"><b>[ ث ِ ق َ ]</font></b> (ع اِمص ) اطمینان . <BR><font color=\"Blue\">◄</font> خاطر جمعی <span class=\"hlight\">:</span> هر سخن که از سر نصیحت ... رود... به راداء آن دلیری نتوان کرد مگر به عقل ... شنونده ثقتی تمام باشد. (کلیله و دمنه ). و اگر خردمندی به قلعه ای پناه گیرد و ثقت افزاید... البته به عیبی منسوب نگردد. (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> استواری . (غیاث اللغة). ج، ثقات . و رجوع به ثقه شود.<br /></font></div>'),
(82344, 'ثقت', '<span class=\"hlight\">ثقت .</span> <font color=\"DarkGreen\"><b>[ ث ِ ق َ ]</font></b> (ع مص ) استوار داشتن . <BR><font color=\"Blue\">◄</font> اعتماد کردن . <BR><font color=\"Blue\">◄</font> درست شدن .<br /></font></div>'),
(82345, 'ثقف', '<span class=\"hlight\">ثقف .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) محلی است در شعر. (مراصد الاطلاع ).<br /></font></div>'),
(82346, 'ثقف', '<span class=\"hlight\">ثقف .</span> <font color=\"DarkGreen\"><b>[ ث ُ ق ُ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ق َ ]</font></b> (ع مص ) زیرک و ماهر شدن . <BR><font color=\"Blue\">◄</font> چست و چالاک شدن .<br /></font></div>'),
(82347, 'ثقف', '<span class=\"hlight\">ثقف .</span> <font color=\"DarkGreen\"><b>[ ث ُ ق ُ ]</font></b> (ع اِ) ج ِ ثقاف .<br /></font></div>'),
(82348, 'ثقف', '<span class=\"hlight\">ثقف .</span> <font color=\"DarkGreen\"><b>[ ث ِ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ق ِ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ق ُ ]</font></b> (ع ص، اِ) مرد استاد. <BR><font color=\"Blue\">◄</font> زیرک . چست و سبک . ندس .<br /></font></div>'),
(82349, 'ثقف', '<span class=\"hlight\">ثقف .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) ابن فروه ٔ ساعدی . صحابی است . و او در خیبر یا در احد بشهادت رسید و بعضی نام او را ثقب گفته اند.<br /></font></div>'),
(82350, 'ثقف', '<span class=\"hlight\">ثقف .</span> <font color=\"DarkGreen\"><b>[ ث َ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ق َ ]</font></b> (ع مص ) دانستن . دریافتن . یافتن . <BR><font color=\"Blue\">◄</font> گرفتن بزودی . <BR><font color=\"Blue\">◄</font> زیرک و سبک و چالاک گردیدن . <BR><font color=\"Blue\">◄</font> ثفافت . <BR><font color=\"Blue\">◄</font> غالب آمدن در دانائی . <BR><font color=\"Blue\">◄</font> ظفر یافتن و رسیدن . <BR><font color=\"Blue\">◄</font> راست کردن نیزه .<br /></font></div>'),
(82351, 'ثقف', '<span class=\"hlight\">ثقف .</span> <font color=\"DarkGreen\"><b>[ ث َ <span class=\"hlight\" dir=\"rtl\">/</span> ث َق َ ]</font></b> (ع ص، اِ) دانا و استاد در حرب و طعن و ضرب .<br /></font></div>'),
(82352, 'ثقف', '<span class=\"hlight\">ثقف .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) ابن عمرو عدوائی . صحابی است از مردم قریش . او با دو برادر خویش درک غزوه ٔ بدر کردند و در غزای خیبر و بروایتی در جنگ احد بدرجه ٔ شهادت رسید.<br /></font></div>'),
(82353, 'ثقف', '<span class=\"hlight\">ثقف .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) ابن عمروبن شمیظ اسدی . رجوع به ثفاف ... شود.<br /></font></div>'),
(82354, 'ثقفی', '<span class=\"hlight\">ثقفی .</span><font color=\"DarkGreen\"><b>[ ث َ ق َ ]</font></b> (اِخ ) قاسم بن فضل مکنی به ابی عبداﷲ حافظاصفهانی متوفی <span class=\"hlight\" dir=\"rtl\">٤٨٩</span> هَ . ق . او راست : کتاب اربعین .<br /></font></div>'),
(82355, 'ثقفی', '<span class=\"hlight\">ثقفی .</span> <font color=\"DarkGreen\"><b>[ ث َ ق َ ]</font></b> (اِخ ) جُبیر. پدر زیاد تابعی است .<br /></font></div>'),
(82356, 'ثقفی', '<span class=\"hlight\">ثقفی .</span> <font color=\"DarkGreen\"><b>[ ث َ ق َ ]</font></b> (اِخ ) ابوعبدالملک مُتطب او ادیب و مساح و عالم به کتاب اقلیدس و طبیب ناصر و مستنصر و اعرج بود. او راست <span class=\"hlight\">:</span> نوادر، در طب . و مستنصر یا ناصر او را والی خزانةالسلاح کرد و در پایان عمر به نزول آب در چشم مبتلی شد. و به بیماری استسقاءدرگذشت . (عیون الانباء ).<br /></font></div>'),
(82357, 'ثقفی', '<span class=\"hlight\">ثقفی .</span> <font color=\"DarkGreen\"><b>[ ث َ ق َ ی ی ]</font></b> (اِخ ) ابراهیم بن محمد اصفهانی مکنی به ابو اسحاق یکی از ثقات فقهاء شیعه و کتاب اخبار الحسن بن علی از اوست . (ابن الندیم ). رجوع به ابراهیم بن محمد ثففی شود.<br /></font></div>'),
(82358, 'ثقفی', '<span class=\"hlight\">ثقفی .</span> <font color=\"DarkGreen\"><b>[ ث َ ق َ فی ی ]</font></b> (ع ص نسبی ) منسوب به ثقیف قسی بن منبه بن بکربن هوازن پدر قبیله ٔ بنوثفیف .<br /></font></div>'),
(82359, 'ثقل', '<span class=\"hlight\">ثقل .</span> <font color=\"DarkGreen\"><b>[ ث َ ق ِ ]</font></b> (ع مص ) سست و کاهل شدن . <BR><font color=\"Blue\">◄</font> گران شدن به وزن .<br /></font></div>'),
(82360, 'ثقل', '<span class=\"hlight\">ثقل .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع ص، اِ) ج ِ ثقیل .<br /></font></div>'),
(82361, 'ثقل', '<span class=\"hlight\">ثقل .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِمص ) سنگینی . گرانی . <BR><font color=\"Blue\">◄</font> (مص ) گران شدن آزمودن وزن بدست . <BR><font color=\"Blue\">◄</font> چربیدن و افزون آمدن چیزی بر چیزی در وزن . <BR><font color=\"Blue\">◄</font> گوسفند را دروا کردن برای سنجیدن گوشت . <BR><font color=\"Blue\">◄</font> سخت بیمار شدن . <BR><font color=\"Blue\">◄</font> سنگین شدن بیماری کسی . <BR><font color=\"Blue\">◄</font> ثقلت المراءة؛ گران شد زن و ظاهر شد آبستنی وی . <BR><font color=\"Blue\">◄</font> ثقل عرفج ؛ تازه و ترگردیدن شاخ آن . ثقل ثمام ؛ تر و تازه گردیدن ثمام .<br /></font></div>'),
(82362, 'ثقل', '<span class=\"hlight\">ثقل .</span> <font color=\"DarkGreen\"><b>[ ث ِ ق َ ]</font></b> (ع اِمص ) گرانی . ضد خفت، سبکی . <BR><font color=\"Blue\">◄</font> گران شدن . (غیاث اللغة).<br /></font></div>'),
(82363, 'ثقل', '<span class=\"hlight\">ثقل .</span> <font color=\"DarkGreen\"><b>[ ث َ ق َ ]</font></b> (ع اِ) متاع و بار مسافر و حشم و خدمتکاران او. بار. بنه . <BR><font color=\"Blue\">◄</font> هرچیز نفیس نگاه داشتنی . و منه الحدیث ؛ انی تارک فیکم الثقلین، کتاب اﷲ و عترتی .<br /></font></div>'),
(82364, 'ثقل', '<span class=\"hlight\">ثقل .</span> <font color=\"DarkGreen\"><b>[ث ِ ]</font></b> (اِخ ) محلی است در شعر زهیر. (مراصد الاطلاع ).<br /></font></div>'),
(82365, 'ثقل', '<span class=\"hlight\">ثقل .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع اِمص، اِ) ثقالت . گرانی . سنگینی . (مقابل خفّت ) <span class=\"hlight\">:</span> خلقی را به ثقل وَطأت و فضل قوت در زیر پای پست میکرد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٨٧</span>). <BR><font color=\"Blue\">◄</font> رخت و باروبنه ٔ مسافر. بار سنگین . چیز گران <span class=\"hlight\">:</span> یعقوب ثقل و بنه ٔ او بر گرفت و بسیستان باز آمد. (تاریخ سیستان ). پنج روز ببود با شکار و نشاط وشراب تا بنه ها و ثقل و پیلان از بژغورک بگذشتند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٨٦</span>). بر آن جانب لشکرگاه کرده و خیمه زده و ثقل و مردمی که نابکار است با بنه ها رها کرده . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٦٥</span>) و آنچه ثقل نشابور بود از جامه و فرش شادیاخ و سلاح و چیزهای دیگر که ممکن نشد بقلعه ٔ میکالی فرستادن سوری مثال داد تا همه در خزانه نهادند. (تاریخ بیهقی <span class=\"hlight\" dir=\"rtl\">٥٥٢</span>). صواب نیست در پیش مصاف این پادشاه ایستادن . رسم خویش نگاه داریم و ما را به بنه و ثقل دل مشغول نه . (تاریخ بیهقی <span class=\"hlight\" dir=\"rtl\">٥٩٠</span>). همه راه پرزره وجوشن و سپر و ثقل بر میگذشتیم که بیفکنده بودند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٦٤٠</span>). و رحل و ثقلی که از سیف الدوله بازماند و چند مربط فیل و بعضی از حشم هند در دست ابوعلی بماند. (ترجمه ٔ تاریخ یمینی نسخه ٔ خطی ص <span class=\"hlight\" dir=\"rtl\">١١٧</span>). و به ابوعلی بن حموله کس فرستاد و از او قلعه خواست که بدان مستظهر شود و رحل وثقل و عیال و اموال خویش آنجایگاه فرستد. (ترجمه ٔ تاریخ یمینی نسخه خطی ص <span class=\"hlight\" dir=\"rtl\">٢٢٦</span>). بسبب رحل و ثقل بسیار از خزاین و اسلحه که از نواحی هراة حاصل کرده بود... فروماند. (ترجمه ٔ تاریخ یمینی نسخه ٔ خطی ص <span class=\"hlight\" dir=\"rtl\">٢٦٤</span>). رحل و ثقل خویش فراهم پیچید و ببخارا رفت . (ترجمه ٔ تاریخ یمینی نسخه ٔ خطی مؤلف ص <span class=\"hlight\" dir=\"rtl\">١٩٠</span>). <BR><font color=\"Blue\">◄</font> کالای خانه . <BR><font color=\"Blue\">◄</font> بم، مقابل زیر(در موسیقی ). (خلاصةالافکار شهاب صیرفی ). <BR><font color=\"Blue\">◄</font> سختی . <BR><font color=\"Blue\">◄</font> سده . امتلاء. تخمه . <BR><font color=\"Blue\">◄</font> گناه . <BR><font color=\"Blue\">◄</font> گنج زمین . دفینه ٔ زمین . <BR><font color=\"Blue\">◄</font> مرده های مدفون در زمین . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> وزن . ج، أثقال .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثقل اجسام </span> ؛ وزن اجسام .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثقل سامعه </span> ؛ گرانگوشی . گرانی گوش .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثقل سرد</span> ؛ شکم دردی که از بسیار خوردن میوه خصوصاً میوه های نارس پدید آید. هیضه . و باء پائیزی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثقل کردن </span> ؛ در تداول عوام، سخت شدن فضول در معده و اجابت نکردن آن با درد شکم .سنگین شدن معده و درد کردن آن از بسیارخواری .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">قوه ٔ ثقل </span> ؛ قوه ٔ جاذبه ٔ زمین .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مرکز ثقل </span> ؛ نقطه ای است که کلیّه ٔ قوای جاذبه وارده از زمین در آنجاتمرکز می یابد. خاصیت مرکز ثقل یک جسم این است که هر گاه نقطه ٔ مزبور را بمحلی تکیه دهیم اثرقوای جاذبه ٔ وارده بر کلیه ٔ ذرات جسم خنثی شده بالنتیجه جسم ساکن میگردد.<br /><BR><font color=\"Blue\">◄</font> مؤلف کشاف اصطلاحات الفنون آرد: ثقل ضدّالخفة و یسمیهما ای الثقل و الخفة المتکلمون اعتماداً و یسمتهما الحکماء میلاً طبعیاًعلی ما فی شرح الطوالع. قال شارح حکمةالعین و فی الحواشی القطبیه الثقل قوّة طبیعیة یتحّرک بها الجسم الی حیت ینطبق به مرکز ثقله علی مرکز العالم لولم یعقه عائق . و قد یقال علی الطبیعة المقتضیة له و علی المدافعة الحاصلة بالاشتراک . و کذا الخقة - انتهی . فالخفّة قوة طبیعیّة یتحّرک بهاالجسم الی المحیط لولم یعقه عائق . و قد یقال علی الطبیعة المقتضیة له و علی المدافعة الحاصلة فَمن فسرّ المیل بنفس المدافعة التی هی من الکیفیّات الملموسة فسرّهما بنفس المدافعة. و من لم یفسّره بها بل بمبداء المدافعه فسّرهما بمبداءالمدافعة. قال القأئلون بان ّالمیل هوالمبداء المدافعة الحرکة لها مراتب متفاوته بالشدة و الضعف و نسبةالمحرک الذی هوالطبیعة الی تلک المراتب علی السویة فیمتنع ان یصدر عن ذلک المحرک شیئی من تلک المراتب الا بتوسط امر ذی مراتب متفاوتة فی الشدة والضعف لیتعین بکل واحدة من هذه المراتب صدور مرتبة معینة من الحرکة. و ذلک الامر هوالمیل . و اجاب عنه الامام الرازی بان الطبیعة قوة ساریة فی الجسم منقسمة بانقسامه . فکلماکان الجسم اکبر کانت طبیعته اقوی و کلما کان اصغر کانت طبیعته اضعف فلم یلزم ان یکون للمدافعة مبداء مغایر للطبیعة حتی یسمّی بالمیل والاعتماد و اما تسمیةالطبیعة بالمیل و الاعتماد فبعید جدا فلا وجود للمیل . هکذا فی شرح التجرید و شرح المواقف . و یفهم من هذا بعدتعمق النظران القائلین بان المیل مبداء المدافعة بعضهم علی ان المیل هوالطبیعة علی ما یدل علیه کلام الامام و الحواشی القطبیة و بعضهم علی انه امر آخر بواسطة تقتضی بها الطبیعة الحرکة المتفاوتة و المدافعة. ففهم من هذا ان ماذکر فی الحواشی القطبیة من المعانی الثلاثة للثقل و الخفة مبنی علی اختلاف المذاهب فلوترک قوله بالاشتراک لکان اولی . اذلیس لهما بالحقیقة الامعنی واحد لکنه مختلف فیه . (التقسیم : کل من الثقل و الخفةاما مطلقان او اضافیان فالثقل المطلق کیفیة تقتضی حرکة الجسم الی حیث ینطبق مرکز ثقله علی مرکز العالم کالارض . والثقل الاضافی کیفیة تقتضی حرکة الجسم الی جانب المرکز فی اکثرالمسافةالممتدة بین المرکز و المحیط. لکنه لا یبلغ المرکز کالماء. و الخفة المطلقة کیفیة تقتضی حرکة الجسم الی حیث ینطبق سطحه علی سطح مقعرفلک القمر کالنار. والخفة الاضافیة کیفیة تقتضی حرکته الی جانب المحیط فی اکثرالمسافة الممتدة بین المرکز و المحیط لکنه لایبلغ المحیط کالهواء. قیل هذا یقتضی ان الارض لوفرض اخراجها عن مکانها لایصل الماء الی مرکز العالم و فیه بعد. وفی حواشی شرح التذکرة ان الماء ایضا طالب للمرکز علی الاطلاق بحیث لو لم تکن الارض لسال الماء الی مرکز العالم الا ان الارض قد سبقت الماء بالوصول الی المرکز لان ّ ذلک الطلب فیها اقوی فغلبت علی الماء فصارت مانعة لوصول الماء الی المرکز و کذا الکلام فی الهواء و النار من ان ّ احدهما طالب له علی الاطلاق و الاخر طالب له لا علی الاطلاق او ان ّ کلیهما طالب له علی الاطلاق الا ان ذلک الطلب فی احدهما اقوی . کذا ذکر عبدالعلی البیرجندی فی حاشیة الچغمینی و یؤید هذا زیادة قید لو لم یعقه عائق فی تعریف الثقل المنقول من الحواشی القطبیة. ثم انه لایخفی ان هذا التقسیم انما هو للثقل و الخفة بالتفسیر الاول و الثانی من التفاسیر الثلاثة المذکورة و یمکن ایضاً اعتباره فیهما بالقیاس الی التفسیر الاخیر کما لایخفی .<br /></font></div>'),
(82366, 'ثقلان', '<span class=\"hlight\">ثقلان .</span> <font color=\"DarkGreen\"><b>[ ث َ ق َ ]</font></b> (ع اِ) تثنیه ٔ ثَقَل . ثقلین . <BR><font color=\"Blue\">◄</font> آدمی و پری . آدمیان و پریان . انس و جن <span class=\"hlight\">:</span> <br />شمس الوزراء احمد عبدالصمد آن کو<br />شمس الوزراء نیست که شمس ثقلان است .<br /> <font color=\"Red\">منوچهری .</font><br /> <BR><font color=\"Blue\">◄</font> سید ثقلان ؛ رسول اکرم صلوات اﷲ علیه <span class=\"hlight\">:</span> <br />زانکه تو هم نام سید ثقلانی <br />مادح هم نام سیدالثقلانم .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(82367, 'ثقلة', '<span class=\"hlight\">ثقلة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ق َ ل َ ]</font></b> (ع اِمص ) گرانی . <BR><font color=\"Blue\">◄</font> نعاس . پینکی . <BR><font color=\"Blue\">◄</font> گرانی طعام . (منتهی الارب ).<br /></font></div>'),
(82368, 'ثقلة', '<span class=\"hlight\">ثقلة.</span> <font color=\"DarkGreen\"><b>[ ث َ ق َ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ث ِ ق َ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ق ِ ل َ<span class=\"hlight\" dir=\"rtl\">/</span> ث ِ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ل َ ]</font></b> (ع اِ) رخت و متاع . ج، أثقال .<br /></font></div>'),
(82369, 'ثقلت', '<span class=\"hlight\">ثقلت .</span> <font color=\"DarkGreen\"><b>[ ث ِ ل َ ]</font></b> (ع اِمص ) گرانی . سنگینی .<br /></font></div>'),
(82370, 'ثقلین', '<span class=\"hlight\">ثقلین .</span> <font color=\"DarkGreen\"><b>[ ث َ ق َ ل َ ]</font></b> (ع اِ) تثنیه ٔ ثَقل . ثقلان . <BR><font color=\"Blue\">◄</font> مردمان و پریان . جن و انس . اگر ثقلین جمع شوند بی اراده ٔ خدای تعالی موئی را نتوانند از سر کم کرد. <BR><font color=\"Blue\">◄</font> دو گروه . (غیاث اللغة). <BR><font color=\"Blue\">◄</font> دوچیز نفیس خطیر <span class=\"hlight\">:</span> انی تارک فیکم الثقلین . (حدیث ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امام ثقلین </span> ؛ امیرالمؤمنین علی علیه السلام و دیگر ائمه ٔ اثنی عشر را نیز گویند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">سیدالثقلین </span> ؛ رسول اکرم صلوات اﷲ علیه .<br /></font></div>'),
(82371, 'ثقوات', '<span class=\"hlight\">ثقوات .</span> <font color=\"DarkGreen\"><b>[ ث َ ق َ ]</font></b> (ع اِ) ج ِ ثقوة.<br /></font></div>'),
(82372, 'ثقوب', '<span class=\"hlight\">ثقوب .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) ج ِ ثَقب .<br /></font></div>'),
(82373, 'ثقوب', '<span class=\"hlight\">ثقوب .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع مص ) ثقابت . ثَقب . <BR><font color=\"Blue\">◄</font> روشن شدن ستاره . <BR><font color=\"Blue\">◄</font> افروخته شدن . <BR><font color=\"Blue\">◄</font> دمیدن بوی . <BR><font color=\"Blue\">◄</font> نافذ رای گردیدن . <BR><font color=\"Blue\">◄</font> بسیارشیر شدن شتر. (تاج المصادر بیهقی ).<br /></font></div>'),
(82374, 'ثقوب', '<span class=\"hlight\">ثقوب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) آتش افروزینه . آتش گیره . هیمه ٔ خرد که به آن آتش برافروزند. ج، ثُقُب .<br /></font></div>'),
(82375, 'ثقوبة', '<span class=\"hlight\">ثقوبة.</span> <font color=\"DarkGreen\"><b>[ ث ُ ب َ ]</font></b> (ع مص ) افروخته شدن آتش . روشن شدن .<br /></font></div>'),
(82376, 'ثقیب', '<span class=\"hlight\">ثقیب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص، اِ) بسیار سرخ . <BR><font color=\"Blue\">◄</font> ناقه ٔ بسیارشیر.<br /></font></div>'),
(82377, 'ثقیب', '<span class=\"hlight\">ثقیب .</span> <font color=\"DarkGreen\"><b>[ ث ُ ق َ ]</font></b> (اِخ ) ابن فروه . رجوع به ثقب ابن فروة شود.<br /></font></div>'),
(82378, 'ثقیب', '<span class=\"hlight\">ثقیب .</span> <font color=\"DarkGreen\"><b>[ ث ُ ق َ ]</font></b> (اِخ ) راهی است به برسوی ثعلبیة بطرف شام . (از مراصد الاطلاع <span class=\"hlight\" dir=\"rtl\">١٠٤</span>).<br /></font></div>'),
(82379, 'ثقیف', '<span class=\"hlight\">ثقیف .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) فقید ثقیف، گم شده ٔ ثقیف . در اول اسلام به طائف دو برادر بودند یکی از آن دو زنی از بنی کنة کرد و سپس به سفری شد و زن خویش به برادر سپرد قضا را روزی چشم اوبه زن برادر افتاد و عاشق وی گشت و عشق خویش پنهان میداشت تا از اثر عشق بیمار گردید برادر او از سفر باز آمد و پزشگان گرد کرد و جملگی در علاج او عاجز آمدند و او وی را نزد حارث بن کلده برد و حارث گفت دو چشم شرمگن بینم و بیماری را نشناسم اینک وی را بیازمایم و او را شراب داد و چون شراب در وی کار کرد گفت :<br />الا رفقا الا رفقا<br /> <font color=\"Red\">قلیلا ما أکوننه </font><br />الما بی ابی الابیا<br /> <font color=\"Red\">ت بالخیف أزرهنه </font><br />غزالا ما رایت الیو<br /> <font color=\"Red\">م فی دور بنی کنة</font><br />اسیل الخدّ مربوب <br /> <font color=\"Red\">و فی منطقه غنه .</font><br />حارث دانست که او عاشق است کرت دیگر بدو شراب خورانید و او گفت :<br />ایهاالجیرة اسلموا<br /> <font color=\"Red\">و قفوا کی تکلموا</font><br />و تقضوا لبانة<br /> <font color=\"Red\">و تحبوا و تنعموا</font><br />خرجت مزنة من الَ<br /><font color=\"Red\">بحر ریا تحمحم </font><br />هی ما کنتی و تز<br /> <font color=\"Red\">عم انی لها حم .</font><br />و برادرش بدانست که او را چه افتاده است گفت ای برادر زن من مطلقه است او را بزنی گیر گفت روزی که من او را بزنی گیرم مطلقه باشد سپس بهبود یافت و از طائف بیرون شد و سر به بیابان نهاد و بیش کس او را ندید و برادراو چندی بماند و سپس از اندوه دوری برادر بمرد و ببرادر گمگشته مثل زدند و او را فقید ثقیف گفتند <span class=\"hlight\">:</span> پسر خرکاش ... از میان بگریخت و در جهان آواره شد و ثانی فقید ثقیف و ثالث قارظین گشت و کس از وی نشان نیافت . (تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٧٨</span>).<br /></font></div>'),
(82380, 'ثقیف', '<span class=\"hlight\">ثقیف .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) نام قبیله ای است که بزعم خود از عرب باشند لکن در حقیقت از بقایای قوم ثمودند که اقدم از عرب است . (سمعانی ). <BR><font color=\"Blue\">◄</font> پدر قبیله ای از هوازِن نام اوقسی ّ بن مُنَبَّه بن بکربن هوازن است یکی از قبایل عرب که در جوار شهر طائف میزیستند. این قوم دیری باج گذار قبیله ٔ بنی عامر بودند پس قلعه ها و حصارها کردند ودر برابر بنوعامر مقاومت کرده خراج از خود بیفکندندو سپس بدوشعبه بنام احلاف و بنی ملک منشعب گشتند و میان این دو شعبه محاربات بسیار بود. پس از وفات ابوطالب، رسول صلوات اﷲ علیه از آنان یاری طلبید و ایشان جواب رد گفتند. در غزوه ٔ هوازن هفتاد تن از قوم ثقیف کشته شد و بقیه در قلاع خویش تحصن گزیدند و بیست روزمحاصره ٔ آنان بکشید و در آخر مسلمانان راه بر آنان ببستند و بنوثقیف ناچار از در اطاعت درآمدند و بقبول مسلمانی تن دردادند و بت خویش را که لات نام داشت بشکستند. پس از رحلت رسول صلوات اﷲ علیه آنگاه که تمام مردم جزیره رده آوردند و قوم ثقیف در مسلمانی پابرجای بماندند. از این قبیله در دوره ٔ اسلام عده ٔ بسیاری علما و شعرا و دیگر مشاهیر برخاست . (قاموس الاعلام ).<br /></font></div>'),
(82381, 'ثقیف', '<span class=\"hlight\">ثقیف .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص، اِ) مرد استاد. <BR><font color=\"Blue\">◄</font> مرد زیرک چالاک .<br /></font></div>'),
(82382, 'ثقیف', '<span class=\"hlight\">ثقیف .</span> <font color=\"DarkGreen\"><b>[ ث ِ ق ق ]</font></b> (ع ص ) سخت ترش و تیز. دژن : خل ّ ثقیف ؛ سرکه ٔ سخت ترش . سرکه ٔ چون الماس .<br /></font></div>'),
(82383, 'ثقیل', '<span class=\"hlight\">ثقیل .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص ) گران . وزین . سنگین .مقابل خفیف، سبک . گران سنگ . گران به وزن . <BR><font color=\"Blue\">◄</font> گران جان . آنکه صحبت وی را ناخوش دارند. (منتهی الارب ). خَلنفَع. ناکس . شبشت . شبست . دهلب <span class=\"hlight\">:</span> <br />چون بخواند نامه ٔ خود آن ثقیل <br />داند او که سوی زندان شد رحیل .<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">کل شی ٔ من الثقیل ثقیل </span> ؛<br />از گرانان بود گران همه چیز.<br /> <font color=\"Red\">(امثال و حکم از قابوسنامه )</font><br /><BR><font color=\"Blue\">◄</font> سخت بیمار. بیماریش سنگین شده . ثاقل . مرد آرمیده . <BR><font color=\"Blue\">◄</font> دیرفعل . <BR><font color=\"Blue\">◄</font> دژگوارد.بدگوارد. که دیرگوارد. بطی ٔ الانهضام . سنگین . دیر هضم . دیرگوار. <BR><font color=\"Blue\">◄</font> نام دردی است که عضو از آن گران معلوم میشود. (غیاث اللغة). ج، ثِقال و ثُقل و ثُقلاء. <BR><font color=\"Blue\">◄</font> ثقیل الظهر؛ بسیار عیال . <BR><font color=\"Blue\">◄</font> درهم ثقیل ؛ به وزن درهمی و دو دانک در هم بوده است .<br /></font></div>'),
(82384, 'ثقیل', '<span class=\"hlight\">ثقیل .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) نام پسر یکی از سلاطین روم :<br />ابر میسره پور قیصر ثقیل <br />ابر میمنه قیصر و کوس و پیل .<br /> <font color=\"Red\">فردوسی (لغت نامه ٔ شاهنامه ٔ ولف ص <span class=\"hlight\" dir=\"rtl\">٧٢٥</span>).</font><br />شاید این لفظ ثفیل باشدصورتی از تئوفیل .<br /></font></div>'),
(82385, 'ثقیلة', '<span class=\"hlight\">ثقیلة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ]</font></b> (ع ص ) تأنیث ثقیل . <BR><font color=\"Blue\">◄</font> اجسام ثقیله، چون خاک و آب .<br /></font></div>'),
(82386, 'ثل', '<span class=\"hlight\">ثل .</span> <font color=\"DarkGreen\"><b>[ ث َل ل ]</font></b> (ع مص ) هلاک شدن . <BR><font color=\"Blue\">◄</font> هلاک گردانیدن . <BR><font color=\"Blue\">◄</font> سرگین انداختن ستور. <BR><font color=\"Blue\">◄</font> خاک در چاه ریختن . <BR><font color=\"Blue\">◄</font> ویران کردن : ثل التراب المجتمع؛ جنبانید آنرا یا طرفی از اطراف آنرا شکست و منهدم ساخت . <BR><font color=\"Blue\">◄</font> تباه کردن نظام کار. (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> درم و زر ریختن در بوته . <BR><font color=\"Blue\">◄</font> ثلل (در همه ٔ معانی ).<br /></font></div>'),
(82387, 'ثلا', '<span class=\"hlight\">ثلا.</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (اِخ ) یکی از قلعه های یمن است . (مراصد الاطلاع ).<br /></font></div>'),
(82388, 'ثلاب', '<span class=\"hlight\">ثلاب .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع اِ) ج ِ ثلب .<br /></font></div>'),
(82389, 'ثلاث', '<span class=\"hlight\">ثلاث .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع عدد، ص، اِ) ثلاثة. سه : اقانیم ثلاث . ظلمات ثلاث . موالید ثلاث . <BR><font color=\"Blue\">◄</font> سه زن .<br /></font></div>'),
(82390, 'ثلاث', '<span class=\"hlight\">ثلاث .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع ص ) سوم . سیم . ثالث .<br /></font></div>'),
(82391, 'ثلاث', '<span class=\"hlight\">ثلاث .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع ص ) ثالث . <BR><font color=\"Blue\">◄</font> سه سه . <BR><font color=\"Blue\">◄</font> سه گان . (مجمل ). مَثلث .<br /></font></div>'),
(82392, 'ثلاث', '<span class=\"hlight\">ثلاث .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) نام موضعی است .<br /></font></div>'),
(82393, 'ثلاث الف', '<span class=\"hlight\">ثلاث الف .</span> <font color=\"DarkGreen\"><b>[ ث َ ث َ اَ ]</font></b> (ع عدد مرکب، ص مرکب، اِ مرکب ) سه هزار.<br /></font></div>'),
(82394, 'ثلاث عشر', '<span class=\"hlight\">ثلاث عشر.</span> <font color=\"DarkGreen\"><b>[ ث َث َ ع َ ش َ ]</font></b> (ع عدد مرکب، ص مرکب، اِ مرکب ) سیزده .<br /></font></div>'),
(82395, 'ثلاثان', '<span class=\"hlight\">ثلاثان .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (اِخ ) آبی است از بنی اسد در جانب حبشه . (مراصد الاطلاع ). <BR><font color=\"Blue\">◄</font> نام موضعی است .<br /></font></div>'),
(82396, 'ثلاثاوات', '<span class=\"hlight\">ثلاثاوات .</span> <font color=\"DarkGreen\"><b>[ ث َ <span class=\"hlight\" dir=\"rtl\">/</span> ث ُ ]</font></b> (ع اِ) ج ِ ثلاثاء. سه شنبه ها.<br /></font></div>'),
(82397, 'ثلاثون', '<span class=\"hlight\">ثلاثون .</span> <font color=\"DarkGreen\"><b>[ ث َ]</font></b> (ع عدد، ص، اِ) سی . و آن ملحق بجمع است نه جمع.<br /></font></div>'),
(82398, 'ثلاثی', '<span class=\"hlight\">ثلاثی .</span> <font color=\"DarkGreen\"><b>[ ث ُ ثی ی ]</font></b> (ع ص نسبی ) سه حرفی (کلمه ) و صیغ اسماء ثلاثی در عربی ده است : فلس . فرس . کتف . عضد. حبر. عنب . ابل . قفل . صرد.عنق . <BR><font color=\"Blue\">◄</font> منسوب به ثلثة. <BR><font color=\"Blue\">◄</font> و در کشاف اصطلاحات الفنون آمده است : بضم ّ ثاء مثلَّثه، نزد علماء صرف عبارت است از اسم یا فعلی که یافت شود در او سه حرف اصلی . یعنی زائد بر سه حرف اصلی حرفی در آن نباشد. و ثلاثی را قطب اعظم هم نامیده اند چنانکه در پاره ای از شروح مراح الارواح ذکر شده . در آنجا که قول صاحب مراح را که گفته است : و الرباعی فرع الثلاثی، شرح میدهد. اگر ثلاثی جز سه حرف اصلی حرف زائدی نداشت آنرا ثلاثی مجرد نامند. مانند زید. وَ ضَرَب َ و اگر دارای حرف زائد بود آنرا ثلاثی مزید خوانند. مانند أکرَم َ و اِستنصَر. و ذوالثلاثة عندهم هوالاجوف ای معتل ّ العین . و ثَلاثِیه در اصطلاح منطق قسمی از قضیه ٔ حملیه است . و شرح آن در ضمن معنی لفظ حمل گفته شود.<br /></font></div>'),
(82399, 'ثلاثیة', '<span class=\"hlight\">ثلاثیة.</span> <font color=\"DarkGreen\"><b>[ ث ُ ثی ی َ ]</font></b> (ع ص نسبی ) تأنیث ثُلاثی ؛ کلمه ٔ ثلاثیة؛ کلمه ٔ سه حرفی .<br /></font></div>'),
(82400, 'ثلاثین', '<span class=\"hlight\">ثلاثین .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع عدد، ص، اِ) سی .<br /></font></div>'),
(82401, 'ثلاج', '<span class=\"hlight\">ثلاج .</span> <font color=\"DarkGreen\"><b>[ ث َ ل ْ لا ]</font></b> (اِخ ) ابوالقاسم عبداﷲبن محمدبن ... بحتربن ثلاج به این نسبت معروف است . (سمعانی ).<br /></font></div>'),
(82402, 'ثلاج', '<span class=\"hlight\">ثلاج .</span> <font color=\"DarkGreen\"><b>[ ث َ ل ْ لا ]</font></b> (ع ص ) برف فروش .<br /></font></div>'),
(82403, 'ثلاجی', '<span class=\"hlight\">ثلاجی .</span> <font color=\"DarkGreen\"><b>[ ث ُ جی ی ]</font></b> (ع ص ) نصل ثُلاجی، پیکان بسیار سپید.<br /></font></div>'),
(82404, 'ثلال', '<span class=\"hlight\">ثلال .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِمص ) هلاک . هلاکی .<br /></font></div>'),
(82405, 'ثلال', '<span class=\"hlight\">ثلال .</span> <font color=\"DarkGreen\"><b>[ ث ِ]</font></b> (ع اِ) ج ِ ثَلة به بعض معانی . رجوع به ثله شود.<br /></font></div>'),
(82406, 'ثلب', '<span class=\"hlight\">ثلب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) عیب . ج، ثلاب .<br /></font></div>'),
(82407, 'ثلب', '<span class=\"hlight\">ثلب .</span> <font color=\"DarkGreen\"><b>[ ث َ ل ِ ]</font></b> (ع ص ) چرکن . <BR><font color=\"Blue\">◄</font> نیزه ٔ رخنه دار. <BR><font color=\"Blue\">◄</font> مردی ثلب ؛ مردی عیب ناک .<br /></font></div>'),
(82408, 'ثلب', '<span class=\"hlight\">ثلب .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ]</font></b> (ع اِمص ) ترنجیدگی . <BR><font color=\"Blue\">◄</font> ریم . ریمناکی . <BR><font color=\"Blue\">◄</font> (مص )رخنه دار شدن . شکافته شدن . <BR><font color=\"Blue\">◄</font> منغص شدن .<br /></font></div>'),
(82409, 'ثلب', '<span class=\"hlight\">ثلب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) سرزنش کردن . نکوهیدن . عیب نمودن . نقص کردن . <BR><font color=\"Blue\">◄</font> راندن . <BR><font color=\"Blue\">◄</font> برگردانیدن . <BR><font color=\"Blue\">◄</font> رخنه کردن .<br /></font></div>'),
(82410, 'ثلب', '<span class=\"hlight\">ثلب .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) ج ِ ثلوب .<br /></font></div>'),
(82411, 'ثلب', '<span class=\"hlight\">ثلب .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (اِخ ) نام صحابی است و یا آن تلب است .<br /></font></div>'),
(82412, 'ثلب', '<span class=\"hlight\">ثلب .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع اِ) ابن البیطار از قول ابن الوحشیة گوید: ثلب نام عربی نباتی است خودرو در کنار جویبارها و اطراف آبها و آن برگهای طویل شبیه ببرگهای آزاد درخت دارد به ارتفاع دو قامت و چوبش شبیه لحبة التیس و گرم و خشک است برگ خشک شده و مسحوق وی را چون در موی ریزند مانع ریختن آن شودو آنرا قوت بخشد... . <BR><font color=\"Blue\">◄</font> (ص، اِ) مرد پیر و شتر پیر که باردار نگرداند. (یعنی آبستن نکند). <BR><font color=\"Blue\">◄</font> شتر پیر دندان و موی دم ریخته . <BR><font color=\"Blue\">◄</font> گرگ کهن سال . ج، اثلاب و ثِلَبَة. <BR><font color=\"Blue\">◄</font> رَجَل ُ ثِلب ؛ مرد عیب ناک .<br /></font></div>'),
(82413, 'ثلبان', '<span class=\"hlight\">ثلبان .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) عنب الثعلب . (بحر الجواهر).<br /></font></div>'),
(82414, 'ثلبة', '<span class=\"hlight\">ثلبة.</span> <font color=\"DarkGreen\"><b>[ ث ِ ل َ ب َ ]</font></b> (ع اِ) ج ِ ثِلب .<br /></font></div>'),
(82415, 'ثلبة', '<span class=\"hlight\">ثلبة.</span> <font color=\"DarkGreen\"><b>[ ث ِ ب َ ]</font></b> (ع ص، اِ) تأنیث ثلب . ناقه ٔ پیر دندان و موی فروریخته .<br /></font></div>'),
(82416, 'ثلبوت', '<span class=\"hlight\">ثلبوت .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ]</font></b> (اِخ ) وادیی است بین طی و ذبیان و بقولی از بنی نصربن فعقس است و در آنجا آبهائی دارند. (مراصد الاطلاع ).<br /></font></div>'),
(82417, 'ثلة', '<span class=\"hlight\">ثلة.</span> <font color=\"DarkGreen\"><b>[ ث ِل ْ ل َ ]</font></b> (ع اِمص ) نیستی . هلاک . ج، ثِلل .<br /></font></div>'),
(82418, 'ثلة', '<span class=\"hlight\">ثلة.</span> <font color=\"DarkGreen\"><b>[ ث ُل ْ ل َ ]</font></b> (ع اِ) گروه مردم . جماعت بسیار. <BR><font color=\"Blue\">◄</font> درم بسیار. <BR><font color=\"Blue\">◄</font> چیزی چون مناره در بیابان که بسایه ٔ آن پناهند. ج، ثُلَل . ثِلَل .<br /></font></div>'),
(82419, 'ثلة', '<span class=\"hlight\">ثلة.</span> <font color=\"DarkGreen\"><b>[ ث ِل ْ ل َ ]</font></b> (ع اِ) رمه ٔ بزرگ از گوسفند و بز درآمیخته، یا خاص است به رمه ٔ میش . ج، ثِلل َ، ثِلال . <BR><font color=\"Blue\">◄</font> رخنه . <BR><font color=\"Blue\">◄</font> پشم گوسفند؛ کساء جیدالثلة. <BR><font color=\"Blue\">◄</font> پشم گوسپند آمیخته بموی و پشم شتر. <BR><font color=\"Blue\">◄</font> مناره مانندی در صحرا که زیر سایه ٔ آن آرام گیرند. <BR><font color=\"Blue\">◄</font> نوبت آب شتران بعد دو روز. <BR><font color=\"Blue\">◄</font> درم بسیار. <BR><font color=\"Blue\">◄</font> گل چاه برآورده شده . ج، ثُلَل . ثِلل . ثِلال .<br /></font></div>'),
(82420, 'ثلث', '<span class=\"hlight\">ثلث .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) سه . <BR><font color=\"Blue\">◄</font> سه یک . سوم بخش . <BR><font color=\"Blue\">◄</font> لفظ معدول است از ثلاثة. دو دانگ . (زمخشری و ملخص اللغات حسن خطیب ). ج، اُثلاث . <BR><font color=\"Blue\">◄</font> قسمی از خطوط یا قلم های اسلامی . قط قلم ثلث به پهنای هشت موی یال برذون است . نام خطی است از خطوط هفتگانه که عبارت است از: مناشیر، محقق، نسخ، ریحان، رقاع، ثلث، تعلیق ؛ و متأخران یک خط دیگر از این استخراج کرده اند که نامش نستعلیق باشد و اصلش نسخ تعلیق . و ثلث را از آن ثلث گویند که در آن سوم حصه ٔ اصول قلم باشد. (غیاث اللغة).<br /></font></div>'),
(82421, 'ثلث', '<span class=\"hlight\">ثلث .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) اصطرلاب ثلث . رجوع به اصطرلاب شود. <BR><font color=\"Blue\">◄</font> (مص ) سوم شدن . بسه کردن . سه یک کردن . سیم شدن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> سه یکی مال کسی بستدن . (تاج المصادر بیهقی ) (زوزنی ).<br /></font></div>'),
(82422, 'ثلث', '<span class=\"hlight\">ثلث .</span> <font color=\"DarkGreen\"><b>[ ث ُ <span class=\"hlight\" dir=\"rtl\">/</span> ث ُ ل ُ ]</font></b> (ع اِ) ثلیث . سه یک . ج، اُثلاث .<br /></font></div>'),
(82423, 'ثلث', '<span class=\"hlight\">ثلث .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع اِ) به هر سه روز یک بار نوبت آب درخت را: سقی نخله الثلث . <BR><font color=\"Blue\">◄</font> ولد سوم ناقة.<br /></font></div>'),
(82424, 'ثلث', '<span class=\"hlight\">ثلث .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) سه یک ستاندن . <BR><font color=\"Blue\">◄</font> سی گردانیدن . <BR><font color=\"Blue\">◄</font> سه گردانیدن چیزی را. <BR><font color=\"Blue\">◄</font> گرفتن ثلث مال . <BR><font color=\"Blue\">◄</font> سوم قوم شدن . <BR><font color=\"Blue\">◄</font> ثلث ناقة؛ بستن سه پستان او را. <BR><font color=\"Blue\">◄</font> ثلث جمل ؛ سه تاه تافتن رسن اشتر را. <BR><font color=\"Blue\">◄</font> ثلث أرض ؛ سه بار شیار کردن زمین را.<br /></font></div>'),
(82425, 'ثلث', '<span class=\"hlight\">ثلث .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (اِخ ) موضعی است در دیار مراد. (مراصد الاطلاع ).<br /></font></div>'),
(82426, 'ثلث ریاسی', '<span class=\"hlight\">ثلث ریاسی .</span> <font color=\"DarkGreen\"><b>[ ث ُ ث ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) قسمی خطعربی اختراع ذوالریاستین فضل بن سهل . (ابن الندیم ).<br /></font></div>'),
(82427, 'ثلث پذیر', '<span class=\"hlight\">ثلث پذیر.</span> <font color=\"DarkGreen\"><b>[ ث ُ پ َ ]</font></b> (نف مرکب )قابل تقسیم به سه جزء .<br /></font></div>'),
(82428, 'ثلثال', '<span class=\"hlight\">ثلثال .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) نوعی از شور گیاه .<br /></font></div>'),
(82429, 'ثلثان', '<span class=\"hlight\">ثلثان .</span> <font color=\"DarkGreen\"><b>[ ث َ ل ِ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ل َ]</font></b> (ع اِ) عنب الثعلب . سگ انگور. تاجریزی . طولیدون . فنا . (اختیارات بدیعی ). غرغره کردن با آب آن ورم زبانرا نافع باشد و خوردن آن قطع احتلام کند. (برهان قاطع). رجوع به تاجریزی شود.<br /></font></div>'),
(82430, 'ثلثان', '<span class=\"hlight\">ثلثان .</span> <font color=\"DarkGreen\"><b>[ ث ُ ل ُ ]</font></b> (ع اِ) دو سه یک . دو حصه از جمله ٔ سه حصه . (غیاث اللغة). رجوع به دو ثلث شود. چهار دانگ . (زمخشری ). <BR><font color=\"Blue\">◄</font> ثلثان شدن شراب ؛ جوشاندن شراب تا آنکه دو ثلث آن تبخیر شود و یک ثلث بجای ماند. <BR><font color=\"Blue\">◄</font> ثلثان و ربع، پنج دانگ و نیم . (زمخشری ).<br /></font></div>'),
(82431, 'ثلثل', '<span class=\"hlight\">ثلثل .</span> <font color=\"DarkGreen\"><b>[ث ُ ث ُ ]</font></b> (ع اِمص ) هدم و انهدام و خرابی و ویرانی .<br /></font></div>'),
(82432, 'ثلثلان', '<span class=\"hlight\">ثلثلان .</span> <font color=\"DarkGreen\"><b>[ ث ُ ث ُ <span class=\"hlight\" dir=\"rtl\">/</span>ث ِ ث ِ ]</font></b> (ع اِ) سگ انگور. عنب الثعلب . (ابن البیطار). <BR><font color=\"Blue\">◄</font> گیاه خشک .<br /></font></div>'),
(82433, 'ثلثلة', '<span class=\"hlight\">ثلثلة.</span> <font color=\"DarkGreen\"><b>[ ث َ ث َ ل َ ]</font></b> (ع مص ) ویران کردن به این که بن را برآورد: ثلثلة تراب، ثَل ِّ تراب .<br /></font></div>'),
(82434, 'ثلثوت', '<span class=\"hlight\">ثلثوت .</span><font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص، اِ) بمعنی ثلوث است، در همه ٔ معانی .<br /></font></div>'),
(82435, 'ثلثی', '<span class=\"hlight\">ثلثی .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ص نسبی ) خط ثلثی ؛ خطی که حروف آن درشت باشد.<br /></font></div>'),
(82436, 'ثلثین', '<span class=\"hlight\">ثلثین .</span> <font color=\"DarkGreen\"><b>[ ث ُ ث َ ]</font></b> (ع اِ) دو ثلث . <BR><font color=\"Blue\">◄</font> قسمی از خط عربی . (ابن الندیم ). قطّ قلم ثلثین به پهنای موی یال برذون است .<br /></font></div>'),
(82437, 'ثلج', '<span class=\"hlight\">ثلج .</span> <font color=\"DarkGreen\"><b>[ ث َ ل ِ ]</font></b> (ع ص ) خنک و سرد: ماء ثلج ؛ آب خنک .<br /></font></div>'),
(82438, 'ثلج', '<span class=\"hlight\">ثلج .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ]</font></b> (ع مص ) ثلوج .آرام گرفتن دل . شاد شدن . <BR><font color=\"Blue\">◄</font> یقین کردن .<br /></font></div>'),
(82439, 'ثلج', '<span class=\"hlight\">ثلج .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) بنوثلج ؛ قبیله ای است .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(82440, 'ثلج', '<span class=\"hlight\">ثلج .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) برف . و آن در سیم سرد و در دوم خشک و مسکّن درد دندان حارّ و اخراج کننده ٔ زلوی در حلق مانده و جهت کرم معده و تقویت هضم معده حاره و تبهای حاره و جرب و حکه و ضماد او بر پیشانی جهت قطع رعاف و آشامیدن او باعث اجتماع حرارت در معده و مخدر و معطّش و مورث سعال و مضر احشاء ضعیف مبرودین و صاحب اورام باطنی است و آب پرورده با او بهتر است و مصحلش قرنفل و عسل و از خواص او است که چون نمک با برف آمیخته بر شیشه پرآب بدستوری بگیرند که شیشه در آن پنهان شود در یک ساعت آب شیشه یخ گردد. (تحفه ٔ حکیم مؤمن ). ج، ثلوج . <BR><font color=\"Blue\">◄</font> ماء ثلج ؛ آب خنک . <BR><font color=\"Blue\">◄</font> بلاد ثلج ؛ یکی از هفت کشور و کشور هفتم است و منسوب است به ماه . <BR><font color=\"Blue\">◄</font> برف باریدن . <BR><font color=\"Blue\">◄</font> تر نهادن چیزی را یعنی خیساندن آن . تر کردن . <BR><font color=\"Blue\">◄</font> شادمان گشتن . <BR><font color=\"Blue\">◄</font> خنک دل شدن . گشاده دل گردانیدن .<br /></font></div>'),
(82441, 'ثلج چینی', '<span class=\"hlight\">ثلج چینی .</span> <font color=\"DarkGreen\"><b>[ ث َ ج ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) یا ثلج صینی رطوبتی منجمدبرفی است شبیه به نمک که از هند آرند جهت بیاض عین و ظلمت بصر و ضمادش بر بدن جهت تب دق نافع است و این اسم را بر بارود نیز استعمال می کنند. (تحفه ٔ حکیم مؤمن ). یطلق علی البارود و علی رطوبة تنعقد علی القصب بأطراف الهند تجلو البیاض و الظلمة. (تذکره ٔ ضریر انطاکی ). نمک چینی و آن سنگی است سفید که بجهت جلای چشم در سرمه بکار برند و بعضی گویند شوره است . (برهان قاطع). سنگ سفید است که در سرمه ها بکار برند و جهت جلاء چشم و تب دق نافع است و طبیعت وی سرد است و خشک وابن بیطار گوید زهره ٔ اسیوس است و در الف صفت آن گفته شد. (اختیارات بدیعی ). و در ترجمه ٔ صیدنه آمده است : از بلاد چین بعراق برند و رنگ او سخت سفید بود و زاید (؟) و چون غبار بود و در غایت لطیفی و خردی و اورا در انواع سرمه ها بکار برند. <BR><font color=\"Blue\">◄</font> بارود. <BR><font color=\"Blue\">◄</font> جد چینی .<br /></font></div>'),
(82442, 'ثلجی', '<span class=\"hlight\">ثلجی .</span> <font color=\"DarkGreen\"><b>[ ث َ جی ی ]</font></b> (ع ص نسبی ) برف فروش .<br /></font></div>'),
(82443, 'ثلجی', '<span class=\"hlight\">ثلجی .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ص نسبی ) منسوب است به ثلج بن عمروبن مالک . (سمعانی ).<br /></font></div>'),
(82444, 'ثلجی', '<span class=\"hlight\">ثلجی .</span><font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) محمدبن شجاع ثلجی . فقیهی است مبتدع .<br /></font></div>'),
(82445, 'ثلخ', '<span class=\"hlight\">ثلخ .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) سرگین کردن گاو در ایام بهار. <BR><font color=\"Blue\">◄</font> آلوده گردیدن به سرگین .<br /></font></div>'),
(82446, 'ثلد', '<span class=\"hlight\">ثلد.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) ثلد فیل ؛ ریخ زدن او.<br /></font></div>'),
(82447, 'ثلط', '<span class=\"hlight\">ثلط.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) ریخ پیل و مانندآن . <BR><font color=\"Blue\">◄</font> (مص ) ریخ زدن گاو و اشتر و کودک وجز آن . <BR><font color=\"Blue\">◄</font> سرگین اوکندن . <BR><font color=\"Blue\">◄</font> ثلط کسی را؛ زدن او را به ثلط. آلودن کسی را به ریخ .<br /></font></div>'),
(82448, 'ثلع', '<span class=\"hlight\">ثلع.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) سرکوفتن . سرشکستن . شکستن چنانکه سر را.<br /></font></div>'),
(82449, 'ثلغ', '<span class=\"hlight\">ثلغ.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) ثلغ رأس ؛ شکستن و شکافتن سر.<br /></font></div>'),
(82450, 'ثلل', '<span class=\"hlight\">ثلل .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ]</font></b> (ع مص ) ثل . هلاک کردن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> هلاک شدن . <BR><font color=\"Blue\">◄</font> افتادگی دندان . <BR><font color=\"Blue\">◄</font> سرگین انداختن ستور. <BR><font color=\"Blue\">◄</font> ویران شدن . <BR><font color=\"Blue\">◄</font> ثل یا ثلل بئر؛ گل برآوردن از چاه . لاروبی چاه . <BR><font color=\"Blue\">◄</font> ثلل تراب مجتمع؛ جنبانیدن آن را، یا شکستن طرفی از اطراف آن یا منهدم کردن . و همچنین است ثل یا ثلل کثیب . <BR><font color=\"Blue\">◄</font> ثلل دار یا ثل دار؛ ویران کردن خانه را و آن چنان باشد که بن دیوار بر کنند و سپس دیوار را بجنبانند تا در افتد. <BR><font color=\"Blue\">◄</font> ثلل تراب در بئر؛ انباشتن خاک را در چاه . <BR><font color=\"Blue\">◄</font> ثلل دراهم ؛ فروریختن درهم ها را. <BR><font color=\"Blue\">◄</font> ثل اﷲ عرش فلان ؛ نفرین است و معنی آن، میراند او را و ببرد ملک او را.<br /></font></div>'),
(82451, 'ثلل', '<span class=\"hlight\">ثلل .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ]</font></b> (ع اِ) ج ِ ثُلّة.<br /></font></div>'),
(82452, 'ثلل', '<span class=\"hlight\">ثلل .</span> <font color=\"DarkGreen\"><b>[ ث ِ ل َ ]</font></b> (ع اِ) ج ِ ثِلّة. گوسپندان بسیار.<br /></font></div>'),
(82453, 'ثلل', '<span class=\"hlight\">ثلل .</span> <font color=\"DarkGreen\"><b>[ ث ُ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ث ِ ل َ ]</font></b> (ع اِ) ج ِ ثَلّة ببعض معانی . گلهای از چاه برآورده . <BR><font color=\"Blue\">◄</font> هلاک . رجوع به ثَلة شود.<br /></font></div>'),
(82454, 'ثلم', '<span class=\"hlight\">ثلم .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) رخنه کردن در. <BR><font color=\"Blue\">◄</font> ترک دادن به . <BR><font color=\"Blue\">◄</font> شکستن کناره ٔ وادی . تثلیم . <BR><font color=\"Blue\">◄</font> بینی بریدن . (غیاث اللغة). <BR><font color=\"Blue\">◄</font> اسقاط فاء فعولن است تا عولن بماند فع لن بجای آن بنهند و ثلم در اشعار عجم نیاید. (المعجم فی معاییر اشعار العجم ). بفتح ثاء مثلثه رخنه کردن است کمافی الصراح . و نزد عروضیان حذف فاء فعولن باشد که عولن باقی ماند و بجای او فعلن بنهند. و رکنی که ثلم در آن واقعمیشود أثلم خوانند چنانچه در عنوان الشرف گفته . و عروض سیفی هم با آن موافقت کرده و در پاره ای از رسائل عروض مغربیان آمده که خرم اسقاط اولین متحرک از وَتد مجموع را گویند در صورتی که جزء در صدر بیت واقع شود. پس اگر عمل خرم در فعولن سالم صورت گرفته باشد آنرا ثَلم نامند. و در عروض قطب الدین سرخسی گوید: ثلم خرم سالم است و خرم اسقاط اول وتد مجموع و سالم هم جزئی است که زحاف در آن نباشد و در جامعالصنایع گوید: خرم و ثلم افکندن متحرک اول باشد تا از مفاعیلن مفعولن و از فعولن فعلن ماند - انتهی . و لا یخفی ما فی هذه العبارات من التخالف . (کشاف اصطلاحات الفنون ).<br /></font></div>'),
(82455, 'ثلم', '<span class=\"hlight\">ثلم .</span> <font color=\"DarkGreen\"><b>[ ث ُ ل َ ]</font></b> (ع اِ) ج ِ ثُلمة.<br /></font></div>'),
(82456, 'ثلم', '<span class=\"hlight\">ثلم .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ]</font></b> (اِخ ) محلی است در صمان . (مراصد الاطلاع ).<br /></font></div>'),
(82457, 'ثلمة', '<span class=\"hlight\">ثلمة.</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (ع اِ) ثلمت . تَرَک . سوراخ . رخنه <span class=\"hlight\">:</span> خواست که بقوت و شوکت خویش انتقامی کشد و ثلمه ای که از قهر و قوت احزاب اسلام در ولایت و نواحی مملکت او ظاهر شده بود برگیرد. (ترجمه ٔتاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٢</span>). از هر گوشه وهنی و از هر طرف ثلمه ای حادث میشود. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢١٧</span>). به استیناف مناجزت و سد حادثه ٔ ثلمت قیام نماید. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٢٨</span>). سد ثلمة و قوام امّة بمکان او حاصل آورد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٧٩</span>). که هر کس به مصلحت ولایت و رعیت خویش داناتر باشد و به ثلمه و خلل واقف تر. (جهان گشای جوینی ). <BR><font color=\"Blue\">◄</font> خط. (در چو خط) . <BR><font color=\"Blue\">◄</font> چاک . <BR><font color=\"Blue\">◄</font> ثلمه ٔ قدح ؛ موضع لب پریدگی آن . ج، ثُلَم .<br /></font></div>'),
(82458, 'ثلمة', '<span class=\"hlight\">ثلمة.</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (ع مص ) ثلم . رخنه کردن . (تاج المصادر بیهقی ).<br /></font></div>'),
(82459, 'ثلمت', '<span class=\"hlight\">ثلمت .</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (ع اِ) رجوع به ثلمة شود.<br /></font></div>'),
(82460, 'ثلمط', '<span class=\"hlight\">ثلمط.</span> <font color=\"DarkGreen\"><b>[ ث َ م َ ]</font></b> (ع اِ) ثُلموط. لای روان و گشاده و رقیق .<br /></font></div>'),
(82461, 'ثلموط', '<span class=\"hlight\">ثلموط.</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) ثلمط. لای گشاده و رقیق .<br /></font></div>'),
(82462, 'ثلوب', '<span class=\"hlight\">ثلوب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص ) بسیار عیب کننده ٔ مردم . ج، ثُلب .<br /></font></div>'),
(82463, 'ثلوث', '<span class=\"hlight\">ثلوث .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص، اِ) ناقه ای که سه خنور شیر دهد. <BR><font color=\"Blue\">◄</font> ناقه ای که سرپستان وی خشک شده و یکی بمانده است یا ناقه ای که یک پستانش بریده و یا بی شیر باشد. ثَلثوث .<br /></font></div>'),
(82464, 'ثلوج', '<span class=\"hlight\">ثلوج .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع مص ) ثلج . برف باریدن . <BR><font color=\"Blue\">◄</font> آرمیدن تن . (تاج المصادربیهقی ). <BR><font color=\"Blue\">◄</font> آرام گرفتن دل و یقین کردن .<br /></font></div>'),
(82465, 'ثلوج', '<span class=\"hlight\">ثلوج .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) ج ِ ثلج .<br /></font></div>'),
(82466, 'ثلی', '<span class=\"hlight\">ثلی .</span> <font color=\"DarkGreen\"><b>[ ث ُل ْ لا ]</font></b> (ع اِ) عزّت رفته .<br /></font></div>'),
(82467, 'ثلیب', '<span class=\"hlight\">ثلیب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) گیاه سیاه دیرینه یا گیاه دوساله . <BR><font color=\"Blue\">◄</font> نوعی از شورگیاه .<br /></font></div>'),
(82468, 'ثلیث', '<span class=\"hlight\">ثلیث .</span> <font color=\"DarkGreen\"><b>[ ث ُل ْ ل َ ]</font></b> (اِخ ) محلی است برراه طی بطرف شام . (مراصد الاطلاع ).<br /></font></div>'),
(82469, 'ثلیث', '<span class=\"hlight\">ثلیث .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) سه یک . این وزن در اعداد دیگر هست چون نصیف و سبیع و ثمین، و ابوزید خمیس و ثلیث را منکر شده است .<br /></font></div>'),
(82470, 'ثلیل', '<span class=\"hlight\">ثلیل .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ)بز کوهی . <BR><font color=\"Blue\">◄</font> آواز آب یا آواز ریختن آب .<br /></font></div>'),
(82471, 'ثم', '<span class=\"hlight\">ثم .</span> <font color=\"DarkGreen\"><b>[ ث َم م ]</font></b> (ع مص ) گرد کردن . فراهم آوردن . <BR><font color=\"Blue\">◄</font> پاسپر کردن . <BR><font color=\"Blue\">◄</font> نیکو کردن . <BR><font color=\"Blue\">◄</font> چیزی به اصلاح آوردن . <BR><font color=\"Blue\">◄</font> رُفتن خانه و جای . <BR><font color=\"Blue\">◄</font> مرمت کردن : کنا أهل ثَمة و رمّة. <BR><font color=\"Blue\">◄</font> جعجع الدهر بی عن ثَمَة و رَمّة؛ أی عن قلیله و کثیره . <BR><font color=\"Blue\">◄</font> فراهم و گرد آوردن چیزی را. (و استعمال آن در گیاه بیشتر است ). <BR><font color=\"Blue\">◄</font> ثم ّ یده بالحشیش ؛ بعلف مالید دست را. <BR><font color=\"Blue\">◄</font> ثمت الشاة النبت ؛ برکند گوسپند گیاه را از بن . <BR><font color=\"Blue\">◄</font> ثم ّ طعام ؛ خوردن همه ٔ طعام بد و نیک آن را.<br /></font></div>'),
(82472, 'ثم', '<span class=\"hlight\">ثم .</span> <font color=\"DarkGreen\"><b>[ ث َم ْ م َ ]</font></b> (ع ق ) آنجا. ثَمَّة <span class=\"hlight\">:</span> <br />هست احول را در این ویرانه دیر<br />گونه گونه نقل نو که ثم ّ خیر.<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(82473, 'ثم', '<span class=\"hlight\">ثم .</span> <font color=\"DarkGreen\"><b>[ ث ُم م ]</font></b> (ع اِ) قماش مشکهای آب و آوندها، مالهم ثم ّ و لا رم ّ. مایملک ثّما و لا رَمّا، هیچ ندارند. هیچ ندارد.<br /></font></div>'),
(82474, 'ثم', '<span class=\"hlight\">ثم .</span> <font color=\"DarkGreen\"><b>[ ث ُم ْ م َ ]</font></b> (ع حرف ربط) حرف عطف است برای مهلت . پس . سپس . باز. پس از آن . <BR><font color=\"Blue\">◄</font> هم . وَ هم . <BR><font color=\"Blue\">◄</font> ثم ماذا؛ سپس چه ؟ نتیجه چیست ؟<br /></font></div>'),
(82475, 'ثم ماذا', '<span class=\"hlight\">ثم ماذا.</span> <font color=\"DarkGreen\"><b>[ ث ُم ْ م َ ]</font></b> (ع جمله ٔ اسمیه ٔ استفهامی ) سپس چه ؟ میخواهید چه نتیجه بگیرید. مقصود از این مقدمه چیست .<br /></font></div>'),
(82476, 'ثما', '<span class=\"hlight\">ثما.</span><font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) موضعی است در حجاز. (معجم البلدان ).<br /></font></div>'),
(82477, 'ثماد', '<span class=\"hlight\">ثماد.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) ج ِ ثَمَد. (دهار).<br /></font></div>'),
(82478, 'ثماد', '<span class=\"hlight\">ثماد.</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع اِ) ثَمَد. آب اندک . آب باقی در زمین هموار و سخت یا آبی که در سرما ظاهر گردد و در گرما خشک .<br /></font></div>'),
(82479, 'ثماد', '<span class=\"hlight\">ثماد.</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (اِخ ) موضعی است در دیار بنی تمیم قرب المروت . (مراصد الاطلاع ).<br /></font></div>'),
(82480, 'ثماد', '<span class=\"hlight\">ثماد.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) قلعه ای است در یمن در جبل جُحاف . (مراصد الاطلاع ).<br /></font></div>'),
(82481, 'ثمادالطیر', '<span class=\"hlight\">ثمادالطیر.</span> <font color=\"DarkGreen\"><b>[ ث ِدُطْ طَ ]</font></b> (اِخ ) محلی است در یمن . (مراصد الاطلاع ).<br /></font></div>'),
(82482, 'ثمار', '<span class=\"hlight\">ثمار.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) میوه . <BR><font color=\"Blue\">◄</font> انواع مال .<br /></font></div>'),
(82483, 'ثمار', '<span class=\"hlight\">ثمار.</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع اِ) ج ِ ثَمر و ثمرة. (زمخشری ). میوه ها <span class=\"hlight\">:</span> چگونگی آب و هوا و ثمار هر بقعتی از آن ... (ابن البلخی ).<br />آب هش را میکشد هر بیخ خار<br />آب هوشت چون رسد سوی ثمار.<br /> <font color=\"Red\">مولوی .</font><br />جزو جزو آبستن از شاه بهار<br />جسمشان چون درج پُر درّ ثمار.<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(82484, 'ثمار', '<span class=\"hlight\">ثمار.</span> <font color=\"DarkGreen\"><b>[ ث َم ْ ما ]</font></b>(ع ص ) میوه فروش . فاکهانی . (زمخشری ) (منتهی الارب ).<br /></font></div>'),
(82485, 'ثمال', '<span class=\"hlight\">ثمال .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) ج ِ ثُمالة.<br /></font></div>'),
(82486, 'ثمال', '<span class=\"hlight\">ثمال .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع ص، اِ) فریادرس که بمهمات قوم خود پردازد: فلان ثمال قوم خویش است ؛دادرس آنان است . غیاث . پشت و پناه . کارگذار مردم .<br /></font></div>'),
(82487, 'ثمال', '<span class=\"hlight\">ثمال .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) زهر کشنده .<br /></font></div>'),
(82488, 'ثمال', '<span class=\"hlight\">ثمال .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (اِخ ) ابن صالح، معزالدّولة در نیمه ٔ اوّل مائه ٔ پنجم ظاهراً امارت حلب داشته و ابن بطلان در <span class=\"hlight\" dir=\"rtl\">٤٣٩</span> هَ . ق . نزد او رفته و معزالدوله بدو احسان و اکرام کرده است . رجوع به عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤١</span> و به معزالدولة ثمال بن صالح ... شود.<br /></font></div>'),
(82489, 'ثمالة', '<span class=\"hlight\">ثمالة.</span> <font color=\"DarkGreen\"><b>[ ث ُ ل َ ]</font></b> (اِخ ) لقب عوف بن اسلم که پدر بطنی است و او را ثمالة لقب دادند چون قوم خود را اطعام کرد و شیر با سر شیر آن نوشانید.<br /></font></div>'),
(82490, 'ثمالة', '<span class=\"hlight\">ثمالة.</span> <font color=\"DarkGreen\"><b>[ ث ُ ل َ ]</font></b> (ع اِ) بقیه ٔ آب و طعام در شکم . <BR><font color=\"Blue\">◄</font> باقی آب در تک حوض و خنور. <BR><font color=\"Blue\">◄</font> کف شیر. سر شیر. <BR><font color=\"Blue\">◄</font> لیف سرسبوی . ج، ثُمال .<br /></font></div>'),
(82491, 'ثمالی', '<span class=\"hlight\">ثمالی .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ص نسبی ) منسوب است به ثماله ٔ ازدی . (انساب سمعانی ). رجوع به ابوحمزه شود.<br /></font></div>'),
(82492, 'ثمام', '<span class=\"hlight\">ثمام .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) گیاهی است که بفارسی یز نامند. (منتهی الارب ). یزبُن . و آن از درختان کوهی باشد شبیه به اَثل و از آن حصیر سازند. مؤلف تحفةالمؤمنین گوید: بعربی اسم نباتیست شبیه بگندم و قدش کوتاه تر و ساقش باریکتر و بی بند و غیر مجوف و خوشه ٔ او شبیه به ارزن و طعم او شیرین و در تنکابن زراواش نامند. در دوم گرم ودر اول خشک و ضماد تازه ٔ او جهت ورم چشم و منع ریختن مواد و آشامیدن او محلل ریاح و مفتح سدد و خاکستر او جهت تقویت مژگان و رویانیدن آن و تقویت باصره نافع و مضر گرده و مصحلش کتیرا و قدر شربتش تا پنج مثقال و بدلش تودری است - انتهی . <BR><font color=\"Blue\">◄</font> برگ ِ گیاه یز را عرب حجنةالثمام گوید. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> هذاعلی طرف الثمام ؛ یعنی این چیزی است که دست بدان میرسد و این مثل است در آنکه سهل المأخذ باشد.<br /></font></div>'),
(82493, 'ثمام', '<span class=\"hlight\">ثمام .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (اِخ ) ابن لیث . محدث است .<br /></font></div>'),
(82494, 'ثمامة', '<span class=\"hlight\">ثمامة.</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (اِخ ) ابن ثال . صحابی است .<br /></font></div>'),
(82495, 'ثمامة', '<span class=\"hlight\">ثمامة.</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (اِخ ) ابن بجاد العبدی . صحابی است .<br /></font></div>'),
(82496, 'ثمامة', '<span class=\"hlight\">ثمامة.</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (اِخ ) العبسی القعقاعی . ابوعثمان بن ثمامة صاحب الجبار. از معمرین عصر هارون الرشید و مورد عنایت اوست . مؤلف عیون الانباء آورده است که خواهر او زوجه ٔ عبدالملک بن مروان و مادر ولید و سلیمان خلفای اموی بود و خواهر دیگرش زوجه ٔ مهدی وقتی ثمامة سخت بیمار شد هارون الرشید ابواسحاق ابراهیم بن المهدی را بعیادت او فرستاد ابوخالد یزیدبن یوحنا که خدمت ابراهیم میکرد با حسن تدبیر و جرأت داروئی به وی داد و ثمامة شفا یافت هارون را طریق معالجه ٔ یزید خوش آمد و ده هزار درهم به وی بخشید.<br /></font></div>'),
(82497, 'ثمامة', '<span class=\"hlight\">ثمامة.</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (اِخ ) ابن حزن . صحابی است .<br /></font></div>'),
(82498, 'ثمامة', '<span class=\"hlight\">ثمامة.</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (اِخ ) ابن شفی ابوعلی . تابعی است ... رجوع به ابوعلی همدانی یا اصبحی شود.<br /></font></div>'),
(82499, 'ثمامة', '<span class=\"hlight\">ثمامة.</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (اِخ ) ابن عدی از مردم قریش . صحابی و مهاجر است و درک غزوه ٔ بدر کرده و در خلافت عثمان ولایت صنعای شام داشت . (قاموس الاعلام ).<br /></font></div>'),
(82500, 'ثمامة', '<span class=\"hlight\">ثمامة.</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (اِخ ) ابن اشرف النمیری . پیشوای ثمامیة. فرقه ای از معتزله . او شناختن خدای را ضروری نمیشمرد و ببقاء روح یهود و نصاری و مشرکین قائل نبود و می گفت که آنان را چون بهائم بعث وحشر و نشر و سؤال و بازپرس نیست . (قاموس الاعلام ).<br /></font></div>'),
(82501, 'ثمامة', '<span class=\"hlight\">ثمامة.</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (اِخ ) ابن اُثال الحنفی . رئیس یمامه از مردم قبیله ٔ بنی حنیفه . پیغمبر در سال ششم هجری سلیطبن عمرو را بدعوت با نامه نزد او فرستاد او در یکی از غزوات اسیر مسلمین شد و مدت سه روز رسول صلوات اﷲ علیه به وی تکلیف قبول اسلام کردو وی نپذیرفت و سپس رسول اکرم او را عفو فرمود و اوپس از خلاصی بازگشت و بارغبت و میل خویش مسلمانی گرفت و آنگاه که مسیلمة در یمامه خروج کرد و مردم یمامه به وی گرویدند او از متابعت مسیلمة سرباز زد و گروهی از بنی حنیفه را از پیروی مسیلمة منع کرد و با جیشی که از جانب پیغمبر صلوات اﷲ علیه به تنکیل مسیلمه مأمور گردید دستیاری کرد تا آنکه مسیلمة بهزیمت شد لیکن مردم بنی قیس به کین مسیلمه وی را شهید کردند.<br /></font></div>'),
(82502, 'ثمامة', '<span class=\"hlight\">ثمامة.</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (اِخ ) ابن ابی ثمامة الجذامی . صحابی است .<br /></font></div>'),
(82503, 'ثمامة', '<span class=\"hlight\">ثمامة.</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (اِخ ) صخیرات الثمامة یکی از منازل پیغمبر بود بسوی بدر. نام معروف آن صخیرات الثمام است و بعضی صخیرات الیمام گویند. (معجم البلدان ).<br /></font></div>'),
(82504, 'ثمامة', '<span class=\"hlight\">ثمامة.</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (ع اِ) یک یزبُن . (منتهی الارب ).<br /></font></div>'),
(82505, 'ثمامی', '<span class=\"hlight\">ثمامی .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ص نسبی ) منسوب است به ثمامةبن عبداﷲبن انس . (انساب سمعانی ).<br /></font></div>'),
(82506, 'ثمامیة', '<span class=\"hlight\">ثمامیة.</span> <font color=\"DarkGreen\"><b>[ ث َ می ی َ ]</font></b> (اِخ ) گروهی از معتزله از اتباع ثمامةبن اشرس نمیری . و آنان گویند که افعال عباد را فاعلی نیست و افعال بخودی خودتولید شوند، و معرفت زائیده نظر است . و نظر واجب است پیش از شرع . و یهود و نصارا و مجوس و زنادقه در جهان دیگر خاک شوند و نه به بهشت شوند و نه به دوزخ روند و کودکان و چهارپایان نیز در همین حکم باشند. و استطاعت، سلامت آلات بدن است از آفتها و پیشتر از فعل تواند بود و هر یک از کافران که آفریننده ٔ خود را نشناسد معذور باشد. و معارف بتمامها ضروری است و آدمی را جز اراده فعلی نیست . و ماسوای آن حادثی است بلامحدث . و جهان و ایجاد آن فعلی است که از خدای تعالی طبعاًصادر شده بالایجاب . از این رو قائل بقدم این جهان میباشند. کذا فی شرح المواقف . (کشاف اصطلاحات الفنون ).<br /></font></div>'),
(82507, 'ثمان', '<span class=\"hlight\">ثمان .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع ق ) هشتگان هشتگان .<br /></font></div>'),
(82508, 'ثمان', '<span class=\"hlight\">ثمان .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع عدد، اِ) هشت . ثمانیه . هشت زن .<br /></font></div>'),
(82509, 'ثمان کهره', '<span class=\"hlight\">ثمان کهره .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام محلی است که چنگیزخان آنجا پس از مخالفت با اونک خان طغرل و ظفر بر او در سال <span class=\"hlight\" dir=\"rtl\">٥٩٩</span> هَ . ق . که سال عمرش به <span class=\"hlight\" dir=\"rtl\">٤٩</span> رسیده بود بر تخت خانی برآمد. (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦</span> و <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(82510, 'ثمانون', '<span class=\"hlight\">ثمانون .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع عدد، ص، اِ) هشتاد. ثمانین .<br /></font></div>'),
(82511, 'ثمانون الف', '<span class=\"hlight\">ثمانون الف .</span> <font color=\"DarkGreen\"><b>[ ث َ نو ن َ اَ ]</font></b> (ع عدد مرکب، ص مرکب، اِ مرکب ) هشتاد هزار.<br /></font></div>'),
(82512, 'ثمانی', '<span class=\"hlight\">ثمانی .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) گیاهی است . <BR><font color=\"Blue\">◄</font> هشت . ثمانیة. <BR><font color=\"Blue\">◄</font> نام پشته هاست و از آن رو آنان را ثمانی گویند که هشت قاره اند. <BR><font color=\"Blue\">◄</font> ثمانی نسوة؛ هشت زن .<br /></font></div>'),
(82513, 'ثمانی عشر', '<span class=\"hlight\">ثمانی عشر.</span> <font color=\"DarkGreen\"><b>[ ث َ ع َ ش َ ]</font></b> (ع عدد مرکب، ص مرکب، اِ مرکب ) هژده . هجده .<br /></font></div>'),
(82514, 'ثمانیة', '<span class=\"hlight\">ثمانیة.</span> <font color=\"DarkGreen\"><b>[ ث َ نی ی َ ]</font></b> (اِخ ) فرقه ای از فرق میان عیسی و محمد علیهماالسلام . (ابن الندیم ).<br /></font></div>'),
(82515, 'ثمانیة', '<span class=\"hlight\">ثمانیة.</span> <font color=\"DarkGreen\"><b>[ ث َ ی َ ]</font></b> (ع عدد، ص، اِ) ثمانی . <BR><font color=\"Blue\">◄</font> هشت مرد. <BR><font color=\"Blue\">◄</font> دراهمی که وزن ده عدد آن هشت مثقال بوده است . (مفاتیح العلوم ). <BR><font color=\"Blue\">◄</font> ثمانیة رجال ؛ هشت مرد. <BR><font color=\"Blue\">◄</font> آباء ثمانیه ؛ هشت فلک یعنی افلاک سبعه ٔ سیاره و فلک البروج . <BR><font color=\"Blue\">◄</font> جنات ثمانیه ؛ هشت بهشت . هشت خلد چنانکه حافظ گوید:<br />گدای کوی تو از هشت خلد مستغنی است <br />اسیر عشق تو از هر دوعالم آزاد است .<br /><BR><font color=\"Blue\">◄</font> رذائل ثمانیة، دو طرف افراط و تفریط فضائل اربعه .<br /></font></div>'),
(82516, 'ثمانیة', '<span class=\"hlight\">ثمانیة.</span> <font color=\"DarkGreen\"><b>[ ث َ نی ی َ ]</font></b> (اِخ ) موضعی است . (معجم البلدان از جوهری ).<br /></font></div>'),
(82517, 'ثمانین', '<span class=\"hlight\">ثمانین .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) توراة الثمانین، نامی است ترجمه ٔ یونانی از تورات را و این ترجمه را هفتاد و دو تن (ثعالبی در ثمارالقلوب هشتاد تن آورده است ) یهود مصری بفرمان بطلمیوس محب الاخوة کرده اند. و آنرا توریةالسبعین نیز نامند و این همان ترجمه است که فردوسی بدان نام هفتادکرد داده <span class=\"hlight\">:</span> <br />کنیزک بدادار سوگند خورد<br />بزنار و شماس و هفتادکرد.<br /> <font color=\"Red\">فردوسی .</font><br /> <br />و معتبرترین ترجمه های توراة همین ترجمه است .<br /></font></div>'),
(82518, 'ثمانین', '<span class=\"hlight\">ثمانین .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) شهری است نزدیک جزیره ٔ ابن عمر بالای موصل بدامنه ٔ کوه جودی . گویند پس از قرار گرفتن کشتی نوح بر جودی هشتاد مرد که با وی از کشتی فرود آمدند بدین جای اقامت گزیدند و قریه ای بنا کردند و از اینرو این محل را بنام ثمانین (هشتادان ) خواندند. (مراصد الاطلاع ). شهری است پربرکت و دارای جامع. (انساب سمعانی ). از آن شهر است عمربن ثابت ثمانینی نحوی . (روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٣٢٢</span>).<br /></font></div>'),
(82519, 'ثمانین', '<span class=\"hlight\">ثمانین .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع عدد، ص، اِ) هشتاد. ثمانون . <BR><font color=\"Blue\">◄</font> احمق من صاحب ضأن ثمانین ؛ مثل است و قصه آن است که اعرابی کسری را مژده ای برد و کسری گفت هر چه خواهی درخواه که تراست و او هشتاد میش خواهش کرد.<br /></font></div>'),
(82520, 'ثمانینی', '<span class=\"hlight\">ثمانینی .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) عمربن حضر مکنی به ابوحفص . یکی از مشاهیر محدثین است .<br /></font></div>'),
(82521, 'ثمانینی', '<span class=\"hlight\">ثمانینی .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) در نزد شیعیان مراد از او سید مرتضی علم الهدی است و صاحب روضات (ص <span class=\"hlight\" dir=\"rtl\">٣٨٣</span>) در وجه تلقب او به ثمانینی گوید: و کان یلقب بالثمانینی لانه احرز من کل شی ٔ ثمانین حتی کان عمره ثمانین سنة و ثمانیة أشهر.<br /></font></div>'),
(82522, 'ثمانینی', '<span class=\"hlight\">ثمانینی .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) عمربن ثابت الضریر، مکنی به ابوالقاسم از مردم قریه ٔ ثمانین . یکی از مشاهیر نحات از شاگردان ابن جنی . اورا در نحو و دیگر اقسام ادب عرب تآلیف بسیار است و از جمله شرح برلمعه و بر تصریف ملوکی و کتاب المقید فی النحو. (روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٣٢٢</span>). و وفات وی بسال <span class=\"hlight\" dir=\"rtl\">٤٨٢</span> هَ . ق . بوده است .<br /></font></div>'),
(82523, 'ثمة', '<span class=\"hlight\">ثمة.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ابن لفافة العکی . ابوعبداﷲ. تابعی است .<br /></font></div>'),
(82524, 'ثمة', '<span class=\"hlight\">ثمة.</span> <font color=\"DarkGreen\"><b>[ ث ُم ْ م َ ]</font></b> (ع اِ) یک مشت گیاه . <BR><font color=\"Blue\">◄</font> گیاه یز.<br /></font></div>'),
(82525, 'ثمة', '<span class=\"hlight\">ثمة.</span> <font color=\"DarkGreen\"><b>[ ث ِم ْ م َ ]</font></b> (ع اِ) مرد پیر.<br /></font></div>'),
(82526, 'ثمة', '<span class=\"hlight\">ثمة.</span> <font color=\"DarkGreen\"><b>[ ث َم ْ م َ ت َ ]</font></b> (ع ق ) آنجا. ثم ّ.<br /></font></div>'),
(82527, 'ثمة', '<span class=\"hlight\">ثمة.</span> <font color=\"DarkGreen\"><b>[ ث َم ْ م َ ]</font></b> (ع مص ) مرمت و نیکو کردن .<br /></font></div>'),
(82528, 'ثمثام', '<span class=\"hlight\">ثمثام .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص، اِ) آنکه چون چیزی را بگیرد بشکند.<br /></font></div>'),
(82529, 'ثمثم', '<span class=\"hlight\">ثمثم .</span> <font color=\"DarkGreen\"><b>[ ث َ ث َ ]</font></b> (ع اِ) سگ شکاری .<br /></font></div>'),
(82530, 'ثمثم', '<span class=\"hlight\">ثمثم .</span> <font color=\"DarkGreen\"><b>[ ث َ ث َ ]</font></b> (اِخ ) عبدی . شاعری است .<br /></font></div>'),
(82531, 'ثمثمة', '<span class=\"hlight\">ثمثمة.</span> <font color=\"DarkGreen\"><b>[ ث َ ث َ م َ ]</font></b> (ع مص ) پوشیدن سر آوند. <BR><font color=\"Blue\">◄</font> بازماندن و بحال خود گذاشتن . ترویح قلیل، یقال : ثمثموا بنا ساعة. <BR><font color=\"Blue\">◄</font> نیکو ناکرده شدن کار. <BR><font color=\"Blue\">◄</font> آویختن مشک را از ستون تا شیر در آن ریزند. <BR><font color=\"Blue\">◄</font> دو تا شدن و برگردیدن . یقال : هذا سیف ٌ لایثمثم فَصله ؛ أی لاینثنی اذا ضُرب َ به و لایرتد. (منتهی الارب ).<br /></font></div>'),
(82532, 'ثمج', '<span class=\"hlight\">ثمج .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) با هم آمیختن .<br /></font></div>'),
(82533, 'ثمد', '<span class=\"hlight\">ثمد.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) موضعی است در بطن ملیحة که آن را روضةالثمد نامند. <BR><font color=\"Blue\">◄</font> بطنی است از تیم بنی جریرة. <BR><font color=\"Blue\">◄</font> ابرق الثمدین، نام جائی است . (مراصد الاطلاع ).<br /></font></div>'),
(82534, 'ثمد', '<span class=\"hlight\">ثمد.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) تهی دست گردانیدن از کثرت سؤال سائلان مرد را. <BR><font color=\"Blue\">◄</font> برکشیدن آب مرد را از بس آرامش . <BR><font color=\"Blue\">◄</font> فربه گردیدن .<br /></font></div>'),
(82535, 'ثمد', '<span class=\"hlight\">ثمد.</span> <font color=\"DarkGreen\"><b>[ ث َ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ م َ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ م ِ ]</font></b> (ع اِ)آب اندک بی ماده یا آب باقی در زمین هموار و سخت یا آبی که در سرما ظاهر شود و در گرما خشک . ج، ثِماد.<br /></font></div>'),
(82536, 'ثمدالروم', '<span class=\"hlight\">ثمدالروم .</span> <font color=\"DarkGreen\"><b>[ ث َ دُرْ رو ]</font></b> (اِخ ) محلی است میان شام و مدینه ٔ منوره نزدیک حجر.<br /></font></div>'),
(82537, 'ثمر', '<span class=\"hlight\">ثمر.</span> <font color=\"DarkGreen\"><b>[ ث َ م َ ]</font></b>(ع اِ) آنچه بحاصل آرد نبات و شجر از خوشه و میوه ومانند آن . بر. بار. میوه . فاکهة. حاصل <span class=\"hlight\">:</span> <br />دانش ثمر درخت دین است <br />برشو بدرخت مصطفائی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بهر خدمت هر که بر بندد کمر<br />از درخت معرفت یابد ثمر.<br /> <font color=\"Red\">عطار.</font><br />از باغ نشاط تو بروید گل رامش <br />وز شاخ مراد تو برآید ثمر فتح .<br /> <BR><font color=\"Blue\">◄</font> حاصل . نتیجه . نفع. سود. فایده <span class=\"hlight\">:</span> <br />خراب کردن بتخانه خردکار نبود<br />بدانچه کرده بیابد ملک ثواب و ثمر.<br /> <font color=\"Red\">فرخی .</font><br />و رجوع به تمتع شود.<br /><BR><font color=\"Blue\">◄</font> کناره ٔ زبان . <BR><font color=\"Blue\">◄</font> گره ها و بندهای تازیانه . <BR><font color=\"Blue\">◄</font> اثر. <BR><font color=\"Blue\">◄</font> انواع مال و زر و فرزند. (از منتخب و غیاث اللغه ). ج، ثِمار و ثَمِر. جج، اَثمار، اَثمُر، ثُمُر. (اقرب الموارد).<br /></font></div>'),
(82538, 'ثمر', '<span class=\"hlight\">ثمر.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) وادی است در بادیه .<br /></font></div>'),
(82539, 'ثمر', '<span class=\"hlight\">ثمر.</span> <font color=\"DarkGreen\"><b>[ ث ُ م ُ ]</font></b> (ع اِ) جج ِ ثَمر. (اقرب الموارد).<br /></font></div>'),
(82540, 'ثمر', '<span class=\"hlight\">ثمر.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) میوه آوردن درخت . <BR><font color=\"Blue\">◄</font> پخته شدن میوه . رسیدن میوه . <BR><font color=\"Blue\">◄</font> ثمر مردی ؛ بسیار مال شدن او. <BR><font color=\"Blue\">◄</font> ثمر غنم را؛ گرد کردن برای گوسفندان درختان را (منتهی الارب ).<br /></font></div>'),
(82541, 'ثمر', '<span class=\"hlight\">ثمر.</span> <font color=\"DarkGreen\"><b>[ ث َ م ِ ]</font></b> (ع اِ) ج ِ ثَمَر.<br /></font></div>'),
(82542, 'ثمر', '<span class=\"hlight\">ثمر.</span> <font color=\"DarkGreen\"><b>[ ث َ م ِ ]</font></b> (ع ص ) بسیار: مال ثمر؛ مالی بسیار.<br /></font></div>'),
(82543, 'ثمر', '<span class=\"hlight\">ثمر.</span> <font color=\"DarkGreen\"><b>[ ث َ م َ ]</font></b> (اِخ ) دهی است به یمن .<br /></font></div>'),
(82544, 'ثمرات', '<span class=\"hlight\">ثمرات .</span> <font color=\"DarkGreen\"><b>[ ث َ م َ ]</font></b> (ع اِ) ج ِ ثمرة. درختها. ثمره ها. میوه ها. بارها <span class=\"hlight\">:</span> <br />کشتی حسنات وثمراتش بدرودی .<br /> <font color=\"Red\">منوچهری .</font><br />چون نقاب خاک از چهره بگشاد <font color=\"DarkGreen\"><b>[ دانه ]</font></b> ...لاشک آنرا بپرورانند و از ثمرات آن منفعت گیرند. (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> فوائد، نتائج <span class=\"hlight\">:</span> و فوائد و ثمرات آن او را مهنا شود. (کلیله و دمنه ). هر که طاعت را شعار و دثار خویش کند از ثمرات دنیا و عقبی بهره ور گردد. (کلیله و دمنه ). وانواع تمتع و برخورداری از مواسم جوانی و ثمرات ملک و دولت ارزانی دارد. (کلیله و دمنه ). و یکی از ثمرات نیکوئی آن است که از حسرت فنا و زوال دنیا فارغ توان زیست . (کلیله و دمنه ). و ثمرات و فواید آن را بصحیفه ٔ دل بنگاشتم . (کلیله و دمنه ). و هر چند در ثمرات عفت تأمل بیش کردم رغبت من در اکتساب آن زیادت گشت . (کلیله و دمنه ).<br /></font></div>'),
(82545, 'ثمرت', '<span class=\"hlight\">ثمرت .</span> <font color=\"DarkGreen\"><b>[ ث َ م َ رَ ]</font></b> (ع اِ) رجوع به ثمرة شود.<br /></font></div>'),
(82546, 'ثمرتو', '<span class=\"hlight\">ثمرتو.</span> <font color=\"DarkGreen\"><b>[ ث َ م َ ]</font></b> (اِخ ) مرکز بلوک دول از ولایت ارومیه . (جغرافیای سیاسی ایران تألیف کیهان ).<br /></font></div>'),
(82547, 'ثمردادن', '<span class=\"hlight\">ثمردادن .</span> <font color=\"DarkGreen\"><b>[ ث َ م َ دَ ]</font></b> (مص مرکب ) باردادن . میوه دادن . انتاج کردن .<br /></font></div>'),
(82548, 'ثمره', '<span class=\"hlight\">ثمره .</span> <font color=\"DarkGreen\"><b>[ ث َ م َ رَ ]</font></b> (اِخ ) یا صد کلمه ٔ بطلمیوس . فصوص مقتبس از کتاب بطلمیوس فلکی در احکام نجوم . حاج خلیفه گوید اسم آن بیونانی انطرومطا یعنی صد کلمه است و آن ثمره ٔ کتب چهارگانه آن است که بطلمیوس برای شاگردش سورس تألیف کرد. شروح چند بر ثمره نوشته اند مانند شرح ابی یوسف الاقلیدسی و شرح ابی محمدالشیبانی و شرح ابی سعیدالثمالی و شرح ابن طبیب الجاثلیقی السرخسی و شرح بعض منجمین که چنین آغاز میشود: احمداﷲ حمداً لایبلغ الافکار حده . الخ . آن منجم گوید که آن شرح را از امیر ابی شجاع رستم بن المرزبان در سال <span class=\"hlight\" dir=\"rtl\">٤٨٥</span> هَ . ق . فرا گرفته و در آن بین شروح مذکور جمع کرده است . دیگر شرح علامه ٔ نصیرالدین محمدبن محمد طوسی متوفی بسال <span class=\"hlight\" dir=\"rtl\">٦٧٢</span> هَ . ق . که آن شرح مفید به فارسی است و خواجه آن را برای صاحب دیوان محمدبن شمس الدین تألیف کرده است - انتهی .<br /></font></div>'),
(82549, 'ثمره', '<span class=\"hlight\">ثمره .</span> <font color=\"DarkGreen\"><b>[ ث َ م َ رَ ]</font></b> (ع اِ) میوه . بار <span class=\"hlight\">:</span> <br />مدحت تو شرف دهد ثمره <br />خدمت تو سعادت آرد بار.<br /> <font color=\"Red\">مسعودسعد.</font><br />نکته ٔ حکمتش ثمره ای از شجره ٔ طوبی و بذله ٔ سخنش شکوفه ای از روضه ٔ خلد. (ترجمه ٔ تاریخ یمینی ). <BR><font color=\"Blue\">◄</font> سود. نفع. فایده . جدوی . <BR><font color=\"Blue\">◄</font> حاصل . نتیجه <span class=\"hlight\">:</span> و ثمره ٔ این اعتراف ورضا آن است که احاطه کند زیادتی فضل خدا را. (تاریخ بیهقی ). در این روزگار که به هرات آمدیم <font color=\"DarkGreen\"><b>[ مسعود ]</font></b> وی <font color=\"DarkGreen\"><b>[ آلتونتاش ]</font></b> را بخواندیم تا ما را ببیند و ثمره ٔکردارهای خویش را بیابد. (تاریخ بیهقی ). عاقل ... بداند که خواهش دنیوی ... بجز پشیمانی ثمره ای ندارد. (کلیله و دمنه ). و میخواستیم ثمره ٔ آن از حطام دنیوی هرچه تمامتر بیابد. (کلیله و دمنه ). و ثمره و محمدت آن متوجه شده . (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> در عبارت ذیل ظاهراً بمعنی نخبه آمده است <span class=\"hlight\">:</span> سلطان را از فوائد آن ثمره ٔ غرائب و زبده ٔ حقائب روی نمود. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٧٤</span>). <BR><font color=\"Blue\">◄</font> تمتع. ج، اَثمار. ثَمر. ثِمار. ثمرات . ثُمُر. (زمخشری ). <BR><font color=\"Blue\">◄</font> ثمرةالنخل ؛ بار نخل .<br /></font></div>'),
(82550, 'ثمرکاج', '<span class=\"hlight\">ثمرکاج .</span> <font color=\"DarkGreen\"><b>[ ث َ م َ رِ ]</font></b> (ترکیب اضافی، اِ مرکب ) ارزه .<br /></font></div>'),
(82551, 'ثمط', '<span class=\"hlight\">ثمط.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) گل گشاده یعنی تُنک و آبکی . وتول رقیق . <BR><font color=\"Blue\">◄</font> خمیر بسیار رقیق .<br /></font></div>'),
(82552, 'ثمطلة', '<span class=\"hlight\">ثمطلة.</span> <font color=\"DarkGreen\"><b>[ ث َ طَ ل َ ]</font></b> (ع مص ) مسترخی و فروهشته گردیدن . استرخاء. <BR><font color=\"Blue\">◄</font> ثلمطة.<br /></font></div>'),
(82553, 'ثمعد', '<span class=\"hlight\">ثمعد.</span> <font color=\"DarkGreen\"><b>[ ث َ ع َ ]</font></b> (ع ص ) نیکوروی : غلامی ثَمعد؛ کودکی نیکورو.<br /></font></div>'),
(82554, 'ثمغ', '<span class=\"hlight\">ثمغ.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص )سرکوفتن . سرشکستن . <BR><font color=\"Blue\">◄</font> سپیدی را به سیاهی آمیختن . <BR><font color=\"Blue\">◄</font> ثمغ راس بحنا؛ نیک رنگ کردن سررا به حنا. <BR><font color=\"Blue\">◄</font> ثمغ راس بدهن ؛ روغن مالیدن به سر. <BR><font color=\"Blue\">◄</font> ثمغ ثوب ؛ نیک سرخ کردن جامه .<br /></font></div>'),
(82555, 'ثمغ', '<span class=\"hlight\">ثمغ.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) مالی بود در مدینه عمربن الخطاب را که آنرا وقف کرد و بعضی گویند زمینی بوده است او را و بعضی گفته اند موضعی است به خیبر و بعضی گفته اند اول جائی است که تصدق کرده شد در اسلام . (منتهی الارب ). بعضی از مغاربه آنرا با فتح ثا و میم میخوانند. (مراصد الاطلاع ).<br /></font></div>'),
(82556, 'ثمغه', '<span class=\"hlight\">ثمغه .</span> <font color=\"DarkGreen\"><b>[ ث َ غ َ ]</font></b> (ع اِ) بالای کوه . سرکوه .<br /></font></div>'),
(82557, 'ثمقولس', '<span class=\"hlight\">ثمقولس .</span> (معرب، اِ) بیونانی توتیا را نامند. (فهرست مخزن الادویه ).<br /></font></div>'),
(82558, 'ثمل', '<span class=\"hlight\">ثمل .</span> <font color=\"DarkGreen\"><b>[ ث َ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ م َ ]</font></b> (ع مص ) ثمول . طعام وآب خورانیدن . <BR><font color=\"Blue\">◄</font> خوردن . <BR><font color=\"Blue\">◄</font> غم خواری کردن . <BR><font color=\"Blue\">◄</font> اقامت کردن . درنگی نمودن . <BR><font color=\"Blue\">◄</font> بیهوش شدن . <BR><font color=\"Blue\">◄</font> مست گردیدن .<br /></font></div>'),
(82559, 'ثمل', '<span class=\"hlight\">ثمل .</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (ع اِ) ج ِ ثَمْلَة و ثُمْلَة.<br /></font></div>'),
(82560, 'ثمل', '<span class=\"hlight\">ثمل .</span> <font color=\"DarkGreen\"><b>[ ث َ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ م َ ]</font></b> (ع اِ) سعت عیش .یقال : اختار فلان دارالثمل ؛ ای دارالخفض و المقام .<br /></font></div>'),
(82561, 'ثمل', '<span class=\"hlight\">ثمل .</span> <font color=\"DarkGreen\"><b>[ ث َ م َ ]</font></b> (ع اِ) ج ِ ثَملة.<br /></font></div>'),
(82562, 'ثمل', '<span class=\"hlight\">ثمل .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) اندک از عقل و حزم . ثُملة.<br /></font></div>'),
(82563, 'ثمل', '<span class=\"hlight\">ثمل .</span> <font color=\"DarkGreen\"><b>[ ث َ م َ ]</font></b> (ع اِ) مستی . <BR><font color=\"Blue\">◄</font> سایه .<br /></font></div>'),
(82564, 'ثمل', '<span class=\"hlight\">ثمل .</span> <font color=\"DarkGreen\"><b>[ ث َ م ِ ]</font></b> (ع ص ) مست . <BR><font color=\"Blue\">◄</font> بیهوش . <BR><font color=\"Blue\">◄</font> محب : هو ثمل ُ اًلی کذا؛ یعنی او محب است مر او را.<br /></font></div>'),
(82565, 'ثمل', '<span class=\"hlight\">ثمل .</span> <font color=\"DarkGreen\"><b>[ ث ِ م ِ ]</font></b> (ع ص ) مست . (دهار). <br /></font></div>'),
(82566, 'ثمل', '<span class=\"hlight\">ثمل .</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (ع اِ) ج ِ ثُملة.<br /></font></div>'),
(82567, 'ثملة', '<span class=\"hlight\">ثملة.</span> <font color=\"DarkGreen\"><b>[ ث َ م َ ل َ ]</font></b> (ع اِ) باقی آب در تک حوض یا خنور و مانند آن . <BR><font color=\"Blue\">◄</font> باقی خرما در خنور. <BR><font color=\"Blue\">◄</font> خرقه ٔ حیض . ج، ثمل . <BR><font color=\"Blue\">◄</font> پشم پاره ای که بدان روغن بر مشک و شتر مالند.<br /></font></div>'),
(82568, 'ثملة', '<span class=\"hlight\">ثملة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ]</font></b> (ع اِ) ثُمل . رجوع به ثُمل شود. <BR><font color=\"Blue\">◄</font> گلی که از تک چاه برآید. <BR><font color=\"Blue\">◄</font> پشم پاره ای که بدان قطران بر شتر و روغن بمشک مالند. <BR><font color=\"Blue\">◄</font> باقی آب در تک خنور و حوض . <BR><font color=\"Blue\">◄</font> دانه و پست و خرما در خنور، ج، ثُمل .<br /></font></div>'),
(82569, 'ثملة', '<span class=\"hlight\">ثملة.</span> <font color=\"DarkGreen\"><b>[ ث ُ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ل َ ]</font></b> (ع اِ) باقی آب در تک خنور و حوض . <BR><font color=\"Blue\">◄</font> باقی دانه و پست و خرما در خنور. ج، ثُمل .<br /></font></div>'),
(82570, 'ثمم', '<span class=\"hlight\">ثمم .</span> <font color=\"DarkGreen\"><b>[ ث ُ م ُ ]</font></b> (ع اِ) ج ِ ثموم .<br /></font></div>'),
(82571, 'ثمن', '<span class=\"hlight\">ثمن .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) هشتم هفت کس شدن . <BR><font color=\"Blue\">◄</font> هشت گردانیدن . <BR><font color=\"Blue\">◄</font> هشت یک گرفتن . هشت یک مال ستدن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> بها کردن متاع .<br /></font></div>'),
(82572, 'ثمن', '<span class=\"hlight\">ثمن .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) هشت یک . <BR><font color=\"Blue\">◄</font> سه تسو. <BR><font color=\"Blue\">◄</font> هشتم حصه . (لغت نامه ٔ مقامات حریری ): ثمن الدایره ؛ هشت یک دایره . ج، اثمان .<br /></font></div>'),
(82573, 'ثمن', '<span class=\"hlight\">ثمن .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع مص ) هشت یک گرفتن . هشتم شدن .<br /></font></div>'),
(82574, 'ثمن', '<span class=\"hlight\">ثمن .</span> <font color=\"DarkGreen\"><b>[ ث َ م َ ]</font></b> (ع اِ) بها. ارز.نرخ . اخش . قیمت . مقابل ِ مثمن و صرف . ج، اثمان . اَثمُن . اَثمِنة <span class=\"hlight\">:</span> در میان اهل دیلم غلائی ظاهر شد بسبب تردد لشکر و تفحص از مواضع غلات و اقوات و تاراج کردن آن بی عوضی و ثمنی . (ترجمه ٔ تاریخ یمینی ).<br />هم ز لطف و جوش جان با ثمن <br />پرده ای بر روی جان شد شخص تن .<br /> <font color=\"Red\">مولوی .</font><br />تو وکیلم باش و نیمی بهر من <br />مشتری شو قبض کن از من ثمن .<br /> <font color=\"Red\">مولوی .</font><br />گوهر بود کش آب زیادت کند ثمن <br />گوهر بود که آتشش افزون کند بها.<br />هر آنکه کنج قناعت بگنج دنیا داد<br />فروخت یوسف مصری بکمترین ثمنی .<br /> <font color=\"Red\">حافظ.</font><br />ثمن، بفتحتین هو ما یلزم بالبیع و ان لم یقّوم به . کذا فی جامع الرموز. فالقیمة ما قوّم به مقوم . والثمن قد یکون مساویاً للقیمة و قد یکون زائداً منه و قد یکون ناقصاً عنه و یجی ٔ ایضاً فی لفظ المال . و الحاصل ان ّ ما یقدّره الاقدان بکونه عوضاً للمبیعفی عقدالبیع یسمی ثَمناً و ما قدره اهل السوق و قرروه فیما بینهم و روّجوه فی معاملاتهم یسمّی قیمة و یقال له فی الفارسیة نرخ بازار. و فی البرجندی، فی فصل الصرف : قال الفقراء الثمن عندالعرب ما یکون دیناً فی الذّمة و الدراهم و الدنانیر لاتستحق بالعقد الا دینا فی الذّمة و العرض لایستحق بالعقد الا عیناً فکانت مبیعة فی کل حال و المکیل و الموزون یستحق بالعقد تارةًعیناً و تارةً دیناً. فان کان معیّنا فی العقد کان مبیعاً و ان لم یکن معیناً و صحبه الباء و قابله مبیع فهو ثمن . و نوع آخر و هو سلعة فی الاصل کالفلوس فان کانت رائجة کانت ثَمَنا و ان کانت کاسدة کانت سلعة و الثَمَن اذا اطلق یراد به الدراهم و الدنانیر. (کشاف اصطلاحات الفنون ).<br /></font></div>'),
(82575, 'ثمن', '<span class=\"hlight\">ثمن .</span> <font color=\"DarkGreen\"><b>[ ث ُ <span class=\"hlight\" dir=\"rtl\">/</span> ث ُ م ُ ]</font></b> (ع اِ) هشت یک . ج، اَثمان .<br /></font></div>'),
(82576, 'ثمن', '<span class=\"hlight\">ثمن .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع اِ) شب هشتم از تشنگی هشت روزه ٔ شتر.<br /></font></div>'),
(82577, 'ثمنش', '<span class=\"hlight\">ثمنش .</span> <font color=\"DarkGreen\"><b>[ ث ُ م ِ ن ُ ]</font></b> (معرب، اِ) گیاه ضعیف . <BR><font color=\"Blue\">◄</font> هرچه از نباتات ما بین درخت و گیاه باشد. این لفظ مأخوذ از یونانی است .<br /></font></div>'),
(82578, 'ثمنیة', '<span class=\"hlight\">ثمنیة.</span> <font color=\"DarkGreen\"><b>[ ث ُ نی ی َ ]</font></b> (ع اِ) هشت یک .<br /></font></div>'),
(82579, 'ثموت', '<span class=\"hlight\">ثموت .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص ) آنکه گاه آرَمِش حدث کند.<br /></font></div>'),
(82580, 'ثمود', '<span class=\"hlight\">ثمود.</span> <font color=\"DarkGreen\"><b>[ ث َ <span class=\"hlight\" dir=\"rtl\">/</span> ث ُ ]</font></b> (اِخ ) نام یکی از قبائل قدیم عرب . مسکن این قبیله در موصل میان حجازو شام بوده و در قرآن کریم نام این قبیله مانند قبیله ٔ عاد در ردیف جدیس <font color=\"DarkGreen\"><b>[ کذا ]</font></b> و طسم بیامده است و چنانکه انساب شناسان عرب گویند این قوم از فرزندان ثمودبن جاثربن ارم بن سام بن نوح علیه السلام باشند قومی بودند روستائی و قری و شهرها داشتند از سنگهای جسیم برآورده و مصانعی در صخره ها حفر کرده . و بت پرستیدندی و خدای تعالی صالح پیغامبر را بدانان فرستاد و او مردمان را به خدا خواند و به اعجاز شتری ماده از تخته سنگی برآورد قوم ثمود در عبادت بتان اصرار ورزیدند و در آخر آن شتر ماده را پی کردند و در این وقت عذاب صیحه بر ایشان فرود آمد و آن آوازی بود سخت مدهش از جانب آسمان که دلهای آنان در سینه ها ببرید و بمردند وآنگاه که رسول ما صلوات اﷲ علیه با اصحاب از نزدیکی زمینهای ثمود میگذشت مسلمانان را از درآمدن بدان ملک و آشامیدن آب آن منع فرمود. (قاموس الاعلام ). صاحب مجمل التواریخ گوید: ارم بن سام را هفت پسر بودند نام ایشان عاد. ثمود. صحار. جاسم . وبار. طسم . جدیس . و اینان را عرب العاربه خوانند... ثمود... با فرزندان و جماعت <font color=\"DarkGreen\"><b>[ خویش ]</font></b> میان شام و حجاز آرام گرفت جائی که آنراحجر خوانند و خدای تعالی صالح پیغامبر را بدین جماعت فرستاد... <span class=\"hlight\">:</span> <br />یفنیهم الملک المظفرمثل ما<br />فنیت ثمود فی الزمان الغابر.<br /> <font color=\"Red\">(منسوب به ابوعلی سینا).</font><br /> <br />ای از دل تو خدای ایمان برده <br />کفرت سبق از ثمود و هامان برده ...<br /> <font color=\"Red\">فخرالدین محمد سرخسی ؟</font><br />این همان چشمه ٔ خورشید جهان افروز است <br />که همی تافت بر آرامگه عادو ثمود.<br /> <font color=\"Red\">سعدی .</font><br />قصه ٔ عاد و ثمود از بهر چیست <br />تا بدانی کانبیارا نازکیست .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(82581, 'ثمود', '<span class=\"hlight\">ثمود.</span> (اِخ ) ابن الندیم گوید ثمود نام کتابی است در کیمیا و صنعت و مؤلف آن حکما بوده اند .<br /></font></div>'),
(82582, 'ثمول', '<span class=\"hlight\">ثمول .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع مص ) ثَمْل . ثَمَل . طعام وآب خورانیدن . <BR><font color=\"Blue\">◄</font> غمخواری کردن . <BR><font color=\"Blue\">◄</font> اقامت کردن . و درنگی کردن . <BR><font color=\"Blue\">◄</font> نوشیدن شراب پیش از آنکه طعامی خورده باشند. (منتهی الارب )<br /></font></div>'),
(82583, 'ثموم', '<span class=\"hlight\">ثموم .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص ) نعت فاعلی از ثَم ّ. <BR><font color=\"Blue\">◄</font> شاة ثموم ؛ گوسفند که گیاه را از بن برکند. ج، ثُمُم .<br /></font></div>'),
(82584, 'ثمومة', '<span class=\"hlight\">ثمومة.</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (ع مص ) اثمام . گداخته شدن .<br /></font></div>'),
(82585, 'ثمیر', '<span class=\"hlight\">ثمیر.</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (اِخ ) محدث است و او جد محمدبن عبدالرحیم است .<br /></font></div>'),
(82586, 'ثمیر', '<span class=\"hlight\">ثمیر.</span> <font color=\"DarkGreen\"><b>[ث َ ]</font></b> (ع اِ) شیری که مسکه ٔ آن ظاهر نشده یا شیری که مسکه ٔ آن ظاهر گردیده باشد. <BR><font color=\"Blue\">◄</font> مسکه که ظاهر شود بر ماست پیش از جمع شدن . <BR><font color=\"Blue\">◄</font> شب ماهتاب . (دهار). <BR><font color=\"Blue\">◄</font> میوه دار. (غیاث اللغة).<br /></font></div>'),
(82587, 'ثمیری', '<span class=\"hlight\">ثمیری .</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (ع ص نسبی ) نسبتی است به جد، یعنی محمدبن عبدالرحیم بن مصری الثمیری . (سمعانی ).<br /></font></div>'),
(82588, 'ثمیغه', '<span class=\"hlight\">ثمیغه .</span> <font color=\"DarkGreen\"><b>[ ث َ غ َ ]</font></b> (ع اِ) طعام رقیق و چرب . <BR><font color=\"Blue\">◄</font> زخم در گوشت سر. <BR><font color=\"Blue\">◄</font> زمینی است نمناک .<br /></font></div>'),
(82589, 'ثمیل', '<span class=\"hlight\">ثمیل .</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b> (اِخ ) ابن عبداﷲ اشعری . تابعی است .<br /></font></div>'),
(82590, 'ثمیل', '<span class=\"hlight\">ثمیل .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) شیر ترش . <BR><font color=\"Blue\">◄</font> آب دست دان . <BR><font color=\"Blue\">◄</font> ج تمیلة. رجوع به تمیلة شود.<br /></font></div>'),
(82591, 'ثمیلة', '<span class=\"hlight\">ثمیلة.</span> <font color=\"DarkGreen\"><b>[ث َ ل َ ]</font></b> (ع اِ) بقیه ٔ آب و طعام در شکم . <BR><font color=\"Blue\">◄</font> آب اندک باقی مانده در تک حوض یا مشک . <BR><font color=\"Blue\">◄</font> جای آب و طعام در شکم . <BR><font color=\"Blue\">◄</font> باقی دانه و پست و خرما در خنور. <BR><font color=\"Blue\">◄</font> باقی مانده ٔ هر چیز. <BR><font color=\"Blue\">◄</font> خانه ای که در آن فرش و قماش باشد. <BR><font color=\"Blue\">◄</font> مرغی است . <BR><font color=\"Blue\">◄</font> دیوارمانندی که ازسنگ سازند تا آب را منع کند. <BR><font color=\"Blue\">◄</font> آن طعام که پیش از نوشیدن شراب خورند. <BR><font color=\"Blue\">◄</font> (مص ) آشامیدن شراب که پیش از آن طعامی نخورده باشند. <BR><font color=\"Blue\">◄</font> (اِ) گل که از چاه برآرند. ج، ثمیل و ثمایل .<br /></font></div>'),
(82592, 'ثمیمة', '<span class=\"hlight\">ثمیمة.</span> <font color=\"DarkGreen\"><b>[ ث َ م َ ]</font></b> (ع اِ) ابریق سربسته .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(82593, 'ثمین', '<span class=\"hlight\">ثمین .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص ) گران . گران بها. پرقیمت . بیش بها.پربها. بهاور. بهائی . قیمتی . گران قیمت <span class=\"hlight\">:</span> <br />تا هر دو تهنیت را در پیش او بریم <br />صافی تر و شریف تر از لؤلؤ ثمین .<br /> <font color=\"Red\">فرخی .</font><br />آنکو نکو خواهد ترا گر سنگ بر گیرد ز ره <br />از دولت تو گردد آن در دست او در ثمین .<br /> <font color=\"Red\">فرخی .</font><br />عادتی دارد بی عیب تر از صورت حور<br />صورتی دارد پاکیزه تر از در ثمین .<br /> <font color=\"Red\">فرخی .</font><br />بحرم و کانم چون بحر و چو کان حاصل من <br />خلق را دُر ثمین و گهر پیش بهاست .<br /> <font color=\"Red\">مسعودسعد.</font><br />ز بسکه کند دو زلف و ز بسکه راندم اشک <br />یکی چو دُرِّ ثمین و یکی چو مشک ختن .<br /> <font color=\"Red\">مسعودسعد (دیوان چ رشید یاسمی <span class=\"hlight\" dir=\"rtl\">٣٨٨</span>).</font><br />اکنون شمتی از محاسن عدل که پادشاهان را ثمین ترین حلیتی و نفیس ترین موهبتی است یاد کرده شود. (کلیله و دمنه ). مهابت خاموشی ملک را... زیور ثمین است . (کلیله و دمنه ). پانصد غلام از ممالیک خاص نزدیک مجلس بایستادند با قباهای رومی و منطقه های زر مرصع بجواهر ثمین . (ترجمه ٔ تاریخ یمینی ). بخلعتهای ثمین و بخششهاء بی اندازه مشرف گردانید.(ترجمه ٔ تاریخ یمینی ).<br />هیچ عاقل افکند دُرّ ثمین <br />در میان مستراح پر چمین .<br /> <font color=\"Red\">مولوی .</font><br />هم چنان کرد و هم اندر دم زمین <br />سبز گشت از سنبل وحب ثمین .<br /> <font color=\"Red\">مولوی .</font><br />آنکه گر خواهد همه خاک زمین <br />سر بسر زر گردد و دُرّثمین .<br /> <font color=\"Red\">مولوی .</font><br />او همین گفت و همه میران همین <br />هر یکی را خلعتی داد او ثمین .<br /> <font color=\"Red\">مولوی .</font><br />شبه فروش چه داند بهای در ثمین .<br /> <font color=\"Red\">سعدی .</font><br />ابلهی را دیدم سمین خلعتی ثمین در بر. (گلستان سعدی ).<br /><BR><font color=\"Blue\">◄</font> پرمایه . <BR><font color=\"Blue\">◄</font> نفیس . نفیسه . <BR><font color=\"Blue\">◄</font> عزیز. <BR><font color=\"Blue\">◄</font> (اِ) هشت یک . هشتم حصه .<br /></font></div>'),
(82594, 'ثمینة', '<span class=\"hlight\">ثمینة.</span> <font color=\"DarkGreen\"><b>[ ث َ ن َ ]</font></b> (ع ص ) تأنیث ثمین .چیزی گران قیمت . <BR><font color=\"Blue\">◄</font> احجار ثمینه ؛ جواهر.<br /></font></div>'),
(82595, 'ثمینة', '<span class=\"hlight\">ثمینة.</span> <font color=\"DarkGreen\"><b>[ ث َ ن َ ]</font></b> (اِخ ) شهری است یا زمینی است .<br /></font></div>'),
(82596, 'ثن', '<span class=\"hlight\">ثن .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (پسوند) مزید مؤخریست در بعض امکنه و بیشتر در ماورأالنهر مثل : کناثن، و اما مزید مؤخر دیگری که نیز درآخر ثن دارد از این قبیل نیست مانند: کوخمیثن، اسمیثن، انشمیثن، فرزامیثن، رامیثن، زامیثن، خشمیثن، اردخشمیثن، ارتخشمیثن، خمیثن و زندرامیثن، چه مزید مؤخر آنها (میثن ) صورتی از (میهن ) بمعنی جای باش است .<br /></font></div>'),
(82597, 'ثن', '<span class=\"hlight\">ثن .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع اِ) علف خشک بر هم افتاده و بسیار. <BR><font color=\"Blue\">◄</font> حشیش خشک . <BR><font color=\"Blue\">◄</font> خشکی گیاه . <BR><font color=\"Blue\">◄</font> چوب سیاه .<br /></font></div>'),
(82598, 'ثنا کردن', '<span class=\"hlight\">ثنا کردن .</span> <font color=\"DarkGreen\"><b>[ ث َ ک َ دَ ]</font></b> (مص مرکب ) اثناء، تثنیه . حمد و ستایش کردن <span class=\"hlight\">:</span> <br />ثنا میکنم ایزد پاک را<br />ثریاده طارم تاک را.<br /><font color=\"Red\">ظهوری .</font><br /></font></div>'),
(82599, 'ثناخوان', '<span class=\"hlight\">ثناخوان .</span> <font color=\"DarkGreen\"><b>[ ث َ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) مدّاح <span class=\"hlight\">:</span> <br />گر چه دوریم از بساط قرب همت دور نیست <br />بنده ٔ شاه شمائیم و ثناخوان شما.<br /> <font color=\"Red\">حافظ.</font><br />صدثنا خوان که یکتن است چو او<br />بزم او را دو صد ثناخوان باد.<br /></font></div>'),
(82600, 'ثناخواندن', '<span class=\"hlight\">ثناخواندن .</span> <font color=\"DarkGreen\"><b>[ ث َ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا دَ ]</font></b> (مص مرکب ) مدح کردن <span class=\"hlight\">:</span> <br />از آن پس ثنا خواند بر شهریار<br />چنان چون بود درخور نامدار.<br /> <font color=\"Red\">فردوسی .</font><br />همانکه آنش ثنا خواند اینش لعنت کرد<br />بسوی آن حجری بود و سوی این گهری .<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(82601, 'ثناخوانی', '<span class=\"hlight\">ثناخوانی .</span> <font color=\"DarkGreen\"><b>[ ث َ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (حامص مرکب ) مدح <span class=\"hlight\">:</span> <br />بقای مجلس او باد و سوزنی او را<br />بده زبان شده چون سوسن از ثناخوانی .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(82602, 'ثناخواه', '<span class=\"hlight\">ثناخواه .</span> <font color=\"DarkGreen\"><b>[ ث َ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) مدح جوی <span class=\"hlight\">:</span> <br />دل اختر از جان هواخواه اوست <br />زبان زمانه ثناخواه اوست .<br /><font color=\"Red\">اسدی .</font><br /></font></div>'),
(82603, 'ثنادی', '<span class=\"hlight\">ثنادی .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) ج ِ ثُندوة.<br /></font></div>'),
(82604, 'ثناسرای', '<span class=\"hlight\">ثناسرای .</span> <font color=\"DarkGreen\"><b>[ ث َ س َ ]</font></b> (نف مرکب ) مدح گو. ستایشگر <span class=\"hlight\">:</span> <br />گاه به الحان ثناسرای تو باشم <br />گاه غزل گوی بر بتان پریوش .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(82605, 'ثنان', '<span class=\"hlight\">ثنان .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع اِ) گیاه بسیار و بهم پیچیده .<br /></font></div>'),
(82606, 'ثنان', '<span class=\"hlight\">ثنان .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (اِخ ) موضعی است .<br /></font></div>'),
(82607, 'ثنانیوش', '<span class=\"hlight\">ثنانیوش .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (نف مرکب ) مدح شنو. دعاشنو <span class=\"hlight\">:</span> <br />ثنانیوش و عطابخش باش از پی آنک <br />ثنانیوش و عطابخش راست طول بقا.<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(82608, 'ثناگر', '<span class=\"hlight\">ثناگر.</span> <font color=\"DarkGreen\"><b>[ ث َ گ َ ]</font></b> (ص مرکب ) مدّاح . ستایشگر <span class=\"hlight\">:</span> <br />لبش پر ز خنده دلش پر ز کام <br />سپهرش ثناگر ستاره غلام .<br /> <font color=\"Red\">فردوسی .</font><br />مردی باشم ثناگر و شاعر<br />بندی باشد محل و مقدارم !<br /><font color=\"Red\">مسعودسعد.</font><br />خلقی ثناگرند مرا در هجای او<br />بر خود زبان خلق ثناگر همی کنم .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(82609, 'ثناگستر', '<span class=\"hlight\">ثناگستر.</span> <font color=\"DarkGreen\"><b>[ ث َ گ ُ ت َ ]</font></b> (نف مرکب ) مدح گستر. مدّاح <span class=\"hlight\">:</span> <br />گمان برم که من اندر زمین همان شجرم <br />شجر که دید ثناگستر و ستایش گر.<br /><font color=\"Red\">فرخی .</font><br />آن ثناگستر منم کاندر همه گیتی بحق <br />عزّ و ناز از مدحهای شاه حق گستر گرفت .<br /><font color=\"Red\">مسعودسعد.</font><br /></font></div>'),
(82610, 'ثناگستردن', '<span class=\"hlight\">ثناگستردن .</span> <font color=\"DarkGreen\"><b>[ ث َ گ ُ ت َ دَ ]</font></b> (مص مرکب ) مدح گفتن <span class=\"hlight\">:</span> <br />تا سزا باشد ثناگستردن آل رسول <br />بنده در عالم بنام تو ثناگستر سزد.<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(82611, 'ثناگستری', '<span class=\"hlight\">ثناگستری .</span> <font color=\"DarkGreen\"><b>[ ث َ گ ُ ت َ ]</font></b> (حامص مرکب ) مدّاحی . ستایشگری .<br /></font></div>'),
(82612, 'ثناگستریدن', '<span class=\"hlight\">ثناگستریدن .</span> <font color=\"DarkGreen\"><b>[ ث َ گ ُ ت َ دَ ]</font></b> (مص مرکب ) ثنا گفتن <span class=\"hlight\">:</span> <br />زمین بوس کرد و ثنا گسترید<br />بدانسان که او را سزاوار دید.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(82613, 'ثناگفتن', '<span class=\"hlight\">ثناگفتن .</span> <font color=\"DarkGreen\"><b>[ ث َ گ ُ ت َ ]</font></b> (مص مرکب ) مدح گفتن . ستایش کردن . بستودن . حمد گفتن . مدح کردن . اثناء. استثناء <span class=\"hlight\">:</span> <br />منت با این همه ثنا گویم <br />در جهان تا همی ثناباشد.<br /><font color=\"Red\">مسعودسعد.</font><br /></font></div>'),
(82614, 'ثناگو', '<span class=\"hlight\">ثناگو.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (نف مرکب ) ثناگوی . مداح . دعاگو. ستایشگر. حامد. ستاینده <span class=\"hlight\">:</span> <br />من ثناگوی بزرگانم ومداح ملوک <br />خاصه مدحتگر آن راد عطابخش کریم .<br /> <font color=\"Red\">فرخی .</font><br />نه بیهده سخنش در میان خلق افتاد<br />نه خیرخیر ثنا گوی او شد آن لشکر.<br /> <font color=\"Red\">فرخی .</font><br />دیوان شاعران مقدم بر این گو است <br />دیوان شاعران ثناگوی رو بیار.<br /> <font color=\"Red\">فرخی .</font><br />سوزنی پیر ثناگوی تو است <br />چو کند مدح تو انشاء و نشید.<br /> <font color=\"Red\">سوزنی .</font><br />این ثناگوی تو که سینه ٔ خود<br />صدف لؤلؤ حکم دارد.<br /> <font color=\"Red\">سوزنی .</font><br />ثنای تو ناگفته غبنی است فاحش <br />مبادا ثناگوی صدر تو مغبون .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(82615, 'ثناگوینده', '<span class=\"hlight\">ثناگوینده .</span> <font color=\"DarkGreen\"><b>[ ث َ ی َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف مرکب ) ثناگوینده بر محسن . شاکر و شکور. (منتهی الارب ).<br /></font></div>'),
(82616, 'ثنایا', '<span class=\"hlight\">ثنایا.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) ج ِ ثَنیة. پشته ها. راههای سربالا در کوه که دشوار باشد؛ فلان طلاّع الثنایا؛ اذا کان سامیاً لمعالی الامور. <BR><font color=\"Blue\">◄</font> چهار دندان پیشین دو از فوق و دو از تحت . <BR><font color=\"Blue\">◄</font> شهیدانی که استثنا کرد ایشان را خدای تعالی از صعقه . حیث قال <span class=\"hlight\">:</span> و نفخ فی الصور فصعق من فی السموات و من فی الأرض الاّ من شاء اﷲ. (قرآن <span class=\"hlight\" dir=\"rtl\">٦٨/٣٩</span>).<br /></font></div>'),
(82617, 'ثنایة', '<span class=\"hlight\">ثنایة.</span> <font color=\"DarkGreen\"><b>[ث ِ ی َ ]</font></b> (ع اِ) رسن از ابریشم یا از موی و جز آن .<br /></font></div>'),
(82618, 'ثنة', '<span class=\"hlight\">ثنة.</span> <font color=\"DarkGreen\"><b>[ ث ُن ْ ن َ ]</font></b> (ع اِ) زهار. <BR><font color=\"Blue\">◄</font> میان ناف و زهار. <BR><font color=\"Blue\">◄</font> اندرون شکم مردم . <BR><font color=\"Blue\">◄</font> مویهای دراز که بر تندی پاشنه ٔ اسب باشد. <BR><font color=\"Blue\">◄</font> وسط مردم و غیر آن . <BR><font color=\"Blue\">◄</font> ثنةالبطن ؛ زیر ناف تا فرج از درون شکم . <BR><font color=\"Blue\">◄</font> موضعی در رحم که جنین در آن جای دارد. ج، ثُنن .<br /></font></div>'),
(82619, 'ثنت', '<span class=\"hlight\">ثنت .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) ثنت شفه ؛ فروهشته گردیدن و خون آلود شدن لب . <BR><font color=\"Blue\">◄</font> ثنت لثه ؛ خون آمدن از لثه . <BR><font color=\"Blue\">◄</font> ثنت لحم ؛ بوی گرفتن گوشت .<br /></font></div>'),
(82620, 'ثنت', '<span class=\"hlight\">ثنت .</span> <font color=\"DarkGreen\"><b>[ ث َ ن ِ ]</font></b> (ع ص، اِ) گوشت گندیده .<br /></font></div>'),
(82621, 'ثنتان', '<span class=\"hlight\">ثنتان .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع عدد، اِ) تأنیث اثنان . دو. <BR><font color=\"Blue\">◄</font> دو زن . ثنتان ثنتان ؛ دو دو.<br /></font></div>'),
(82622, 'ثنتایة', '<span class=\"hlight\">ثنتایة.</span> <font color=\"DarkGreen\"><b>[ث ِ ی َ ]</font></b> (ع ص ) مردی ثنتایه ؛ مردی بدخوی و بدزبان .<br /></font></div>'),
(82623, 'ثنتة', '<span class=\"hlight\">ثنتة.</span> <font color=\"DarkGreen\"><b>[ ث َ ن ِ ت َ ]</font></b> (ع ص ) نعت است از ثَنَت . <BR><font color=\"Blue\">◄</font> لثة. ثَنتَة. لثه ٔ فروهشته و خون آلود گردیده .<br /></font></div>'),
(82624, 'ثنتل', '<span class=\"hlight\">ثنتل .</span> <font color=\"DarkGreen\"><b>[ ث ِ ت ِ ]</font></b> (ع ص ) کوتاه بالا. قصیرالقامة.<br /></font></div>'),
(82625, 'ثنتلة', '<span class=\"hlight\">ثنتلة.</span> <font color=\"DarkGreen\"><b>[ ث َ ت َ ل َ ]</font></b> (ع مص ) پلید گردیدن پس از نظافت .<br /></font></div>'),
(82626, 'ثنتلة', '<span class=\"hlight\">ثنتلة.</span> <font color=\"DarkGreen\"><b>[ ث َ ت َ ل َ ]</font></b> (ع ص، اِ) بیضه ٔ گنده . تخم مرغ گندیده .<br /></font></div>'),
(82627, 'ثنتین', '<span class=\"hlight\">ثنتین .</span> <font color=\"DarkGreen\"><b>[ ث ِ ت َ ]</font></b> (ع عدد، اِ) تأنیث اِثنان . <BR><font color=\"Blue\">◄</font> دو. <BR><font color=\"Blue\">◄</font> دو زن .<br /></font></div>'),
(82628, 'ثنط', '<span class=\"hlight\">ثنط.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) کفانیدن، شَق ّ.<br /></font></div>'),
(82629, 'ثنطب', '<span class=\"hlight\">ثنطب .</span> <font color=\"DarkGreen\"><b>[ ث ُ طُ ]</font></b> (ع اِ) کارد قفص گران . کارد قفس سازان . (منتهی الارب ).<br /></font></div>'),
(82630, 'ثنن', '<span class=\"hlight\">ثنن .</span> <font color=\"DarkGreen\"><b>[ ث ُ ن َ ]</font></b> (ع اِ) ج ِ ثُنة.<br /></font></div>'),
(82631, 'ثنوی', '<span class=\"hlight\">ثنوی .</span> <font color=\"DarkGreen\"><b>[ ث َ ن َ وی ی ]</font></b> (ع ص نسبی ) منسوب است به اثنان یا اثنی عشر در صورتی که علم باشد. <BR><font color=\"Blue\">◄</font> منسوب به ثنویة قائلین بدو اصل <span class=\"hlight\">:</span> <br />کسی که با تو دم از اتحاد و صدق نزد<br />اگر چه هست موحد یکی است با ثنوی .<br /> <font color=\"Red\">سوزنی .</font><br />از ثنای توبسی بی خبر است <br />هم چنان چون ثنوی از توحید<br /> <font color=\"Red\">سوزنی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ثنوی زاده </span> ؛ کسی که پدر یا پدر و مادر ثنوی دارد <span class=\"hlight\">:</span> <br />ز جمله ٔ ثنوی زادگانش می شمرند<br />اگر بود نه عجب هم عجب اگر نبود<br />موحدیست گذشتن ز ملّت ثنوی <br />ولیکن از ثنوی زادگی گذر نبود.<br /> <font color=\"Red\">سوزنی .</font><br />رجوع به زندیق شود.<br /></font></div>'),
(82632, 'ثنوی', '<span class=\"hlight\">ثنوی .</span> <font color=\"DarkGreen\"><b>[ ث َوا ]</font></b> (ع اِ) سروپای شتر قمار. <BR><font color=\"Blue\">◄</font> اسم است استثنا را، و هر چه که آن را استثنا کنند. ثُنیا.<br /></font></div>'),
(82633, 'ثنویة', '<span class=\"hlight\">ثنویة.</span> <font color=\"DarkGreen\"><b>[ ث َ ن َ وی ی َ ]</font></b> (ع ص نسبی ) تأنیث ثَنَوی . قول به دو اصل . <BR><font color=\"Blue\">◄</font> (مص جعلی، اِ) شرک . <BR><font color=\"Blue\">◄</font> گروهی که به دو خدا قائلند. صاحب کشاف اصطلاحات الفنون گوید: فرقه ای از کفار هستند که به دو آفریدگار قائل شده اند. میگویند ما در این جهان نیکیها و بدیهای بسیاری مشاهده میکنیم . و بالضروره ذات واحدی نمیتواند هم نیک باشد و هم بد. پس باید هر یک از خیر و شر را فاعلی علی حده باشد. و البته این سخن در برابر دلائلی که بر وحدانیت حق موجود است باطل خواهد بود و <font color=\"DarkGreen\"><b>[ کذا ]</font></b> قولهم الواحد لا یکون خیرا شریرا بمعنی انّه یوجد خیراً کثیراً و شراً کثیراً. فرقه ٔ مانویّه و دیصانیه از ثنویّه قائل شده اند بر اینکه فاعل خیر نور و فاعل شر ظلمت است . و تباهی این گفتار نیز بسی روشن است . زیرا نور و ظلمت هر دو از اعراض میباشند. و از این رو قدم جسم لازم آید. و در آن صورت آفریدگار بایستی نیازمند به جسم باشد. و گویا این فرقه در این گفتار معنی دیگری اراده کرده اند که غیر از معنی متعارف است . چه آنها میگویند نور زنده و دانا و توانا و شنونده و بیننده است . گروه مجوس از این طایفه گویند فاعل خیر یزدان و فاعل شر اهریمن است . و از اهریمن شیطان مقصودشان باشد. چنانکه در شرح مواقف بیان شد در مبحث توحید. و در انسان کامل در باب سر ادیان گوید طایفه ای بسوی پرستش نور و ظلمت رفته اند و گفته اند که ما اختصاص دادن پرستش را به هر چه که منسوب به نور باشد معقول تر می یابیم و از این رو بپرستش مطلق نور پرداختند و نام نور را یزدان نهاده و به اهریمن نام ظلمت دادند. و این جماعت را ثنویّه گفتند. وآنان خدای تعالی را من حیث هو هو میپرستند. زیرا اوتعالی و تقدّس بنفسه جمع اضداد نموده و شمول مراتب حقیت و خلقیت را جهة خود احراز فرموده است . و در دو وصف بدو حکم و در دو جهان بدو صفت خود را ظاهر ساخته پس آنچه که منسوب بحقیقت الوهیت است حق عزّ اسمه خود را در انوار بظهور رساند و آنچه که منسوب بخلقیت است، آن ظلمت باشد. پس بدین جهت نور را پرستیدند برای این راز خدائی که جامع دو وصف و شامل دو ضدّ است . طائفه ای هم بجانب آتش گرائیدند و آن را پرستیدند. زیرا که میگویند زندگانی بر اساس حرارت غریزیّه قائم است . و این حرارت غریزیّه معنی است و صورت وجودی آن آتش باشد پس اصل وجود آتش است و بس . و اینان مجوس و گبران باشند که خدای تعالی را از نظر یکی بودن میپرستند. پس همچنانکه احدیّت در جمیع مراتب اسماء و صفات تعبیه شده، آتش نیز همچنان باشد چه او نیرومندترین عناصر و اسطقسات و بالاترین آنهاست . و هیچ طبیعتی نزدیک بآتش نشود جز آنکه خود آتش گردد. بواسطه ٔ نیروئی که در آتش یافت میگردد. و این است لطیفه ٔ آتش پرستی .<br /></font></div>'),
(82634, 'ثنویین', '<span class=\"hlight\">ثنویین .</span> <font color=\"DarkGreen\"><b>[ ث َ ن َ وی ی ]</font></b> (ع ص نسبی، اِ) ج ِ ثنوی .<br /></font></div>'),
(82635, 'ثنگ', '<span class=\"hlight\">ثنگ .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) بمعنی ارتنگ است که نام کتاب صنایع و بدایع مانی نقاش باشد و ثنگ در اصل بمعنی نقش و نگار است . (برهان قاطع). رجوع به ارتنگ شود.<br /></font></div>'),
(82636, 'ثنی', '<span class=\"hlight\">ثنی .</span> <font color=\"DarkGreen\"><b>[ ث َ نی ی ]</font></b> (ع اِ) شتر نر شش ساله . ماده شتر پنج ساله بششم درآمده . اسب، گوسپند و بز و گاو سه ساله . ج، ثنیان و ثناء. مؤلف کشاف اصطلاحات الفنون گوید: بر وزن کریم کسی را نامندکه چهار دندان واقعشده در جلو دهان او افتاده باشد.و این دندانها که دو در بالا و دو در پائین قرار گرفته ثنایا نامیده میشود. ولی این دندانها در حیوانات به اختلاف واقع شوند. و در مهذب الاسماء گوید: ثنی اسب و گاو و گوسپند سه ساله و اشتر پنجساله را نامند. الاثناء و الثنیات جمع. و در کنزاللغات آمده که ثنی گاوو گوسپند دو ساله که پا در سوم نهاده باشد و شتر پنجساله که پا در ششم نهاده باشد و آهوی شش ساله . و بیرجندی در کتاب الاضحیه آورده که بز و میشی که دو سالش تمام نشده و در شرف داخل شدن در سال سوم باشند ثنی نامیده میشوند و در نهایة اللغه ٔ ابن اثیر جزری است که گوسفندی که در سال سوم پانهاده باشد ثنی گویند و در مذهب ابن حنبل گوسفندی را نامند که در دوسالگی داخل شده باشد و گاوی را هم که دو سالش تمام و در سال سوم پا نهاده باشد ثنی خوانند چنانکه در هدایه ذکر شده است . و در خلاصه گفته است که گاو تمام سه ساله را هم ثنی مینامند و وفق بین این اقوال بمختصر تجوزی ممکن باشد و ثنی شتری را نیز گویند که پنجسالش تمام و در سال ششم پا نهاده باشد. و در خزانه گفته است که شتر چهار سال تمام و پا نهاده در پنجسالگی را نیز ثنی گویند. سخن بیرجندی در اینجا تمام است و فی جامعالرموز قیل اثنایا ابن حول و ابن ضعفه و ابن خمس من ذوی ظلف و خف لکن فی کتب اللغة هو من ذی ظلف ما دخل فی السنةالثالثة و من ذی خف فی السادسة. و هکذا فی المحیط لکنه قال هو من الغنم ما دخل فی الثانیة. ثم قال هذاکله قول الفقهاء فهم یوافقون اهل اللغة فی الاکثر.<br /></font></div>'),
(82637, 'ثنی', '<span class=\"hlight\">ثنی .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) دو تاه . ج، اَثناء.<br /></font></div>'),
(82638, 'ثنی', '<span class=\"hlight\">ثنی .</span> <font color=\"DarkGreen\"><b>[ ث ِ نی ی ]</font></b> (اِخ ) نام محلی است در جزیره نزدیک بشر در مشرق رصافه . <BR><font color=\"Blue\">◄</font> محلی است نزدیک ادم نزدیک ذی قار و در آنجا آثار قدیم موجود است .<br /></font></div>'),
(82639, 'ثنی', '<span class=\"hlight\">ثنی .</span> <font color=\"DarkGreen\"><b>[ ث ِن ْی ْ ]</font></b> (ع اِ) یک تاه از تاهها. ج، اَثناء. <BR><font color=\"Blue\">◄</font> کار دوباره : لاثنی فی الصدقة. <BR><font color=\"Blue\">◄</font> گشت کوه و وادی . <BR><font color=\"Blue\">◄</font> نوردِ نامه . <BR><font color=\"Blue\">◄</font> دوم . <BR><font color=\"Blue\">◄</font> روز دوشنبه . <BR><font color=\"Blue\">◄</font> بچه ٔ دوم . <BR><font color=\"Blue\">◄</font> ناقه وزنی که بار دویم بزاید. <BR><font color=\"Blue\">◄</font> مهتر دوم از مهتری . <BR><font color=\"Blue\">◄</font> پاسی و پاره ای از شب : مضی ثنی من اللیل . <BR><font color=\"Blue\">◄</font> ساعت . وقت . <BR><font color=\"Blue\">◄</font> ثنی الحیة؛ گشت و پیچ و خم مار یا آنچه از او معوج شود.<br /></font></div>'),
(82640, 'ثنی', '<span class=\"hlight\">ثنی .</span> <font color=\"DarkGreen\"><b>[ ث َ ن ْی ْ ]</font></b> (ع مص ) بازداشتن از حاجت . <BR><font color=\"Blue\">◄</font> واگردانیدن . <BR><font color=\"Blue\">◄</font> دوم شدن دیگری را. <BR><font color=\"Blue\">◄</font> دو تا کردن . ورمالیدن . <BR><font color=\"Blue\">◄</font> دوتا شدن . <BR><font color=\"Blue\">◄</font> کاری که دوباره کرده شود. <BR><font color=\"Blue\">◄</font> دوبار شیار کردن زمین را. <BR><font color=\"Blue\">◄</font> سه ساله شدن چهارپای . <BR><font color=\"Blue\">◄</font> عقال بستن شتر را.<br /></font></div>'),
(82641, 'ثنیا', '<span class=\"hlight\">ثنیا.</span> <font color=\"DarkGreen\"><b>[ ث ُ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ]</font></b> (ع اِ) ثنوی . <BR><font color=\"Blue\">◄</font> سر و پاهای شتر قمار. <BR><font color=\"Blue\">◄</font> اسم است استثنا را و هر چه که آنرا استثنا کنند.<br /></font></div>'),
(82642, 'ثنیات', '<span class=\"hlight\">ثنیات .</span> <font color=\"DarkGreen\"><b>[ ث َ نی یا ]</font></b> (ع ص، اِ) ج ِ ثنیّة. ناقه های در سال ششم درآمده . <BR><font color=\"Blue\">◄</font> مادیان های در چهارم آمده . <BR><font color=\"Blue\">◄</font> گوسفندان و گاوان در سیم درآمده .<br /></font></div>'),
(82643, 'ثنیان', '<span class=\"hlight\">ثنیان .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع ص، اِ) ج ِ ثَنی . شتران نر در سال ششم درآمده . ثناء.<br /></font></div>'),
(82644, 'ثنیان', '<span class=\"hlight\">ثنیان .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع ص، اِ) آنکه دومین کس باشد در مهتری و فضیلت . مهتر دوم در مهتری . <BR><font color=\"Blue\">◄</font> مرد بی عقل و بی رای و رای تباه . ج، ثنیة.<br /></font></div>'),
(82645, 'ثنیان', '<span class=\"hlight\">ثنیان .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (اِخ ) نام موضعی که در آنجا غمّان و تغلب و ذبیان و غیرهم بر بنی عذره تاخت آوردند و ظفر نصیب بنی عذره گردید. <BR><font color=\"Blue\">◄</font> نام موضعی است که در آنجا غمّان و تغلب و ذبیان و غیر هم بر بنی زهره ظفر یافتند.<br /></font></div>'),
(82646, 'ثنیة', '<span class=\"hlight\">ثنیة.</span> <font color=\"DarkGreen\"><b>[ ث َ نی ی َ ]</font></b> (اِخ ) موضعی است دور از مدینه و در آن عقبه ای است . (منتهی الارب ).<br /></font></div>'),
(82647, 'ثنیة', '<span class=\"hlight\">ثنیة.</span> <font color=\"DarkGreen\"><b>[ ث َ نی ی َ ]</font></b> (ع اِ) پشته . راه پشته و کوه . راه دو کوه . راه بسوی کوه . <BR><font color=\"Blue\">◄</font> شهیدانی که استثناء کرد ایشان را اﷲ تعالی از صعقه حیث قال : و نفخ فی الصور فَصَعِق َ من فی السموات و من فی الارض الا مَن شاء اﷲ (قرآن <span class=\"hlight\" dir=\"rtl\">٦٨/٣٩</span>). <BR><font color=\"Blue\">◄</font> چهار دندان پیشین دو از فوق و دو از تحت . پیشین . ج، ثنایا. <BR><font color=\"Blue\">◄</font> ناقه ٔ در سال ششم درآمده . <BR><font color=\"Blue\">◄</font> مادیان در چهارم درآمده . <BR><font color=\"Blue\">◄</font> گوسفند و گاو در سوم درآمده . ج، ثنیات . <BR><font color=\"Blue\">◄</font> ستایش، بمدح باشد یا بذم . <BR><font color=\"Blue\">◄</font> خرمابن مستثنی از بیع. <BR><font color=\"Blue\">◄</font> سر و پاهای شتر قمار. <BR><font color=\"Blue\">◄</font> اسم است استثنا را و هر چه که آن را استثنا کنند.<br /></font></div>'),
(82648, 'ثنیة', '<span class=\"hlight\">ثنیة.</span> <font color=\"DarkGreen\"><b>[ ث َ نی ی َ ]</font></b> (اِخ ) نام موضعی است در خارج حصن کرک میان راه دمشق به حجاز.<br /></font></div>'),
(82649, 'ثنیة', '<span class=\"hlight\">ثنیة.</span> <font color=\"DarkGreen\"><b>[ ث ِن ْ ی َ ]</font></b> (ع ص، اِ) ج ِ ثُنیان .<br /></font></div>'),
(82650, 'ثنیة', '<span class=\"hlight\">ثنیة.</span> <font color=\"DarkGreen\"><b>[ ث ِن ْ ی َ ]</font></b> (ع ص، اِ) فرومایه . خوارتر و زبون تر چیزی : فلان ثِنیةُ اهل بیته .<br /></font></div>'),
(82651, 'ثنیتان', '<span class=\"hlight\">ثنیتان .</span> <font color=\"DarkGreen\"><b>[ ث َ نی ی َ ]</font></b> (ع اِ) دو از ثنایا. (دندان ).<br /></font></div>'),
(82652, 'ثهات', '<span class=\"hlight\">ثهات .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) ثَهت . خواندن و بانگ کردن .<br /></font></div>'),
(82653, 'ثهت', '<span class=\"hlight\">ثهت .</span> <font color=\"DarkGreen\"><b>[ ث َ هََ ]</font></b> (ع مص ) ثَهات . خواندن وبانگ کردن .<br /></font></div>'),
(82654, 'ثهت گوش', '<span class=\"hlight\">ثهت گوش .</span> <font color=\"DarkGreen\"><b>[ ث َ ت َ ]</font></b> (اِخ ) ساتاگید. نام ناحیتی در جنوب کابل کنونی . این سرزمین در زمان کوروش جزو ممالک او بود. <br /></font></div>'),
(82655, 'ثهثهة', '<span class=\"hlight\">ثهثهة.</span> <font color=\"DarkGreen\"><b>[ ث َ ث َ هََ ]</font></b> (ع مص ) ثهثهه ٔ ثلج ؛ آب شدن و گداختن برف .<br /></font></div>'),
(82656, 'ثهل', '<span class=\"hlight\">ثهل .</span> <font color=\"DarkGreen\"><b>[ ث َ هََ ]</font></b> (ع مص )گسترده شدن چیزی بر روی زمین . منبسط شدن بر زمین .<br /></font></div>'),
(82657, 'ثهلان', '<span class=\"hlight\">ثهلان .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) کوهی است عظیم بنی نمیر را در ناحیه ٔ شریف . (تاج العروس ). کوهی است در عالیه . (میدانی ). و گویند در بلاد بنی نمیر است . (مراصد الاطلاع ). شعرا و نویسندگان بدان تمثل کنند. مثل ثهلان ؛ یعنی باوقار. بارزانت و حلیم و نیز گران چنانکه گویند: اَثقل من ثهلان . و بلند و مرتفع <span class=\"hlight\">:</span> <br />براند خسرو مشرق بسوی بیلارام <br />بدان حصاری کز برج او خجل ثهلان .<br /> <font color=\"Red\">عنصری .</font><br />عمان و محیط و نیل و جیحون <br />جودی و حری و قاف و ثهلان .<br /> <font color=\"Red\">خاقانی .</font><br />شراری جهد ز آهن نعل اسبش <br />که حرّ اقش اروند و ثهلان نماید.<br /> <font color=\"Red\">خاقانی .</font><br />پیش آن بادپرستان بشکوه <br />کوه ثهلان شوم انشأاﷲ.<br /> <font color=\"Red\">خاقانی .</font><br />چون خور بر اسب قله ٔ سنجدبش آمدن <br />از نعل قله، قله ٔ ثهلان شکستنش .<br /> <font color=\"Red\">خاقانی (دیوان چ سجادی ص <span class=\"hlight\" dir=\"rtl\">٥٣٠</span>).</font><br />حلمش بسوی قله ٔ ثهلان نظر نمود<br />نشمرد جز غبار و کلوخی محقرش .<br /><font color=\"Red\">محمد دقایقی مروزی .</font><br /></font></div>'),
(82658, 'ثهلان', '<span class=\"hlight\">ثهلان .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) از اعلام مردان عرب است .<br /></font></div>'),
(82659, 'ثهلل', '<span class=\"hlight\">ثهلل .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ]</font></b> (اِخ ) موضعی است بر ساحل دریای کاظمة.(منتهی الارب ). قریه ای است در ریف . (مراصد الاطلاع ).<br /></font></div>'),
(82660, 'ثهلل', '<span class=\"hlight\">ثهلل .</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ث ُ ل ُ ]</font></b> (ع اِ) شخص مجهول یا اسم باطل است ؛ گویند هوالضلال بن ثهلل .<br /></font></div>'),
(82661, 'ثهمد', '<span class=\"hlight\">ثهمد.</span> <font color=\"DarkGreen\"><b>[ ث َ م َ ]</font></b> (اِخ ) کوه سرخ رنگی است از کوههای حمی و در اطرافش ریگزارهای بسیار است در دیار غنی . و گویند موضعی است در دیار بنی عامر. (مراصد الاطلاع ).<br /></font></div>'),
(82662, 'ثهمد', '<span class=\"hlight\">ثهمد.</span> <font color=\"DarkGreen\"><b>[ ث َ م َ ]</font></b>(ع ص، اِ) فربه بزرگ . <BR><font color=\"Blue\">◄</font> زن فربه بزرگ .<br /></font></div>'),
(82663, 'ثهو', '<span class=\"hlight\">ثهو.</span> <font color=\"DarkGreen\"><b>[ ث َهَْ وْ ]</font></b> (ع مص ) احمق شدن .<br /></font></div>'),
(82664, 'ثهود', '<span class=\"hlight\">ثهود.</span><font color=\"DarkGreen\"><b>[ ث َ وَ ]</font></b> (ع ص، اِ) ثَوهد. کودک فربه تمام خلقت .<br /></font></div>'),
(82665, 'ثواب', '<span class=\"hlight\">ثواب .</span> <font color=\"DarkGreen\"><b>[ ث َوْ وا ]</font></b> (اِخ ) ابن حزابة. نام او در کتب آمده است . (منتهی الارب ). و همچنین نام پسرش قتیبة. (تاج العروس ).<br /></font></div>'),
(82666, 'ثواب', '<span class=\"hlight\">ثواب .</span> <font color=\"DarkGreen\"><b>[ ث َوْ وا ]</font></b> (اِخ ) ابن عتبه . محدث است .<br /></font></div>'),
(82667, 'ثواب', '<span class=\"hlight\">ثواب .</span> <font color=\"DarkGreen\"><b>[ ث َ وْ وا ]</font></b> (اِخ ) نام مردی که او را به اطاعت مثل زنند: اطوع من ثواب . گویند او بسفری یا جنگی رفت و مفقودالخبر گردید و زن وی نذر کرد که اگر بازآیدمهار در بینی او کرده کشان تا مکه برد و او چون بازآمد و نذر زن بدانست هم بدان صورت بزیارت خانه شد.<br /></font></div>'),
(82668, 'ثواب', '<span class=\"hlight\">ثواب .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) مردی صاحب تدبیر و شجاعت وزیر حضرت داود قاتل شلوم بن داود که به دست سلیمان بقتل رسید. (حبیب السیر چ طهران ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣</span>).<br /></font></div>'),
(82669, 'ثواب', '<span class=\"hlight\">ثواب .</span> <font color=\"DarkGreen\"><b>[ث َ ]</font></b> (ع اِ) هر عملی که از بندگان ایزدتعالی سر زندکه در ازاء آن بنده استحقاق بخشایش و آمرزش الهی رادریابد... آنرا ثواب نامند و برخی گفته اند ثواب بخشیدن است آنچه را ملایم طبع آدمی باشد. (تعریفات سید جرجانی ). مقابل عقاب . کرفه . مزد طاعت . <BR><font color=\"Blue\">◄</font> عوض . اجر. جزاء. جزاء خیر در آخرت . (غیاث اللغة). حسنة. پاداش <span class=\"hlight\">:</span> غزوی نیکو برود بر ایشان امسال وثواب آن خداوند را باشد. (تاریخ بیهقی ). ثمره ٔ این اعتراف و رضا آن است که احاطه کند زیادتی فضل خدا راو دریابد مرتبه ٔ بلند ثواب را. (تاریخ بیهقی ). و چنان دید امیرالمؤمنین ... که بگرداند خاطر خود را از جزع بر این مصیبت ها بسوی باز یافت اجر و ثواب . (تاریخ بیهقی ). در حالتی که خواهان است چیزی را که نزد اوست از ثواب . (تاریخ بیهقی ). مردم را که ایزد... این دو نعمت عطا داده است لاجرم از بهایم جداست و به ثواب و عقاب میرسد. (تاریخ بیهقی ). و حشر و قیامت خواهد بود و سؤال و جواب و ثواب و عقاب . (تاریخ بیهقی ).<br />از تو بکشم عقاب دنیا<br />از بهر ثواب آن جهانی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آنکه بی خدمتی ثواب دهیش <br />بایدش دید بی گناه عقاب .<br /> <font color=\"Red\">مسعودسعد.</font><br />بر تو فرخنده باد ماه صیام <br />خلد بادت ز کردگار ثواب .<br /> <font color=\"Red\">مسعودسعد.</font><br />مگر که خدمت تو طاعت خدای شده ست <br />که هست بسته در او خلق را ثواب و عقاب .<br /> <font color=\"Red\">مسعودسعد.</font><br />و همت بر اکتساب ثواب آخرت مقصور گردان . (کلیله و دمنه ). و در کتب طب آورده اند که فاضلترین اطباء آنست که بر علاج از جهت ثواب آخرت مواظبت نماید. (کلیله و دمنه ). در معنی بعث و قیامت و ثواب و عقاب بر سبیل افترا چیزی نگفتم . (کلیله و دمنه ص <span class=\"hlight\" dir=\"rtl\">٥١</span>). و ثواب و ثناء آن ایام میمون ملک را مدخر شود. (کلیله و دمنه ). و ثواب آن روزگار همایون اعلی را مدخر گردانیده گشت . (کلیله و دمنه ). آنگاه نفس خویش را میان چهار کار مخیر گردانیدم <span class=\"hlight\">:</span> وفور مال و ذکر سایر و لذات حال و ثواب باقی . (کلیله و دمنه ). و آنکه سعی برای مصالح دنیا مصروف داردزندگانی بر وی وبال باشد و از ثواب آخرت بازماند. (کلیله و دمنه ). آن که طالبند <font color=\"DarkGreen\"><b>[ دنیا جویان ]</font></b> فراخی معیشت و رفعت منزلت و رسیدن بثواب آخرت . (کلیله و دمنه ). اگر کسی ... از مال حلال صدقه دهد چندان ثواب نیابد که یکساعت از روز برای حفظ مال ... در جهاد باشد. (کلیله و دمنه ). غایت نادانی است ... چشم داشتن بثواب آخرت به ریا در عبادت . (کلیله و دمنه ).<br />ثوابت باشد ای دارای خرمن <br />اگر رحمی کنی بر خوشه چینی .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> احسان <span class=\"hlight\">:</span> <br />مفرمای انتظارم بیشتر زین <br />کرم کن یا جوابی یا ثوابی .<br /> <font color=\"Red\">ابن یمین .</font><br />ثواب راه بخانه ٔ صاحب خودمی برد.<br /> <BR><font color=\"Blue\">◄</font> در بیت ذیل مسعود اگر تحریفی نشده باشد ثواب بمعنی غیر معمول آمده است <span class=\"hlight\">:</span> <br />در رضا و ثواب ایزد کوش <br />گرچه صعب است مرگ فرزندان .<br />ج، مثوبه . <BR><font color=\"Blue\">◄</font> ثواب خواستن، استثابه . <BR><font color=\"Blue\">◄</font> ثواب دادن . اجر دادن . تثویب . <BR><font color=\"Blue\">◄</font> انگبین . شهد. عسل . <BR><font color=\"Blue\">◄</font> منج انگبین . نحل . زنبور عسل . مگس انگبین .<br /></font></div>'),
(82670, 'ثواب', '<span class=\"hlight\">ثواب .</span> <font color=\"DarkGreen\"><b>[ ث َوْ وا ]</font></b> (ع ص ) جامه فروش . <BR><font color=\"Blue\">◄</font> بزاز. ثیابی . <BR><font color=\"Blue\">◄</font> جامه دار. صاحب جامه .<br /></font></div>'),
(82671, 'ثوابة', '<span class=\"hlight\">ثوابة.</span> <font color=\"DarkGreen\"><b>[ ث َ ب َ ]</font></b> (اِخ ) ابن یونس . پدرآل ثوابة. (ابن الندیم ص <span class=\"hlight\" dir=\"rtl\">٧</span>). رجوع به بنوثوابه شود.<br /></font></div>'),
(82672, 'ثوابة', '<span class=\"hlight\">ثوابة.</span> <font color=\"DarkGreen\"><b>[ ث َ ب َ ]</font></b> (ع اِ) یک ثواب . <BR><font color=\"Blue\">◄</font> یکی منج انگبین . یک نحل .<br /></font></div>'),
(82673, 'ثوابة', '<span class=\"hlight\">ثوابة.</span><font color=\"DarkGreen\"><b>[ ث َ ب َ ]</font></b> (اِخ ) ابوالحسین از آل ثوابةبن یونس . او در قرن چهارم میزیست و با ابن الندیم مؤلف کتاب الفهرست معاصر بود. او راست : کتاب رسائل . (ابن الندیم ).<br /></font></div>'),
(82674, 'ثوابة', '<span class=\"hlight\">ثوابة.</span> <font color=\"DarkGreen\"><b>[ ث َ ب َ ]</font></b> (اِخ ) درب ثوابة در بغداد است . (مراصد الاطلاع ).<br /></font></div>'),
(82675, 'ثوابت', '<span class=\"hlight\">ثوابت .</span> <font color=\"DarkGreen\"><b>[ ث َ ب ِ ]</font></b> (ع ص، اِ) ج ِ ثابتة . تمام ستارگان جز هفت ستاره ٔ سیاره . ستارگان آرمیده . ستارگان یابانی . ستارگان بیابانی . نجوم ثابته، خلاف سیارات و از آن رو آنان را ثوابت گویند که حرکت آنان در نظر ما یا نامشهود و یا نسبت بسیارات نهایت بطی ٔ باشد. و ثوابت را قدما در چهل وهشت صورت تصویر کرده اند و از آن دوازده بر منطقةالبروج و بیست ویک بر شمال و پانزده بجنوب . و قدما هزاروبیست و دو ستاره در مجموع صور شناخته بودند. ولی طبق تحقیقات منجمین معاصر جمعاً <span class=\"hlight\" dir=\"rtl\">٧٦٠٠</span> عدد از ثوابت با چشم دیده میشود ولی در نیمکره ٔ شمالی فقط تا <span class=\"hlight\" dir=\"rtl\">٢٥٠٠</span> ستاره ٔ ثابت میتوان دید و تعداد مجموع ثوابت را دومیلیارد دانسته اند.<br />صورتهای منطقةالبروج : <span class=\"hlight\" dir=\"rtl\">١</span> - حمل . بره . الکبش . بره ٔ فلک . برج حمل . <span class=\"hlight\" dir=\"rtl\">٢</span> - ثور . گاو. گاو گردون . برج ثور. گاو فلک . <span class=\"hlight\" dir=\"rtl\">٣</span> - جوزا . توأمان . دوپیکر. برج جوزا. <span class=\"hlight\" dir=\"rtl\">٤</span> - سرطان . خرچنگ . خرچنگ فلک . برج سرطان . <span class=\"hlight\" dir=\"rtl\">٥</span> - اسد . شیر. شیر فلک . برج اسد. شیر سپهر. <span class=\"hlight\" dir=\"rtl\">٦</span> - سنبله . عذراء. خوشه . برج سنبله . خوشه ٔ سپهر. خوشه ٔ چرخ . <span class=\"hlight\" dir=\"rtl\">٧</span> - میزان . ترازو. شاهین . برج میزان . ترازوی فلک . شاهین فلک . <span class=\"hlight\" dir=\"rtl\">٨</span> - عقرب . کژدم . برج عقرب . کژدم چرخ . کژدم گردون . کژدم نیلوفری . <span class=\"hlight\" dir=\"rtl\">٩</span> - قوس . رامی . قوس فلک . کمان چرخ . برج قوس . <span class=\"hlight\" dir=\"rtl\">١٠</span> - جدی . بزغاله . بزیچه ٔچرخ . برج جدی . بزغاله ٔ فلک . <span class=\"hlight\" dir=\"rtl\">١١</span> - دلو . ساکب الماء. برج دلو. <span class=\"hlight\" dir=\"rtl\">١٢</span> - حوت . حوتین . ماهی . برج حوت . ماهی سپهر. سمکه .<br />صورتهای شمالی : <span class=\"hlight\" dir=\"rtl\">١</span> - دب اصغر. ضواجع. هفت اورنگ کهین . سریر فلک . بنات النعش صغری . <span class=\"hlight\" dir=\"rtl\">٢</span> - دب اکبر. هفت اورنگ مهین . بنات النعش کبری . دختران نعش بزرگ . <span class=\"hlight\" dir=\"rtl\">٣</span> - تنین . اژدهای فلک . التنین . <span class=\"hlight\" dir=\"rtl\">٤</span> - قیقاوس . ملتهب . الاثافی . کیکاوس . قیقاووس . <span class=\"hlight\" dir=\"rtl\">٥</span> - عوّاء. بؤرطیس . حارس . بقار. گاوچران . راعی الشاء. حارس الشمال . صباح . حارس السماء. <span class=\"hlight\" dir=\"rtl\">٦</span> - اکلیل شمالی . فکه .کاسه ٔ درویشان . قصعةالمساکین . کاسه ٔ یتیمان . کاسه ٔ لئیمان . <span class=\"hlight\" dir=\"rtl\">٧</span> - جاثی علی رکبتیه . <span class=\"hlight\" dir=\"rtl\">٨</span> - لورا. شلیاق . کشف . السلحفاة. نسر واقع. چنگ رومی . سلیاق . <span class=\"hlight\" dir=\"rtl\">٩</span> - دجاجه . الدجاجة. ماکیان . اوزالعراقی . الفوارس . (مفاتیح خوارزمی ). الطائر. <span class=\"hlight\" dir=\"rtl\">١٠</span> - مراءة ذات الکرسی . ذات الکرسی . خداوند کرسی . عرش . منبر. <span class=\"hlight\" dir=\"rtl\">١١</span> - حامل رأس الغول . برساوس . سوار. برشاووش . <span class=\"hlight\" dir=\"rtl\">١٢</span> - ممسک العنان . ممسک الاعنة. صاحب المعز. حامل العناق . انیخس . (مفاتیح خوارزمی ). القاید. ذوالعنان . گیرنده ٔ عنان . <span class=\"hlight\" dir=\"rtl\">١٣</span> - حوا. <span class=\"hlight\" dir=\"rtl\">١٤</span> - حیةالحوا. <span class=\"hlight\" dir=\"rtl\">١٥</span> - سهم . تیر. نوک نشابه . السهم . <span class=\"hlight\" dir=\"rtl\">١٦</span> - عقاب . العقاب . (صورتین عقاب و سهم را تواماً نسر طائر خوانند). <span class=\"hlight\" dir=\"rtl\">١٧</span> - دلفین . الصلیب . <span class=\"hlight\" dir=\"rtl\">١٨</span> - فرس اول . قطعةالفرس . <span class=\"hlight\" dir=\"rtl\">١٩</span> - فرس ثانی . فرس اعظم . الفرس . <span class=\"hlight\" dir=\"rtl\">٢٠</span> - المراءة التی لم تر بعلا . ناقه . اندرومیدا. المراءةالمسلسلة. <span class=\"hlight\" dir=\"rtl\">٢١</span> - مثلث . الاشراط.<br />صورتهای جنوبی : <span class=\"hlight\" dir=\"rtl\">١</span> - قیطس . سبعالبحر. <span class=\"hlight\" dir=\"rtl\">٢</span> - جبار. الجبار. <span class=\"hlight\" dir=\"rtl\">٣</span>- نهر. النهر. اریدانوس .<span class=\"hlight\" dir=\"rtl\">٤</span> - ارنب . الأرنب . خرگوش . <span class=\"hlight\" dir=\"rtl\">٥</span> - کلب اکبر. سگ بزرگ .کلب الجبار. شعری العبور. شعرای یمانی . <span class=\"hlight\" dir=\"rtl\">٦</span> - کلب مقدم . کلب اصغر. سگ کوچک . شعرای شامیة. الغمیصاء. <span class=\"hlight\" dir=\"rtl\">٧</span> - شجاع . الشجاع . الحیة. <span class=\"hlight\" dir=\"rtl\">٨</span> - سفینه . کشتی . السفینة. <span class=\"hlight\" dir=\"rtl\">٩</span> - کاس . باطیه . معلف . <span class=\"hlight\" dir=\"rtl\">١٠</span> - غراب . الغراب . <span class=\"hlight\" dir=\"rtl\">١١</span> - قنطورس . حامل السبع. الظلیم . <span class=\"hlight\" dir=\"rtl\">١٢</span> - سبع. ذئب . <span class=\"hlight\" dir=\"rtl\">١٣</span> - مجمره . الببغاء. آتشدان (بیرونی ). محراب نفاطة. <span class=\"hlight\" dir=\"rtl\">١٤</span> - اکلیل جنوبی . <span class=\"hlight\" dir=\"rtl\">١٥</span> - حوت جنوبی . <br />متأخرین دو صورت بر صور چهل و هشت گانه افزوده اند: <span class=\"hlight\" dir=\"rtl\">١</span> - شعر بر نیکی . هلبه . موی ملکه برنیس . حوض . ضفیرةالاسد. ذات الشعور. <span class=\"hlight\" dir=\"rtl\">٢</span> - انطونیوس . <BR><font color=\"Blue\">◄</font> بروج ثوابت، ستارگان فلک هشتم . (بقول قدماء). <BR><font color=\"Blue\">◄</font> ثوابت منطقةالبروج، بروج دوازده گانه باشد <span class=\"hlight\">:</span> <br />دگر چرخ ده و دو خانه باشد<br />ثوابت را در او کاشانه باشد.<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(82676, 'ثوابکار', '<span class=\"hlight\">ثوابکار.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ص مرکب ) کسی که عمل نیکو و خیر کند.<br /></font></div>'),
(82677, 'ثوابکاری', '<span class=\"hlight\">ثوابکاری .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) نیکوئی و عمل در خور پاداش نیک .<br /></font></div>'),
(82678, 'ثوابی', '<span class=\"hlight\">ثوابی .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ص نسبی ) منسوب به ثوابة که دروازه ای است به بغداد. (سمعانی ).<br /></font></div>'),
(82679, 'ثواج', '<span class=\"hlight\">ثواج .</span><font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) بانگ گوسفند و گاو. <BR><font color=\"Blue\">◄</font> (مص ) بانگ کردن گوسفند. (تاج المصادر بیهقی ) (زوزنی ).<br /></font></div>'),
(82680, 'ثوار', '<span class=\"hlight\">ثوار.</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع مص ) مُثاورة. برجهیدن .<br /></font></div>'),
(82681, 'ثوار', '<span class=\"hlight\">ثوار.</span> <font color=\"DarkGreen\"><b>[ ث َوْ وا ]</font></b> (ع ص، اِ) گاوبان .<br /></font></div>'),
(82682, 'ثواط', '<span class=\"hlight\">ثواط.</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) زکام .<br /></font></div>'),
(82683, 'ثواقب', '<span class=\"hlight\">ثواقب .</span> <font color=\"DarkGreen\"><b>[ ث َ ق ِ ]</font></b> (ع اِ) ج ِ ثاقب . روشنی ها. لوامع. <BR><font color=\"Blue\">◄</font> ستاره های روشنی دهنده <span class=\"hlight\">:</span> مناقب او در همه ٔ جهان چون ثواقب درخشان بود. (ترجمه ٔ تاریخ یمینی ).<br /></font></div>'),
(82684, 'ثواقل', '<span class=\"hlight\">ثواقل .</span> <font color=\"DarkGreen\"><b>[ ث َ ق ِ ]</font></b> (ع اِ) ج ِ ثاقل . یعنی دینار کامل .<br /></font></div>'),
(82685, 'ثوالة', '<span class=\"hlight\">ثوالة.</span> <font color=\"DarkGreen\"><b>[ ث َوْ وا ل َ ]</font></b> (ع اِ) اسم است گروه ملخ را.<br /></font></div>'),
(82686, 'ثوالث', '<span class=\"hlight\">ثوالث .</span> <font color=\"DarkGreen\"><b>[ ث َ ل ِ ]</font></b> (ع ص، اِ) ثالثة.<br /></font></div>'),
(82687, 'ثوام', '<span class=\"hlight\">ثوام .</span> <font color=\"DarkGreen\"><b>[ ث َوْ وا ]</font></b> (ع ص، اِ) سیرفروش .<br /></font></div>'),
(82688, 'ثوامین', '<span class=\"hlight\">ثوامین .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص، اِ) ج ِ ثامِنه .<br /></font></div>'),
(82689, 'ثوانی', '<span class=\"hlight\">ثوانی .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص، اِ) ج ِ ثانیه که بمعنی دوم است و شصتم حصه ٔ دقیقه . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> ثوانی نجوم ؛ هرچه بزیر فلک قمر پیدا آید از چیزهای نورانی جز برق و صاعقه . و از آن جمله است، انسی . جابیه . حربه . ذوذنب . ذوذوابة. شهب . طیفور. عمود. فارس . قصعی . مصباحی . نیازک . وردی . و از آن رو آنان را ثوانی نجوم گویند که در دلائل و احکام در مرتبه ٔ ثانی اند و احکام و دلائل اولیه نجوم را باشد.<br /></font></div>'),
(82690, 'ثواکل', '<span class=\"hlight\">ثواکل .</span> <font color=\"DarkGreen\"><b>[ ث َ ک ِ ]</font></b> (ع ص، اِ) ج ِ ثاکل و ثکلی و ثاکله و ثکول .<br /></font></div>'),
(82691, 'ثوب', '<span class=\"hlight\">ثوب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) ثؤوب . ثَوبان . بازگشتن بعد از رفتن . <BR><font color=\"Blue\">◄</font> گرد آمدن مردم . <BR><font color=\"Blue\">◄</font> گرد آمدن آب بعد از آنکه رفته بود. <BR><font color=\"Blue\">◄</font> پر آب گردیدن حوض و ظرف و مانند آن یا قریب به پری رسیدن . <BR><font color=\"Blue\">◄</font> سرزنش کردن کسی را بر کار بد. <BR><font color=\"Blue\">◄</font> جامه کشیدن از بیمار. <BR><font color=\"Blue\">◄</font> فربه شدن بعد از لاغری مرض .<br /></font></div>'),
(82692, 'ثوب', '<span class=\"hlight\">ثوب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) ابن شحمه ٔ تمیمی ملقب به مجیرالطیر. و او ست که حاتم طی را اسیر کرد. (تاج العروس ).<br /></font></div>'),
(82693, 'ثوب', '<span class=\"hlight\">ثوب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) ابن النار. شاعری جاهلی است . (تاج العروس ).<br /></font></div>'),
(82694, 'ثوب', '<span class=\"hlight\">ثوب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) ابن تَلدة. مردی بود درازعمر. و او راست : شعر در روز قادسیه و از بنووالبه است . (تاج العروس ).<br /></font></div>'),
(82695, 'ثوب', '<span class=\"hlight\">ثوب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) جامه . لباس . لبس . لبوس . ملبس : پوشیدنی . پوشاک . پوشش <span class=\"hlight\">:</span> <br />اصاروا الجو قبرک واستنابوا<br />عن الاکفان ثوب السافیات <br />هر که ثوبی با تن عاری دهد<br />در دو عالم ایزدش یاری دهد.<br /> <font color=\"Red\">عطار.</font><br />و گویند: فی ثوبی ابی ان افیه ؛ یعنی برذمه ٔ من و پدر من است وفای آن . <BR><font color=\"Blue\">◄</font> دل . قلب . <BR><font color=\"Blue\">◄</font> عمل . <BR><font color=\"Blue\">◄</font> پیه تنکی که بالای شکمبه و روده باشد. چادر پیه . ثرب . <br /></font></div>'),
(82696, 'ثوبان', '<span class=\"hlight\">ثوبان .</span> <font color=\"DarkGreen\"><b>[ ث َ وَ ]</font></b> (ع مص ) ثوب . ثُؤب . بازگشتن پس از رفته بودن . <BR><font color=\"Blue\">◄</font> ثوبان مردم ؛ گرد آمدن ایشان . <BR><font color=\"Blue\">◄</font> ثوبان جسم ؛ فربهی گرفتن پس از لاغری از مرض . <BR><font color=\"Blue\">◄</font> ثَوبان حوض ؛ پر آب شدن یا نزدیک به پری شدن آن . <BR><font color=\"Blue\">◄</font> ثَوبَان ماء؛ گرد آمدن آب پس از رفته بودن .<br /></font></div>'),
(82697, 'ثوبان', '<span class=\"hlight\">ثوبان .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) نام دو تن از صحابه ٔ کرام است .<br /></font></div>'),
(82698, 'ثوبان', '<span class=\"hlight\">ثوبان .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) ابن بجدد مکنی به ابی عبداﷲ او از آزاد کردگان رسول صلوات اﷲ علیه و از حمیر یمن است . وی به حضر و سفر ملازم خدمت رسول (ص ) بود و پس از رحلت پیغمبر مدتی بشام و زمانی به رمله و گاهی به مصر و در آخر در حمص اقامت داشت و در فتح مصر حاضر بود و بسال <span class=\"hlight\" dir=\"rtl\">٥١</span> هَ . ق . (و بقولی <span class=\"hlight\" dir=\"rtl\">٥٥</span>) در حمص وفات کرد. از او روایات بسیار منقول است . (قاموس الاعلام ).<br /></font></div>'),
(82699, 'ثوبان', '<span class=\"hlight\">ثوبان .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ )ابن ابراهیم، ابوالفیض . شیخ ذوالنون مصری یکی از اکابر عرفاء صاحب کرامات و خوارق عادات و وفات او بسال هَ . ق . بود. رجوع به ابی الفضل ثوبان ... و نیز رجوع به ذوالنون مصری شود.<br /></font></div>'),
(82700, 'ثوبانی', '<span class=\"hlight\">ثوبانی .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b>(ص نسبی ) منسوب است به ثوبان که مولی حضرت رسول بوده و قبرش در عمراس در شش میلی رمله است . (سمعانی ).<br /></font></div>'),
(82701, 'ثوبانی', '<span class=\"hlight\">ثوبانی .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) ثوبانیة.<br /></font></div>'),
(82702, 'ثوبانیة', '<span class=\"hlight\">ثوبانیة.</span> <font color=\"DarkGreen\"><b>[ ث َنی ی َ ]</font></b> (اِخ ) ثوبانی . طایفه ای از مرجئه باشند که به ثوبان بن مرجی انتساب دارند. اینان گویند ایمان عبارت است از اقرار به ایزد تعالی و پیمبران او لیکن چیزهائی که فعل و ترکش از روی تجویز عقل است داخل در ایمان نیست . (سمعانی ). فرقه ای از مرجئه و از یاران ثوبان مرجئی هستند. میگویند ایمان عبارت است از شناسائی و اقرار به وجود خدای یگانه و حقانیت رسول او و بکل مالا یجوز فی العقل ان یعقله . و اما ما جاز فی العقل ان یعقله فلیس الاعتقاد به من الایمان . و این گروه بالاجماع قایلند بر این که خدای تعالی اگر در روز واپسین از گنهکاری اغماض کرد و او را بخشود هر یک از گنهکاران را هم که مانند او باشد خواهد بخشود. و همچنین اگر یکی را از آتش دوزخ رهائی عطا فرمود سایرین را هم مانند او از دوزخ رهائی عطا فرماید. این فرقه عقیده ٔ ثابتی ندارند بر اینکه مؤمنان بالاخره از دوزخ خارج خواهند شد. ابن غیلان که یکی از پیشوایان این فرقه است بین اِرجاء و قدر را جمع کرده است . بدین معنی که افعال بندگان را بخود بندگان نسبت میدهد. و ابن غیلان از کسانی است که به خروج امام قائل میباشند و عقیده ٔ او این است که امامی که خروج خواهد کرد حتماً باید از طایفه ٔ قریش باشد. کذا فی شرح المواقف . و کشاف اصطلاحات الفنون . و رجوع به ابو ثوبان المرجی شود.<br /></font></div>'),
(82703, 'ثوبة', '<span class=\"hlight\">ثوبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ب َ ]</font></b> (اِخ ) ابن نمر بسی . مکنی به ابومحجن قاضی مصر. از قبیله ٔ بس بطنی از حمیر.<br /></font></div>'),
(82704, 'ثوبة', '<span class=\"hlight\">ثوبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ب َ ]</font></b> (اِخ ) ابن جُمیر. صاحب لیلی اخیلیه است و او را دیوانی است .<br /></font></div>'),
(82705, 'ثوبتین', '<span class=\"hlight\">ثوبتین .</span> (اِخ ) نام موضعی است . (ملحق کتاب الجماهر ).<br /></font></div>'),
(82706, 'ثوبری', '<span class=\"hlight\">ثوبری .</span> <font color=\"DarkGreen\"><b>[ ث َ ب َ ]</font></b> (ص نسبی ) منسوب است به ثوبرةبن حبش بن هلال السلمی . (سمعانی ).<br /></font></div>'),
(82707, 'ثوبیه', '<span class=\"hlight\">ثوبیه .</span> <font color=\"DarkGreen\"><b>[ ث َ بی ی َ ]</font></b> (اِخ ) یکی از مرضعات رسول صلوات اﷲ علیه است . او در اول کنیز ابولهب بود و آنگاه که بشارت ولادت رسول صلوات اﷲ علیه برد، آزاد شد. او دایگان حمزه ٔ سیدالشهداء عم رسول (ص ) نیز بود. و در اسلام او اختلاف است . (قاموس الاعلام و حبیب السیر). و در بعض مراجع نام او ثویبه آمده است . رجوع به ثویبه شود.<br /></font></div>'),
(82708, 'ثوج', '<span class=\"hlight\">ثوج .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) جوالی که از برگ خرما سازند و بدان خاک و گچ کشند.<br /></font></div>'),
(82709, 'ثوجمی', '<span class=\"hlight\">ثوجمی .</span> <font color=\"DarkGreen\"><b>[ ج ُ ]</font></b> (ص نسبی ) منسوب است به توجم که بطنی است از معاذف و آنان را ثواجه خوانند. (سمعانی ).<br /></font></div>'),
(82710, 'ثوخ', '<span class=\"hlight\">ثوخ .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) ثوخ اِصبع؛ فرو رفتن انگشت در چیزی نرم و آماسیده .<br /></font></div>'),
(82711, 'ثوخر', '<span class=\"hlight\">ثوخر.</span> <font color=\"DarkGreen\"><b>[ ث ُ رَ ]</font></b> (اِخ )پدر اوتان َ پارسی از دوستان داریوش که به وی در کشتن گئوماتای مغ مدد کرد. <br /></font></div>'),
(82712, 'ثوذسیس', '<span class=\"hlight\">ثوذسیس .</span> (اِخ ) رجوع به ثاوذوسیوس شود.<br /></font></div>'),
(82713, 'ثوذسیوس', '<span class=\"hlight\">ثوذسیوس .</span> (اِخ ) جاثلیق . رجوع به ثاوذوسیوس شود.<br /></font></div>'),
(82714, 'ثور', '<span class=\"hlight\">ثور.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) ثوران . انگیخته شدن گرد و دود و مانند آن . انگیخته شدن خشم و فتنه . <BR><font color=\"Blue\">◄</font> برجستن به غضب برای زدن کسی . <BR><font color=\"Blue\">◄</font> برانگیخته شدن . <BR><font color=\"Blue\">◄</font> برآمدن حصبه و سرخجه بر اندام . <BR><font color=\"Blue\">◄</font> برجستن سنگ خوار و ملخ و جز آن . <BR><font color=\"Blue\">◄</font> ظاهر شدن خون . <BR><font color=\"Blue\">◄</font> بهیجان آمدن دل . <BR><font color=\"Blue\">◄</font> برآمدن آب و روان گردیدن آن .<br /></font></div>'),
(82715, 'ثور', '<span class=\"hlight\">ثور.</span> <font color=\"DarkGreen\"><b>[ ث َ]</font></b> (اِخ ) ابن یزید. محدث است و از ابوعمر عبداﷲ بن عامر الیحصبی روایت کند. <br /></font></div>'),
(82716, 'ثور', '<span class=\"hlight\">ثور.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) پدر بطنی است از مضر و منسوب بدان قبیله است سفیان بن سعید ثوری .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(82717, 'ثور', '<span class=\"hlight\">ثور.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِ) گاو نر. بَقر. <BR><font color=\"Blue\">◄</font> گاو فلک . گاو گردون . یکی از صور دوازده گانه ٔ منطقةالبروج میان حمل و جوزا و آن چون نیم گاوی تخیل شده که روی سوی مشرق و پشت به مغرب دارد و یکصد و چهل و یک ستاره بر آن رصد کرده اند و ثریا و عین الثور در این صورت باشد و بودن آفتاب در این برج به اردی بهشت (نیسان سریانی ) باشد. رجوع به اردی بهشت شود. و بیت الشرف ماه در آن است . <BR><font color=\"Blue\">◄</font> یکی از دو خانه ٔ زهره است و خانه ٔ دیگر آن میزان است . (مفاتیح العلوم ) <span class=\"hlight\">:</span> <br />سوسن لطیف و شیرین چون خوشه های سیمین <br />شاخ و ستاک نسرین چون برج ثور و جوزا.<br /> <font color=\"Red\">کسائی .</font><br />همیشه تا نبود ثور خانه ٔ خورشید<br />چنان کجا نبود شیر خانه ٔ بهرام .<br /> <font color=\"Red\">فرخی .</font><br />بداد ثور بسی شیر اول و آخر<br />به یک لگد که برآورد ریخت ناگاهان .<br /> <font color=\"Red\">مسعودسعد.</font><br />به کوهی که با ثور بمناطحه میکوشید و بیشه ای که روی زمین از چشم کواکب می پوشید التجا کرد. (ترجمه ٔ تاریخ یمینی ). <BR><font color=\"Blue\">◄</font> کالثور یضرب لما عافت البقر، مثل است . گوساله ٔ بسته رازدن . <BR><font color=\"Blue\">◄</font> ثور ابرد؛ گاوی که خالهای سیاه و سفید دارد. <BR><font color=\"Blue\">◄</font> ثور ثریا (فلک )؛ گاو پروین . <BR><font color=\"Blue\">◄</font> ثور رامح ؛ گاوی که هر دو شاخ داشته باشد. ج، اَثُور. اثوار. ثیار. ثَورَة. ثِیَرة. ثیران . <BR><font color=\"Blue\">◄</font> لخت بزرگ از پینو. پاره ای کشک . ج، اَثُور. ثورَة. <BR><font color=\"Blue\">◄</font> مهتر. پیشوای قوم . <BR><font color=\"Blue\">◄</font> سفیدی بن ناخن . <BR><font color=\"Blue\">◄</font> دیوانگی . <BR><font color=\"Blue\">◄</font> سرخی تابان شفق . <BR><font color=\"Blue\">◄</font> پاره ای پنیر. <BR><font color=\"Blue\">◄</font> مرد نادان . احمق .<br /></font></div>'),
(82718, 'ثور', '<span class=\"hlight\">ثور.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) نام اسب عاص بن سعید.<br /></font></div>'),
(82719, 'ثور', '<span class=\"hlight\">ثور.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) سلمی . صحابی است .<br /></font></div>'),
(82720, 'ثور', '<span class=\"hlight\">ثور.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ )ابن یزید اعرابی . رجوع به ابوالجاموس ثور... شود.<br /></font></div>'),
(82721, 'ثور', '<span class=\"hlight\">ثور.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) ابن یزیدبن محمدالرحبی . ابوخالد. تابعی است .<br /></font></div>'),
(82722, 'ثور', '<span class=\"hlight\">ثور.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) ابن مرتّع. اسم او عمرو است واو از ملوک معدّ و از اجداد حجر آکل المرار از ملوک کنده و نیز از اجداد اشعث ابن قیس و فدکندة و از اجداد یعقوب بن اسحاق کندی فیلسوف عرب بوده است . <br /></font></div>'),
(82723, 'ثور', '<span class=\"hlight\">ثور.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) ابن عُفیربن عدی . و او کندة است . <br /></font></div>'),
(82724, 'ثور', '<span class=\"hlight\">ثور.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) ابن عزرة. صحابی است .<br /></font></div>'),
(82725, 'ثور', '<span class=\"hlight\">ثور.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) ابن تلیده . صحابی است .<br /></font></div>'),
(82726, 'ثور', '<span class=\"hlight\">ثور.</span> در مجمل التواریخ (ص <span class=\"hlight\" dir=\"rtl\">٢٥</span>) او فرزند جمشید از پریچهره دختر زابلشاه دانسته شده است ولیکن در گرشاسب نامه این نام بصورت تور آمده است .<br /></font></div>'),
(82727, 'ثور', '<span class=\"hlight\">ثور.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) وادیی است به بلاد مزینه . <BR><font color=\"Blue\">◄</font> کوهی است به مدینه در شمالی احد و آن کوچک و مدور است . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کوهی است در مکه و آنجا غاری است مذکور در قرآن که رسول (ص ) با صدیق در آنجا نهان شد گویند آن را ثور اَطحل می گفتند و آن کوههائی است در مکه و این گفته خطاست . در حدیث است که پیغمبراز ثور تا عیر را حریم مدینه قرار داد. ابوعبیده گفته است که اهل مدینه کوهی به اسم ثور نمی شناسند بلکه اهل حدیث گویند که پیغمبر حریم مدینه را از عیر تا احد قرار داد و بعد عبارت را غیر از این تأویل کرده اند. (مراصد الاطلاع ). از آن رو آن کوه را ثور نامند که ثور ابن عبدمنات بر وی فرود آمدی . (منتهی الارب ).<br /></font></div>'),
(82728, 'ثور', '<span class=\"hlight\">ثور.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) ابن ابی فاخته سعیدبن علاقه . تابعی است .<br /></font></div>'),
(82729, 'ثور اطحل', '<span class=\"hlight\">ثور اطحل .</span> <font color=\"DarkGreen\"><b>[ ث َ رِ اَ ح َ ]</font></b> (ع اِ مرکب ) رجوع به ثور شود.<br /></font></div>'),
(82730, 'ثور شباک', '<span class=\"hlight\">ثور شباک .</span> <font color=\"DarkGreen\"><b>[ رُ ش ِ ]</font></b> (اِخ ) موضعی است .<br /></font></div>'),
(82731, 'ثور واهر', '<span class=\"hlight\">ثور واهر.</span> <font color=\"DarkGreen\"><b>[ رَ هََ رَ ]</font></b> (اِ) بفارسی هخامنشی بمعنی بهار پرغرور. نام یکی از سه ماه بهار که در کتیبه ٔ بیستون ازداریوش بزرگ آمده است . <br /></font></div>'),
(82732, 'ثور کلاته', '<span class=\"hlight\">ثور کلاته .</span> <font color=\"DarkGreen\"><b>[ ث َ ت َ ]</font></b> (اِخ ) از روستاهای استراباد. (سفرنامه ٔ مازندران و استرآباد رابینو ص <span class=\"hlight\" dir=\"rtl\">١٢٧</span>).<br /></font></div>'),
(82733, 'ثورا', '<span class=\"hlight\">ثورا.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) نام نهری است از انهار دمشق . (مراصد الاطلاع ).<br /></font></div>'),
(82734, 'ثوران', '<span class=\"hlight\">ثوران .</span> <font color=\"DarkGreen\"><b>[ ث َ وَ ]</font></b> (ع مص )ثور. برانگیخته شدن . <BR><font color=\"Blue\">◄</font> برخاستن گرد و دود و فتنه . برآمدن گرد و دود. <BR><font color=\"Blue\">◄</font> برجستن سنگ خوار و ملخ . <BR><font color=\"Blue\">◄</font> ظاهر شدن خون . <BR><font color=\"Blue\">◄</font> برآمدن گره بر اندام . <BR><font color=\"Blue\">◄</font> برآمدن حصبه بر اندام : ثارت به الحصبة. <BR><font color=\"Blue\">◄</font> بهیجان آمدن دل و روان گردیدن آب . <BR><font color=\"Blue\">◄</font> خاستن به سوی کسی برای زدن او. (زوزنی ).<br /></font></div>'),
(82735, 'ثورت', '<span class=\"hlight\">ثورت .</span> <font color=\"DarkGreen\"><b>[ ث َ رَ ]</font></b> (ع اِ) رجوع به ثورة شود.<br /></font></div>'),
(82736, 'ثوری', '<span class=\"hlight\">ثوری .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ص نسبی ) منسوب است به ثور که بطنی است از همدان . (سمعانی ).<br /></font></div>'),
(82737, 'ثوری', '<span class=\"hlight\">ثوری .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ص نسبی ) منسوب به ثور. گاوی . <br /></font></div>'),
(82738, 'ثوری', '<span class=\"hlight\">ثوری .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) (ملاعلی ...)یکی از شعرای ایران و این بیت اول رباعی از اوست :<br />تا کی بمن آزار و جفا خواهی کرد<br />با غیر برغم من وفا خواهی کرد.<br /></font></div>'),
(82739, 'ثوری', '<span class=\"hlight\">ثوری .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) رجوع به سفیان ثوری شود.<br /></font></div>'),
(82740, 'ثوری', '<span class=\"hlight\">ثوری .</span> <font color=\"DarkGreen\"><b>[ ث َ را ]</font></b> (اِخ ) رجوع به ثوراء شود.<br /></font></div>'),
(82741, 'ثوری', '<span class=\"hlight\">ثوری .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) عبداﷲبن محمدبن هارون مکنی به ابو محمد. او از شاگردان اصمعی بود و روایت از ابوعبیده و غیر او داشت و کتاب سیبویه را نزد ابی عمر جرمی خوانده است . او راست : کتاب امثال و کتاب اضداد و کتاب النوادرو کتاب فعلت و افتعلت و کتاب الخیل . (ابن الندیم ).<br /></font></div>'),
(82742, 'ثوریان', '<span class=\"hlight\">ثوریان .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) فرقه ای از متصوفه بر طریقت ابی الحسن احمدبن ثوری . (کشف المحجوب هجویری ).<br /></font></div>'),
(82743, 'ثوسیوس', '<span class=\"hlight\">ثوسیوس .</span> (اِخ ) شاعری یونانی است . <br /></font></div>'),
(82744, 'ثوع', '<span class=\"hlight\">ثوع .</span> <font color=\"DarkGreen\"><b>[ ث ُ وَ ]</font></b> (ع اِ) درختی است کوهی، بلند پیوسته سبز وساقش سطبر و خوشه های آن ببطم ماند و بکاری نیاید.<br /></font></div>'),
(82745, 'ثوفیل', '<span class=\"hlight\">ثوفیل .</span> <font color=\"DarkGreen\"><b>[ ث َ ءُ ]</font></b> (اِخ ) یا بقول ابن الندیم تیوفیلی بن ثوما نصرانی رهاوی . ابن منجم . او در بغداد رئیس منجمین مهدی خلیفه بود و علم احکام نیک دانستی و گویند او را پیش گوئیهای غریب بود و سال عمر او به حدود نود رسید او راست : نقل سوفسطیقای ارسطو ظاهراً بسریانی، چه یحیی بن عدی از نقل ثوفیلی سوفسطیقا را بعربی ترجمه کرده است . رجوع به تیوفیلی شود.<br /></font></div>'),
(82746, 'ثول', '<span class=\"hlight\">ثول .</span> <font color=\"DarkGreen\"><b>[ ث َ]</font></b> (ع اِ) گروه زنبوران عسل . (واحد از لفظ خود ندارد). <BR><font color=\"Blue\">◄</font> نر از زنبور عسل . <BR><font color=\"Blue\">◄</font> خانه ٔ زنبوران عسل . <BR><font color=\"Blue\">◄</font> شوره ٔ درخت . <BR><font color=\"Blue\">◄</font> نره ٔ شتر. <BR><font color=\"Blue\">◄</font> غلاف نره ٔ شتر. ج، اثوال .<br /></font></div>'),
(82747, 'ثول', '<span class=\"hlight\">ثول .</span> <font color=\"DarkGreen\"><b>[ث َ ]</font></b> (ع مص ) احمق گردیدن . <BR><font color=\"Blue\">◄</font> دیوانه شدن گرفتن . <BR><font color=\"Blue\">◄</font> ثولاء شدن گوسفند و آن استرخائی است در اعضای گوسفند یا دیوانگی گوسفند که چون بدو عارض شود تبعیت گوسفندان گذارد و تنها چرد. <BR><font color=\"Blue\">◄</font> ثول وعاء؛ ریختن همه ٔ آنچه را که در خنور بود.<br /></font></div>'),
(82748, 'ثول', '<span class=\"hlight\">ثول .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع ص، اِ) ج ِ أثول .<br /></font></div>'),
(82749, 'ثوم', '<span class=\"hlight\">ثوم .</span> (ع اِ) سیر. تریاق روستائی . و از آن بری و بستانی هر دو باشد. در تحفه ٔ حکیم مؤمن آمده است : ثوم بفارسی سیرگویند و بری او اسقوردیون است و بستانی دو قسم می باشد. یکی بسیار دندانه و یکی منحصر به یک دندانه و بقدر پیاز کوچکی و جبلی او را بفارسی موسیر نامند برگش عریض تر از برگ نرگس و گلش بنفش و بیخش یکعدد و بی دندانه و بزرگ مقدار و در بوی مانند بستانی و بهتر از همه بستانی مشهور پر دندانه است . در آخر سیم گرم و خشک و با رطوبت فضیله و محلل و مدر بول و حیض و عرق و مفتح و جالی و جاذب و مخفف رطوبات معده و مفاصل و حرارت او شبیه به حرارت غریزی و ملطف و رقیق کننده ٔ خون و با قوه ٔ تریاقیه و خوردن او با مراعات زمان و مزاج و به حد اعتدال حافظ صحت و رافع مضرت آبهای مختلف و هوای وبائی و تعفن آن است و جهت گزیدن هوام و سگ دیوانه و تصفیه ٔ حلق و صوت و قطع اخلاط غلیظه و قولنج ریحی و نسیان و ربو و سپرز و ریاح تهی گاه و در مرطوبین محرک باه و مولد منی و در محرورین مجفف و معطش و جهت تبهای کهنه و قروح شش و درد معده و مفاصل و رفع کرم شکم و زلوی در حلق مانده و رفع تشنگی که از بلغم و از سده ٔ ماساریقا باشد و تقطیرالبول و نیکوئی رنگ رخسار و ملطف غذاهای غلیظه و جهت ضیق النفس و فالج و رعشه و تحلیل اورام و حصاة گرده و با شراب جهت سم افعی و دوام آن باعث سقوط موی سفید و روئیدن موی سیاه و با انجیر و سداب و با مغز گردکان قوی تر از فادزهر و مطبوخ او با زیره و برگ صنوبر جهت تقویت دندان و با شیر گوسفند و بعد ازان با روغن تازه و بعد از آن با عسل سرشته باشند و در تحریک باه بی عدیل و اکثار او در عدم مراعات مزاج و سن و فصل محرق خون و مضر بواسیر و زنان حامله و شیرده و صاحبان زحیر و خنازیر و مولد صفرای بسیار تند و مضعف باصره و مهیج امراض نایبه و مبخر و مضر شش و مصلح او پختن اوست در آب با قلیلی نمک و اضافه نمودن روغن بادام و روغن کره و استعمال گشنیز و سکنجبین وآب انار ترش و شیرین و امثال آن و نشستن در طبیخ برگ و ساق او جهت احتباس حیض و اخراج مشیمه و طلاء او با عسل جهت بثور لبنیه و قوبا و قروح رطبه سر و نخاله ٔ او و بهق و جرب منقرح و با برگ انجیر سیاه و زیره جهت گزیدن ابن عرس و عقرب و افعی بخوردن با شراب و طلاء با جند و روغن زیتون و با سرکه جهت تحلیل رطوبت غلیظه و ورم اعضاء و ضماد پخته ٔ او با شیر جهت گشودن دمل و تضمید محرق او با عسل جهت ازاله ٔ رنگ خون منجمد در تحت پلک چشم و با روغن بان جهت داءالثعلب و روغنی که سیر در او مکرر جوشانیده باشند جهت جمود خون در اطراف بدن و شقاق که از برودت باشد و جهت مفاصل و قولنج بلغمی و سحج شرباً و ضماداً نافع و غرغره با سرکه ترشی سیر جهت اخراج زلوئی که در حلق مانده باشد و جهت ذبحه مفید و مضمضه ٔ طبیخ او با کندر جهت درد دندان بارد مفید و بدلش پیاز عنصل و سیر صحرائی و طلاءاو با نوشادر جهت برص و بهق و بازفت جهت داخس و خشونت ناخن و کجی آن و طبیخ او کشنده قمل است - انتهی . در اختیارات بدیعی آمده است : بپارسی سیر گویند و بستانی و بری و کراثی بود. ثوم بری اسقوریدون است و گفته شود و ثوم کراثی مرکب بود و بقوت اقوی بود و محلل نفخ بود و آب گردش را نافع بود و خاکستر وی بر بهق چون با عسل طلا کنند نافع بود و کراث و طبیعت ثوم گرم و خشک بود در چهارم و گویند در سیم و در حرارت و یبوست از بصل اقوی بود و محلل نفخ بود و بر داءالثعلب با عسل و روغن حب البان بیامیزند و بدان بمالند موی برویاند و جرب و قوبا را سود دهد و خوردن وی خام و یا بریان کرده یا پخته حلق را صافی گرداند و سرفه ٔ کهن را که از سردی بود سود دارد و خوردن وی کرم را بکشد مجموع و علق از حلق بیرون آورد و وی نافع بود جهت گزیدگی جانوران و سگ دیوانه و رتیلا و ابن عرس و عقرب و افعی با شراب خوردن و ضماد کردن مر طبع را نرم دارد و بول براند و درد روده را نافع بود وقتی که بی تب بود بغایت مقوی باه بود و قولنج و عرق النسا را نافع بود اما مصدع بود و مضعف چشم و چون پخته بود حرارت و حراقت وی کمتر بود و مصلح وی ترشی و روغن بود و گوشت فربه . و صاحب تقویم گوید مصلح وی بنفشه و هلیله بود و بدل ثوم بری ثوم بستانی بود - انتهی . <BR><font color=\"Blue\">◄</font> ثوم ِ عنیف، سیر تیز. <BR><font color=\"Blue\">◄</font> ثوم کرُاثی ؛ ثوم از نوع تره و گندنا.<br /></font></div>'),
(82750, 'ثوم بری', '<span class=\"hlight\">ثوم بری .</span> <font color=\"DarkGreen\"><b>[ م ِ ب َرْ ری ]</font></b> (ترکیب وصفی، اِ مرکب ) موسیر. سیر صحرائی . ثوم الکلب . ثوم الحیة. مَطر قال . (ابن البیطار). اسقوردیون . شقردیون . (ابن البیطار). رجوع به ثوم الحبة شود.<br /></font></div>'),
(82751, 'ثوم ذهبی', '<span class=\"hlight\">ثوم ذهبی .</span> <font color=\"DarkGreen\"><b>[ م ِ ذَ هََ ]</font></b> (ترکیب وصفی، اِ مرکب ) رجوع به مولی شود.<br /></font></div>'),
(82752, 'ثومالاا', '<span class=\"hlight\">ثومالاا.</span> (معرب، اِ) مثنان است . (ابن البیطار). و مثنان درخت گرم دانه است و آن نوعی از مازریون است و گرم دانه تخم وی بود. (اختیارات بدیعی ). و آن دو قسم است یکی را شاخها بقدر دو ذرع و متعدد و درشت و برگش شبیه به برگ مازریون و از آن باریکتر و با رطوبت چسبنده و گلش سفید و ما بین گل ثمرش میروید شبیه به تخم مورد و مایل باستداره و بعد از رسیدن سرخ میشود و پوست او صلب و سیاه و مغز او سفید و جرمدانق و درمانه نیز نامند... و قسم دیگر او در مصر کثیرالوجود است . منبتش کنار آبها و ریگزارها و نباتش بقدر دو شبر و چتری برگش مانند برگ ابهل و در پهلوی هم و گلش زرد و باریک و تخمش مایل بسفیدی و بقدر تخم انجره ... (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(82753, 'ثومة', '<span class=\"hlight\">ثومة.</span> <font color=\"DarkGreen\"><b>[ ث ِ وَ م َ ]</font></b> (ع اِ) درختی است بزرگ بی بار خوش بوی تر از آس و از آن مسواک سازند و آن در بثراء روید.<br /></font></div>'),
(82754, 'ثومة', '<span class=\"hlight\">ثومة.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) ابن مخاشن . پدر قبیله ای است .<br /></font></div>'),
(82755, 'ثومة', '<span class=\"hlight\">ثومة.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (ع اِ)یکی سیر. <BR><font color=\"Blue\">◄</font> بند شمشیر. برازبان شمشیر.<br /></font></div>'),
(82756, 'ثومس', '<span class=\"hlight\">ثومس .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (معرب، اِ) بیونانی حاشا را نامند. صاحب برهان قاطع گوید: بسریانی نوعی از پودنه ٔ کوهی است و ان گلهای کوچک بسیار دارد وبسرخی مایل است و آنرا بعربی سعتر الحمام خوانند.<br /></font></div>'),
(82757, 'ثومه', '<span class=\"hlight\">ثومه .</span> (اِخ ) قلعه ای است در یمن . (مراصد الاطلاع ).<br /></font></div>'),
(82758, 'ثومون', '<span class=\"hlight\">ثومون .</span> (اِ) تخمی است شبیه به خبّه، بفارسی تخم زرداب گویند و بترکی صفرا اودی نامند. منبت گیاه اوامکنه ٔ سایه ناک و او شبیه به سداب و برگش درازتر و گلش سفید و تخمش تلخ و تند و ریزه و گویند تربد زرد بیخ او است و در افعال مشابه خربق . در سیم گرم و خشک و منقی و مسهل اخلاط غلیظه و اقسام کرم شکم و مخرج جنین و مدرّ بول و حیض و محلل اورام بارده و قدر شربتش نیم مثقال و مصلحش کتیراست . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(82759, 'ثوهد', '<span class=\"hlight\">ثوهد.</span> <font color=\"DarkGreen\"><b>[ ث َ هََ ]</font></b> (ع ص، اِ) جوان نوخاسته فربه که نزدیک ببلوغ باشد. <BR><font color=\"Blue\">◄</font> کودک فربه تمام خلقت مراهق . ج، ثواهد.<br /></font></div>'),
(82760, 'ثوور', '<span class=\"hlight\">ثوور.</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع مص ) ثَور. رجوع به ثَور شود. (معنی مصدری ).<br /></font></div>'),
(82761, 'ثوی', '<span class=\"hlight\">ثوی .</span> <font color=\"DarkGreen\"><b>[ ث َ وی ی ]</font></b> (ع اِ) مهمانسرای . <BR><font color=\"Blue\">◄</font> مهمان . <BR><font color=\"Blue\">◄</font> بندی . ج، اَثویاء. <BR><font color=\"Blue\">◄</font> مجاور یکی از حرمین شریفین .<br /></font></div>'),
(82762, 'ثوی', '<span class=\"hlight\">ثوی .</span> <font color=\"DarkGreen\"><b>[ ث َ وی ی ]</font></b> (ع اِ) ج ِ ثَوّة.<br /></font></div>'),
(82763, 'ثوی', '<span class=\"hlight\">ثوی .</span> <font color=\"DarkGreen\"><b>[ ث ُ وی ی ]</font></b> (ع مص ) ثُوَّة. <BR><font color=\"Blue\">◄</font> اقامت دراز کردن . <BR><font color=\"Blue\">◄</font> فرود آمدن .<br /></font></div>'),
(82764, 'ثوی', '<span class=\"hlight\">ثوی .</span> <font color=\"DarkGreen\"><b>[ث ِ وی ی ]</font></b> (ع اِ) جامه ٔ گروهه که بالای میخ بندند و بر آن مشک شیر بجنبانند تا مشک دریده و پاره نگردد.<br /></font></div>'),
(82765, 'ثویب', '<span class=\"hlight\">ثویب .</span> <font color=\"DarkGreen\"><b>[ ث ُوَ ]</font></b> (اِخ ) البکائی . ابوالرشید محدث و تابعی است .<br /></font></div>'),
(82766, 'ثویب', '<span class=\"hlight\">ثویب .</span> <font color=\"DarkGreen\"><b>[ ث ُ وَ ]</font></b> (اِخ ) کلاعی . محدث است .<br /></font></div>'),
(82767, 'ثویبة', '<span class=\"hlight\">ثویبة.</span> <font color=\"DarkGreen\"><b>[ ث ُ وَ ب َ ]</font></b> (ع اِ مصغر) تصغیر ثُبةَ و عامه ثُبیة گویند.<br /></font></div>'),
(82768, 'ثویبة', '<span class=\"hlight\">ثویبة.</span> <font color=\"DarkGreen\"><b>[ ث ُ وَ ب َ ]</font></b> (اِخ ) نام مولاة ابولهب که نبی صلوات اﷲ علیه و حمزه و ابوسلمه را شیر داده است .در بعض مراجع ثوبیة آمده است . رجوع به ثوبیه شود.<br /></font></div>'),
(82769, 'ثویر', '<span class=\"hlight\">ثویر.</span> <font color=\"DarkGreen\"><b>[ ث ُوَ ]</font></b> (ع اِ مصغر) تصغیر ثور. <BR><font color=\"Blue\">◄</font> (اِخ ) زمین ریگ زار و سنگستانی است سفید رنگ از بنی ابی بکربن کلاب نزدیک سواج و کوههای حمی ضریة. (مراصد الاطلاع ).<br /></font></div>'),
(82770, 'ثویر', '<span class=\"hlight\">ثویر.</span> <font color=\"DarkGreen\"><b>[ ث ُ وَ ]</font></b> (اِخ ) آبی است از منزلهای تغلب بجزیره . (مراصد الاطلاع ).<br /></font></div>'),
(82771, 'ثویر', '<span class=\"hlight\">ثویر.</span> <font color=\"DarkGreen\"><b>[ ث ُ وَ ]</font></b> (اِخ ) ابن ابی فاخته سعیدبن علاقه، مکنی به ابی الجهم . مولی جعدة هبیرة. تابعی است .<br /></font></div>'),
(82772, 'ثویر', '<span class=\"hlight\">ثویر.</span> <font color=\"DarkGreen\"><b>[ ث ُ وَ ]</font></b> (اِخ ) ابوحامد. تابعی است .<br /></font></div>'),
(82773, 'ثویر', '<span class=\"hlight\">ثویر.</span><font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) اَبرق ُالثویر. موضعی است بدیار عرب .<br /></font></div>'),
(82774, 'ثویلة', '<span class=\"hlight\">ثویلة.</span> <font color=\"DarkGreen\"><b>[ ث َ ل َ ]</font></b> (ع اِ) گرد آمدن گاه گیاه . <BR><font color=\"Blue\">◄</font> گروه مردم از خانه های متفرق .<br /></font></div>'),
(82775, 'ثوینا', '<span class=\"hlight\">ثوینا.</span> <font color=\"DarkGreen\"><b>[ ث ُ وَ ]</font></b> (ع اِ) آرد خشکی که زیر پرازده گسترند. (منتهی الارب ).<br /></font></div>'),
(82776, 'ثویه', '<span class=\"hlight\">ثویه .</span> <font color=\"DarkGreen\"><b>[ ث َ وی ی َ ]</font></b> (ع اِ) زن . <BR><font color=\"Blue\">◄</font> جای گوسپند و شتر. آغل شتران و گوسپندان . <BR><font color=\"Blue\">◄</font> مکان و جای . <BR><font color=\"Blue\">◄</font> سنگ توده ٔ پست که در صحرا سازند برای نشان .<br /></font></div>'),
(82777, 'ثویه', '<span class=\"hlight\">ثویه .</span> <font color=\"DarkGreen\"><b>[ ث َ وی ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ث ُ وی ی َ ]</font></b> (اِخ ) موضعی است نزدیک کوفه و در آن است قبور ابوموسی الاشعری و مغیرةبن شعبة و زیادبن ابی سفیان . و گویند زندانی است در یک فرسخی حیره که نعمان بن منذر محبوسین را آنجا زندانی میکرد. (مراصد الاطلاع ).<br /></font></div>'),
(82778, 'ثک', '<span class=\"hlight\">ثک .</span> <font color=\"DarkGreen\"><b>[ ث َ ک ک ]</font></b> (ع مص ) سیاحت کردن در زمین .<br /></font></div>'),
(82779, 'ثکالی', '<span class=\"hlight\">ثکالی .</span> <font color=\"DarkGreen\"><b>[ ث َ لا ]</font></b> (ع ص، اِ) ج ِ ثکلی .<br /></font></div>'),
(82780, 'ثکامه', '<span class=\"hlight\">ثکامه .</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ ]</font></b>(اِخ ) نام شهری است در زمین عقیل . (مراصد الاطلاع ).<br /></font></div>'),
(82781, 'ثکد', '<span class=\"hlight\">ثکد.</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) آبی است بنوتمیم را.<br /></font></div>'),
(82782, 'ثکد', '<span class=\"hlight\">ثکد.</span> <font color=\"DarkGreen\"><b>[ ث ُ ک ُ ]</font></b> (اِخ ) آبی است از کلب وبه قولی آبی است میان کوفه و شام . (مراصد الاطلاع ).<br /></font></div>'),
(82783, 'ثکل', '<span class=\"hlight\">ثکل .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِمص ) حُلق . فرزندمردگی . <BR><font color=\"Blue\">◄</font> مرگ . هلاک . <BR><font color=\"Blue\">◄</font> (مص ) مصیبت زده شدن بمردن فرزند. بی فرزند شدن مادر. <BR><font color=\"Blue\">◄</font> گم کردن دوست . (تاج المصادر بیهقی ).<br /></font></div>'),
(82784, 'ثکل', '<span class=\"hlight\">ثکل .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع اِمص ) بی فرزندی .<br /></font></div>'),
(82785, 'ثکل', '<span class=\"hlight\">ثکل .</span> <font color=\"DarkGreen\"><b>[ ث ُ ک ُ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ک َ ]</font></b> (ع مص ) بی فرزند شدن مادر. <BR><font color=\"Blue\">◄</font> گم شدن دوست کسی را. <BR><font color=\"Blue\">◄</font> مردن .<br /></font></div>'),
(82786, 'ثکلان', '<span class=\"hlight\">ثکلان .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص، اِ) نعت مذکر از ثکل . مرد فرزندمرده یا دوست گم کرده .<br /></font></div>'),
(82787, 'ثکلانة', '<span class=\"hlight\">ثکلانة.</span> <font color=\"DarkGreen\"><b>[ ث َ ن َ ]</font></b> (ع ص، اِ) نعت مؤنث است از ثَکل .<br /></font></div>'),
(82788, 'ثکلی', '<span class=\"hlight\">ثکلی .</span> <font color=\"DarkGreen\"><b>[ ث َ لا ]</font></b> (ع ص، اِ) نعت مؤنث از ثکل . زن فرزندمرده، بچه گم کرده . ج، ثکالی . <BR><font color=\"Blue\">◄</font> زن عزیزمرده و گم کرده دوست . ثکول . ثاکلة. ج، ثواکل .<br /></font></div>'),
(82789, 'ثکم', '<span class=\"hlight\">ثکم .</span> <font color=\"DarkGreen\"><b>[ ث ُ ک َ ]</font></b> (اِخ ) نام مردی است .<br /></font></div>'),
(82790, 'ثکم', '<span class=\"hlight\">ثکم .</span> <font color=\"DarkGreen\"><b>[ ث َ ک َ ]</font></b> (ع مص ) ایستادن . <BR><font color=\"Blue\">◄</font> ملازم و مقیم شدن . <BR><font color=\"Blue\">◄</font> لازم گرفتن .<br /></font></div>'),
(82791, 'ثکم', '<span class=\"hlight\">ثکم .</span> <font color=\"DarkGreen\"><b>[ ث ُ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ک َ ]</font></b> (ع اِ) میانه ٔ راه و واضح آن . <BR><font color=\"Blue\">◄</font> میان مرد.<br /></font></div>'),
(82792, 'ثکم', '<span class=\"hlight\">ثکم .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع مص ) ثکم آثار؛ پی گرفتن و پیروی کردن اثر کسی . <BR><font color=\"Blue\">◄</font> ثکم امر؛ لازم گرفتن آن . <BR><font color=\"Blue\">◄</font> ثکم بمکان ؛ مقیم شدن در آن و ملازم گرفتن . (تاج المصادر بیهقی ).<br /></font></div>'),
(82793, 'ثکمة', '<span class=\"hlight\">ثکمة.</span> <font color=\"DarkGreen\"><b>[ث ُ م َ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ک َ م َ ]</font></b> (ع اِ) میانه ٔ راه و واضح آن .<br /></font></div>'),
(82794, 'ثکمة', '<span class=\"hlight\">ثکمة.</span> <font color=\"DarkGreen\"><b>[ ث ُ م َ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ م َ ]</font></b> (اِخ ) نام مردی است .<br /></font></div>'),
(82795, 'ثکن', '<span class=\"hlight\">ثکن .</span> <font color=\"DarkGreen\"><b>[ ث ُ ]</font></b> (ع اِ) راه راست . <BR><font color=\"Blue\">◄</font> شاه راه .<br /></font></div>'),
(82796, 'ثکن', '<span class=\"hlight\">ثکن .</span> <font color=\"DarkGreen\"><b>[ ث ُ ک َ ]</font></b> (ع اِ) ج ِ ثکنة.<br /></font></div>'),
(82797, 'ثکن', '<span class=\"hlight\">ثکن .</span> <font color=\"DarkGreen\"><b>[ ث َ ک َ ]</font></b> (ع اِ) ثکن طریق ؛ میانه ٔ راه .<br /></font></div>'),
(82798, 'ثکن', '<span class=\"hlight\">ثکن .</span> <font color=\"DarkGreen\"><b>[ ث َ ک َ ]</font></b> (اِخ ) نام کوهی است .<br /></font></div>'),
(82799, 'ثکنة', '<span class=\"hlight\">ثکنة.</span> <font color=\"DarkGreen\"><b>[ ث ُ ن َ ]</font></b> (ع اِ)مرکز جند. میانه و مرکز اجناد بر رایات . <BR><font color=\"Blue\">◄</font> مجتمع جند بر لواء و علم قائد خویش . مؤلف تاج العروس از المحکم نقل میکند که کلمه فارسی است و ج ِ عربی آن ثکن است . <BR><font color=\"Blue\">◄</font> گروهی از کبوتران و مرغان . <BR><font color=\"Blue\">◄</font> گردن بند. <BR><font color=\"Blue\">◄</font> حمیل . <BR><font color=\"Blue\">◄</font> رایت . علامت . <BR><font color=\"Blue\">◄</font> قبر. <BR><font color=\"Blue\">◄</font> چاه آتش . <BR><font color=\"Blue\">◄</font> مغاکچه . <BR><font color=\"Blue\">◄</font> نیت ایمان با کفر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> پاره ای پشم که بر گردن شتر آویزند. <BR><font color=\"Blue\">◄</font> میانه ٔ لشکر.<br /></font></div>'),
(82800, 'ثکول', '<span class=\"hlight\">ثکول .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (ع ص، اِ) نعت مؤنث است از ثکل، مانند ثاکل و ثکلی و ثکلانة. زنی که فرزند یا دوستش نایافت یافوت شده باشد. <BR><font color=\"Blue\">◄</font> هبول . <BR><font color=\"Blue\">◄</font> فلات ثکول ؛ بیابانی که رونده در آن گم گردد و هلاک شود.<br /></font></div>'),
(82801, 'ثکین', '<span class=\"hlight\">ثکین .</span> (اِخ ) کوهی است دربادیه در شعر عبدالمسیح بن نفیله . (مراصد الاطلاع ).<br /></font></div>'),
(82802, 'ثی', '<span class=\"hlight\">ثی .</span> (ع حرف، اِ) نام دیگر حرف ثاء.<br /></font></div>'),
(82803, 'ثیاب', '<span class=\"hlight\">ثیاب .</span> (ع اِ) ج ِ ثوب . جامه ها <span class=\"hlight\">:</span> <br />اینکه توبینی نه همه مردمند<br />بلکه ذئابند بزیر ثیاب .<br /> <font color=\"Red\">ناصرخسرو.</font><br />در ثیاب ربوده از درویش <br />کی بدست آیدت بهشت و ثواب .<br /> <font color=\"Red\">ناصرخسرو.</font><br /><BR><font color=\"Blue\">◄</font> تَعلق ّ بثیاب اﷲ؛ ای بأستارالکعبة. <BR><font color=\"Blue\">◄</font> فلان طاهر الثیاب ؛ پاک است از عیوب . <BR><font color=\"Blue\">◄</font> اعمال، أن المیت لیبعث ُ فی ثیابه . (حدیث ). <BR><font color=\"Blue\">◄</font> ثیاب قبطیه ؛ کتان باریک سفید و غیر آن که بقبط منسوب است .<br /></font></div>'),
(82804, 'ثیابی', '<span class=\"hlight\">ثیابی .</span> <font color=\"DarkGreen\"><b>[ بی ی ]</font></b> (ع ص نسبی ) جامه دار. ثوّاب . بزاز.<br /></font></div>'),
(82805, 'ثیابی', '<span class=\"hlight\">ثیابی .</span> <font color=\"DarkGreen\"><b>[ بی ی ]</font></b> (اِخ ) محمودبن عمر. محدث است و از آن رو وی را ثیابی گویند که جامه دار حمام بود.<br /></font></div>'),
(82806, 'ثیابی', '<span class=\"hlight\">ثیابی .</span> <font color=\"DarkGreen\"><b>[ بی ی ]</font></b> (اِخ ) یکی از شعرای عثمانی در مائه ٔ دهم هجری . او امی بود و شغل خیاطت میورزید و از آنرو تخلص ثیابی گرفت . (قاموس الاعلام ).<br /></font></div>'),
(82807, 'ثیاتل', '<span class=\"hlight\">ثیاتل .</span> <font color=\"DarkGreen\"><b>[ ث َ ت ِ ]</font></b> (ع اِ) ج ِ ثیتل .<br /></font></div>'),
(82808, 'ثیادریطوس', '<span class=\"hlight\">ثیادریطوس .</span> (اِخ ) نام ملکی ازملوک یونان که برای او معجونی ساختند و آن را بنام او موسوم کردند. گویند اول کس که آن را ساخت اندروماخس ثانی و به قولی ابقراط بود. و آن داروئی است نیکو که اثر آن هفت سال برجای ماند. (تذکره ٔ ضریر انطاکی ). ظاهراً این کلمه مصحف مثروذیطوس (میتریدات = مهرداد)است و این معجون نیز همان تریاق فاروق مشهور است .<br /></font></div>'),
(82809, 'ثیادورس', '<span class=\"hlight\">ثیادورس .</span> (اِخ ) طبیب نصرانی که در ایران میزیست و به حذاقت در طب معروف بود و شاپور ذوالاکتاف یا بقولی بهرام گور برای او بیعه ای در شهر وی بنا کرد. این روایت معرف قدر و اعتبار او در نزد ایرانیان است و عصر او را نیز معلوم میدارد. او راست : کتابی جامع در طب که به کناش معروف است . ابن الندیم گوید که آن کتاب به عربی نقل شده است و شاید این شخص همان تئودورس ملقب به شارح باشد که کتب او را کوماس و پروبوس و هی باس در قرن پنجم میلادی ترجمه کردند. (لکلرک، تاریخ طب عرب . ابن الندیم، کتاب الفهرست ).<br /></font></div>'),
(82810, 'ثیادورس', '<span class=\"hlight\">ثیادورس .</span> (اِخ ) یکی از ناقلین نصاری به عربی . او راست : ترجمه ٔ انالوطیقای اولی از ارسطو و گویندآنرا به حنین عرضه داشت و حنین آنرا اصلاح کرد. (ابن الندیم ). نام او را ثیاذورس نیز آورده اند. (قفطی ).<br /></font></div>'),
(82811, 'ثیادورس', '<span class=\"hlight\">ثیادورس .</span> (اِخ ) انطاکی . دکترلکلرک در تاریخ طب عرب بنقل از ابن العبری آورده است ثیادورس نصرانی یعقوبی بود که در انطاکیه سریانی و لاتینی آموخت و به تحصیل علوم کوشید و کرتی بموصل آمد و بمحضر درس کمال الدین بن یونس باستفادت پرداخت سپس به انطاکیه بازگشت چون دانست که علوم وی ناقص است بار دوم بموصل عزیمت کرد و بعد به بغداد شد و مطالعات طبی خویش را کامل ساخت و چندی به خدمت سلطان علاءالدین پیوست و بعد به دربارقسطنطین ملک ارمنستان رفت لیکن او طالب مقامی بالاتربود تا آنکه با سفیری از فردریک دوم دیدار کرد و بتوسط او نزد فردریک شتافت و فردریک او را گرامی داشت و مورد اعزاز و تکریم قرار داد چون چندی بخت و اقبال با او مساعد شد هوای یار و دیارش بر سر افتاد و بی خبر بخلاف میل حامی خویش راه دریا پیش گرفت اتفاقاً کشتی او را به بندری افکند که هم در قلمرو فردریک بودثیادورس دانست که باید با فردریک بار دیگر دیدار کند و از ترس خویشتن را به زهر بکشت . (نقل باختصار).<br /></font></div>'),
(82812, 'ثیادوس', '<span class=\"hlight\">ثیادوس .</span> (اِخ ) ظاهراً اصل کلمه ٔ نیاطوس نام پسر موریق (موریس ). ملک روم که به خسرو دوم (پرویز) در دفع بهرام چوبین مدد کرد. (مجمل التواریخ و القصص ص <span class=\"hlight\" dir=\"rtl\">٧٨</span> و حاشیه ٔ آن ).<br /></font></div>'),
(82813, 'ثیاذریطوس', '<span class=\"hlight\">ثیاذریطوس .</span> (اِخ ) رجوع به ثیادریطوس شود.<br /></font></div>'),
(82814, 'ثیاذوق', '<span class=\"hlight\">ثیاذوق .</span> (اِخ ) طبیب معروف نصاری بمائه ٔ اول هجری در دولت بنی امیه . او پزشک حجاج بن یوسف ثقفی بود و حجاج باو اعتمادی تمام داشت و بدستور او عمل میکرد روایت کنند که روزی حجاج که عادت گل خواری داشت ازو پرسید دوای گل خوردن چیست گفت عزیمت مردی چون تو. حجاج از ان پس بترک آن عادت گفت ثیاذوق در تدبیر صحت به حجاج وصایائی کرده که از آن جمله است : تا به دارو حاجت نیفتد مگیر. از میوه جزرسیده مخور. خوردنیها را هر چه بیشتر بخای . پس از طعام چاشت خفتن را بأسی نیست لیکن چون به شب غذا خوری تا راه نرفته ای هر چند پنجاه گام باشد مخسب و تا گرسنه نباشی هیچ مخور. در آرامش با زنان افراط مکن . از حبس بول بپرهیز. هر دو روز یک بار استحمام کن . در حال سیری به حمام مرو. با امتلاء معده با زنان میارام . از گوشت خشک (قدیم ) نمک سود بپرهیز. ناشتا آب سرد میاشام . چون شکم از طعام پرباشد بر پهلوی چپ خسب . بازن پیر ازدواج مکن . از «سواک » غفلت مورز. گوشت از پی گوشت مخور. ثیاذوق بکمال پیری رسید و در شهر واسط در حدود سال <span class=\"hlight\" dir=\"rtl\">٩٠</span> هَ . ق . وفات کرد از مؤلفات اوست . کتاب کناش کبیر که برای پسر خود تألیف کرد و دیگر کتاب ابدال الادویة و کیفیة دقها و ایقاعها و اذابتها و شی ٔ من تفسیر أسماء الادویة فرات بن شحاثا طبیب یهودی از شاگردان او بود. <br /></font></div>'),
(82815, 'ثیاذووس', '<span class=\"hlight\">ثیاذووس .</span> (اِخ ) الاثینی . فیلسوف است . <br /></font></div>'),
(82816, 'ثیار', '<span class=\"hlight\">ثیار.</span> (ع اِ) ج ِ ثور. گاوان .<br /></font></div>'),
(82817, 'ثیب', '<span class=\"hlight\">ثیب .</span> <font color=\"DarkGreen\"><b>[ ث َی ْ ی ِ ]</font></b> (ع ص، اِ) کالم . زن شوی دیده که اکنون بی شوی است به طلاق یا مرگ شوی . بیوه . عوان . مقابل . دوشیزه . ج، ثیبات . <BR><font color=\"Blue\">◄</font> مردزن گرفته که اکنون بی زن است . مقابل پسر. عزب . <BR><font color=\"Blue\">◄</font> خلاف بکر. و در مرد و زن هر دو مستعمل است .<br /></font></div>'),
(82818, 'ثیب', '<span class=\"hlight\">ثیب .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) کوهی است به شرقی مدینةالرسول .<br /></font></div>'),
(82819, 'ثیبات', '<span class=\"hlight\">ثیبات .</span> <font color=\"DarkGreen\"><b>[ ث َی ْ ی ِ ]</font></b> (ع ص، اِ) ج ِ ثیب . زنان بیوه از شوی مرده و یا طلاق گرفته .<br /></font></div>'),
(82820, 'ثیبان', '<span class=\"hlight\">ثیبان .</span> <font color=\"DarkGreen\"><b>[ ث َ ]</font></b> (اِخ ) نام روستائی است .<br /></font></div>'),
(82821, 'ثیبة', '<span class=\"hlight\">ثیبة.</span> <font color=\"DarkGreen\"><b>[ ث َی ْ ی ِ ب َ ]</font></b> (ع ص، اِ) زن شوهردیده و از شوهر جدامانده خواه به طلاق و خواه به مرگ شوی . کالم . بیوه . مقابل باکره ؛ دوشیزه .<br /></font></div>'),
(82822, 'ثیة', '<span class=\"hlight\">ثیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع اِ) آغل گوسفندان .<br /></font></div>'),
(82823, 'ثیتا', '<span class=\"hlight\">ثیتا.</span> (یونانی، حرف، اِ) نام حرف هشتم است از حروف یونانی . رجوع به ثتا شود. و آن نماینده ٔ ستاره های قدر ششم است .<br /></font></div>'),
(82824, 'ثیتل', '<span class=\"hlight\">ثیتل .</span> <font color=\"DarkGreen\"><b>[ ث َ ت َ ]</font></b> (اِخ ) نام کوهی است .(منتهی الارب ). <BR><font color=\"Blue\">◄</font> محلی است نزدیک نباج که جنگ مشهوری در آنجا واقع شد بین نباج و ثیتل . منزلی است برای مسافران بصره . <BR><font color=\"Blue\">◄</font> و گویند قریه ای است . <BR><font color=\"Blue\">◄</font> و گویند شهری است از بنی حمان .<br /></font></div>'),
(82825, 'ثیتل', '<span class=\"hlight\">ثیتل .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (ع اِ) بز کوهی نر. <BR><font color=\"Blue\">◄</font> گاو کوهی نر. <BR><font color=\"Blue\">◄</font> نوعی از کاو دشتی . نمش . ج، ثیاتل . <BR><font color=\"Blue\">◄</font> مرد فربه که در وی گمان خیر دارند. <BR><font color=\"Blue\">◄</font> عنین .<br /></font></div>'),
(82826, 'ثیر', '<span class=\"hlight\">ثیر.</span> (ع اِ) پرده ٔ چشم .<br /></font></div>'),
(82827, 'ثیران', '<span class=\"hlight\">ثیران .</span> (ع اِ) ج ِ ثَور. گاوان . گاوان نر.<br /></font></div>'),
(82828, 'ثیرما', '<span class=\"hlight\">ثیرما.</span> (معرب، اِ) به یونانی آب گرم . او گرم . (نخبةالدهر).آب گرم معدنی . حمام گرم معدنی . رجوع به ثرمة شود.<br /></font></div>'),
(82829, 'ثیریون', '<span class=\"hlight\">ثیریون .</span> (معرب، اِ) به یونانی، دفلی است . (تحفه ٔ حکیم مؤمن ). خرزهره . سم الحمار.<br /></font></div>'),
(82830, 'ثیسناس', '<span class=\"hlight\">ثیسناس .</span> (اِخ ) خطیب یونانی شاگرد غراب صقلی از جمله ٔ خطباء یونان که از انواع فلسفه به تعلم خطابه گرائید و نزد غراب صقلی به تحصیل آن فن اشتغال جست و جزئی وافر از آن فن بیاموخت گویند سپس او را با استاد در امر اجرت تعلیم نزاع افتاد. (قفطی ص <span class=\"hlight\" dir=\"rtl\">١٠٩</span>).<br /></font></div>'),
(82831, 'ثیقوس', '<span class=\"hlight\">ثیقوس .</span> (معرب، اِ) به یونانی اذخر است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(82832, 'ثیل', '<span class=\"hlight\">ثیل .</span> <font color=\"DarkGreen\"><b>[ ث َ <span class=\"hlight\" dir=\"rtl\">/</span> ثی ]</font></b> (ع اِ)غلاف نره ٔ شتر. <BR><font color=\"Blue\">◄</font> نره ٔ شتر. ج، اَثیال .<br /></font></div>'),
(82833, 'ثیل', '<span class=\"hlight\">ثیل .</span> (ع ص، اِ) ج ِ اَثیل .<br /></font></div>'),
(82834, 'ثیل', '<span class=\"hlight\">ثیل .</span> <font color=\"DarkGreen\"><b>[ ث َی ْ ی ِ <span class=\"hlight\" dir=\"rtl\">/</span> ثی ]</font></b> (ع اِ)بیدگیا. فرزد. فریز. چمن . مرغ . گیاهی است که نجم نیز گویند. در اختیارات بدیعی آمده است : نجیل و نجیر ونجمه خوانند به پارسی بیدگیا خوانند و آن نوعی از حرشف است و طبیعت وی سرد و خشک است در اول و گویند معتدل است نافع بود جهت جراحتهای تازه و منع نزله کند و بیخ وی و تخم وی منع قی کند و ادرار بول کند تمام و اسهال باز دارد. از تخم وی لعوق سازند. سنگ گرده را بریزاند و طبع آن ریش مثانه را نافع بود - انتهی . در تحفه ٔ حکیم مؤمن آمده است : به لغت ترکی ییلان اودی و در تنکابن گرک چرواش گویند و آن نباتی است که درکنار آبها و زمین نمناک میروید مخصوص زمانی نیست و بر روی زمین پهن میشود و شاخهای او دراز و با بندها بسیار و برگش بسیار ریزه و بر هر بندی رسته ای و گلش مابین سرخی و سفیدی و با برگ آمیخته و طعمش مایل به شیرینی در اول سرد و خشک و قابض و طبیخ او جهت مغص وعسر بول و قروح مثانه و طبیخ بیخ او جهت سنگ گرده وگزیده ٔ هوام و ضماد او جهت جراحات تازه و آب گیاه او از نیم رطل تا یک رطل در رفع سم اقسام مارها و سگ دیوانه گزیده مجرب و رافع حرقةالبول و احتباس بول و حصات و تبهای حاره و سل بغایت آزموده است و مانع نزلات و اورام حاره و ضماد خاکستر او جهت قطع خون بواسیرو تحلیل اورام و تجفیف قروح بغایت نافع و قسمی از آن را برگ مثل لبلاب و گلش خوشبو و ثمرش ریزه و عروق او در ضخامت بقدر انگشتی و در عدد پنج یا شش میباشد عصاره ٔ او با ادویه ٔ مناسبه جهت علل چشم و تحلیل مواد و تخمش بغایت مدر بول و جهت قطع قی و اسهال و منع ریختن مواد به معده و احشا و حصاة گرده و مثانه و قروح آن مفید است و قسمی از آن می باشد که هر گاه گاو از آن بخورد اعضای او ورم میکند. سوخته ٔ او در ظرف مس جهت قطع خون بواسیر ضماداً از مجربات شمرده اند و گویند زیاده بر سه بار احتیاج نمی افتد و ضماد تازه ٔ اوبا روغن گل بغایت ملین و منضج است - انتهی . مؤلف برهان قاطع گوید: نوعی از حرشف است که کنگر باشد و آنرا به فارسی بید گیا خوانند بول را براند و شکم را ببندد گویند عربی است و بعضی گویند سریانی - انتهی .<br /></font></div>'),
(82835, 'ثیل', '<span class=\"hlight\">ثیل .</span> <font color=\"DarkGreen\"><b>[ ث َی ْ ی ِ ]</font></b> (ع اِ) ثیل باشد که بید گیا خوانند. رجوع به ثیل شود.<br /></font></div>'),
(82836, 'ثیلة', '<span class=\"hlight\">ثیلة.</span> <font color=\"DarkGreen\"><b>[ ث َی ْ ی ِ ل َ ]</font></b> (ع اِ) واحد ثیل .<br /></font></div>'),
(82837, 'ثیلة', '<span class=\"hlight\">ثیلة.</span> <font color=\"DarkGreen\"><b>[ ث َی ْ ی ِ ل َ ]</font></b> (اِخ ) آبی است به قطن . (مراصد الاطلاع ).<br /></font></div>'),
(82838, 'ثیم مرمان', '<span class=\"hlight\">ثیم مرمان .</span> <font color=\"DarkGreen\"><b>[ م ِرْ ]</font></b> (اِخ ) یکی از دانشمندانی که از خطوط میخی و آثار قدیمه ٔ بنی سام اطلاعاتی جمع کرده و تبصره های مفید بر آن افزوده است . <br /></font></div>'),
(82839, 'ثیموم', '<span class=\"hlight\">ثیموم .</span> (اِ) نام نباتی است شبیه به گندم که رفع سفیدی چشم کند و آنرا نمام نیز گویند.<br /></font></div>'),
(82840, 'ثین', '<span class=\"hlight\">ثین .</span> (اِخ ) نام یکی از خاندانهای بزرگ چین . (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٥٥</span>).<br /></font></div>'),
(82841, 'ثین', '<span class=\"hlight\">ثین .</span> (ع اِ) مستخرج مروارید از دریا. <BR><font color=\"Blue\">◄</font> مثقب مروارید.<br /></font></div>'),
(82842, 'ثیوبة', '<span class=\"hlight\">ثیوبة.</span> <font color=\"DarkGreen\"><b>[ ث َ ب َ ]</font></b> (ع مص ) ثیوبت . خلاف بکارت . بیوگی .<br /></font></div>'),
(82843, 'ثیودورس', '<span class=\"hlight\">ثیودورس .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (اِخ ) یکی از ریاضیون و مهندسین یونانی بعد از بطلمیوس . او در اسکندریه مقیم بود. او راست : کتاب ُالاُکر، در سه مقاله . کتاب المساکن، یک مقاله . کتاب اللیل و النهار، دو مقاله . (ابن الندیم ). و ظاهراً این نام صورتی محرف از ثاوذوسیوس است . رجوع به ثاوذوسیوس شود.<br /></font></div>'),
(82844, 'ثیوذوفروس', '<span class=\"hlight\">ثیوذوفروس .</span> (اِخ ) رجوع به ثیودورس و ثاوذوسیوس شود.<br /></font></div>'),
(82845, 'ثیوفرسطس', '<span class=\"hlight\">ثیوفرسطس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) جانشین ارسطو در لوقیون . (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٧</span>). رجوع به ثاوفرسطس شود.<br /></font></div>'),
(82846, 'ثییة', '<span class=\"hlight\">ثییة.</span> <font color=\"DarkGreen\"><b>[ ث ُ ی َی ْ ی َ ]</font></b> (ع اِ مصغر) مصغر ثاء، حرف چهارم از حروف هجاء عرب .<br /></font></div>');
